@font-face {
    font-family: "Inter";
    font-style: normal;
    font-weight: 400;
    font-display: swap;
    src: url("/vendor/workraken/static/fonts/inter-latin-v1.woff2") format("woff2");
}

@font-face {
    font-family: "Inter";
    font-style: normal;
    font-weight: 500;
    font-display: swap;
    src: url("/vendor/workraken/static/fonts/inter-latin-v1.woff2") format("woff2");
}

@font-face {
    font-family: "Inter";
    font-style: normal;
    font-weight: 600;
    font-display: swap;
    src: url("/vendor/workraken/static/fonts/inter-latin-v1.woff2") format("woff2");
}

@font-face {
    font-family: "Montserrat";
    font-style: normal;
    font-weight: 600;
    font-display: swap;
    src: url("/vendor/workraken/static/fonts/montserrat-semibold-latin-v1.woff2") format("woff2");
}

:root {
    --wk-section-stripe-width: 3px;
    --brand-primary: #6D28D9;
    --brand-neutral: #2C0E3A;
    --brand-primary-soft: #E9D5FF;
    --whatsapp-brand-green: #25D366;
    --font-body: "Inter", "Segoe UI", Arial, sans-serif;
    --font-title: "Inter", "Segoe UI", Arial, sans-serif;
    --font-brand: "Montserrat", "Inter", "Segoe UI", Arial, sans-serif;
    --font-button: "Inter", "Segoe UI", Arial, sans-serif;
    --font-regular: 400;
    --font-medium: 500;
    --font-semibold: 600;
    --bg: #F8F5FF;
    --surface: #ffffff;
    --surface-soft: #FBF9FF;
    --surface-strong: #EEE7F7;
    --ink: #17111F;
    --muted: #17111F;
    --muted-soft: #17111F;
    --line: #DED3EB;
    --line-strong: #CDBBDD;
    --border: #DED3EB;
    --text: #17111F;
    --sidebar: #F3EDFB;
    --sidebar-soft: #ffffff;
    --sidebar-line: rgba(62, 20, 112, 0.16);
    --accent-violet: #6D28D9;
    --accent-purple: #7C4DFF;
    --accent-amber: #b7791f;
    --accent-amber-text: #96620a;
    --accent-rose: #be4b5b;
    --accent-blue: #2563eb;
    --link-blue: #1f6fd6;
    --link-blue-dark: #7cc8ff;
    --positive: #087f6f;
    --danger: #c23d42;
    --active-row-background: #dcfce7;
    --active-row-background-hover: #bbf7d0;
    --active-row-accent: #15803d;
    --active-row-text: #000000;
    --ended-row-background: #fee2e2;
    --ended-row-background-hover: #fecaca;
    --ended-row-accent: #dc2626;
    --ended-row-text: #000000;
    --reservation-row-background: #fef3c7;
    --reservation-row-background-hover: #fde68a;
    --reservation-row-accent: #b45309;
    --reservation-row-text: #000000;
    --blacklist-row-background: #f3e8ff;
    --blacklist-row-background-hover: #e9d5ff;
    --blacklist-row-accent: #7e22ce;
    --blacklist-row-text: #000000;
    --overdue-row-background: #ffedd5;
    --overdue-row-background-hover: #fed7aa;
    --overdue-row-accent: #c2410c;
    --overdue-row-text: #000000;
    --shadow-card: 0 1px 2px rgba(43, 47, 51, 0.06), 0 10px 24px rgba(43, 47, 51, 0.05);
    --shadow-lift: 0 8px 22px rgba(43, 47, 51, 0.09);
}

* {
    box-sizing: border-box;
}

html {
    background: var(--bg);
    scroll-behavior: smooth;
}

body {
    margin: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: var(--font-body);
    font-size: 15px;
    font-weight: var(--font-regular);
    line-height: 1.42;
    letter-spacing: 0;
}

a {
    color: inherit;
    text-decoration: none;
}

button,
input,
select,
textarea {
    font: inherit;
    letter-spacing: 0;
}

button,
.button,
input[type="button"],
input[type="submit"],
input[type="reset"],
[role="button"] {
    font-family: var(--font-button);
    font-weight: var(--font-medium);
}

.app-shell {
    --active-sidebar-width: 272px;
    display: grid;
    grid-template-columns: 272px minmax(0, 1fr);
    min-height: 100vh;
    transition: grid-template-columns 0.18s ease;
}

.app-shell.is-sidebar-collapsed {
    --active-sidebar-width: 78px;
    grid-template-columns: 78px minmax(0, 1fr);
}

.sidebar {
    position: sticky;
    top: 0;
    z-index: 110;
    display: flex;
    flex-direction: column;
    height: 100vh;
    padding: 18px 16px;
    border-right: 1px solid #d7e0e4;
    background: var(--sidebar);
    color: #000000;
    transition: padding 0.18s ease;
}

.sidebar-toggle {
    position: absolute;
    top: 22px;
    right: -17px;
    z-index: 120;
    display: inline-grid;
    place-items: center;
    width: 34px;
    height: 34px;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: #ffffff;
    color: var(--brand-primary);
    cursor: pointer;
    box-shadow: var(--shadow-card);
}

.sidebar-toggle::before {
    width: 9px;
    height: 9px;
    margin-left: 3px;
    border-bottom: 2px solid currentColor;
    border-left: 2px solid currentColor;
    content: "";
    transform: rotate(45deg);
    transition: margin 0.18s ease, transform 0.18s ease;
}

.sidebar-toggle:hover,
.sidebar-toggle:focus-visible {
    border-color: rgba(109, 40, 217, 0.28);
    outline: none;
    box-shadow: 0 0 0 4px rgba(109, 40, 217, 0.13);
}

.app-shell.is-sidebar-collapsed .sidebar {
    align-items: center;
    padding-right: 10px;
    padding-left: 10px;
}

.app-shell.is-sidebar-collapsed .sidebar-toggle::before {
    margin-right: 3px;
    margin-left: 0;
    transform: rotate(225deg);
}

.brand {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 76px;
    padding: 10px 12px;
    border: 1px solid #ccd7dd;
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    box-shadow: 0 2px 10px rgba(16, 24, 32, 0.09);
}

.brand-copy,
.nav-label,
.sidebar-logout-label {
    min-width: 0;
    overflow: hidden;
    opacity: 1;
    transition: opacity 0.14s ease, width 0.18s ease;
    white-space: nowrap;
}

.app-shell.is-sidebar-collapsed .brand {
    justify-content: center;
    gap: 0;
    width: 100%;
    padding-right: 8px;
    padding-left: 8px;
}

.app-shell.is-sidebar-collapsed .brand-copy,
.app-shell.is-sidebar-collapsed .nav-label,
.app-shell.is-sidebar-collapsed .sidebar-logout-label {
    width: 0;
    opacity: 0;
    pointer-events: none;
}

.brand-logo {
    width: 50px;
    height: 50px;
    filter: none;
    object-fit: contain;
}

.brand-mark-dark {
    display: none;
}

.brand .brand-wordmark,
.brand strong,
.brand small {
    display: block;
}

.brand .brand-wordmark {
    width: 142px;
    max-width: 100%;
    height: auto;
    object-fit: contain;
}

.brand .brand-wordmark-dark {
    display: none;
}

html[data-theme="dark"] .app-shell .brand-mark-light,
html[data-theme="dark"] .app-shell .brand .brand-wordmark-light {
    display: none;
}

html[data-theme="dark"] .app-shell .brand-mark-dark,
html[data-theme="dark"] .app-shell .brand .brand-wordmark-dark {
    display: block;
}

.brand strong {
    font-family: var(--font-brand);
    font-size: 30px;
    font-weight: 600;
    line-height: 1;
}

.brand small {
    margin-top: 3px;
    color: var(--muted);
}

.brand-name {
    font-family: var(--font-brand);
    font-weight: 600;
}

.brand-primary {
    color: var(--brand-primary);
}

.brand-neutral {
    color: #000000;
}

.nav-list {
    display: grid;
    gap: 5px;
    margin-top: 22px;
}

.app-shell.is-sidebar-collapsed .nav-list,
.app-shell.is-sidebar-collapsed .sidebar-session {
    width: 100%;
}

.nav-link {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 52px;
    padding: 0 12px;
    border-radius: 8px;
    color: #000000;
    font-size: 16px;
    font-weight: 600;
}

.app-shell.is-sidebar-collapsed .nav-link {
    justify-content: center;
    gap: 0;
    padding-right: 0;
    padding-left: 0;
}

.nav-link:hover,
.nav-link.is-active {
    background: var(--brand-primary);
    color: #fff;
}

.nav-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    flex: 0 0 40px;
    padding: 5px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: transparent;
    color: currentColor;
    box-shadow: none;
    overflow: hidden;
}

.sidebar-logout-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    flex: 0 0 32px;
    color: currentColor;
}

.nav-icon svg,
.sidebar-logout-icon svg {
    width: 100%;
    height: 100%;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
}

.nav-link:not(:hover):not(.is-active) .nav-icon-violet { color: var(--accent-violet); }
.nav-link:not(:hover):not(.is-active) .nav-icon-teal { color: var(--accent-purple); }
.nav-link:not(:hover):not(.is-active) .nav-icon-amber { color: var(--accent-amber); }
.nav-link:not(:hover):not(.is-active) .nav-icon-rose { color: var(--accent-rose); }
.nav-link:not(:hover):not(.is-active) .nav-icon-blue { color: var(--accent-blue); }

.app-shell.is-sidebar-collapsed .nav-icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
}

.nav-dot {
    width: 10px;
    height: 10px;
    flex: 0 0 10px;
    border-radius: 999px;
    background: var(--accent-violet);
}

.nav-dot-violet { background: var(--accent-violet); }
.nav-dot-teal { background: var(--accent-purple); }
.nav-dot-amber { background: var(--accent-amber); }
.nav-dot-rose { background: var(--accent-rose); }
.nav-dot-blue { background: var(--accent-blue); }

.sidebar-session {
    display: grid;
    gap: 10px;
    margin-top: auto;
}

.sidebar-logout-form {
    margin: 0;
}

.sidebar-logout-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    width: 100%;
    min-height: 50px;
    padding: 0 14px;
    border: 1px solid rgba(248, 113, 113, 0.55);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.07);
    color: #fff;
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
}

.app-shell.is-sidebar-collapsed .sidebar-logout-button {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    min-height: 52px;
    margin: 0 auto;
    padding: 0;
}

.app-shell.is-sidebar-collapsed .sidebar-logout-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    flex: 0 0 34px;
    padding: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    line-height: 0;
}

.app-shell.is-sidebar-collapsed .sidebar-logout-icon-image {
    transform: translateX(2px);
}

.sidebar-logout-button:hover {
    border-color: rgba(254, 202, 202, 0.8);
    background: rgba(185, 28, 28, 0.18);
}

.sidebar-footer {
    display: grid;
    gap: 4px;
    padding: 13px 14px;
    border: 1px solid var(--sidebar-line);
    border-radius: 8px;
    color: var(--ink);
}

.sidebar-footer strong {
    color: inherit;
    font-size: 16px;
}

.content {
    min-width: 0;
    width: 100%;
    max-width: 1640px;
    margin: 0 auto;
    padding: 20px 30px 44px;
}

.topbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 18px;
    margin-bottom: 20px;
}

.topbar-main {
    display: grid;
    min-width: 0;
    gap: 3px;
}

.topbar-side {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 18px;
    min-width: 0;
}

.topbar-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
}

.topbar-parking-logo {
    flex: 0 0 auto;
    width: 44px;
    height: 44px;
    object-fit: contain;
}

.topbar-user {
    display: grid;
    gap: 2px;
    min-height: 42px;
    padding: 7px 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--muted);
    box-shadow: var(--shadow-card);
}

.topbar-user span {
    font-size: 11px;
    font-weight: var(--font-semibold);
    line-height: 1;
    text-transform: uppercase;
}

.topbar-user strong {
    max-width: 220px;
    overflow: hidden;
    color: var(--ink);
    font-size: 14px;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.logout-form {
    margin: 0;
}

.logout-button {
    min-height: 42px;
    padding: 0 14px;
    border: 1px solid rgba(185, 28, 28, 0.35);
    border-radius: 8px;
    background: #b91c1c;
    color: #fff;
    font-weight: 600;
    cursor: pointer;
    box-shadow: var(--shadow-card);
}

.logout-button:hover {
    border-color: rgba(153, 27, 27, 0.5);
    background: #991b1b;
}

.topbar-main,
.topbar-side,
.module-hero > div:first-child {
    min-width: 0;
}

.topbar h1,
.panel h2,
.module-hero h2 {
    margin: 0;
    color: var(--ink);
    font-family: var(--font-title);
    font-weight: 600;
    line-height: 1.16;
    letter-spacing: 0;
}

.topbar h1 {
    font-size: 31px;
}

.parking-title-picker {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
}

.parking-title-lead {
    color: var(--muted);
    font-weight: var(--font-medium);
}

/* El nombre del estacionamiento activo abre la lista de todos los estacionamientos. */
.parking-title-name {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    max-width: min(560px, 68vw);
    padding: 0;
    border: 0;
    background: none;
    color: var(--ink);
    font: inherit;
    line-height: inherit;
    cursor: pointer;
}

.parking-title-name > span {
    overflow: hidden;
    border-bottom: 2px solid rgba(109, 40, 217, 0.3);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.parking-title-name::after {
    flex: 0 0 auto;
    width: 0;
    height: 0;
    border-top: 7px solid currentColor;
    border-right: 6px solid transparent;
    border-left: 6px solid transparent;
    opacity: 0.75;
    content: "";
}

.parking-title-name:hover > span,
.parking-title-name:focus-visible > span {
    border-bottom-color: currentColor;
}

.parking-switch-hint {
    margin: 4px 0 0;
    color: var(--muted);
    font-size: 13px;
}

.parking-switch-panel {
    width: min(760px, 100%);
}

.parking-switch-list {
    display: grid;
    gap: 12px;
}

.parking-switch-option {
    display: grid;
    grid-template-columns: 56px minmax(0, 1fr);
    align-items: center;
    gap: 14px;
    padding: 14px 16px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    text-align: left;
    cursor: pointer;
}

.parking-switch-option:hover,
.parking-switch-option:focus-visible {
    border-color: var(--line-strong);
    box-shadow: var(--shadow-card);
}

.parking-switch-option.is-active {
    border-color: rgba(109, 40, 217, 0.45);
    background: rgba(109, 40, 217, 0.07);
}

.parking-switch-option-logo {
    display: grid;
    place-items: center;
    width: 56px;
    height: 56px;
}

.parking-switch-option-logo img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.parking-switch-option-body {
    display: grid;
    gap: 8px;
    min-width: 0;
}

.parking-switch-option-name {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    font-family: var(--font-title);
    font-size: 18px;
    font-weight: 600;
}

.parking-switch-option-badge {
    padding: 2px 8px;
    border-radius: 999px;
    background: rgba(109, 40, 217, 0.14);
    color: var(--accent-purple);
    font-family: var(--font-body);
    font-size: 11px;
    font-weight: var(--font-semibold);
    text-transform: uppercase;
}

.parking-switch-option-fields {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    gap: 8px 16px;
}

.parking-switch-option-fields > span {
    display: grid;
    gap: 2px;
    min-width: 0;
    overflow: hidden;
    font-size: 14px;
    text-overflow: ellipsis;
}

.parking-switch-option-fields small {
    color: var(--muted);
    font-size: 11px;
    font-weight: var(--font-semibold);
    text-transform: uppercase;
}


.module-hero h2 {
    max-width: 760px;
    font-size: 26px;
}

.panel h2 {
    font-size: 20px;
}

.eyebrow {
    margin: 0 0 7px;
    color: var(--brand-primary);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0;
    text-transform: uppercase;
}

.year-form,
.month-form {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 52px;
    padding: 8px 10px 8px 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    box-shadow: var(--shadow-card);
}

.year-form label,
.month-form label {
    color: var(--muted);
    font-size: 13px;
    font-weight: 600;
}

select,
.search-input {
    height: 40px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
    color: var(--ink);
}

select {
    min-width: 96px;
    padding: 0 10px;
}

.search-input {
    width: 260px;
    padding: 0 13px;
}

.search-input::placeholder,
input::placeholder {
    color: var(--muted-soft);
}

.module-hero,
.panel,
.kpi-card {
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    box-shadow: var(--shadow-card);
}


.kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 12px;
}

.kpi-grid-wide {
    /* Prioriza una fila: ancho mínimo del 90% y separación compacta entre tarjetas. */
    grid-template-columns: repeat(auto-fit, minmax(171px, 1fr));
    gap: 4px;
    margin: 16px 0 0;
}

.kpi-grid-wide > :is(.kpi-card) {
    container-name: kpi-card-wide;
    container-type: inline-size;
}

.kpi-card {
    display: flex;
    position: relative;
    min-width: 0;
    min-height: 96px;
    overflow: hidden;
    padding: 15px 16px;
    box-shadow: none;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.kpi-card span {
    display: block;
    color: var(--muted);
    font-size: 16px;
    font-weight: 600;
}

.kpi-card strong {
    display: block;
    margin-top: 12px;
    font-size: 30px;
    font-weight: 600;
    line-height: 1.08;
    max-width: 100%;
    overflow-wrap: anywhere;
    white-space: normal;
    font-variant-numeric: tabular-nums;
}

@media (min-width: 821px) {
    @container kpi-card-wide (max-width: 180px) {
        .kpi-grid-wide .kpi-card span {
            font-size: 14px;
        }

        .kpi-grid-wide .kpi-card strong {
            font-size: 27px;
        }
    }

    @container kpi-card-wide (max-width: 171px) {
        .kpi-grid-wide .kpi-card span {
            font-size: 12.8px;
        }

        .kpi-grid-wide .kpi-card strong {
            font-size: 24px;
        }
    }
}

a.kpi-card {
    color: inherit;
    text-decoration: none;
}

.kpi-card.is-clickable {
    cursor: pointer;
}

.kpi-card.is-clickable:hover,
.kpi-card.is-clickable:focus-visible {
    border-color: var(--brand-neutral);
    box-shadow: 0 0 0 2px rgba(0, 108, 122, 0.14);
    outline: 0;
}

.kpi-card-map-button {
    display: block;
    width: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    text-align: center;
    cursor: pointer;
}

.kpi-card-map-button strong {
    white-space: normal;
}

.kpi-card-map-button:hover strong,
.kpi-card-map-button:focus-visible strong {
    color: var(--accent-blue);
}

.tone-positive strong { color: var(--positive); }
.tone-danger strong { color: var(--danger); }
.tone-blue strong { color: var(--accent-blue); }
.tone-partial strong { color: #7b3fc6; }
.tone-strong strong { color: var(--accent-violet); }

.service-status {
    display: inline-flex;
    align-items: center;
