    --brand-neutral: #ffffff;
    --brand-primary-soft: rgba(173, 63, 227, 0.24);
    --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.2), 0 12px 28px rgba(0, 0, 0, 0.24);
