.variable-grid-heading-actions {
    justify-content: flex-end;
}

.variable-form-section h3,
.variable-grid-heading h3 {
    grid-column: 1 / -1;
    margin: 0;
    color: var(--ink);
    font-size: 15px;
    line-height: 1.25;
}

.location-country-picker {
    position: relative;
    display: block;
    min-width: 0;
    text-transform: none;
}

.entry-form .location-country-button {
    display: grid;
    grid-template-columns: 24px minmax(0, 1fr);
    align-items: center;
    gap: 10px;
    width: 100%;
    height: 42px;
    min-width: 0;
    padding: 0 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
    color: var(--ink);
    font: inherit;
    font-weight: 600;
    line-height: 1;
    text-align: left;
    cursor: pointer;
}

.location-flag {
    width: 24px;
    height: 16px;
    border: 1px solid rgba(0, 0, 0, 0.12);
    border-radius: 3px;
    background: #fff;
    object-fit: cover;
}

.location-country-button span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.location-country-menu {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    z-index: 45;
    display: none;
    width: min(260px, calc(100vw - 48px));
    max-height: 300px;
    overflow: auto;
    padding: 6px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #fff;
    box-shadow: var(--shadow-lift);
}

.location-country-picker.is-open .location-country-menu {
    display: grid;
    gap: 2px;
}

.entry-form .location-country-option {
    display: grid;
    grid-template-columns: 24px minmax(0, 1fr);
    align-items: center;
    gap: 10px;
    width: 100%;
    min-height: 34px;
    min-width: 0;
    padding: 7px 8px;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: var(--ink);
    font: inherit;
    font-weight: 600;
    line-height: 1.2;
    text-align: left;
    cursor: pointer;
}

.entry-form .location-country-option:hover,
.entry-form .location-country-option.is-selected {
    background: var(--surface-strong);
}

.location-country-option img {
    width: 24px;
    height: 16px;
    border: 1px solid rgba(0, 0, 0, 0.12);
    border-radius: 3px;
    background: #fff;
    object-fit: cover;
}

.location-country-option span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.variable-grid-heading {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.field-label-row {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.field-label-row > span:first-child {
    min-width: 0;
}

/* El mapa queda como un glifo de líneas: verde únicamente cuando las
   coordenadas están confirmadas y rojo para cualquier estado pendiente. */
.entry-form .address-verification-status {
    --address-status-color: var(--danger);
    display: inline-grid;
    place-items: center;
    flex: 0 0 22px;
    width: 22px;
    min-width: 22px;
    height: 22px;
    min-height: 22px;
    padding: 0;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--address-status-color);
    cursor: pointer;
    box-shadow: none;
}

.entry-form .address-verification-status svg {
    width: 21px;
    height: 21px;
}

.entry-form .address-verification-status:is(
    .is-unknown,
    .is-checking,
    .is-found,
    .is-suggestion,
    .is-not-found
) {
    --address-status-color: var(--danger);
}

.entry-form .address-verification-status.is-located {
    --address-status-color: #22c55e;
}

.entry-form .address-verification-status:is(:hover, :focus-visible) {
    border: 0;
    background: transparent;
    color: var(--address-status-color);
    outline: 2px solid var(--address-status-color);
    outline-offset: 2px;
    filter: none;
}

.entry-form .address-verification-status:disabled {
    border: 0;
    background: transparent;
    color: var(--address-status-color);
    cursor: default;
    filter: none;
}

.entry-form .location-address-suggestion {
    position: relative;
    display: inline-grid;
    place-items: center;
    align-self: center;
    flex: 0 0 22px;
    width: 22px;
    min-width: 22px;
    height: 22px;
    min-height: 22px;
}

.entry-form .location-address-suggestion[hidden],
.entry-form .location-address-suggestion-popover[hidden] {
    display: none;
}

.entry-form .location-address-suggestion-trigger {
    display: inline-grid;
    place-items: center;
    width: 18px;
    min-width: 18px;
    max-width: 18px;
    height: 18px;
    min-height: 18px;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: #f59e0b;
    color: #000000;
    font-size: 12px;
    font-weight: 900;
    line-height: 1;
    text-transform: none;
    cursor: pointer;
    box-shadow: none;
    transform: none;
}

.entry-form .location-address-suggestion-trigger:is(:hover, :focus-visible) {
    border: 0;
    background: color-mix(in srgb, #f59e0b 82%, #000000);
    color: #000000;
    outline: 2px solid #f59e0b;
    outline-offset: 2px;
    filter: none;
}

.location-address-suggestion-popover {
    position: absolute;
    z-index: 30;
    top: calc(100% + 7px);
    right: 0;
    display: grid;
    gap: 9px;
    width: max-content;
    max-width: min(330px, calc(100vw - 64px));
    padding: 8px 10px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.35;
    text-align: left;
    white-space: normal;
    box-shadow: 0 12px 30px rgba(16, 24, 33, 0.18);
}

.entry-form .location-address-suggestion-correct {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-width: 0;
    min-height: 32px;
    padding: 7px 10px;
    border: 0;
    border-radius: 6px;
    background: var(--brand-primary);
    color: #ffffff;
    font: inherit;
    font-weight: 800;
    line-height: 1.2;
    text-transform: none;
    cursor: pointer;
    box-shadow: none;
}

.entry-form .location-address-suggestion-correct:is(:hover, :focus-visible) {
    border: 0;
    background: color-mix(in srgb, var(--brand-primary) 82%, #000000);
    color: #ffffff;
    outline: 2px solid var(--brand-primary);
    outline-offset: 2px;
    filter: none;
}

.location-address-control {
    position: relative;
