.employee-section-grid input[readonly][role="button"]:hover:not(:disabled) {
    border-color: rgba(109, 40, 217, 0.42);
}

.employee-section-grid input[readonly][role="button"]:focus-visible {
    border-color: var(--brand-primary);
    outline: 3px solid rgba(109, 40, 217, 0.18);
}

.employee-section-grid input[readonly][role="button"]:disabled {
    border-color: #d5dfe2;
    background: #edf2f3;
    color: #000000;
    opacity: 1;
}

.employee-schedule-label {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 7px;
}

.employee-shift-chip {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: fit-content;
    min-height: 22px;
    padding: 3px 8px;
    border: 1px solid #8fa9b4;
    border-radius: 999px;
    background: #edf4f6;
    color: #000000;
    font-size: 11px;
    font-weight: 800;
    line-height: 1.2;
    text-transform: uppercase;
}

.employee-shift-chip.is-rotated {
    border-color: #83c7ac;
    background: #e8f7ee;
    color: #146c35;
}

.employee-schedule-preview {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 8px;
}

.employee-schedule-preview[hidden] {
    display: none;
}

.employee-schedule-preview span {
    padding: 5px 8px;
    border-radius: 999px;
    background: var(--brand-primary-soft);
    color: var(--brand-primary);
    font-size: 12px;
    font-weight: 800;
    text-transform: none;
}

.employee-rotation-box {
    display: grid;
    min-width: 0;
    gap: 0;
    padding: 0;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #ffffff;
}

.employee-rotation-box label {
    margin: 0;
}

.employee-rotation-intro {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-width: 0;
    padding: 10px 12px;
    background: linear-gradient(180deg, #fbfdfd 0%, #f4f9fa 100%);
}

.employee-rotation-box:has(.employee-rotation-settings:not([hidden])) .employee-rotation-intro {
    border-bottom: 1px solid var(--line);
}

.entry-form .employee-rotation-intro .employee-toggle-line {
    display: flex;
    align-items: center;
    align-self: auto;
    min-width: 0;
    min-height: 32px;
    gap: 9px;
    padding: 0;
    cursor: pointer;
}

.entry-form .employee-rotation-intro .employee-toggle-line input[type="checkbox"][role="switch"] {
    appearance: none;
    width: 38px;
    min-width: 38px;
    max-width: 38px;
    height: 22px;
    min-height: 22px;
    max-height: 22px;
    margin: 0;
    padding: 0;
    border: 1px solid #9bb0b8;
    border-radius: 999px;
    background: radial-gradient(circle at 8px 50%, #ffffff 0 6px, transparent 6.5px), #dfe8eb;
    box-shadow: inset 0 0 0 1px rgba(49, 75, 86, 0.04);
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}

.entry-form .employee-rotation-intro .employee-toggle-line input[type="checkbox"][role="switch"]:checked {
    border-color: var(--brand-primary);
    background: radial-gradient(circle at calc(100% - 8px) 50%, #ffffff 0 6px, transparent 6.5px), var(--brand-primary);
}

.entry-form .employee-rotation-intro .employee-toggle-line input[type="checkbox"][role="switch"]:focus-visible {
    border-color: var(--brand-primary);
    outline: 3px solid rgba(109, 40, 217, 0.2);
    outline-offset: 2px;
}

.entry-form .employee-rotation-intro .employee-toggle-line input[type="checkbox"][role="switch"]:disabled {
    opacity: 0.58;
}

.employee-rotation-intro-copy {
    display: grid;
    min-width: 0;
    gap: 2px;
    color: var(--ink);
    line-height: 1.25;
    text-transform: none;
}

.employee-rotation-intro-copy strong {
    font-size: 13px;
    font-weight: 800;
}

.employee-rotation-intro-copy small {
    color: var(--muted);
    font-size: 11.5px;
    font-weight: 650;
    line-height: 1.35;
}

.employee-rotation-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 24px;
    flex: 0 0 auto;
    padding: 3px 9px;
    border: 1px solid #c3d0d5;
    border-radius: 999px;
    background: #edf2f4;
    color: #000000;
    font-size: 10.5px;
    font-weight: 800;
    letter-spacing: 0.02em;
    line-height: 1;
    text-transform: uppercase;
}

.employee-rotation-status.is-active {
    border-color: #72bea0;
    background: #e2f5eb;
    color: #146c35;
}

.employee-rotation-settings {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
    gap: 12px;
    min-width: 0;
    padding: 12px;
    background: #f7fafb;
}

.employee-rotation-settings[hidden],
.employee-rotation-source-panel[hidden] {
    display: none !important;
}

.employee-rotation-step {
    display: grid;
    align-content: start;
    gap: 11px;
    min-width: 0;
    padding: 12px;
    border: 1px solid #d7e3e7;
    border-radius: 8px;
    background: #ffffff;
}

.employee-rotation-step-heading {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    min-width: 0;
}

.employee-rotation-step-heading > span:last-child {
    display: grid;
    min-width: 0;
    gap: 2px;
}

.employee-rotation-step-heading strong {
    color: var(--ink);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.25;
}

.employee-rotation-step-heading small {
    color: var(--muted);
    font-size: 11.5px;
    font-weight: 600;
    line-height: 1.4;
}

.employee-rotation-step-number {
    display: inline-grid;
    place-items: center;
    width: 24px;
    height: 24px;
    flex: 0 0 24px;
    border-radius: 999px;
    background: var(--brand-primary);
    color: #ffffff;
    font-size: 11px;
    font-weight: 850;
    line-height: 1;
}

.employee-rotation-rule-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
    gap: 10px;
    min-width: 0;
}

.employee-rotation-duration-field {
    display: grid;
    align-content: start;
    gap: 7px;
    min-width: 0;
}

.employee-rotation-presets {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    min-width: 0;
}

.entry-form .employee-rotation-presets button {
    width: auto;
    min-width: 0;
    height: 30px;
    min-height: 30px;
    padding: 0 10px;
    border: 1px solid #c7d6db;
    border-radius: 999px;
    background: #ffffff;
    color: #000000;
    box-shadow: none;
    filter: none;
    font-size: 11px;
    font-weight: 750;
    line-height: 1;
    white-space: nowrap;
}

.entry-form .employee-rotation-presets button:hover:not(:disabled) {
    border-color: rgba(109, 40, 217, 0.42);
    background: #f1f9fa;
    color: var(--brand-primary);
    filter: none;
}

.entry-form .employee-rotation-presets button:focus-visible {
    border-color: var(--brand-primary);
    outline: 3px solid rgba(109, 40, 217, 0.18);
    outline-offset: 1px;
}

.entry-form .employee-rotation-presets button[aria-pressed="true"] {
    border-color: var(--brand-primary);
    background: var(--brand-primary-soft);
    color: var(--brand-primary);
    box-shadow: inset 0 0 0 1px rgba(109, 40, 217, 0.08);
}

.entry-form .employee-rotation-presets button:disabled {
    border-color: #d5dfe2;
    background: #edf2f3;
    color: #000000;
    opacity: 1;
    box-shadow: none;
}

.employee-rotation-field-error {
    display: block;
    color: var(--danger);
    font-size: 11.5px;
    font-weight: 750;
    line-height: 1.35;
    text-transform: none;
}

.employee-rotation-field-error[hidden] {
    display: none !important;
}

.entry-form .employee-rotation-duration-field input[aria-invalid="true"] {
    border-color: var(--danger);
    box-shadow: 0 0 0 3px rgba(197, 43, 77, 0.12);
    outline: 0;
}

.employee-rotation-source-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    min-width: 0;
}

.employee-rotation-source-options .employee-rotation-source-option {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: 8px;
    min-width: 0;
    min-height: 58px;
    padding: 8px 9px;
    border: 1px solid #cfdde1;
    border-radius: 8px;
    background: #fbfdfd;
    color: var(--ink);
    font-size: 12px;
    font-weight: 650;
    line-height: 1.25;
    text-transform: none;
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}

.employee-rotation-source-option > input[type="radio"] {
    width: 16px;
    min-width: 16px;
    max-width: 16px;
    height: 16px;
    min-height: 16px;
    max-height: 16px;
    margin: 0;
    padding: 0;
    accent-color: var(--brand-primary);
}

.employee-rotation-source-option > span {
    display: grid;
    min-width: 0;
    gap: 2px;
}

.employee-rotation-source-option strong {
    color: var(--ink);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.25;
}

.employee-rotation-source-option small {
    color: var(--muted);
    font-size: 11px;
    font-weight: 600;
    line-height: 1.35;
}

.employee-rotation-source-option:hover:not(:has(input:disabled)) {
    border-color: rgba(109, 40, 217, 0.38);
    background: #f3fafb;
}

.employee-rotation-source-option:focus-within {
    border-color: var(--brand-primary);
    outline: 3px solid rgba(109, 40, 217, 0.18);
    outline-offset: 1px;
}

.employee-rotation-source-option:is(.is-selected, :has(input:checked)) {
    border-color: var(--brand-primary);
    background: #eef9fa;
    box-shadow: none;
}

.employee-rotation-source-option:has(input:disabled) {
    border-color: #d7e0e3;
    background: #f0f4f5;
    color: #000000;
    opacity: 1;
    box-shadow: none;
}

.employee-rotation-source-option:has(input:disabled) :is(strong, small) {
    color: inherit;
}

.employee-rotation-source-panel {
    display: grid;
    min-width: 0;
    padding: 10px;
    border: 1px solid #d7e3e7;
    border-radius: 8px;
    background: #f7fafb;
}

.employee-rotation-source-panel > label {
    min-width: 0;
}

.employee-rotation-guidance {
    grid-column: 1 / -1;
    margin: 0;
    padding: 9px 11px;
    border: 1px solid #d5e1e5;
    border-radius: 7px;
    background: #f2f6f7;
    color: var(--muted);
    font-size: 12px;
    font-weight: 650;
    line-height: 1.45;
    text-transform: none;
}

.employee-rotation-reciprocity {
    margin: 9px 0 0;
    padding: 8px 10px;
    border: 1px solid #9cc3d5;
    border-radius: 7px;
    background: #eaf4f9;
    color: #1f4a5c;
    font-size: 12px;
    font-weight: 650;
    line-height: 1.45;
    text-transform: none;
}

.employee-rotation-reciprocity[hidden] {
    display: none !important;
}

.employee-rotation-preview {
    --employee-rotation-base-border: #9eb4bd;
    --employee-rotation-base-surface: #f4f8fa;
    --employee-rotation-rotated-border: #83c7ac;
    --employee-rotation-rotated-surface: #e8f7ee;
    display: block;
    min-width: 0;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
}

.employee-rotation-preview[hidden] {
    display: none !important;
}

.employee-rotation-calendar {
    display: block;
    min-width: 0;
    padding: 0;
    overflow: hidden;
}

.employee-rotation-calendar[open] > .employee-rotation-calendar-summary {
    margin-bottom: 0;
    border-bottom: 1px solid var(--line);
}

.employee-rotation-calendar-summary {
    align-items: center;
    min-height: 52px;
    padding: 10px 12px;
    border: 0;
    border-radius: 0;
    background: #f5fafb;
}

.employee-rotation-calendar-summary .collapsible-heading {
    font-size: 16px;
}

.employee-rotation-calendar-summary strong {
    display: none;
}

.employee-rotation-calendar-summary small {
    display: block;
    margin-top: 2px;
    color: var(--muted);
    font-size: 12px;
    font-weight: 700;
    text-transform: none;
}

.employee-rotation-calendar-body {
    min-width: 0;
    overflow: visible;
    padding: 12px;
}

.employee-rotation-overview {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    min-width: 0;
    margin-bottom: 10px;
}

.employee-rotation-overview:empty {
    display: none;
}

.employee-rotation-phase {
    display: grid;
    align-content: start;
    gap: 4px;
    min-width: 0;
    padding: 10px 11px;
    border: 1px solid var(--employee-rotation-base-border);
    border-left: 4px solid #6d8d99;
    border-radius: 8px;
    background: var(--employee-rotation-base-surface);
}

.employee-rotation-phase.is-rotated {
    border-color: var(--employee-rotation-rotated-border);
    border-left-color: #2f9a68;
    background: var(--employee-rotation-rotated-surface);
}

.employee-rotation-phase.is-incomplete {
    border-color: #d6b45d;
    border-left-color: #c18a12;
    background: #fff9e8;
}

.employee-rotation-phase-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
    margin-bottom: 2px;
}

.employee-rotation-phase-duration {
    display: inline-flex;
    align-items: center;
    min-height: 22px;
    flex: 0 0 auto;
    padding: 2px 7px;
    border: 1px solid rgba(82, 102, 110, 0.2);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.7);
    color: #000000;
    font-size: 10.5px;
    font-weight: 800;
    line-height: 1;
}

.employee-rotation-phase > strong {
    min-width: 0;
    color: var(--ink);
    font-size: 13px;
    line-height: 1.3;
    overflow-wrap: anywhere;
}

.employee-rotation-phase > small {
    min-width: 0;
    color: var(--muted);
    font-size: 11.5px;
    font-weight: 650;
    line-height: 1.35;
    overflow-wrap: anywhere;
}

.employee-rotation-phase > p {
    min-width: 0;
    margin: 2px 0 0;
    color: #000000;
    font-size: 11.5px;
    font-weight: 750;
    line-height: 1.35;
    overflow-wrap: anywhere;
}

.employee-rotation-phase.is-incomplete > p {
    color: #715816;
}

.employee-rotation-phase.is-incomplete .employee-shift-chip,
.employee-rotation-preview-cell.is-incomplete .employee-shift-chip {
    border-color: #c59a31;
    background: #fff2c9;
    color: #73510b;
}

.employee-rotation-preview-notice {
    margin: 0 0 10px;
    padding: 8px 10px;
    border: 1px solid #dcc27c;
    border-radius: 7px;
    background: #fff8e5;
    color: #66501a;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.4;
}

.employee-rotation-preview-notice[hidden] {
    display: none !important;
}

.employee-rotation-day-detail {
    min-width: 0;
    overflow: hidden;
    border: 1px solid #d5e1e5;
    border-radius: 8px;
    background: #ffffff;
}

.employee-rotation-day-detail > summary {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto 18px;
    align-items: center;
    gap: 9px;
    min-height: 42px;
    padding: 8px 10px;
    color: var(--ink);
    cursor: pointer;
    list-style: none;
}

.employee-rotation-day-detail > summary::-webkit-details-marker {
    display: none;
}

.employee-rotation-day-detail > summary::after {
    content: "";
    justify-self: center;
    width: 7px;
    height: 7px;
    margin-top: -3px;
    border-right: 2px solid var(--brand-primary);
    border-bottom: 2px solid var(--brand-primary);
    transform: rotate(45deg);
    transition: transform 0.15s ease, margin 0.15s ease;
}

.employee-rotation-day-detail[open] > summary {
    border-bottom: 1px solid #d5e1e5;
    background: #f5fafb;
}

.employee-rotation-day-detail[open] > summary::after {
    margin-top: 3px;
    transform: rotate(225deg);
}

.employee-rotation-day-detail > summary:focus-visible {
    outline: 3px solid rgba(109, 40, 217, 0.18);
    outline-offset: -3px;
}

.employee-rotation-day-detail > summary span {
    color: var(--ink);
    font-size: 13px;
    font-weight: 800;
}

.employee-rotation-day-detail > summary small {
    color: var(--muted);
    font-size: 11px;
    font-weight: 700;
    text-align: right;
}

.employee-rotation-day-detail-body {
    min-width: 0;
    overflow: visible;
    padding: 10px;
}

.employee-rotation-preview-grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 7px;
    min-width: 0;
    overflow: visible;
    background: transparent;
}

.employee-rotation-preview-cell {
    display: grid;
    align-content: start;
    min-width: 0;
    gap: 5px;
    min-height: 100px;
    padding: 8px;
    border: 1px solid var(--employee-rotation-base-border);
    border-radius: 7px;
    background: var(--employee-rotation-base-surface);
}

.employee-rotation-preview-cell.is-base {
    border-color: var(--employee-rotation-base-border);
    background: var(--employee-rotation-base-surface);
}

.employee-rotation-preview-cell.is-rotated {
    border-color: var(--employee-rotation-rotated-border);
    background: var(--employee-rotation-rotated-surface);
}

.employee-rotation-preview-cell.is-change {
    border-left: 4px solid #d8a526;
}

.employee-rotation-preview-cell.is-sample-jump {
    border-top: 2px dashed #d8a526;
}

.employee-rotation-preview-cell.is-incomplete {
    border-color: #d6b45d;
    background: #fff9e8;
}

.employee-rotation-preview-cell strong,
.employee-rotation-preview-cell small {
    min-width: 0;
    overflow-wrap: anywhere;
    white-space: normal;
}

.employee-rotation-preview-cell strong {
    color: var(--ink);
    font-size: 13px;
}

.employee-rotation-preview-cell small {
    color: var(--muted);
    font-size: 11px;
    font-weight: 700;
}

.employee-rotation-preview-cell.is-rotated small {
    color: #146c35;
}

.employee-rotation-preview-cell.is-incomplete small {
    color: #715816;
}

.employee-contract-section {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    min-height: 0;
}

.employee-contract-section:not([open]) {
    grid-template-rows: auto;
}

.employee-contract-body {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 10px;
    min-height: 0;
}

.employee-contract-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 8px;
    margin-right: auto;
}

.employee-contract-actions .button {
    width: auto;
    min-width: 132px;
}

.employee-contract-preview {
    display: grid;
    min-height: 360px;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
}

.employee-contract-preview[hidden] {
    display: none;
}

.employee-contract-preview iframe {
    width: 100%;
    height: 100%;
    min-height: 0;
    border: 0;
    background: #fff;
}

.employee-contract-preview .empty-state {
    display: grid;
    place-items: center;
}
.entry-form .variable-row .mini-button,
.variable-collapsible-section .variable-row .mini-button {
    min-width: 0;
    width: 88px;
    height: 42px;
    padding: 0 10px;
}

.variable-collapsible-section .variable-row .mini-button.wide {
    width: 188px;
}

.variable-row-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.variable-collapsible-section input,
.variable-collapsible-section select,
.variable-collapsible-section textarea {
    width: 100%;
    min-width: 0;
    height: 42px;
    padding: 0 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
    color: var(--ink);
    font: inherit;
    font-weight: 600;
}

.variable-collapsible-section select[multiple] {
    height: 86px;
    padding: 8px 10px;
}

/* El listado de estacionamientos es un desplegable más del formulario: la caja
   la pone .panel y acá sólo queda la grilla interna del cuerpo. */
.parking-config-list {
    grid-column: 1 / -1;
    margin-top: 2px;
}

.parking-config-list-body {
    display: grid;
    gap: 8px;
}

.parking-config-table-wrap {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
}

.parking-config-table {
    width: 100%;
    min-width: 900px;
    border-collapse: collapse;
    color: var(--ink);
}

.parking-config-table :is(th, td) {
    padding: 11px 12px;
    border-bottom: 1px solid var(--line);
    text-align: left;
    vertical-align: middle;
    overflow-wrap: anywhere;
}

.parking-config-table thead th {
    background: var(--surface);
    color: var(--ink);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.02em;
    text-transform: uppercase;
    white-space: nowrap;
}

.parking-config-table tbody tr:last-child :is(th, td) {
    border-bottom: 0;
}

.parking-config-table tbody th {
    color: var(--ink);
    font-size: 14px;
    font-weight: 800;
}

.parking-config-table tbody td:nth-child(2),
