}

.entry-form[data-parking-registration-create-form]:has(
    [data-registration-contract-fields]:not([hidden])
) .parking-registration-submit-actions > .parking-registration-contract-increase-fields {
    order: 4;
}

.entry-form[data-parking-registration-create-form]:has(
    [data-registration-contract-fields]:not([hidden])
) .parking-registration-submit-buttons {
    grid-column: 1 / -1;
    order: 5;
    margin-inline-start: 0;
}

.entry-form .parking-registration-submit-actions > button,
