html[data-theme="dark"] .app-shell .entry-form .parking-registration-submit-actions > .parking-registration-charge-submit:not(:disabled),
html[data-theme="dark"] .app-shell .entry-form .parking-registration-submit-buttons > .parking-registration-charge-submit:not(:disabled) {
    border-color: #18a47e;
    background: #0d6f59;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .parking-registration-submit-actions > .parking-registration-charge-submit:disabled[data-quote-pending-enabled],
html[data-theme="dark"] .app-shell .entry-form .parking-registration-submit-buttons > .parking-registration-charge-submit:disabled[data-quote-pending-enabled] {
