    color: var(--danger);
    background: rgba(194, 61, 66, 0.09);
}

.parking-maintenance-status.is-aviso {
    border-color: rgba(183, 121, 31, 0.3);
    color: #8a570f;
    background: rgba(183, 121, 31, 0.1);
}

.parking-maintenance-record-body {
