}

.parking-maintenance-record-panel .record-modal-header p {
    margin: 4px 0 0;
    color: var(--muted);
    font-size: 14px;
}

.parking-maintenance-record-panel .parking-maintenance-record-body {
    padding: 0;
}

.parking-maintenance-record-panel > .record-modal-actions {
