}

.parking-maintenance-renewal-amount.is-estimated {
    color: var(--brand-primary);
}

.parking-maintenance-renewal-amount.is-paid {
    color: var(--positive);
}

.parking-maintenance-renewal-amount.is-notice {
    color: var(--muted);
}

.parking-maintenance-renewal-status {
    display: inline-flex;
    min-height: 28px;
