    border-radius: 999px;
    color: var(--muted);
    background: var(--surface);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.2;
    text-align: center;
}

.parking-maintenance-renewal-status.is-registrada {
    border-color: rgba(8, 127, 111, 0.28);
    color: var(--positive);
    background: rgba(8, 127, 111, 0.09);
}

.parking-maintenance-renewal-status:is(.is-pendiente, .is-hoy, .is-aviso) {
    border-color: rgba(183, 121, 31, 0.3);
    color: #8a570f;
    background: rgba(183, 121, 31, 0.1);
}

.parking-maintenance-renewal-status.is-vencida {
    border-color: rgba(194, 61, 66, 0.3);
    color: var(--danger);
    background: rgba(194, 61, 66, 0.09);
}

.parking-maintenance-renewal-status.is-espera {
    opacity: 1;
}

.parking-maintenance-renewal-button {
