    border-color: var(--brand-primary) !important;
    background: var(--brand-primary) !important;
    color: #fff !important;
    white-space: nowrap;
}

.parking-maintenance-renewal-button:hover,
.parking-maintenance-renewal-button:focus-visible {
    border-color: #5B21B6 !important;
    background: #5B21B6 !important;
    color: #fff !important;
}

.parking-maintenance-renewal-action-state {
    color: var(--muted);
    font-size: 12px;
    font-weight: 700;
}

.record-modal-panel.parking-maintenance-renew-panel {
    width: min(900px, 100%);
}

.parking-maintenance-renew-manual-fields {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    align-items: end;
    gap: 12px;
}

.parking-maintenance-renew-manual-fields[hidden],
.parking-maintenance-renew-catalog-fields[hidden],
.parking-maintenance-renew-catalog-fields > [hidden],
.parking-maintenance-renew-schedule[hidden],
.parking-maintenance-renew-estimate[hidden] {
    display: none;
}

.parking-maintenance-renew-catalog-fields {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: end;
    gap: 12px;
}

.parking-maintenance-renew-estimate {
    flex: 0 0 auto;
    color: var(--muted);
    font-size: 11px;
    font-weight: 600;
    text-transform: none;
    white-space: nowrap;
}

.parking-maintenance-renew-amount-heading {
    display: flex;
    min-width: 0;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
}

.parking-maintenance-renew-heading,
.parking-maintenance-payment-history-heading {
    display: grid;
    align-self: center;
    gap: 3px;
}

.parking-maintenance-renew-heading,
.parking-maintenance-renew-actions {
    grid-column: 1 / -1;
}

.parking-maintenance-renew-primary-field,
.parking-maintenance-renew-payment-field {
    grid-column: span 2;
}

.parking-maintenance-renew-primary-field input[readonly] {
    background: var(--surface);
    cursor: default;
}

.parking-maintenance-renew-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 10px;
}

.parking-maintenance-payment-history {
    display: grid;
    gap: 10px;
    padding: 14px;
    border: 1px solid var(--line);
    border-radius: 10px;
}

.parking-maintenance-payment-history-table {
    display: grid;
    grid-template-columns: minmax(140px, 0.5fr) minmax(160px, 1fr);
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 8px;
}

.parking-maintenance-payment-history-table > span,
.parking-maintenance-payment-history-table > strong {
    min-width: 0;
    padding: 8px 10px;
    border-bottom: 1px solid var(--line);
}

.parking-maintenance-payment-history-table > :nth-last-child(-n + 2) {
    border-bottom: 0;
}

.parking-maintenance-payment-history-table > :nth-child(even) {
    border-left: 1px solid var(--line);
}

.parking-maintenance-payment-history-header {
    color: var(--muted);
    background: var(--surface-soft);
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
}

@media (max-width: 1100px) {
    .parking-maintenance-keys-summary,
    .parking-maintenance-keys-form {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .parking-maintenance-form,
    .parking-maintenance-edit-form {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .parking-maintenance-renew-form {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .parking-maintenance-renew-manual-fields {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .parking-maintenance-record-detail-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .parking-maintenance-renew-heading,
    .parking-maintenance-renew-actions {
        grid-column: 1 / -1;
    }

    .parking-maintenance-renew-primary-field,
    .parking-maintenance-renew-payment-field {
        grid-column: auto;
    }

    .parking-maintenance-notice-field {
        grid-column: 1 / -1;
    }

    .parking-maintenance-form-actions,
    .parking-maintenance-edit-actions {
        grid-column: 1 / -1;
    }

    .parking-maintenance-unit-row {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .parking-maintenance-unit-remove {
        justify-self: end;
    }
}

@media (max-width: 720px) {
    .parking-maintenance-keys-summary,
    .parking-maintenance-keys-form {
        grid-template-columns: 1fr;
    }

    .parking-maintenance-keys-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .parking-maintenance-keys-actions button {
        width: 100%;
    }

    .parking-maintenance-form,
    .parking-maintenance-edit-form {
        grid-template-columns: 1fr;
    }

    .parking-maintenance-form > .parking-maintenance-item-field,
    .parking-maintenance-form > .parking-maintenance-description-field {
        grid-column: auto;
    }

    .parking-maintenance-units-heading {
        align-items: flex-start;
    }

    .parking-maintenance-unit-row {
        grid-template-columns: 1fr;
    }

    .parking-maintenance-unit-remove {
        justify-self: end;
    }

    .parking-maintenance-notice-field {
        grid-column: auto;
    }

    .parking-maintenance-renew-form {
        grid-template-columns: 1fr;
    }

    .parking-maintenance-renewal-filter-form,
    .parking-maintenance-renew-manual-fields,
    .parking-maintenance-renew-catalog-fields,
    .parking-maintenance-record-detail-grid {
        grid-template-columns: 1fr;
    }

    .parking-maintenance-record-detail-grid .parking-maintenance-record-detail-wide {
        grid-column: auto;
    }

    .parking-maintenance-renew-actions button {
        width: 100%;
    }

    .parking-maintenance-renew-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .parking-maintenance-renew-schedule {
        grid-column: auto;
        grid-template-columns: 1fr;
    }

    .parking-maintenance-payment-history-table {
        grid-template-columns: minmax(105px, 0.65fr) minmax(0, 1fr);
    }

    .parking-maintenance-table {
        overflow: visible;
        border: 0;
        border-radius: 0;
        background: transparent;
    }

    .parking-maintenance-table-head {
        display: none;
    }

    .parking-maintenance-list {
        gap: 10px;
        min-width: 0;
    }

    .parking-maintenance-record,
    .parking-maintenance-record:first-child {
        border: 1px solid var(--line);
        border-radius: 10px;
    }

    .parking-maintenance-record-summary {
        grid-template-columns: 1fr;
        gap: 8px;
        min-width: 0;
        padding: 12px;
    }

    .parking-maintenance-record-cell,
    .parking-maintenance-record-status {
        display: grid;
        grid-template-columns: minmax(120px, 0.45fr) minmax(0, 1fr);
        gap: 10px;
        min-height: 0;
    }

    .parking-maintenance-record-cell::before,
    .parking-maintenance-record-status::before {
        align-self: center;
        color: var(--muted);
        content: attr(data-label);
        font-size: 11px;
        font-weight: 800;
        text-transform: uppercase;
    }

    .parking-maintenance-record-stacked::before {
        grid-row: 1 / span 3;
    }

    .parking-maintenance-record-stacked > strong,
    .parking-maintenance-record-stacked > small {
        grid-column: 2;
    }

    .parking-maintenance-form-actions,
    .parking-maintenance-edit-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .parking-maintenance-form-actions button,
    .parking-maintenance-edit-actions button {
        width: 100%;
    }
}

html[data-theme="dark"] .app-shell .parking-maintenance-status:is(.is-proximo, .is-vence-hoy, .is-aviso) {
