.gastos-distribution-filter-card span {
    overflow: hidden;
    font-size: 13px;
    font-weight: 750;
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.gastos-distribution-filter-card.is-selected {
