.logo-file-upload {
    min-width: 0;
    min-height: 42px;
}

.logo-file-upload > [data-file-label] {
    min-height: 42px;
    gap: 9px;
    border-radius: 10px;
    box-shadow: 0 8px 18px rgba(109, 40, 217, 0.2);
    transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
}

.logo-file-upload > [data-file-label]::before {
    content: "↑";
    display: inline-grid;
    width: 24px;
    height: 24px;
    place-items: center;
    border: 1px solid rgba(255, 255, 255, 0.45);
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.14);
    color: #fff;
    font-size: 16px;
    font-weight: 900;
    line-height: 1;
}

.logo-file-upload:hover > [data-file-label] {
    transform: translateY(-1px);
    box-shadow: 0 10px 22px rgba(109, 40, 217, 0.28);
}

.logo-file-upload:active > [data-file-label] {
    transform: translateY(0);
}

.logo-upload-control > .logo-file-upload:first-child,
.logo-upload-actions:not(.has-logo) .logo-file-upload,
.logo-upload-actions-simple .logo-file-upload {
    grid-column: 1 / -1;
}

.entry-form .logo-remove-button {
    width: 100%;
    min-width: 0;
    min-height: 42px;
    padding: 0 12px;
    border: 1px solid rgba(194, 61, 66, 0.45);
    border-radius: 10px;
    background: var(--danger);
    color: #ffffff;
    font-weight: 750;
    box-shadow: 0 8px 18px rgba(194, 61, 66, 0.18);
}

.entry-form .logo-remove-button:hover,
.entry-form .logo-remove-button:focus-visible {
    background: var(--danger);
    color: #ffffff;
    filter: brightness(1.06);
    outline: 3px solid rgba(194, 61, 66, 0.2);
    outline-offset: 2px;
}

.logo-download-button {
    display: inline-grid;
    width: 42px;
    min-width: 42px;
    height: 42px;
    min-height: 42px;
    aspect-ratio: 1;
    padding: 0;
    place-items: center;
    border: 1px solid var(--brand-primary);
    border-radius: 50%;
    background: var(--brand-primary);
    color: #ffffff;
    box-shadow: 0 8px 18px rgba(109, 40, 217, 0.2);
    cursor: pointer;
}

.logo-download-button svg {
    width: 21px;
    height: 21px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.logo-download-button:hover,
.logo-download-button:focus-visible {
    color: #ffffff;
    filter: brightness(1.08);
    outline: 3px solid rgba(109, 40, 217, 0.2);
    outline-offset: 2px;
}

.logo-upload-status {
    min-width: 0;
    max-width: 72%;
    overflow: hidden;
    color: var(--muted);
    font-size: 12px;
    font-weight: 650;
    line-height: 1.2;
    text-align: right;
    text-overflow: ellipsis;
    text-transform: none;
    white-space: nowrap;
}

.logo-upload-status.is-selected {
    color: var(--brand-primary);
    font-weight: 750;
}

.logo-upload-status.is-pending-delete {
    color: var(--danger);
    font-weight: 750;
}

.public-image-upload-field {
    min-width: 0;
}

.public-image-upload-control {
    grid-template-columns: minmax(120px, 220px) minmax(0, 1fr);
}

.public-image-upload-preview {
    width: 100%;
    height: auto;
    aspect-ratio: 16 / 10;
    object-fit: cover;
}

.availability-field input[readonly] {
    cursor: pointer;
}

[data-availability-modal] {
    padding: 12px;
}

[data-availability-modal] .variable-dialog-panel {
    width: min(1180px, calc(100vw - 24px));
    max-height: calc(100dvh - 24px);
    padding: 34px 30px 26px;
}

.availability-dialog-form {
    display: grid;
    gap: 12px;
}

.availability-dialog-copy {
    margin: 0;
    color: var(--ink);
    font-size: 14px;
    font-weight: 600;
}

.availability-season-panel {
    display: grid;
    gap: 10px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: var(--surface-soft);
    color: var(--ink);
}

.availability-season-panel[hidden],
.availability-saved-schedules[hidden],
.availability-saved-schedules [hidden] {
    display: none;
}

.availability-season-heading,
.availability-saved-schedules-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    color: var(--ink);
    font-size: 13px;
}

.availability-season-heading {
    justify-content: flex-start;
}

.availability-season-ranges {
    width: min(390px, calc(100vw - 70px));
}

.availability-season-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(110px, 1fr));
    gap: 8px;
}

.availability-season-option {
    position: relative;
    display: inline-flex;
    min-height: 38px;
    align-items: center;
    justify-content: center;
    margin: 0;
    padding: 0 10px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font-size: 12px;
    font-weight: 750;
    cursor: pointer;
    user-select: none;
}

.availability-season-option:hover {
    border-color: var(--brand-primary);
}

.availability-season-option:has(input:checked) {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
}

.availability-season-option.is-unavailable {
    border-color: var(--line);
    background: var(--surface-soft);
    color: var(--ink);
    cursor: default;
}

.availability-season-option:has(input:focus-visible) {
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 25%, transparent);
    outline-offset: 2px;
}

.availability-season-grid[aria-invalid="true"] .availability-season-option:not(.is-unavailable) {
    border-color: var(--danger);
}

.availability-season-option input[type="checkbox"] {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    margin: 0;
    padding: 0;
    opacity: 0;
    cursor: inherit;
}

.availability-saved-schedules {
    display: grid;
    gap: 8px;
    padding-top: 10px;
    border-top: 1px solid var(--line);
}

.availability-saved-schedules-list {
    display: grid;
    gap: 6px;
}

.availability-saved-schedule {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 9px 10px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
}

.availability-saved-schedule.is-editing {
    border-color: var(--brand-primary);
    box-shadow: inset 3px 0 0 var(--brand-primary);
}

.availability-saved-schedule-copy {
    display: grid;
    min-width: 0;
    gap: 2px;
    color: var(--ink);
    font-size: 12px;
}

.availability-saved-schedule-copy > span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.availability-saved-schedule-actions {
    display: inline-flex;
    flex: 0 0 auto;
    gap: 6px;
}

.availability-saved-schedule-actions button {
    min-height: 30px;
    padding: 4px 9px;
    border: 1px solid var(--brand-primary);
    border-radius: 7px;
    background: var(--brand-primary);
    color: #ffffff;
    font-size: 12px;
    font-weight: 700;
}

.availability-saved-schedule-actions .availability-saved-schedule-remove {
    border-color: var(--danger);
    background: var(--danger);
}

.availability-schedule-scroll {
    max-width: 100%;
    padding-bottom: 4px;
    overflow-x: auto;
}

.availability-schedule-grid {
    display: grid;
    grid-template-columns: minmax(116px, 1.1fr) repeat(7, minmax(102px, 1fr));
    align-items: center;
    gap: 8px;
    min-width: 900px;
}

.availability-visit {
    display: contents;
}

.availability-visit[hidden] {
    display: none;
}

.availability-schedule-corner {
    min-height: 38px;
}

.availability-row-title {
    color: var(--ink);
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}

.availability-day-control {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 6px;
}

.availability-day {
    position: relative;
    display: inline-flex;
    flex: 1 1 auto;
    width: 100%;
    min-width: 0;
    min-height: 38px;
    align-items: center;
    justify-content: center;
    padding: 0 10px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
    color: var(--ink);
    font-size: 12px;
    font-weight: 750;
    cursor: pointer;
    user-select: none;
}

.availability-day:hover {
    border-color: var(--brand-primary);
}

.availability-day:has(input:checked) {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
}

.availability-day.is-invalid,
.availability-day.is-invalid:has(input:checked) {
    border-color: var(--danger);
    background: var(--danger);
    color: #ffffff;
}

.availability-day:has(input:focus-visible) {
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 25%, transparent);
    outline-offset: 2px;
}

.availability-day input[type="checkbox"] {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    margin: 0;
    padding: 0;
    opacity: 0;
    cursor: pointer;
}

.availability-day-error-help {
    flex: 0 0 18px;
}

.availability-day-error-help[hidden],
.availability-day-error-indicator[hidden] {
    display: none;
}

.availability-day-error-indicator {
    position: static;
    display: inline-grid;
    width: 18px;
    height: 18px;
    place-items: center;
    margin: 0;
    transform: none;
    border-radius: 50%;
    background: var(--danger);
    color: #ffffff;
    font-size: 12px;
    font-weight: 900;
    line-height: 1;
}

.availability-day-error-popover {
    right: 0;
    left: auto;
}

.availability-day-control:nth-child(-n + 5) .availability-day-error-popover {
    right: auto;
    left: 0;
}

.availability-all-day {
    position: relative;
    display: inline-flex;
    min-height: 38px;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
    color: var(--ink);
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    user-select: none;
}

.availability-all-day:hover,
.availability-all-day:has(input:focus-visible) {
    border-color: var(--brand-primary);
}

.availability-all-day:has(input:checked) {
    border-color: #0c7d89;
    background: #0c6f79;
    color: #ffffff;
}

.availability-all-day input[type="checkbox"] {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    margin: 0;
    padding: 0;
    opacity: 0;
    cursor: pointer;
}

.availability-schedule-grid input[type="time"] {
    width: 100%;
    min-width: 0;
    height: 42px;
    padding: 0 10px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    font-weight: 600;
}

.availability-schedule-grid input[type="time"]:disabled,
.availability-schedule-grid input[type="time"][readonly] {
    background: var(--surface-soft);
    color: var(--ink);
    cursor: default;
    opacity: 1;
}

.availability-schedule-grid input[type="time"][aria-invalid="true"] {
    border-color: var(--danger);
    outline: 2px solid color-mix(in srgb, var(--danger) 22%, transparent);
}

.availability-visit-separator {
    display: flex;
    grid-column: 1 / -1;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 4px;
    padding-top: 10px;
    border-top: 1px solid var(--line);
    color: var(--ink);
}

.availability-add-row {
    display: flex;
    justify-content: flex-start;
}

.availability-add-row[hidden] {
    display: none;
}

.availability-add-button,
.availability-remove-button {
    display: inline-flex;
    width: auto;
    min-height: 34px;
    align-items: center;
    justify-content: center;
    gap: 7px;
    margin: 0;
    padding: 6px 11px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
    color: var(--ink);
    font-size: 12px;
    font-weight: 700;
}

.availability-add-button:hover,
.availability-remove-button:hover {
    border-color: var(--brand-primary);
}

@media (max-width: 520px) {
    [data-availability-modal] .variable-dialog-panel {
        padding: 28px 14px 18px;
    }

    .availability-season-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .availability-saved-schedules-heading,
    .availability-saved-schedule {
        align-items: stretch;
        flex-direction: column;
    }

    .availability-saved-schedule-actions button {
        flex: 1 1 0;
    }
}

.panel-actions,
.row-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

.row-actions {
    min-width: 210px;
}

.inline-form {
    display: inline-flex;
    margin: 0;
}

.mini-button,
.inline-form .mini-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 34px;
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--surface);
    color: var(--text);
    font: inherit;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
}

.mini-button:hover {
    border-color: rgba(109, 40, 217, 0.32);
    color: var(--brand-primary);
}

.mini-button.edit {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #fff;
}

.mini-button.edit:hover {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #fff;
    filter: brightness(1.04);
}

.mini-button.danger {
    border-color: var(--danger);
    background: var(--danger);
    color: #fff;
}

.mini-button.danger:hover {
    border-color: #9f2f34;
    background: #9f2f34;
    color: #fff;
}

.detail-panel {
    display: grid;
    gap: 18px;
}

.mini-kpi-grid {
    display: grid;
    grid-template-columns: repeat(6, minmax(120px, 1fr));
    gap: 10px;
}

.mini-kpi {
    display: grid;
    gap: 6px;
    min-height: 78px;
    padding: 14px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--surface);
}

.mini-kpi span {
    color: var(--muted);
    font-size: 0.78rem;
    font-weight: 600;
    text-transform: uppercase;
}

.mini-kpi strong {
    color: var(--text);
    font-size: 1.05rem;
}

.mini-kpi.tone-positive strong {
    color: #047c72;
}

.mini-kpi.tone-danger strong {
    color: #c83d4b;
}

.mini-kpi.tone-partial strong {
    color: #7b3fc6;
}

.mini-kpi.tone-fragmented strong,
.kpi-card.tone-fragmented strong {
    color: #0b5f9c;
}

.span-2 {
    grid-column: span 2;
}

.bars {
    display: grid;
    gap: 12px;
}

.bar-row {
    display: grid;
    grid-template-columns: minmax(72px, 0.36fr) minmax(140px, 1fr) minmax(150px, auto);
    align-items: center;
    gap: 14px;
    min-height: 42px;
    padding: 8px 10px;
    border: 1px solid rgba(216, 227, 229, 0.75);
    border-radius: 8px;
    background: linear-gradient(180deg, #ffffff 0%, #f8fbfb 100%);
}

.bar-row span {
    min-width: 0;
    overflow: hidden;
    color: var(--muted);
    font-size: 13px;
    font-weight: 600;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.bar-row strong {
    display: grid;
    gap: 2px;
    min-width: 0;
    text-align: right;
    color: var(--ink);
    font-size: 14px;
    line-height: 1.15;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
}

.bar-row strong small {
    overflow: hidden;
    color: var(--muted);
    font-size: 11px;
    font-weight: 600;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.bar-track {
    height: 14px;
    overflow: hidden;
    border: 1px solid rgba(109, 40, 217, 0.08);
    border-radius: 999px;
    background: #edf4f5;
}

.bar-track i {
    display: block;
    width: 0;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--brand-primary), var(--accent-purple));
    box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.08);
}

.bar-row.is-negative .bar-track i {
    background: linear-gradient(90deg, #c23d42, #e86d73);
}

/* Métricas de consultas públicas */
.metrics-panels {
    gap: 14px;
}

.metrics-chart-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px;
}

.metrics-chart-section {
    display: grid;
    gap: 14px;
    min-width: 0;
}

.metrics-chart-section > h3 {
    margin: 0;
    color: var(--text);
    font-size: 17px;
    line-height: 1.25;
}

.metrics-chart {
    min-width: 0;
}

.metrics-columns-viewport {
    max-width: 100%;
    overflow-x: auto;
    padding: 12px 10px 8px;
    border: 1px solid var(--line);
    border-radius: 10px;
    background:
        repeating-linear-gradient(
            to top,
            transparent 0,
            transparent 44px,
            color-mix(in srgb, var(--line) 72%, transparent) 45px
        ),
        var(--surface-soft);
    scrollbar-width: thin;
}

.metrics-columns-plot {
    display: grid;
    grid-template-columns: repeat(var(--metrics-chart-count), minmax(30px, 1fr));
    gap: 8px;
    min-width: max(100%, calc(var(--metrics-chart-count) * 40px));
}

.metrics-column {
    display: grid;
    grid-template-rows: 24px 180px 28px;
    gap: 5px;
    min-width: 0;
    color: var(--text);
    text-align: center;
}

.metrics-column-value {
    overflow: hidden;
    color: var(--text);
    font-size: 12px;
    line-height: 24px;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
}

.metrics-column-track {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    min-width: 0;
    height: 180px;
    border-bottom: 2px solid var(--line);
}

.metrics-column-track i {
    display: block;
    width: min(76%, 34px);
    min-height: 0;
    border-radius: 7px 7px 2px 2px;
    background: linear-gradient(180deg, var(--accent-purple), var(--brand-primary));
    box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.16);
}

.metrics-column-track i[style="height: 0%"] {
    height: 2px !important;
    background: var(--line);
    box-shadow: none;
}

.metrics-column-label {
    overflow: hidden;
    color: var(--text);
    font-size: 12px;
    font-weight: 700;
    line-height: 28px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.metrics-bars-chart .bar-row {
    grid-template-columns: minmax(120px, 0.3fr) minmax(180px, 1fr) minmax(84px, auto);
}

.metrics-bars-chart .bar-label,
.metrics-bars-chart .bar-value,
.metrics-bars-chart .bar-value small {
    color: var(--text);
}

.metrics-record-count {
    color: var(--text);
    font-weight: 700;
    text-align: right;
}

@media (max-width: 900px) {
    .metrics-chart-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 640px) {
    .metrics-columns-viewport {
        padding-inline: 8px;
    }

    .metrics-bars-chart .bar-row {
        grid-template-columns: 88px minmax(120px, 1fr);
    }
}

.gastos-distribution-panel .bar-row {
    grid-template-columns: minmax(88px, 0.28fr) minmax(260px, 1fr) minmax(230px, auto);
    min-height: 58px;
    padding: 10px 12px;
}

.gastos-distribution-panel .bar-label {
    font-size: 15px;
    line-height: 1.3;
}

.gastos-distribution-panel .bar-value {
    font-size: 17px;
    line-height: 1.2;
}

.gastos-distribution-panel .bar-value small {
    font-size: 13px;
    line-height: 1.3;
}

.gastos-distribution-panel .gastos-distribution-track {
    position: relative;
    isolation: isolate;
    height: 28px;
}

.gastos-distribution-panel .gastos-distribution-track > i {
    position: absolute;
    z-index: 0;
    inset: 0 auto 0 0;
}

.gastos-distribution-panel
    .gastos-distribution-track
    > .gastos-distribution-segment {
    border-radius: 999px;
}

.gastos-distribution-panel
    .gastos-distribution-track
    > .gastos-distribution-segment.is-gastos {
    background: linear-gradient(90deg, #7c3aed, #a78bfa);
}

.gastos-distribution-panel
    .gastos-distribution-track
    > .gastos-distribution-segment.is-mantenimiento {
    background: linear-gradient(90deg, #007a85, #2dd4bf);
}

.gastos-distribution-panel
    .gastos-distribution-track
    > .gastos-distribution-segment.is-mantenimiento-estimado {
    background: linear-gradient(90deg, #d97706, #fbbf24);
}

.gastos-distribution-panel .bar-row .gastos-distribution-percentage {
    position: absolute;
    z-index: 1;
    inset: 0;
    display: grid;
    place-items: center;
    color: #000000;
    font-size: 14px;
    font-weight: 800;
