}

.availability-hour-cell-time {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 11px;
    font-weight: 900;
    line-height: 1;
    white-space: nowrap;
    z-index: 1;
}

.availability-hour-block .availability-grid-icon {
    position: absolute;
    top: 50%;
    right: 2px;
    width: 10px;
    height: 10px;
    flex-basis: 10px;
    transform: translateY(-50%);
    z-index: 1;
}

/* La celda ocupada se parte en dos zonas superpuestas y accesibles: el botón
   de detalle cubre la franja ocupada y el de continuación toda la superficie
   libre que queda desde el último egreso (--availability-continuation-start).
   Los dos son transparentes: la hora, el relleno y el símbolo se dibujan
   debajo y no capturan clics. */
.availability-hour-block .availability-hour-cell-time,
.availability-hour-block .availability-grid-icon {
    pointer-events: none;
}

.availability-hour-detail-action {
    position: absolute;
    inset: 0;
    z-index: 1;
    width: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: inherit;
    background: transparent;
    appearance: none;
    cursor: pointer;
}

.availability-hour-block.has-continuation-action .availability-hour-detail-action {
    right: auto;
    width: var(--availability-continuation-start, 100%);
}

.availability-hour-continuation-action {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: var(--availability-continuation-start, auto);
    z-index: 1;
    width: auto;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    appearance: none;
    cursor: pointer;
}

.availability-hour-continuation-action:hover {
    background: rgba(8, 127, 111, 0.18);
}

.availability-hour-detail-action:focus-visible,
.availability-hour-continuation-action:focus-visible {
    outline: 2px solid #6D28D9;
    outline-offset: -2px;
}

.availability-hour-table td[data-availability-slot] {
    background: #fbfffd;
}

.availability-hour-table td[data-availability-occupancy] {
    background: #fff8fa;
}

.availability-hour-table td[data-availability-status="Parcial"] {
    background: #fbf7ff;
}

.availability-hour-table td[data-availability-status="Fragmentado"] {
    background: #f4f9ff;
}

.availability-hour-table td[data-availability-status="Reservado"] {
    background: #fffaf0;
}

.availability-hour-table td[data-availability-slot]:hover .availability-hour-slot-button,
.availability-hour-slot-button:hover {
    border-color: rgba(8, 127, 111, 0.58);
    background: #e5f8ef;
}

/* Las 24 horas entran completas en la grilla de Estacionamiento. Alquileres
   conserva su ancho histórico y los dispositivos angostos siguen pudiendo
   desplazarse horizontalmente. */
@media (min-width: 1100px) {
    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-wrap {
        max-height: none;
    }

    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-table {
        min-width: 0;
    }

    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-table th[data-availability-axis="horas"] {
        padding: 7px 2px;
    }

    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-heading {
        min-width: 28px;
        padding: 0 4px;
    }

    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-table td {
        padding: 6px 2px;
    }

    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-cell,
    .availability-panel[data-availability-resource-label="espacio"] .availability-hour-table .availability-cell {
        min-width: 0;
    }
}

html[data-theme="dark"] .app-shell .availability-hour-continuation-action:hover {
    background: rgba(101, 223, 190, 0.24);
}

/* El calendario es un desplegable del apartado Empleados: el encabezado lo pone
   el <summary>, así que acá sólo queda el cuerpo. */
.employee-calendar-body {
    display: grid;
    gap: 0;
    min-width: 0;
}

.employee-month-calendar,
.employee-hour-list {
    display: grid;
    gap: 14px;
}

/* El `display: grid` de arriba le ganaba al `hidden` del navegador, así que la
   vista por horas se dibujaba abajo del mes aunque estuviera apagada. */
.employee-month-calendar[hidden],
.employee-hour-list[hidden] {
    display: none;
}

.employee-calendar-filter {
    align-items: end;
    gap: 14px;
    margin-bottom: 16px;
    padding: 14px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: linear-gradient(180deg, #ffffff 0%, #f8fbfb 100%);
    box-shadow: 0 8px 20px rgba(43, 47, 51, 0.04);
}

.employee-calendar-filter .availability-hour-controls {
    align-items: end;
}

.employee-month-weekdays,
.employee-month-grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 10px;
}

.employee-month-weekdays span {
    min-height: 30px;
    display: grid;
    place-items: center;
    border: 1px solid transparent;
    border-radius: 8px;
    background: #eef6f7;
    color: #000000;
    font-size: 12px;
    font-weight: 800;
    text-align: center;
    text-transform: uppercase;
}

.employee-month-day {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 158px;
    gap: 8px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: linear-gradient(180deg, #ffffff 0%, #fbfdfd 100%);
    color: var(--ink);
    text-align: left;
    cursor: pointer;
    box-shadow: 0 6px 16px rgba(43, 47, 51, 0.04);
    transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.employee-month-day.has-events {
    border-color: rgba(109, 40, 217, 0.22);
    background: linear-gradient(180deg, #ffffff 0%, #f4fafb 100%);
}

.employee-month-day.has-absences {
    border-color: rgba(198, 138, 24, 0.42);
    box-shadow: inset 0 3px 0 rgba(198, 138, 24, 0.42);
}

.employee-month-day:hover {
    border-color: rgba(109, 40, 217, 0.42);
    box-shadow: 0 12px 26px rgba(16, 24, 33, 0.09);
    transform: translateY(-1px);
}

.employee-month-day.is-outside {
    min-height: 158px;
    border-style: dashed;
    background: #f5f8f9;
    opacity: 1;
    cursor: default;
    box-shadow: none;
}

.employee-month-day.is-today {
    border-color: rgba(37, 99, 235, 0.45);
    box-shadow: inset 0 0 0 1px rgba(37, 99, 235, 0.18), 0 8px 18px rgba(37, 99, 235, 0.07);
}

.employee-month-day.is-selected {
    border-color: var(--brand-primary);
    box-shadow: inset 0 0 0 2px rgba(109, 40, 217, 0.24), 0 12px 26px rgba(109, 40, 217, 0.08);
}

.employee-month-day-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 8px;
}

.employee-month-day-head strong {
    color: var(--ink);
    font-size: 23px;
    line-height: 1;
}

.employee-month-day-head small {
    padding: 4px 7px;
    border-radius: 999px;
    background: #eef6f7;
    color: #000000;
    font-size: 11px;
    font-weight: 800;
}

.employee-day-timelines {
    display: grid;
    gap: 8px;
    min-width: 0;
}

.employee-day-event {
    display: grid;
    gap: 5px;
    min-width: 0;
    padding: 8px 9px;
    border: 1px solid color-mix(in srgb, var(--employee-color, var(--brand-primary)) 20%, var(--line));
    border-left: 4px solid var(--employee-color, var(--brand-primary));
    border-radius: 8px;
    background: color-mix(in srgb, var(--employee-color, var(--brand-primary)) 8%, #ffffff);
}

.employee-day-event.is-absence {
    border-left-color: #c68a18;
    border-color: rgba(198, 138, 24, 0.28);
    background: #fff8e8;
}

.employee-day-event.is-certificado-medico {
    border-left-color: #b5475a;
    border-color: rgba(181, 71, 90, 0.28);
    background: #fff2f4;
}

.employee-day-event-name {
    display: flex;
    align-items: center;
    min-width: 0;
    gap: 6px;
    color: var(--ink);
    font-size: 11px;
    font-weight: 800;
}

.employee-day-event-name span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.employee-day-track {
    position: relative;
    display: block;
    height: 8px;
    border-radius: 999px;
    background: rgba(196, 209, 212, 0.46);
    overflow: hidden;
}

.employee-day-segment {
    position: absolute;
    top: 0;
    bottom: 0;
    min-width: 2px;
    border-radius: 999px;
}

.employee-day-time,
.employee-day-extra {
    color: var(--muted);
    font-size: 10px;
    font-weight: 800;
}

.employee-day-extra {
    display: inline-flex;
    justify-self: start;
    padding: 4px 8px;
    border-radius: 999px;
    background: #f0f4f5;
    color: #000000;
}

.employee-hour-list-head,
.employee-hour-row {
    display: grid;
    grid-template-columns: minmax(190px, 0.7fr) 92px repeat(5, minmax(0, 1fr));
    gap: 12px;
    align-items: center;
}

.employee-hour-list-head {
    position: sticky;
    top: 0;
    z-index: 1;
    min-height: 42px;
    padding: 0 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #eef6f7;
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
    text-transform: uppercase;
}

.employee-hour-list-head strong {
    color: var(--ink);
    text-transform: none;
}

.employee-hour-row {
    position: relative;
    padding: 14px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 8px 20px rgba(43, 47, 51, 0.05);
}

.employee-hour-row::before {
    content: "";
    position: absolute;
    top: 14px;
    bottom: 14px;
    left: 0;
    width: 4px;
    border-radius: 0 999px 999px 0;
    background: var(--employee-color, var(--brand-primary));
}

.employee-hour-person {
    min-width: 0;
}

.employee-hour-person strong {
    display: flex;
    align-items: center;
    min-width: 0;
    gap: 7px;
    color: var(--ink);
    font-size: 15px;
}

.employee-hour-person small {
    display: block;
    margin-top: 3px;
    color: var(--muted);
    font-size: 11px;
    font-weight: 700;
}

.employee-hour-timeline {
    position: relative;
    grid-column: 3 / -1;
    min-height: 48px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: linear-gradient(90deg, rgba(196, 209, 212, 0.42) 1px, transparent 1px) 0 0 / calc(100% / 24) 100%, linear-gradient(180deg, #ffffff 0%, #f8fbfc 100%);
    overflow: hidden;
}

.employee-hour-grid-line {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 1px;
    background: rgba(87, 105, 112, 0.24);
}

.employee-hour-grid-line.is-6 { left: 25%; }
.employee-hour-grid-line.is-12 { left: 50%; }
.employee-hour-grid-line.is-18 { left: 75%; }

.employee-hour-bar {
    position: absolute;
    top: 8px;
    bottom: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 34px;
    padding: 0 8px;
    border-radius: 8px;
    box-shadow: 0 4px 10px rgba(16, 24, 33, 0.12);
    font-size: 12px;
    font-weight: 900;
    line-height: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.employee-hour-empty {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
}

.employee-hour-absence {
    margin: 7px;
    border: 1px solid rgba(198, 138, 24, 0.34);
    border-radius: 8px;
    background: #fff6df;
    color: #7a5200;
}

.employee-hour-absence.is-certificado-medico {
    border-color: rgba(181, 71, 90, 0.34);
    background: #fff0f3;
    color: #8f2e40;
}

.availability-status.is-vacation {
    border: 1px solid rgba(198, 138, 24, 0.35);
    background: #fff1c9;
    color: #704900;
}

.availability-status.is-medical {
    border: 1px solid rgba(181, 71, 90, 0.35);
    background: #ffe3e8;
    color: #8f2e40;
}

/* Selección de la grilla: superficie completa, sin confundirla con Libre. */
.availability-action-cell:is(.is-availability-selected, .is-availability-anchor),
.availability-table :is(td, th):is(.is-availability-selected, .is-availability-anchor) {
    border-color: var(--line);
    background: var(--selection-option-background);
    box-shadow: none;
    color: var(--ink);
}

.availability-table td.is-availability-invalid {
    background: #fbe1e5;
    box-shadow: inset 0 0 0 2px rgba(138, 31, 44, 0.26);
}

.availability-table th.is-availability-invalid {
    background: #fbe1e5;
    box-shadow: inset 0 0 0 2px rgba(138, 31, 44, 0.26);
    color: #8a1f2c;
}

.availability-action-cell.is-availability-selected .availability-slot-button,
.availability-slot-button.is-availability-selected {
    background: #6D28D9;
    box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.2);
    color: #fff;
}

.availability-action-cell.is-availability-anchor .availability-slot-button,
.availability-slot-button.is-availability-anchor {
    background: #6D28D9;
    box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.28);
    color: #fff;
}

.availability-action-cell.is-availability-invalid .availability-slot-button,
.availability-slot-button.is-availability-invalid {
    background: #b42332;
    box-shadow: 0 0 0 3px rgba(180, 35, 50, 0.18);
    color: #fff;
}

body.availability-selecting {
    user-select: none;
}

.availability-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 28px;
    min-width: 74px;
    padding: 0 9px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
}

.availability-state-summary {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
}

.availability-reservation-note {
    display: inline-flex;
    flex-direction: column;
    gap: 1px;
    color: #6b4300;
    font-size: 10px;
    font-weight: 700;
    line-height: 1.25;
    text-transform: none;
}

.availability-reservation-note time {
