.record-modal-header,
.record-modal-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.record-modal-header {
    align-items: flex-start;
    padding-right: 44px;
}

.record-modal-header h2 {
    margin: 0;
    font-size: 24px;
}

.record-modal-close {
    position: absolute;
    top: 8px;
    right: 8px;
    display: inline-grid;
    place-items: center;
    flex: 0 0 auto;
    width: 28px;
    min-width: 28px;
    height: 28px;
    min-height: 28px;
