}

.entry-form .record-modal-close {
    width: 28px;
    min-width: 28px;
    height: 28px;
    min-height: 28px;
    padding: 0;
    border-radius: 999px;
    background: var(--danger);
    color: #fff;
    font-size: 18px;
    font-weight: 800;
