.parking-client-panel {
    /* Los selectores de contactos siguen en grilla: la cuarta fila es la lista
       y es la única que se estira. Los selectores de cliente y de contrato son
       flex y no usan estas filas. */
    grid-template-rows: auto auto auto minmax(0, 1fr) auto;
    width: min(560px, 100%);
    max-height: min(82vh, 680px);
}

.parking-client-selection-panel {
    display: flex;
    flex-direction: column;
    width: min(1180px, 100%);
}

[data-client-picker-modal] > .parking-client-selection-panel {
    width: min(1600px, 100%);
    max-height: min(92dvh, 900px);
}

.parking-client-selection-panel > .parking-client-list {
    flex: 1 1 auto;
    max-height: 480px;
}

.parking-client-picker-grid {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
}

.parking-client-picker-grid[hidden] {
    display: none;
}

.parking-client-picker-grid > .parking-client-list {
    flex: 1 1 auto;
    max-height: none;
}

.parking-existing-contract-panel :is(
    .parking-client-list-meta,
    .parking-client-empty
) {
    color: var(--ink);
}

.parking-existing-contract-panel .parking-client-list-item.is-selected {
    border-color: var(--brand-primary);
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand-primary) 22%, transparent);
}

.parking-client-type-toggle {
    display: inline-grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 6px;
    width: min(320px, 100%);
    padding: 4px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #f6fafb;
}

.parking-client-type-toggle[hidden] {
    display: none !important;
}

.parking-client-type-toggle button {
    min-height: 38px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: var(--muted);
    font: inherit;
    font-size: 13px;
    font-weight: 800;
    cursor: pointer;
}

.parking-client-type-toggle button.is-active,
.parking-client-type-toggle button:focus-visible {
    background: var(--brand-primary);
    color: #fff;
    outline: none;
}

.parking-client-search-field {
    display: grid;
    gap: 6px;
    color: #000;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.2;
    text-transform: uppercase;
}

.parking-client-search-field[hidden] {
    display: none !important;
}

.parking-client-search-field input {
    width: 100%;
    min-height: 44px;
    padding: 0 14px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
    color: var(--ink);
    font-size: 14px;
    font-weight: 600;
    outline: none;
}

.parking-client-search-field input:focus {
    border-color: var(--brand-primary);
    box-shadow: 0 0 0 3px rgba(109, 40, 217, 0.13);
}

.parking-client-list {
    display: grid;
    align-content: start;
    gap: 8px;
    min-height: 0;
    max-height: 430px;
    overflow: auto;
    padding: 2px;
}

.parking-client-list-item {
    display: grid;
    gap: 3px;
    width: 100%;
    padding: 12px 14px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #fff;
    color: var(--ink);
    text-align: left;
    cursor: pointer;
}

/* Los selectores conservan botones de fila para que click y teclado tengan la
   misma conducta. El selector de contratos sigue usando tres columnas; el de
   clientes cambia su grilla según se muestren personas o empresas. */
.parking-client-selection-panel .parking-client-list-item {
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) minmax(0, 1.3fr);
    align-items: center;
    gap: 13px;
}

[data-client-picker-modal][data-client-picker-kind-view="cliente"]
    :is(.parking-client-table-head, .parking-client-list-item) {
    grid-template-columns:
        minmax(0, 1.2fr)
        minmax(0, 0.8fr)
        minmax(0, 0.78fr)
        minmax(0, 0.85fr)
        minmax(0, 1fr)
        minmax(0, 1.35fr);
}

[data-client-picker-modal][data-client-picker-kind-view="empresa"]
    :is(.parking-client-table-head, .parking-client-list-item) {
    grid-template-columns:
        minmax(0, 1.2fr)
        minmax(0, 0.8fr)
        minmax(0, 0.85fr)
        minmax(0, 1fr)
        minmax(0, 0.8fr)
        minmax(0, 0.75fr)
        minmax(0, 0.8fr)
        minmax(0, 0.95fr)
        minmax(0, 1.25fr);
}

[data-client-picker-modal] .parking-client-list {
    gap: 0;
    padding: 0;
}

[data-client-picker-modal]
    [data-client-picker-column-kind][hidden] {
    display: none !important;
}

[data-client-picker-modal] .parking-client-list-item {
    padding: 13px 14px;
    border: 0;
    border-bottom: 1px solid var(--line);
    border-radius: 0;
}

[data-client-picker-modal] .parking-client-list-item:last-child {
    border-bottom: 0;
}

.parking-client-selection-panel .parking-client-list-item.is-selected {
    border-color: var(--brand-primary);
    background: color-mix(in srgb, var(--brand-primary) 14%, #ffffff);
    box-shadow: none;
}

.parking-client-pagination-toolbar {
    justify-content: flex-start;
}

.parking-client-table-head {
    display: grid;
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) minmax(0, 1.3fr);
    gap: 13px;
    padding: 0 15px;
    color: var(--ink);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

[data-client-picker-modal] .parking-client-table-head {
    flex: 0 0 auto;
    padding: 12px 14px;
    border-bottom: 1px solid var(--line);
    background: var(--surface);
}

.parking-client-table-head[hidden] {
    display: none;
}

.parking-client-option-value {
    display: grid;
    align-content: start;
    min-width: 0;
    gap: 3px;
}

.parking-client-option-value small {
    color: var(--ink);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.04em;
    line-height: 1.2;
    text-transform: uppercase;
}

.parking-client-option-value > :is(strong, span) {
    min-width: 0;
    overflow-wrap: anywhere;
}

.parking-client-option-value > strong {
    color: var(--ink);
    font-size: 13px;
    line-height: 1.3;
}

.parking-client-option-vehicles {
    grid-column: 1 / -1;
    display: grid;
    gap: 5px;
    margin-top: 5px;
    padding-top: 12px;
    border-top: 1px solid var(--line);
    color: #000000;
}

.parking-client-option-vehicles[hidden] {
    display: none !important;
}

.parking-client-option-vehicles-title {
    color: #000000;
    font-size: 13px;
}

.parking-client-option-vehicle {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
    padding: 9px 10px;
    border: 1px solid var(--line);
    border-radius: 7px;
    background: var(--surface);
}

.parking-client-option-vehicle-field {
    display: grid;
    gap: 2px;
    min-width: 0;
}

.parking-client-option-vehicle-field > small {
    color: #000000;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.parking-client-option-vehicle-field > strong,
.parking-client-option-vehicles-empty {
    color: #000000;
    font-size: 13px;
    overflow-wrap: anywhere;
}

.parking-client-list-item[hidden] {
    display: none !important;
}

.parking-client-list-item:hover,
.parking-client-list-item:focus-visible {
    border-color: var(--brand-primary);
    background: #f3fbfc;
    outline: none;
}

/* El selector usa exactamente la misma señal semántica que las grillas de
   Registros, Clientes y Vehículos. La mayor especificidad preserva la alerta
   también en tema oscuro y cuando la fila queda seleccionada. */
.app-shell [data-client-picker-modal]
    .parking-client-selection-panel
    .parking-client-list-item.is-lista_negra {
    background: var(--blacklist-row-background);
    color: var(--blacklist-row-text);
    border-left: 4px solid var(--blacklist-row-accent);
    box-shadow: none;
}

.app-shell [data-client-picker-modal]
    .parking-client-selection-panel
    .parking-client-list-item.is-lista_negra
    .parking-client-option-value > strong {
    color: var(--blacklist-row-text);
}

.app-shell [data-client-picker-modal]
    .parking-client-selection-panel
    .parking-client-list-item.is-lista_negra:is(:hover, :focus-visible) {
    background: var(--blacklist-row-background-hover);
}

html[data-theme="dark"] .app-shell [data-client-picker-modal]
    .parking-client-selection-panel
    .parking-client-list-item.is-lista_negra,
html[data-theme="dark"] .app-shell [data-client-picker-modal]
    .parking-client-selection-panel
    .parking-client-list-item.is-lista_negra.is-selected {
    background: var(--blacklist-row-background);
    color: var(--blacklist-row-text);
    border-left: 4px solid var(--blacklist-row-accent);
    box-shadow: none;
}

html[data-theme="dark"] .app-shell [data-client-picker-modal]
    .parking-client-selection-panel
    .parking-client-list-item.is-lista_negra:is(:hover, :focus-visible) {
    background: var(--blacklist-row-background-hover);
}

.parking-client-list-name {
    font-size: 14px;
    font-weight: 800;
    line-height: 1.25;
}

.parking-client-list-meta {
    color: var(--muted);
    font-size: 12px;
    font-weight: 600;
    line-height: 1.25;
}

.parking-client-empty {
