    background: var(--surface-soft);
}

.vehicle-period-rate-title {
    color: var(--ink);
    font-size: 13px;
    font-weight: 800;
    text-transform: uppercase;
}

.vehicle-period-rate-title-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
}

.entry-form .vehicle-period-rate-more {
    flex: 0 0 auto;
    width: auto;
    min-width: 0;
    height: auto;
    min-height: 30px;
    padding: 3px 5px;
    border: 0;
    background: transparent;
    color: #2563eb;
    font: inherit;
    font-size: 12px;
    font-weight: 850;
    line-height: 1.2;
    text-decoration: none;
    text-decoration-thickness: 0.11em;

    cursor: pointer;
    box-shadow: none;
}

.entry-form .vehicle-period-rate-more:hover {
    color: #1d4ed8;
    text-decoration-thickness: 0.16em;
}

.entry-form .vehicle-period-rate-more:focus-visible {
    outline: 2px solid #2563eb;
    outline-offset: 2px;
}

.vehicle-period-rate-controls {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
}

.vehicle-period-rate :is(input, select) {
    width: 100%;
    min-width: 0;
}

.vehicle-period-rate-field {
    display: grid;
    gap: 5px;
    min-width: 0;
}

.vehicle-period-rate-field > span {
    color: var(--ink);
    font-size: 11px;
    font-weight: 750;
    line-height: 1.25;
    text-transform: uppercase;
}

.vehicle-period-rate-label-row {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 5px;
}

.vehicle-period-rate-label-row > label {
    display: block;
    color: inherit;
    font: inherit;
    line-height: inherit;
    text-transform: inherit;
}

.vehicle-rate-fraction-base {
    white-space: nowrap;
}

[data-vehicle-modal-rate-fraction-base] {
    color: var(--brand-primary);
    font-weight: 850;
}

.entry-form .vehicle-rate-help-button {
    position: relative;
    width: 14px;
    min-width: 14px;
    height: 14px;
    min-height: 14px;
    flex-basis: 14px;
    font-size: 10px;
}

.entry-form .vehicle-rate-help-button::before {
    position: absolute;
    width: 30px;
    height: 30px;
    content: "";
}

.entry-form .vehicle-rate-help-button:focus-visible {
    outline: 2px solid #6D28D9;
    outline-offset: 2px;
}

.vehicle-rate-help-popover {
    top: auto;
    right: auto;
    bottom: calc(100% + 7px);
    left: 50%;
    transform: translateX(-50%);
    width: min(260px, calc(100vw - 48px));
    min-width: 220px;
    font-size: 12px;
    font-weight: 700;
    text-align: left;
}

.vehicle-rate-fraction-help-popover {
    width: min(330px, calc(100vw - 48px));
}

.vehicle-rate-rounding {
    display: grid;
    min-width: 0;
    gap: 8px;
    margin: 2px 0 0;
    padding: 10px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: color-mix(in srgb, var(--surface) 72%, transparent);
}

.vehicle-rate-rounding legend {
    padding: 0 5px;
    color: var(--ink);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.2;
    text-transform: uppercase;
}

/* En el modal de categoría el redondeo va suelto, sin recuadro ni fondo: la
   tarjeta que lo contiene ya delimita el bloque. */
[data-vehicle-modal] .vehicle-rate-rounding,
.vehicle-rate-tier-column-head .vehicle-rate-rounding {
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
}

.vehicle-rate-rounding-figure {
    color: #a16207;
    font-weight: 900;
}

.vehicle-rate-rounding-controls {
    display: grid;
    grid-template-columns: minmax(0, 1.35fr) minmax(72px, 0.65fr);
    gap: 8px;
}

.vehicle-rate-rounding-controls label {
    display: grid;
    min-width: 0;
    gap: 5px;
}

.vehicle-rate-rounding-controls label > span {
    color: var(--ink);
    font-size: 10px;
    font-weight: 750;
    line-height: 1.25;
    text-transform: uppercase;
}

.vehicle-rate-rounding output {
    min-height: 17px;
    color: var(--muted);
    font-size: 11px;
    font-weight: 700;
    line-height: 1.35;
}

.vehicle-rate-rounding.is-disabled input {
    border-color: #c5cfd3;
    background: #e6eaec;
    color: #000000;
    box-shadow: none;
    cursor: default;
    opacity: 1;
}

.vehicle-period-rate-field :is(input[readonly], input:disabled),
.vehicle-period-rate-field.is-inactive input {
    border-color: #c5cfd3;
    background: #e6eaec;
    color: #000000;
    box-shadow: none;
    cursor: default;
    opacity: 1;
}

.vehicle-period-rate-field.is-inactive > span,
.vehicle-period-rate-derived > span {
    color: #000000;
}

.vehicle-period-rate small {
    min-height: 18px;
    color: var(--muted);
    font-size: 13px;
    font-weight: 700;
}

.vehicle-category-models-section {
    padding-top: 2px;
}

[data-vehicle-rate-tiers-modal],
[data-weekend-surcharge-modal] {
    z-index: 94;
}

.weekend-surcharge-mode-field .field-label-line {
    display: block;
}

.weekend-surcharge-mode-field .required-mark {
    margin-left: 3px;
}

.weekend-surcharge-control {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: stretch;
    gap: 8px;
}

.entry-form .weekend-surcharge-configure {
    width: auto;
    min-width: 0;
    height: auto;
    min-height: 42px;
    padding: 6px 8px;
    border: 0;
    background: transparent;
    color: #2563eb;
    font: inherit;
    font-size: 12px;
    font-weight: 850;
    text-decoration: none;

    cursor: pointer;
    box-shadow: none;
}

.entry-form .weekend-surcharge-configure:focus-visible {
    outline: 2px solid #2563eb;
    outline-offset: 2px;
}

.vehicle-rate-tiers-panel,
.weekend-surcharge-panel {
    grid-template-rows: auto minmax(0, 1fr) auto;
    gap: 0;
    width: min(680px, 100%);
    max-height: min(88dvh, 760px);
    padding: 0;
    overflow: hidden;
}

/* La lista de tramos llega a 59 minutos o 24 meses, cada uno con hasta tres
   columnas de precio: la ventana ocupa casi toda la pantalla para que entren
   varias filas sin desplazarse. */
.vehicle-rate-tiers-panel {
    width: min(1180px, 100%);
    max-height: min(94dvh, 1080px);
}

.vehicle-rate-tiers-panel > .record-modal-header,
.weekend-surcharge-panel > .record-modal-header {
    padding: 20px 60px 16px 22px;
    border-bottom: 1px solid var(--line);
    background: #ffffff;
}

.vehicle-rate-tiers-panel > .record-modal-header h2,
.weekend-surcharge-panel > .record-modal-header h2 {
    color: #000000;
}

.vehicle-rate-tiers-panel > .record-modal-actions,
.weekend-surcharge-panel > .record-modal-actions {
    justify-content: flex-end;
    padding: 14px 22px;
    border-top: 1px solid var(--line);
    background: #ffffff;
}

.vehicle-rate-tiers-form,
.weekend-surcharge-form {
    min-height: 0;
    min-block-size: 0;
    padding: 20px 22px;
    overflow-y: auto;
    background: #ffffff;
    color: #000000;
}

.vehicle-rate-tiers-form {
    /* .entry-form reparte sus hijos en columnas automáticas: acá la barra, el
       encabezado y las filas van uno debajo del otro. */
    grid-template-columns: minmax(0, 1fr);
    align-items: stretch;
    overflow-x: auto;
}

.vehicle-rate-tiers-toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    min-width: 0;
}

.entry-form .vehicle-rate-tiers-filter {
    width: auto;
    min-width: 0;
}

.vehicle-rate-tiers-columns {
    align-items: end;
    /* Los 13px repiten el relleno y el borde de cada fila para que las pistas
       del encabezado caigan justo encima de sus celdas. */
    padding: 0 13px 10px;
    border-bottom: 1px solid var(--line);
}

.vehicle-rate-tiers-columns,
.vehicle-rate-tier-row,
[data-vehicle-rate-tier-row] {
    display: grid;
    grid-template-columns:
        minmax(140px, 0.85fr)
        repeat(var(--vehicle-rate-tier-columns, 1), minmax(180px, 1fr));
    gap: 10px;
    min-width: 0;
}

/* El encabezado sólo tiene sentido alineado con sus celdas: en pantallas
   angostas la tabla se desplaza en lugar de apilarse y perder los rótulos. */
.vehicle-rate-tiers-columns,
.vehicle-rate-tiers-rows {
    min-width: fit-content;
}

.entry-form :is(.vehicle-rate-tier-cell, .vehicle-rate-tier-column-head) input:disabled {
    border-color: #c5cfd3;
    background: #e6eaec;
    color: #000000;
    box-shadow: none;
    cursor: default;
    opacity: 1;
}

.vehicle-rate-tier-quantity-head,
.vehicle-rate-tier-column-title {
    color: #000000;
    font-size: 11px;
    font-weight: 850;
    line-height: 1.25;
    text-transform: uppercase;
}

.vehicle-rate-tier-column-head {
    display: grid;
    gap: 8px;
    min-width: 0;
    align-content: start;
}

.vehicle-rate-tier-cell {
    display: grid;
    gap: 4px;
    min-width: 0;
    align-content: start;
}

.vehicle-rate-tier-cell small {
    min-height: 16px;
    color: #000000;
    font-size: 11px;
    font-weight: 700;
    line-height: 1.3;
}

.entry-form .vehicle-rate-tier-toggle {
    align-self: start;
    width: 100%;
    min-width: 0;
}

.vehicle-rate-tiers-rows {
    display: grid;
    gap: 10px;
    min-width: 0;
}

.vehicle-rate-tiers-empty {
    margin: 0;
    padding: 12px;
    border: 1px solid #2563eb;
    border-radius: 8px;
    background: #eff6ff;
    color: #000000;
    font-size: 13px;
    font-weight: 750;
    line-height: 1.4;
}

.vehicle-rate-tier-row,
[data-vehicle-rate-tier-row] {
    align-items: start;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: #ffffff;
    color: #000000;
}

.vehicle-rate-tier-row > label,
[data-vehicle-rate-tier-row] > label {
    min-width: 0;
    color: #000000;
}

.weekend-surcharge-form {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.weekend-surcharge-form > label {
    min-width: 0;
    color: #000000;
}

.weekend-surcharge-end-note {
    grid-column: 1 / -1;
    margin: 2px 0 0;
    padding: 11px 12px;
    border: 1px solid #2563eb;
    border-radius: 8px;
    background: #eff6ff;
    color: #000000;
    font-size: 13px;
    font-weight: 750;
    line-height: 1.4;
}

[data-vehicle-modal] .space-vehicle-picker {
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 8px;
}

[data-vehicle-modal] .space-vehicle-option {
    min-height: 42px;
    border-color: #b8c9ce;
    background: #ffffff;
    color: #000000;
    cursor: pointer;
    transition: border-color 0.16s ease, background 0.16s ease, color 0.16s ease;
}

[data-vehicle-modal] .space-vehicle-option-choice {
    display: flex;
    flex: 1 1 auto;
    align-items: center;
    min-width: 0;
    gap: 8px;
    color: inherit;
    font: inherit;
    line-height: 1.25;
    text-transform: inherit;
    cursor: pointer;
}

[data-vehicle-modal] .space-vehicle-option-choice > span {
    min-width: 0;
    overflow-wrap: anywhere;
}

[data-vehicle-modal] .vehicle-model-info-button {
    display: inline-grid;
    place-items: center;
    flex: 0 0 24px;
    width: 24px;
    min-width: 24px;
    height: 24px;
    min-height: 24px;
    margin-left: auto;
    padding: 0;
    border: 1px solid #8B5CF6;
    border-radius: 999px;
    background: #8B5CF6;
    color: #ffffff;
    font-size: 13px;
    font-weight: 900;
    line-height: 1;
    cursor: pointer;
}

[data-vehicle-modal] .vehicle-model-info-button:hover {
    filter: brightness(1.08);
}

[data-vehicle-modal] .vehicle-model-info-button:focus-visible {
    outline: 3px solid rgba(109, 40, 217, 0.28);
    outline-offset: 2px;
}

[data-vehicle-modal] .space-vehicle-option:has(input:checked) {
    border-color: #8B5CF6;
    background: #e7f7f8;
    color: #004f59;
}

[data-vehicle-modal] .space-vehicle-option:focus-within {
    border-color: var(--brand-primary);
    outline: 3px solid rgba(109, 40, 217, 0.2);
    outline-offset: 1px;
}

[data-vehicle-modal] .space-vehicle-option.is-disabled {
    border-color: rgba(213, 53, 84, 0.72);
    background: #e3e6e8;
    color: #000000;
    box-shadow: inset 3px 0 0 var(--danger);
    opacity: 1;
    cursor: default;
}

[data-vehicle-modal] .space-vehicle-option.is-disabled .space-vehicle-option-choice {
    cursor: default;
}

[data-vehicle-modal] .space-vehicle-option.is-disabled .space-vehicle-option-choice input {
    pointer-events: none;
}

[data-vehicle-modal] .space-vehicle-option.is-disabled:hover {
    border-color: var(--danger);
    background: #d9dde0;
}

[data-vehicle-modal] .space-vehicle-option.is-disabled:focus-within {
    border-color: var(--danger);
    outline: 3px solid rgba(213, 53, 84, 0.24);
}

html[data-theme="dark"] .app-shell [data-vehicle-modal] .space-vehicle-option {
    border-color: #405861;
    background: #172329;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell [data-vehicle-modal] .space-vehicle-option:has(input:checked) {
    border-color: #A855F7;
    background: #0d5962;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell [data-vehicle-modal] .space-vehicle-option.is-disabled {
    border-color: #f0646a;
