}

html[data-theme="dark"] .app-shell [data-space-modal] .space-vehicle-option {
    border-color: #405861;
    background: #172329;
    color: #ffffff;
    box-shadow: none;
}

html[data-theme="dark"] .app-shell [data-space-modal] .space-vehicle-option:hover {
    border-color: #A855F7;
    background: #20343b;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell [data-space-modal] .space-vehicle-option:has(input:checked) {
    border-color: #A855F7;
    background: #0d5962;
    color: #ffffff;
    box-shadow: none;
}

html[data-theme="dark"] .app-shell [data-space-modal] .space-vehicle-option:focus-within {
    border-color: #A855F7;
