    min-height: 56px;
    padding: 0 16px;
    color: var(--ink);
    font-size: 16px;
    font-weight: 900;
    cursor: pointer;
    list-style: none;
}

.public-config-disclosure > summary::-webkit-details-marker {
    display: none;
}

.public-config-disclosure > summary::after {
    content: "+";
    display: inline-grid;
    place-items: center;
    width: 30px;
    height: 30px;
    border-radius: 8px;
    background: #edf7f8;
    color: var(--brand-primary);
