}

.public-config-disclosure > .collapsible-summary::after {
    content: none;
    display: none;
}

.public-config-disclosure[open] > summary {
    border-bottom: 1px solid var(--line);
}

.public-config-disclosure[open] > summary::after {
    content: "-";
}

