}

.public-template-picker {
    grid-template-columns: repeat(3, minmax(180px, 1fr));
    gap: 12px;
}

.public-template-option {
    --template-accent: #6fd4e5;
    --template-shadow: rgba(13, 74, 81, 0.18);
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
    align-items: stretch;
    height: 100%;
    box-sizing: border-box;
    min-height: 310px;
    gap: 12px;
    padding: 14px;
    overflow: hidden;
    cursor: default;
    text-transform: none;
}

.public-template-option[hidden] {
    display: none !important;
}

.public-template-option > .public-template-choice {
    display: grid;
    grid-template-columns: 24px minmax(0, 1fr);
    grid-template-rows: auto auto;
    gap: 12px;
    min-width: 0;
    color: inherit;
    cursor: pointer;
    text-transform: none;
}

.public-template-option input {
    grid-row: 2;
}

.public-template-choice > .public-template-real-thumbnail {
    display: block;
    grid-column: 1 / -1;
    gap: 0;
}

.public-template-preview {
    grid-column: 1 / -1;
    position: relative;
    width: 100%;
    min-height: 0;
    aspect-ratio: 16 / 9;
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--template-accent) 45%, transparent);
    border-radius: 8px;
    background: #071114;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.16), 0 14px 28px var(--template-shadow);
}

.public-template-preview-sheet {
    position: absolute;
    inset: 0;
    opacity: 0;
    visibility: hidden;
    transition: opacity 240ms ease;
}

.public-template-preview-sheet.is-active {
    opacity: 1;
    visibility: visible;
}

.public-template-preview-sheet > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.public-template-preview-pagination {
    position: absolute;
    z-index: 2;
    right: 8px;
    bottom: 8px;
    display: inline-flex;
    align-items: center;
    max-width: calc(100% - 16px);
    padding: 5px 8px;
    border: 1px solid rgba(255, 255, 255, 0.28);
    border-radius: 999px;
    background: rgba(3, 14, 18, 0.82);
    color: #ffffff;
    font-size: 10px;
    line-height: 1;
    box-shadow: 0 5px 14px rgba(0, 0, 0, 0.22);
    backdrop-filter: blur(5px);
    opacity: 0;
    visibility: hidden;
    transform: translateY(3px);
    pointer-events: none;
    transition: opacity 160ms ease, transform 160ms ease, visibility 160ms ease;
}

.public-template-preview.is-preview-active .public-template-preview-pagination {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
    .public-template-preview-sheet {
        transition: none;
    }
}

