}

html[data-theme="dark"]
    .app-shell
    .public-page-builder-parking
    .public-price-period-check:not(:has(input:checked))
    > span {
    color: #D8B4FE;
}

.public-mars-merged-fields .public-price-period-check:focus-within {
    outline: 3px solid rgba(109, 40, 217, 0.2);
    outline-offset: 2px;
}

.public-calculation-vehicle-check:has(input:checked) > span {
    color: #ffffff;
}

.public-calculation-discount-check:has(input:checked) > span {
    color: #ffffff;
}

.public-calculation-discount-preview {
    display: grid;
    gap: 8px;
}

.public-block-editor[data-public-block-editor="calculo"] .public-calculation-discount-preview {
    gap: 10px;
    margin-top: 6px;
}

.public-calculation-discount-preview > legend {
    color: var(--ink);
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-block-editor[data-public-block-editor="calculo"] .public-calculation-discount-preview > legend {
    line-height: 1.35;
}

.public-calculation-discount-preview > div {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.public-calculation-discount-check {
    display: inline-grid;
    gap: 4px;
    min-height: 46px;
    padding: 9px 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
}

.public-calculation-discount-check {
    cursor: pointer;
}

/* Los selectores del editor de Cálculo comparten el contrato visual de los
   modos de Nuevo ingreso, sin reutilizar una clase acoplada a .entry-form. */
.public-block-editor[data-public-block-editor="calculo"] :is(
    .public-calculation-vehicle-check,
    .public-calculation-discount-check
) {
    position: relative;
    border-color: var(--line);
    background: #ffffff;
    color: #000000;
    font-weight: 700;
    opacity: 1;
    user-select: none;
}

.public-block-editor[data-public-block-editor="calculo"] :is(
    .public-calculation-vehicle-check,
    .public-calculation-discount-check
) > span {
    color: inherit;
}

.public-block-editor[data-public-block-editor="calculo"] :is(
    .public-calculation-vehicle-check,
    .public-calculation-discount-check
):not(.is-selection-locked):not(:has(input:disabled)):hover {
    border-color: var(--brand-primary);
}

.public-block-editor[data-public-block-editor="calculo"] :is(
    .public-calculation-vehicle-check,
    .public-calculation-discount-check
):has(input:focus-visible) {
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 25%, transparent);
    outline-offset: 2px;
}

.public-block-editor[data-public-block-editor="calculo"] :is(
    .public-calculation-vehicle-check,
    .public-calculation-discount-check
):has(input:checked):not(.is-selection-locked):not(:has(input:disabled)) {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
}

.public-block-editor[data-public-block-editor="calculo"] :is(
    .public-calculation-vehicle-check.is-selection-locked,
    .public-calculation-discount-check.is-selection-locked,
    .public-calculation-vehicle-check:has(input:disabled),
    .public-calculation-discount-check:has(input:disabled)
) {
    border-color: #9aa5ad;
    background: #d9dee1;
    color: #000000;
    cursor: default;
    opacity: 1;
}

html[data-theme="dark"] .app-shell
    .public-block-editor[data-public-block-editor="calculo"] :is(
        .public-calculation-vehicle-check,
        .public-calculation-discount-check
    ):not(.is-selection-locked):not(:has(input:checked)):not(:has(input:disabled)) {
    border-color: #565656;
    background: #1c1c1c;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell
    .public-block-editor[data-public-block-editor="calculo"] :is(
        .public-calculation-vehicle-check,
        .public-calculation-discount-check
    ):has(input:checked):not(.is-selection-locked):not(:has(input:disabled)) {
    border-color: #8B5CF6;
    background: #6D28D9;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell
    .public-block-editor[data-public-block-editor="calculo"] :is(
        .public-calculation-vehicle-check.is-selection-locked,
        .public-calculation-discount-check.is-selection-locked,
        .public-calculation-vehicle-check:has(input:disabled),
        .public-calculation-discount-check:has(input:disabled)
    ) {
    border-color: #687780;
    background: #465158;
    color: #ffffff;
    opacity: 1;
}

.public-calculation-discount-empty {
    display: grid;
    flex: 1 1 100%;
    gap: 4px;
    padding: 12px;
    border: 1px dashed var(--line);
    border-radius: 8px;
    color: var(--muted);
}

.public-calculation-discount-empty strong {
    color: var(--ink);
}

.public-calculation-discount-empty small {
    line-height: 1.45;
}

/* Los modales del editor de Página web tienen que quedar por encima de la
   vista previa embebida: su barra sticky usa z-index 220 y taparía los
   botones del aviso. Solo el recortador de imagen (4000) queda arriba. */
.public-page-builder .record-modal {
    z-index: 230;
}

.public-footer-redes-field {
    display: grid;
    gap: 14px;
    margin: 14px 2px 6px;
    padding: 0;
    border: 0;
}

.public-footer-redes-field > legend {
    color: var(--ink);
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

/* Dos columnas: a la izquierda las redes con link cargado, a la derecha las
   que faltan configurar. En pantallas angostas quedan una debajo de la otra. */
.public-footer-redes-columns {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr));
    gap: 18px;
    align-items: start;
}

.public-footer-redes-group {
    display: grid;
    gap: 10px;
    align-content: start;
    min-width: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
}

.public-footer-redes-group-title {
    color: var(--ink);
    font-size: 12px;
    font-weight: 900;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.public-footer-redes-options {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.public-footer-redes-empty {
    color: var(--muted);
    font-weight: 800;
    line-height: 1.45;
}

.public-footer-red-check {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    min-height: 44px;
    min-width: 118px;
    margin: 0;
    padding: 0 16px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    font-weight: 900;
    line-height: 1.2;
    cursor: pointer;
}

.public-footer-red-check input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.public-footer-red-icon {
    display: inline-grid;
    place-items: center;
}

.public-footer-red-check svg {
    width: 20px;
    height: 20px;
    flex: 0 0 auto;
    fill: currentColor;
}

.app-shell .public-page-builder-parking .public-footer-red-check:has(input:checked) {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
}

.public-footer-red-check:focus-within,
.public-footer-red-check.is-unloaded:focus-visible {
    outline: 3px solid rgba(109, 40, 217, 0.2);
    outline-offset: 2px;
}

/* Una red sin cargar se lee completa pero se distingue: borde punteado y
   clic que abre el cuadro para pegarle el link. */
.public-footer-red-check.is-unloaded {
    border-style: dashed;
    color: var(--muted);
    cursor: pointer;
    opacity: 0.75;
}

.public-footer-red-check.is-unloaded:hover {
    color: var(--ink);
    opacity: 1;
}

.public-footer-link-panel {
    max-width: 520px;
}

.public-footer-link-form {
    display: grid;
    gap: 8px;
    padding: 0 24px;
}

.public-footer-link-form label {
    color: var(--ink);
    font-weight: 900;
}

.public-footer-link-form input {
    width: 100%;
}

.public-footer-link-help {
    color: var(--muted);
    line-height: 1.5;
}

.location-social-section {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    padding: 0;
    border: 0;
    background: transparent;
}

.location-social-section > div {
    grid-column: 1 / -1;
    display: grid;
    gap: 4px;
}

.location-social-section strong {
    color: var(--ink);
    font-size: 16px;
}

.location-social-section small {
    color: var(--muted);
    font-weight: 800;
}

.location-social-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px 16px;
    align-items: start;
}

.location-social-grid label {
    min-width: 0;
}

.location-social-field {
    display: grid;
    gap: 6px;
}

.social-input-control {
    position: relative;
    display: block;
    min-width: 0;
}

.entry-form .social-input-control > input {
    padding-right: 46px;
}

.entry-form .social-error-button {
    position: absolute;
    top: 50%;
    right: 10px;
    display: inline-grid;
    place-items: center;
    width: 24px;
    min-width: 24px;
    height: 24px;
    min-height: 24px;
    aspect-ratio: 1;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: var(--danger);
    color: #ffffff;
    font-size: 15px;
    font-weight: 900;
    line-height: 1;
    box-shadow: 0 3px 10px rgba(194, 61, 66, 0.28);
    transform: translateY(-50%);
}

.entry-form .social-error-button[hidden] {
    display: none;
}

.entry-form .social-error-button:hover,
.entry-form .social-error-button:focus-visible {
    border-radius: 50%;
    background: var(--danger);
    color: #ffffff;
    filter: brightness(1.08);
}

.entry-form .social-error-button:focus-visible {
    outline: 3px solid rgba(194, 61, 66, 0.24);
    outline-offset: 2px;
}

.location-social-field .social-input-control > input[aria-invalid="true"] {
    border-color: var(--danger);
    box-shadow: 0 0 0 3px rgba(194, 61, 66, 0.12);
}

.social-validation-toast[hidden] {
    display: none;
}

.social-validation-toast {
    position: fixed;
    z-index: 145;
    display: grid;
    grid-template-columns: 28px minmax(0, 1fr) 28px;
    align-items: start;
    gap: 11px;
    width: min(430px, calc(100vw - 36px));
    padding: 15px;
    border: 1px solid rgba(194, 61, 66, 0.36);
    border-left: 4px solid var(--danger);
    border-radius: 12px;
    background: #ffffff;
    color: var(--ink);
    box-shadow: 0 18px 46px rgba(16, 24, 33, 0.24);
    text-align: left;
    text-transform: none;
}

.social-validation-toast-mark {
    display: inline-grid;
    place-items: center;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--danger);
    color: #ffffff;
    font-size: 17px;
    font-weight: 900;
    line-height: 1;
}

.social-validation-toast-copy {
    display: grid;
    gap: 4px;
    min-width: 0;
}

.social-validation-toast-copy strong {
    color: var(--ink);
    font-size: 14px;
    line-height: 1.25;
}

.social-validation-toast-copy > span {
    color: var(--muted);
    font-size: 13px;
    font-weight: 650;
    line-height: 1.4;
}

.entry-form .social-validation-toast-close {
    display: inline-grid;
    place-items: center;
    width: 28px;
    min-width: 28px;
    height: 28px;
    min-height: 28px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--muted);
    font-size: 22px;
    line-height: 1;
}

.entry-form .social-validation-toast-close:hover,
.entry-form .social-validation-toast-close:focus-visible {
    border-radius: 50%;
    background: var(--surface-strong);
    color: var(--ink);
    filter: none;
}

.variables-shell :is(input:not([type="hidden"]), select, textarea, button)[aria-invalid="true"] {
    border-color: var(--danger);
    box-shadow: 0 0 0 3px rgba(194, 61, 66, 0.14);
}

@media (max-width: 980px) {
    .space-location-list-grid,
    .location-social-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 640px) {
    .space-location-list-grid,
    .location-social-grid {
        grid-template-columns: 1fr;
    }
}

.public-builder-side {
    display: grid;
    gap: 18px;
}

.public-builder-side .public-link-qr-section {
    width: 100%;
}

.public-builder-data {
    display: grid;
    gap: 8px;
    padding: 16px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #f7fbfb;
}

.public-builder-data span {
    color: var(--brand-primary);
    font-size: 12px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-builder-data strong {
    color: var(--ink);
    font-size: 22px;
}

.public-builder-data small {
    color: var(--muted);
    font-weight: 700;
}

.public-page-preview-panel {
    padding: 0;
}

.public-page-preview-panel > .panel-header {
    padding: 22px;
}

.public-page-preview-panel[open] > .panel-header {
    margin-bottom: 0;
    padding-bottom: 14px;
}

.public-page-owner-preview {
    padding: 22px;
}

.public-site {
    --public-accent: #7E22CE;
    --public-accent-strong: #5b21b6;
    --public-bg: #faf5ff;
    --public-surface: #ffffff;
    --public-soft: #f3e8ff;
    --public-ink: #000000;
    --public-muted: #000000;
    gap: 22px;
}

.public-site-hero {
    position: relative;
    grid-template-columns: minmax(0, 0.9fr) minmax(300px, 0.46fr);
    min-height: min(76vh, 720px);
    overflow: hidden;
    padding: clamp(24px, 4vw, 56px);
    border: 0;
    background: #102329;
    color: #ffffff;
}

.public-site-hero-media {
    position: absolute;
    inset: 0;
    z-index: 0;
}

.public-site-hero-media::after {
    content: "";
    position: absolute;
    inset: 0;
    background:
        linear-gradient(90deg, rgba(8, 26, 31, 0.92) 0%, rgba(8, 26, 31, 0.72) 42%, rgba(8, 26, 31, 0.22) 100%),
        linear-gradient(0deg, rgba(8, 26, 31, 0.62), rgba(8, 26, 31, 0.08));
}

.public-site-hero-media img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.public-site-copy,
.public-site-visual {
    position: relative;
    z-index: 1;
}

.public-site-copy {
    align-content: center;
    gap: 20px;
}

.public-brand-row {
    color: #75d6df;
}

.public-site-copy h1 {
    max-width: 760px;
    color: #ffffff;
    font-size: clamp(44px, 7vw, 88px);
}

.public-site-copy p {
    max-width: 620px;
    color: #ffffff;
}

.public-site-visual {
    align-self: end;
    display: grid;
    gap: 12px;
    min-height: 0;
    overflow: visible;
    background: transparent;
}

.public-availability-card,
.public-quick-card,
.public-hours-card {
    display: grid;
    gap: 5px;
    padding: 18px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.92);
    color: #000000;
    box-shadow: 0 20px 46px rgba(0, 0, 0, 0.18);
}

.public-quick-card {
    transform: translateX(-28px);
}

.public-hours-card {
    transform: translateX(-8px);
}

.public-availability-card span,
.public-quick-card span,
.public-hours-card span {
    color: var(--public-accent);
    font-size: 12px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-availability-card strong,
.public-quick-card strong,
.public-hours-card strong {
    color: #000000;
    font-size: clamp(28px, 4vw, 46px);
    line-height: 1;
}

.public-hours-card strong {
    font-size: 20px;
    line-height: 1.25;
}

.public-availability-card small,
.public-quick-card small,
.public-hours-card small {
    color: #000000;
    font-weight: 700;
}

.public-hero-stats span {
    border-color: rgba(255, 255, 255, 0.16);
    background: rgba(255, 255, 255, 0.1);
    color: #ffffff;
}

.public-hero-stats strong {
    color: #ffffff;
}

.public-site-grid article,
.public-rate-list article,
.public-site-section,
.public-site-contact,
.public-price-result {
    box-shadow: 0 16px 38px rgba(15, 35, 41, 0.08);
}

.payment-return-page {
    min-height: 100vh;
    background: var(--surface-soft);
}

.payment-return {
    display: grid;
    place-items: center;
    min-height: 100vh;
    padding: 24px;
}

.account-payment {
    display: grid;
    place-items: center;
    min-height: 100vh;
    padding: 24px;
}

.payment-return > img {
    width: min(220px, 64vw);
    margin-bottom: 18px;
}

.account-payment > img {
    width: min(220px, 64vw);
    margin-bottom: 18px;
}

.payment-return-panel {
    width: min(560px, 100%);
}

.account-payment-panel {
    width: min(640px, 100%);
