.calculation-summary {
    display: grid;
    gap: 8px;
    margin-bottom: 12px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
}

.calculation-summary pre {
    margin: 0;
    color: var(--muted);
    font: inherit;
    white-space: pre-wrap;
}

.message-box {
    width: 100%;
    min-height: 220px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    line-height: 1.45;
    resize: vertical;
}

.plan-checkout-body {
    min-height: 100vh;
    background: #f6f9f9;
    color: var(--ink);
}

.plan-checkout {
    display: grid;
    gap: 22px;
    width: min(1320px, calc(100% - 32px));
    margin: 0 auto;
    padding: 28px 0 42px;
}

.plan-checkout-head {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 18px;
    align-items: center;
    padding: 22px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #ffffff;
    box-shadow: var(--shadow-card);
}

.plan-checkout-brand {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    color: var(--ink);
    font-family: var(--font-brand);
    font-weight: var(--font-semibold);
}

.plan-checkout-brand .brand-mark {
    width: clamp(58px, 5vw, 70px);
    height: clamp(58px, 5vw, 70px);
    object-fit: contain;
}

.plan-checkout-brand .brand-wordmark {
    width: clamp(190px, 24vw, 290px);
    max-width: 46vw;
    height: auto;
    object-fit: contain;
}

.plan-checkout-head h1 {
    margin: 0;
    font-family: var(--font-title);
    font-size: clamp(18px, 2vw, 23px);
    font-weight: var(--font-semibold);
    line-height: 1.15;
}

.plan-checkout-head p {
    max-width: 760px;
    margin: 8px 0 0;
    color: var(--muted);
    font-size: 16px;
}

.plan-period-toggle {
    display: inline-grid;
    grid-template-columns: repeat(2, minmax(98px, 1fr));
    gap: 3px;
    padding: 3px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--brand-primary-soft);
}

.plan-period-toggle label,
.plan-option {
    cursor: pointer;
}

.plan-period-toggle input,
.plan-option input {
    position: fixed;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}

.plan-period-toggle span,
.plan-period-toggle label {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 32px;
    border-radius: 6px;
    color: var(--ink);
    font-size: 14px;
    font-weight: var(--font-semibold);
}

.plan-period-toggle label:has(input:checked) {
    background: var(--brand-neutral);
    color: #ffffff;
}

.plan-checkout-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(320px, 380px);
    gap: 18px;
    align-items: start;
}

.plan-picker,
.plan-summary {
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #ffffff;
    box-shadow: var(--shadow-card);
}

.plan-picker {
    overflow: hidden;
}

.plan-picker-row {
    display: grid;
    grid-template-columns: minmax(150px, 0.95fr) repeat(5, minmax(104px, 1fr));
    gap: 0;
    border-top: 1px solid var(--line);
}

.plan-picker-row:first-child {
    border-top: 0;
}

.plan-picker-heading {
    background: var(--brand-neutral);
    color: #ffffff;
    font-size: 12px;
    font-weight: var(--font-semibold);
    text-transform: uppercase;
}

.plan-picker-heading span,
.plan-picker-module,
.plan-option {
    min-height: 76px;
    padding: 14px;
    border-left: 1px solid var(--line);
}

.plan-picker-heading span:first-child,
.plan-picker-module {
    border-left: 0;
}

.plan-picker-module {
    display: flex;
    align-items: center;
    color: var(--ink);
    font-size: 18px;
    font-weight: var(--font-semibold);
}

.plan-option {
    display: grid;
