    border-radius: 8px;
    padding: 12px 14px;
    font-weight: 600;
}

.landing-contact-notice.is-ok {
    background: rgba(109, 40, 217, 0.1);
    color: var(--brand-workraken);
}

.landing-contact-notice.is-error {
    background: rgba(191, 72, 72, 0.1);
    color: #9f2f2f;
}

.landing-final {
    display: grid;
    grid-template-columns: minmax(300px, 0.9fr) minmax(0, 1fr);
    gap: 40px;
    align-items: center;
