    padding-bottom: 100px;
}

.landing-final img {
    width: 100%;
    max-height: 360px;
    object-fit: contain;
}

.landing-final > div {
    display: grid;
    gap: 18px;
}

.landing-bottom-bar {
    background:
        radial-gradient(circle at 18% 18%, rgba(109, 40, 217, 0.34), transparent 32%),
        linear-gradient(135deg, #17061F 0%, #4A155F 52%, #260B32 100%);
    color: #ffffff;
}

.landing-bottom-inner {
    display: grid;
    gap: clamp(9px, 1.25vw, 14px);
    padding: clamp(18px, 2.35vw, 25px) var(--landing-section-inline) clamp(11px, 1.45vw, 14px);
}

.landing-bottom-main {
    display: grid;
    grid-template-columns: minmax(280px, 1.18fr) minmax(170px, 0.58fr) minmax(260px, 0.82fr) minmax(180px, 0.54fr);
    gap: clamp(16px, 2.7vw, 38px);
    align-items: start;
}

.landing-bottom-brand,
.landing-bottom-column {
    display: grid;
    gap: 8px;
