    flex: 0 0 auto;
    width: 60px;
    height: 60px;
    border-radius: 7px;
    background: transparent;
}

.landing-bottom-logo img {
    display: block;
    width: 60px;
    height: 60px;
    object-fit: contain;
}

.landing-bottom-wordmark {
    display: block;
    flex: 0 0 auto;
    width: clamp(124px, 10vw, 144px);
    height: auto;
    object-fit: contain;
}

.landing-bottom-brand p {
    max-width: 300px;
    margin: 0;
    color: #ffffff;
    font-size: clamp(12px, 0.95vw, 14px);
    font-weight: 400;
    line-height: 1.22;
}

.landing-bottom-column h2 {
    margin: 0;
    color: #DDA6F7;
    font-family: var(--font-title);
    font-size: clamp(14px, 1.08vw, 15px);
    font-weight: 400;
    line-height: 1.1;
}

.landing-bottom-column a {
    color: #ffffff;
    font-size: clamp(12px, 1vw, 14px);
    font-weight: 400;
    line-height: 1.2;
    text-decoration: none;
}

.landing-bottom-product,
.landing-bottom-legal nav {
    gap: 6px;
}

.landing-bottom-column a:hover {
    color: #ffffff;
    opacity: 1;
}

.landing-bottom-email {
    display: inline-flex;
    align-items: center;
    gap: 7px;
}

.landing-bottom-email svg {
    flex: 0 0 auto;
    width: 16px;
    height: 16px;
    color: #DDA6F7;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.landing-bottom-legal {
    gap: 14px;
}

.landing-bottom-legal nav {
    display: grid;
}

.landing-bottom-socials {
    display: grid;
    grid-template-columns: repeat(4, 34px);
    justify-content: start;
    gap: 8px;
}

.landing-bottom-social {
    display: inline-grid;
    place-items: center;
    width: 34px;
    height: 34px;
    border: 1.5px solid #DDA6F7;
    border-radius: 999px;
    color: #ffffff;
    text-decoration: none;
}

.landing-bottom-social:hover {
    background: rgba(109, 40, 217, 0.22);
}

.landing-bottom-social img {
    display: block;
    width: 20px;
    height: 20px;
    object-fit: contain;
}

.landing-bottom-copy {
    margin: 0;
    padding-top: clamp(8px, 1.05vw, 12px);
    border-top: 1px solid rgba(255, 255, 255, 0.25);
    color: #ffffff;
    font-size: clamp(11px, 0.85vw, 13px);
    font-weight: 400;
    line-height: 1.15;
    text-align: center;
}

.module-public-hero {
