}

.module-plan-card li {
    position: relative;
    padding-left: 22px;
    color: var(--muted);
}

.module-plan-card li::before {
    position: absolute;
    top: 8px;
    left: 0;
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: var(--brand-primary);
    content: "";
}

