/* Landing layout alignment */
.landing-page {
    /* Paleta WorKraken: el purpura electrico es el color principal. */
    --brand-primary: #6D28D9;
    --brand-primary-soft: #E9D5FF;
    --brand-workraken: #6D28D9;
    --brand-workraken-soft: #E9D5FF;
    --accent-violet: #6D28D9;
    --accent-purple: #7C4DFF;
    --accent-teal: #7C4DFF;
    --accent-amber: #F2A900;
    --accent-amber-text: #9A5D00;
    --accent-rose: #E34B8A;
    --accent-blue: #2F6BFF;
    --landing-lilac: #DDA6F7;
    --landing-canvas: #FFFFFF;
    --landing-canvas-soft: #FCFBFE;
    --landing-plum: #2C0E3A;
    --landing-plum-deep: #17061F;
    --landing-night: #13091A;
    --landing-night-surface: #21102A;
    --landing-max: 1400px;
    --landing-gutter: clamp(16px, 3vw, 48px);
    --landing-container-max: calc(var(--landing-max) + var(--landing-gutter) + var(--landing-gutter));
    --landing-nav-inline: max(var(--landing-gutter), calc((100vw - var(--landing-container-max)) / 2 + var(--landing-gutter)));
    --landing-nav-space: 96px;
    --landing-brand-wordmark-width: clamp(144px, 13.8vw, 180px);
    --landing-brand-mark-size: clamp(60.3px, 5.78vw, 75.4px);
    --landing-section-space: clamp(58px, 7vw, 88px);
    --landing-compact-section-space: clamp(29px, 3.5vw, 44px);
    width: 100%;
    max-width: none;
    min-height: 100vh;
    overflow-x: hidden;
    color: var(--ink);
    zoom: 1;
}

.landing-page img {
    max-width: 100%;
}

.landing-hero {
    position: relative;
    isolation: isolate;
    display: grid;
    grid-template-columns: minmax(0, 1.08fr) minmax(360px, 0.92fr);
    grid-template-areas: "copy art";
    gap: clamp(18px, 3vw, 42px);
    align-items: center;
    width: 100%;
    max-width: var(--landing-container-max);
    min-height: 0;
    overflow: visible;
    margin: 0 auto;
    padding: 24px var(--landing-gutter) clamp(54px, 7vw, 78px);
    background: transparent;
}

.landing-hero::before {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 50%;
    z-index: -1;
    width: 100vw;
    background: var(--landing-canvas);
    content: "";
    transform: translateX(-50%);
}

.landing-hero::after {
    display: none;
}

.landing-hero .landing-nav {
    grid-area: nav;
    width: 100%;
    max-width: none;
    padding: 0;
}

.landing-nav {
    max-width: var(--landing-container-max);
    margin-right: auto;
    margin-left: auto;
}

.landing-brand .brand-mark {
    width: var(--landing-brand-mark-size);
    height: var(--landing-brand-mark-size);
}

.landing-brand .brand-wordmark {
    width: var(--landing-brand-wordmark-width);
    max-width: none;
}

.landing-nav-links {
    flex-wrap: wrap;
    justify-content: center;
    justify-self: center;
    gap: 12px 22px;
    font-size: 17px;
}

.landing-nav-links > a,
.landing-nav-menu > summary,
.landing-nav-menu > div a {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
}

.landing-nav-actions {
    justify-content: flex-end;
    gap: 12px;
}

.landing-mobile-menu-toggle {
    display: none;
}

.landing-command,
.landing-register {
    font-size: 16px;
}

.landing-hero-copy {
    grid-area: copy;
    width: 100%;
    max-width: none;
    margin: 0;
    padding-right: 0;
}

.landing-hero-copy .eyebrow {
    color: var(--ink);
    max-width: 760px;
    font-size: clamp(36px, 3.5vw, 48px);
    line-height: 1.1;
}

.landing-hero-copy .eyebrow span {
    white-space: normal;
}

.landing-hero-copy p:not(.eyebrow) {
    max-width: 620px;
    white-space: normal;
}

.landing-hero-art {
    position: relative;
    grid-area: art;
    z-index: 1;
    inset: auto;
    justify-self: end;
    width: min(100%, 640px);
    max-width: 100%;
    max-height: 500px;
    object-fit: contain;
    filter: drop-shadow(0 22px 34px rgba(109, 40, 217, 0.16));
}

.landing-trust,
.landing-section,
.landing-feature,
.landing-final {
    width: 100%;
    max-width: var(--landing-container-max);
    margin-right: auto;
    margin-left: auto;
    padding-right: var(--landing-gutter);
    padding-left: var(--landing-gutter);
}

.landing-trust {
    align-items: stretch;
    max-width: var(--landing-container-max);
    margin-top: -24px;
    margin-bottom: clamp(44px, 5vw, 72px);
}

.landing-trust article,
.benefit-grid article,
.faq-grid article,
.price-card {
    height: 100%;
}

.landing-section,
.landing-feature,
.landing-final {
    padding-top: var(--landing-section-space);
    padding-bottom: var(--landing-section-space);
}

.landing-section-head,
.landing-contact-head {
    max-width: 760px;
}

.landing-benefits .landing-section-head {
    gap: 20px;
    max-width: 700px;
    margin-bottom: 0;
}

.landing-benefits .landing-section-head h2 span {
    display: block;
}

.pricing-grid {
    align-items: stretch;
}

.landing-benefits {
    display: grid;
    grid-template-columns: minmax(0, 0.9fr) minmax(380px, 0.74fr);
    gap: clamp(34px, 5vw, 78px);
    align-items: center;
}

.landing-benefits .landing-section-head p:not(.eyebrow) {
    max-width: 660px;
    font-size: clamp(16px, 1.25vw, 18px);
    line-height: 1.52;
}

.benefit-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: clamp(18px, 2.6vw, 28px);
    align-items: start;
}

.benefit-grid article {
    display: grid;
    grid-template-columns: minmax(74px, 0.2fr) minmax(0, 1fr);
    gap: clamp(18px, 2.8vw, 28px);
    align-items: start;
    height: auto;
    min-height: 0;
    overflow: visible;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

.benefit-grid article::before {
    display: none;
}

.benefit-grid span {
    display: block;
    color: #E34B8A;
    font-family: var(--font-title);
    font-size: clamp(52px, 7vw, 82px);
    font-weight: var(--font-semibold);
    line-height: 0.85;
    letter-spacing: 0;
}

.landing-benefits.is-scroll-motion-ready .benefit-grid article {
    opacity: 0;
    transform: translateX(-76px);
    will-change: transform, opacity;
}

.landing-benefits.is-scroll-motion-visible .benefit-grid article {
    animation: benefitBlockEnter 0.78s cubic-bezier(0.18, 0.84, 0.28, 1) var(--scroll-motion-delay, 0s) both;
}

.landing-benefits .benefit-grid article:nth-child(1) {
    --scroll-motion-delay: 0s;
}

.benefit-grid article:nth-child(2) span {
    color: #6D28D9;
}

.landing-benefits .benefit-grid article:nth-child(2) {
    --scroll-motion-delay: 0.13s;
}

.benefit-grid article:nth-child(3) span {
    color: #F2A900;
}

.landing-benefits .benefit-grid article:nth-child(3) {
    --scroll-motion-delay: 0.26s;
}

.benefit-grid article:nth-child(4) span {
    color: #2F6BFF;
}

.landing-benefits .benefit-grid article:nth-child(4) {
    --scroll-motion-delay: 0.39s;
}

@keyframes benefitBlockEnter {
    0% {
        opacity: 0;
        transform: translateX(-76px);
    }

    72% {
        opacity: 1;
        transform: translateX(6px);
    }

    100% {
        opacity: 1;
        transform: translateX(0);
    }
}

@media (prefers-reduced-motion: reduce) {
    .landing-trust.is-scroll-motion-visible article,
    .landing-benefits.is-scroll-motion-visible .benefit-grid article,
    .landing-faq.is-scroll-motion-visible .faq-grid summary {
        animation: none;
    }

    .landing-trust.is-scroll-motion-ready article,
    .landing-benefits.is-scroll-motion-ready .benefit-grid article,
    .landing-faq.is-scroll-motion-ready .faq-grid summary {
        opacity: 1;
        transform: none;
        filter: none;
        will-change: auto;
    }
}

.benefit-grid h3 {
    margin-top: 6px;
    font-size: clamp(20px, 2vw, 24px);
    line-height: 1.12;
}

.benefit-grid p {
    max-width: 460px;
    margin-top: 8px;
    font-size: 17px;
    line-height: 1.45;
