    margin-left: auto;
    padding-right: var(--landing-gutter);
    padding-left: var(--landing-gutter);
}

.references-track {
    align-items: stretch;
    padding-top: 0;
    padding-bottom: 0;
}

.reference-card {
    height: 100%;
}

.landing-page .reference-control {
    width: 44px;
    height: 44px;
    min-width: 44px;
    min-height: 44px;
}

.landing-pricing {
    padding-top: var(--landing-section-space);
    padding-bottom: var(--landing-section-space);
    background: var(--brand-neutral);
    box-shadow: 0 0 0 100vmax var(--brand-neutral);
    clip-path: inset(0 -100vmax);
    color: #fff;
}

.landing-benefits,
.landing-references,
.landing-pricing,
.landing-faq,
.landing-contact {
    padding-top: var(--landing-compact-section-space);
    padding-bottom: var(--landing-compact-section-space);
}

.pricing-inner {
    display: grid;
    gap: 18px;
}

.landing-faq-inner,
.landing-contact > .landing-contact-head,
.landing-contact > .landing-contact-form {
    width: 100%;
    max-width: var(--landing-container-max);
    margin-right: auto;
    margin-left: auto;
    padding-right: var(--landing-gutter);
    padding-left: var(--landing-gutter);
}

.landing-contact > .landing-contact-head h2 {
    max-width: 760px;
}

.pricing-head {
    width: 100%;
    max-width: none;
    grid-template-columns: minmax(0, 1fr) minmax(0, 660px);
    align-items: end;
    margin-bottom: 6px;
}

.pricing-head h2,
.pricing-head p {
    max-width: 760px;
}

.pricing-controls {
    justify-self: end;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    justify-items: end;
    gap: 10px;
    max-width: 660px;
    width: 100%;
}

.price-card {
    grid-template-rows: auto auto minmax(var(--price-plan-list-min), 1fr) auto;
}

.landing-pricing.is-single-module .price-card {
    grid-template-rows: auto auto minmax(var(--price-plan-list-min), 1fr) auto;
    align-content: stretch;
}

.landing-pricing.is-single-module .price-card a {
    align-self: end;
    margin-top: 6px;
}

.landing-pricing.is-single-module {
    --price-plan-list-min: clamp(66px, 5vw, 88px);
}

.landing-pricing.is-two-modules {
    --price-plan-list-min: clamp(112px, 7vw, 138px);
}

.landing-pricing.is-three-modules {
    --price-plan-list-min: clamp(150px, 9vw, 178px);
}

.price-card a {
    height: 48px;
    min-height: 48px;
    padding-top: 0;
    padding-bottom: 0;
}

.landing-contact-form {
    width: 100%;
    max-width: none;
}

.landing-final {
    grid-template-columns: minmax(320px, 0.9fr) minmax(0, 1fr);
}

.landing-bottom-inner {
    width: 100%;
    max-width: var(--landing-container-max);
    margin-right: auto;
    margin-left: auto;
    padding-right: var(--landing-gutter);
    padding-left: var(--landing-gutter);
}

.landing-bottom-navigation {
    gap: 20px;
}

.landing-bottom-pricing a {
    color: inherit;
    font: inherit;
}

.module-public-hero {
    padding-right: var(--landing-gutter);
    padding-left: var(--landing-gutter);
}

.module-public-hero .landing-nav,
.module-public-hero-inner,
.module-public-section {
    width: 100%;
    max-width: var(--landing-container-max);
    margin-right: auto;
    margin-left: auto;
    padding-right: var(--landing-gutter);
    padding-left: var(--landing-gutter);
}

.module-public-hero .landing-nav,
.module-public-hero-inner {
    padding-right: 0;
    padding-left: 0;
}

.landing-page .landing-hero,
.landing-page .module-public-hero {
    padding-top: calc(var(--landing-nav-space) + 24px);
}

.landing-page .landing-nav {
    position: fixed;
    top: 0;
    right: 0;
    left: 0;
    z-index: 1000;
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 8px var(--landing-nav-inline);
    border-bottom: 1px solid rgba(109, 40, 217, 0.16);
    background: rgba(255, 255, 255, 0.94);
    box-shadow: 0 1px 0 rgba(43, 47, 51, 0.04);
    opacity: 1;
    transform: translateY(0);
    visibility: visible;
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    transition: padding 0.22s ease, background 0.22s ease, box-shadow 0.22s ease, opacity 0.18s ease, transform 0.22s ease, visibility 0s linear;
}

.landing-theme-toggle {
    display: inline-grid;
    place-items: center;
    flex: 0 0 auto;
    width: 44px;
    height: 44px;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--ink);
    cursor: pointer;
    box-shadow: none;
    transition: background 0.22s ease, border-color 0.22s ease, color 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease, width 0.22s ease, height 0.22s ease;
}

.landing-theme-toggle span {
    font-size: 19px;
    line-height: 1;
}

.landing-theme-toggle:hover {
    background: transparent;
    color: var(--brand-primary);
    box-shadow: none;
    transform: translateY(-1px);
}

.landing-theme-toggle:focus-visible {
    outline: 3px solid rgba(109, 40, 217, 0.28);
    outline-offset: 3px;
}

.landing-page .landing-brand .brand-mark,
.landing-page .landing-brand .brand-wordmark,
.landing-page .landing-nav-links,
.landing-page .landing-nav-actions,
.landing-page .landing-command,
.landing-page .landing-register,
.landing-page .landing-theme-toggle {
    transition: width 0.22s ease, height 0.22s ease, font-size 0.22s ease, gap 0.22s ease, min-height 0.22s ease, padding 0.22s ease, opacity 0.22s ease, background 0.22s ease, border-color 0.22s ease, color 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease;
}

.landing-page.is-nav-compact .landing-nav {
    --landing-brand-wordmark-width: clamp(120px, 10.8vw, 144px);
    --landing-brand-mark-size: clamp(50.2px, 4.52vw, 60.3px);
    padding-top: 6px;
    padding-bottom: 6px;
    background: rgba(255, 255, 255, 0.82);
    box-shadow: 0 14px 34px rgba(76, 22, 100, 0.15);
}

.landing-page.is-nav-compact .landing-nav-links {
    gap: 10px 18px;
    font-size: 16px;
}

.landing-page.is-nav-compact .landing-command,
.landing-page.is-nav-compact .landing-register {
    min-height: 38px;
    padding-right: 12px;
    padding-left: 12px;
    font-size: 14px;
}

.landing-page.is-nav-compact .landing-theme-toggle {
    width: 44px;
    height: 44px;
}

.landing-page.is-nav-hidden .landing-nav {
    opacity: 0;
    transform: translateY(-100%);
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.18s ease, transform 0.22s ease, visibility 0s linear 0.22s;
}

.landing-page section[id] {
    scroll-margin-top: calc(var(--landing-nav-space) + 18px);
}

.landing-page #contacto {
    scroll-margin-top: 0;
}

.legal-document {
    display: grid;
    gap: clamp(26px, 4vw, 42px);
    max-width: min(100%, 960px);
    padding-top: calc(var(--landing-nav-space) + clamp(36px, 5vw, 64px));
    padding-bottom: clamp(56px, 7vw, 88px);
}

.legal-document-head {
    display: grid;
    gap: 12px;
}

.legal-document-head h1 {
    margin: 0;
    color: var(--ink);
    font-family: var(--font-title);
    font-size: clamp(36px, 5vw, 58px);
    font-weight: 600;
    line-height: 1.04;
}

.legal-document-head p {
    max-width: 780px;
    margin: 0;
    color: var(--muted);
    font-size: clamp(16px, 1.3vw, 18px);
    line-height: 1.58;
}

.legal-document-head .eyebrow {
    color: var(--brand-primary);
}

.legal-document-head .legal-updated {
    color: var(--ink);
    font-weight: 600;
}

.legal-index {
    display: grid;
    gap: 14px;
    padding: 20px 0;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
}

.legal-index h2 {
    margin: 0;
    color: var(--ink);
    font-family: var(--font-title);
    font-size: 22px;
    font-weight: 600;
    line-height: 1.16;
}

.legal-index ol {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px 28px;
    margin: 0;
    padding-left: 20px;
    color: var(--muted);
    line-height: 1.45;
}

.legal-index a {
    color: var(--ink);
    font-weight: 600;
    text-decoration: none;
}

.legal-index a:hover {
    color: var(--brand-primary);
}

.legal-document-content {
    display: grid;
    gap: clamp(28px, 4vw, 44px);
}

.legal-document-content section {
    display: grid;
    gap: 11px;
}

.legal-document-content h2 {
    margin: 0;
    color: var(--ink);
    font-family: var(--font-title);
    font-size: clamp(22px, 2.6vw, 30px);
    font-weight: 600;
    line-height: 1.16;
}

.legal-document-content p,
.legal-document-content li {
    color: var(--muted);
    font-size: clamp(15px, 1.12vw, 17px);
    line-height: 1.68;
}

.legal-document-content p {
    margin: 0;
}

.legal-document-content ul {
    display: grid;
    gap: 8px;
    margin: 0;
    padding-left: 20px;
}

.legal-contact-links {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.legal-contact-links a {
    color: var(--ink);
    font-size: clamp(15px, 1.12vw, 17px);
    font-weight: 700;
    line-height: 1.6;
    text-decoration: none;
}

.legal-contact-links a:hover {
    color: var(--brand-primary);
}

.landing-faq-inner {
    display: grid;
    grid-template-columns: minmax(0, 0.95fr) minmax(320px, 0.72fr);
    gap: clamp(34px, 5vw, 72px);
    align-items: center;
}

.landing-faq-content {
    min-width: 0;
}

.landing-faq .landing-section-head {
    max-width: none;
    margin-bottom: 16px;
    text-align: left;
}

.landing-faq .landing-section-head h2 {
    max-width: none;
    font-size: 36.1px;
}

.landing-faq .faq-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0;
}

.landing-faq-art {
    width: 100%;
    max-width: 520px;
    justify-self: end;
    object-fit: contain;
    filter: drop-shadow(0 18px 28px rgba(109, 40, 217, 0.16));
}

.faq-grid details {
    border-top: 1px solid rgba(196, 209, 212, 0.78);
}

.faq-grid details:last-child {
    border-bottom: 1px solid rgba(196, 209, 212, 0.78);
}

.faq-grid summary {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 18px;
    align-items: center;
    padding: 22px 0;
    color: var(--ink);
    font-family: var(--font-title);
    font-size: clamp(20px, 2vw, 24px);
    font-weight: 600;
    line-height: 1.2;
    cursor: pointer;
    list-style: none;
}

.landing-faq .faq-grid details:nth-child(1) summary {
    --scroll-motion-delay: 0s;
}

.landing-faq .faq-grid details:nth-child(2) summary {
    --scroll-motion-delay: 0.13s;
}

.landing-faq .faq-grid details:nth-child(3) summary {
    --scroll-motion-delay: 0.26s;
}

.landing-faq .faq-grid details:nth-child(4) summary {
    --scroll-motion-delay: 0.39s;
}

.landing-faq.is-scroll-motion-ready .faq-grid summary {
    opacity: 0;
    transform: translateX(-76px);
    will-change: transform, opacity;
}

.landing-faq.is-scroll-motion-visible .faq-grid summary {
    animation: benefitBlockEnter 0.78s cubic-bezier(0.18, 0.84, 0.28, 1) var(--scroll-motion-delay, 0s) both;
}

.faq-grid summary::-webkit-details-marker {
    display: none;
}

.faq-grid summary::after {
    color: var(--brand-primary);
    font-size: 28px;
    font-weight: 400;
    line-height: 1;
    content: "+";
}

.faq-grid details[open] summary::after {
    content: "-";
}

.faq-grid details p {
    max-width: 760px;
    margin: -6px 0 22px;
    color: var(--muted);
    font-size: 17px;
    line-height: 1.5;
}

.landing-contact {
    background: #FFFFFF;
    box-shadow: 0 0 0 100vmax #FFFFFF;
}

.landing-contact > .landing-contact-form {
    display: grid;
    grid-template-columns: 1fr;
    gap: 24px;
    align-items: start;
    justify-content: center;
    justify-items: center;
    margin: 0 auto;
}

.landing-contact .landing-contact-head {
    max-width: none;
    margin-bottom: 0;
    text-align: center;
}

.landing-contact .landing-contact-head h2 {
    max-width: none;
    white-space: nowrap;
    font-size: clamp(34px, 3.4vw, 48px);
}

.landing-contact .landing-contact-fields {
    grid-area: fields;
    width: 100%;
}

.landing-contact .landing-contact-layout {
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-areas:
        "fields message"
        ". submit";
    gap: 14px clamp(26px, 4vw, 58px);
    align-items: stretch;
    justify-content: center;
}

.landing-contact .landing-contact-message {
    grid-area: message;
    grid-template-rows: minmax(0, 1fr);
    width: 100%;
}

.landing-contact .landing-message-field {
    grid-template-rows: auto minmax(0, 1fr);
}

.landing-contact .landing-message-field textarea {
    height: 100%;
    min-height: 178px;
}

.landing-contact .landing-contact-submit {
    grid-area: submit;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    justify-self: end;
    min-height: 48px;
    padding: 0 28px;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
}

.landing-contact-art {
    display: none;
}

.landing-cta-strip {
    padding: clamp(14px, 1.9vw, 22px) var(--landing-gutter);
    background: #EFE3FD;
}

.landing-cta-strip-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: clamp(22px, 4vw, 54px);
    width: 100%;
    max-width: var(--landing-container-max);
    margin: 0 auto;
}

.landing-cta-strip h2 {
    max-width: 760px;
    margin: 0;
    color: var(--ink);
    font-family: var(--font-title);
    font-size: clamp(20px, 2.05vw, 27px);
    font-weight: 400;
    line-height: 1.12;
    letter-spacing: 0;
}

.landing-cta-strip .landing-actions {
    flex: 0 0 auto;
    margin-top: 0;
}

.landing-cta-strip .landing-actions a {
    min-height: 36px;
    padding-right: 14px;
    padding-left: 14px;
    font-size: 14px;
    font-weight: 400;
}

.landing-contact-form input::placeholder,
.landing-contact-form textarea::placeholder {
    color: rgba(43, 47, 51, 0.48);
}

html[data-landing-theme="dark"] {
