    }

    .landing-page .landing-theme-toggle {
        order: 1;
        width: 44px;
        height: 44px;
        margin-left: auto;
    }

    .landing-mobile-menu-toggle {
        position: relative;
        order: 2;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 44px;
        height: 44px;
        flex: 0 0 44px;
        padding: 0;
        border: 1px solid var(--line-strong);
        border-radius: 8px;
        background: transparent;
        color: var(--ink);
        cursor: pointer;
    }

    .landing-mobile-menu-toggle > span {
        position: relative;
        display: block;
        width: 20px;
        height: 2px;
        border-radius: 999px;
        background: currentColor;
        transition: transform 0.18s ease, opacity 0.18s ease;
    }

    .landing-mobile-menu-toggle > span::before,
    .landing-mobile-menu-toggle > span::after {
        position: absolute;
        top: 0;
        left: 0;
        width: 20px;
        height: 2px;
        border-radius: 999px;
        background: currentColor;
        content: "";
        transform-origin: center;
        transition: transform 0.18s ease, opacity 0.18s ease;
    }

    .landing-mobile-menu-toggle > span::before {
        transform: translateY(-6px);
    }

    .landing-mobile-menu-toggle > span::after {
        transform: translateY(6px);
    }

    .landing-nav.is-mobile-menu-open .landing-mobile-menu-toggle > span {
        background: transparent;
    }

    .landing-nav.is-mobile-menu-open .landing-mobile-menu-toggle > span::before {
        transform: rotate(45deg);
    }

    .landing-nav.is-mobile-menu-open .landing-mobile-menu-toggle > span::after {
        transform: rotate(-45deg);
    }

    .landing-mobile-menu-toggle:is(:hover, :focus-visible) {
        border-color: rgba(109, 40, 217, 0.5);
        color: var(--brand-primary);
