    box-shadow: 0 14px 28px rgba(183, 121, 31, 0.24);
}

.module-plan-comparison-section {
    background: #f8fbfb;
}

.module-compare-scroll {
    border-color: rgba(196, 209, 212, 0.84);
    box-shadow: 0 12px 30px rgba(43, 47, 51, 0.07);
}

