/* Public parking landing: full-screen, long-form page */
.public-page {
    background: #ffffff;
}

.public-page .public-shell {
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 0;
}

.public-landing {
    --public-accent: #7E22CE;
    --public-accent-strong: #5b21b6;
    --public-highlight: #d9a441;
    --public-ink: #000000;
    --public-muted: #000000;
    --public-soft: #faf5ff;
    --public-line: #e9d5ff;
    display: block;
    position: relative;
    overflow: hidden;
    background: #ffffff;
    color: var(--public-ink);
}

.public-template-urbana {
    --public-accent: #0f766e;
    --public-accent-strong: #0a504b;
    --public-highlight: #f0b84f;
    --public-soft: #edf6f4;
}

.public-template-mapa {
    --public-accent: #146b4f;
    --public-accent-strong: #0b4a38;
    --public-highlight: #66b5bd;
    --public-soft: #eef7f1;
}

.public-template-compacta {
    --public-accent: #9f3341;
    --public-accent-strong: #762632;
    --public-highlight: #7E22CE;
    --public-soft: #f7f2f0;
}

.public-landing-hero {
    position: relative;
    isolation: isolate;
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    min-height: 100vh;
    min-height: 100svh;
    padding: 24px clamp(18px, 4vw, 64px) 32px;
    overflow: hidden;
    background: #0b242b;
    color: #ffffff;
}

.public-landing-media {
    position: absolute;
    inset: 0;
    z-index: -2;
}

.public-landing-media::after {
    position: absolute;
    inset: 0;
    z-index: 1;
    background: rgba(7, 26, 31, 0.72);
    content: "";
}

.public-landing-media img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.public-landing-nav {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    width: min(100%, 1760px);
    margin: 0 auto;
}

.public-landing-brand {
    display: inline-flex;
    align-items: center;
    min-width: 0;
    gap: 14px;
    color: #ffffff;
}

.public-landing-brand img,
.public-landing-brand > span {
    width: 64px;
    height: 64px;
    border: 1px solid rgba(255, 255, 255, 0.24);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.14);
    object-fit: cover;
}

.public-landing-brand > span {
    display: grid;
    place-items: center;
    color: #ffffff;
    font-size: 22px;
    font-weight: 900;
}

.public-landing-brand strong {
    display: block;
    max-width: 380px;
    overflow: hidden;
    color: #ffffff;
    font-size: 24px;
    line-height: 1.05;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.public-landing-links {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.12);
}

.public-landing-links a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 42px;
    padding: 0 14px;
    border-radius: 8px;
    color: #ffffff;
    font-weight: 800;
}

.public-landing-links a:hover {
    background: rgba(255, 255, 255, 0.14);
    color: #ffffff;
}

.public-landing-links .public-landing-nav-cta {
    background: #ffffff;
    color: var(--public-accent-strong);
}

.public-landing-hero-inner {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(360px, 470px);
    align-items: center;
    gap: clamp(28px, 4vw, 72px);
    width: min(100%, 1760px);
    margin: 0 auto;
    padding: 48px 0 28px;
}

.public-landing-copy {
    display: grid;
    gap: 22px;
    max-width: 940px;
}

.public-landing-section-head > span,
.public-landing-panel-copy > span,
.public-landing-calculator-head > span {
    color: #69d4dd;
    font-size: 14px;
    font-weight: 900;
    letter-spacing: 0;
    text-transform: uppercase;
}

.public-landing-copy h1 {
    margin: 0;
    color: #ffffff;
    font-family: var(--font-title);
    font-size: 92px;
    font-weight: 700;
    line-height: 0.94;
    letter-spacing: 0;
    overflow-wrap: anywhere;
}

.public-landing-copy p {
    max-width: 740px;
    margin: 0;
    color: #ffffff;
    font-size: 22px;
    line-height: 1.45;
}

.public-landing-actions,
.public-landing-contact-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
}

.public-landing-primary,
.public-landing-secondary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 52px;
    padding: 0 22px;
    border-radius: 8px;
    font-size: 17px;
    font-weight: 900;
}

.public-landing-primary {
    border: 1px solid var(--public-accent);
    background: var(--public-accent);
    color: #ffffff;
    box-shadow: 0 18px 38px rgba(126, 34, 206, 0.28);
}

.public-landing-primary:hover {
    background: var(--public-accent-strong);
    color: #ffffff;
}

.public-landing-secondary {
    border: 1px solid rgba(255, 255, 255, 0.26);
    background: rgba(255, 255, 255, 0.12);
    color: #ffffff;
}

.public-landing-secondary:hover {
    background: rgba(255, 255, 255, 0.2);
    color: #ffffff;
}

.public-whatsapp-link {
    gap: 9px;
}

.public-whatsapp-link svg {
    width: 20px;
    height: 20px;
    flex: 0 0 auto;
    fill: currentColor;
}

.public-landing-nav-cta.public-whatsapp-link {
    background: #25d366;
    color: #083b1f;
}

.public-landing-nav-cta.public-whatsapp-link:hover {
    background: #35df73;
    color: #052b17;
}

.public-whatsapp-float {
    position: fixed;
    right: 26px;
    bottom: 26px;
    z-index: 80;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 64px;
    height: 64px;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, 0.32);
    border-radius: 999px;
    background: var(--whatsapp-brand-green);
    color: #ffffff;
    font-weight: 900;
    box-shadow: 0 18px 42px rgba(5, 43, 23, 0.24);
}

.public-whatsapp-float:hover {
    background: var(--whatsapp-brand-green);
    color: #ffffff;
    transform: translateY(-1px);
}

.public-whatsapp-float svg {
    width: 36px;
    height: 36px;
    fill: currentColor;
}

.public-whatsapp-float span {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
}

.public-page-owner-preview {
    position: relative;
}

.public-page-owner-preview .public-whatsapp-float {
    position: absolute;
    right: 34px;
    bottom: 34px;
}

.public-landing-hero-card {
    display: grid;
    gap: 14px;
    align-self: center;
    padding: 26px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.94);
    color: var(--public-ink);
    box-shadow: 0 28px 70px rgba(0, 0, 0, 0.28);
}

.public-landing-hero-card > span {
    color: var(--public-accent);
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-landing-hero-card > strong {
    color: var(--public-accent-strong);
    font-size: 92px;
    line-height: 0.9;
}

.public-landing-hero-card > small {
    color: var(--public-muted);
    font-size: 16px;
    font-weight: 800;
}

.public-landing-hero-card div {
    display: grid;
    gap: 10px;
    margin-top: 8px;
    padding-top: 18px;
    border-top: 1px solid var(--public-line);
}

.public-landing-hero-card p {
    display: grid;
    gap: 3px;
    margin: 0;
    color: var(--public-muted);
    font-weight: 700;
    line-height: 1.35;
}

.public-landing-hero-card b {
    color: var(--public-ink);
    font-size: 13px;
    text-transform: uppercase;
}

.public-landing-hero-strip {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    width: min(100%, 1760px);
    margin: 0 auto;
}

.public-landing-hero-strip article {
    display: grid;
    gap: 5px;
    min-width: 0;
    padding: 18px;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.12);
}

.public-landing-hero-strip span {
    color: #ffffff;
    font-size: 12px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-landing-hero-strip strong {
    color: #ffffff;
    font-size: 34px;
    line-height: 1;
}

.public-landing-section {
    width: min(100% - 64px, 1680px);
    margin: 0 auto;
    padding: 112px 0;
}

.public-landing-section-head {
    display: grid;
    gap: 14px;
    max-width: 920px;
    margin-bottom: 36px;
}

.public-landing-section-head > span,
.public-landing-panel-copy > span,
.public-landing-calculator-head > span {
    color: var(--public-accent);
}

.public-landing-section-head h2,
.public-landing-panel-copy h2,
.public-landing-contact h2 {
    margin: 0;
    color: var(--public-ink);
    font-family: var(--font-title);
    font-size: 58px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0;
}

.public-landing-section-head p,
.public-landing-panel-copy p,
.public-landing-contact p {
    max-width: 780px;
    margin: 0;
    color: var(--public-muted);
    font-size: 19px;
    line-height: 1.5;
}

.public-landing-intro {
    padding-top: 126px;
}

.public-landing-feature-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
}

.public-landing-feature-grid article,
.public-landing-rate-cards article {
    display: grid;
    gap: 14px;
    min-width: 0;
    padding: 28px;
    border: 1px solid var(--public-line);
    border-radius: 8px;
    background: #ffffff;
    box-shadow: 0 18px 44px rgba(20, 34, 41, 0.08);
}

.public-landing-feature-grid article > span {
    display: inline-grid;
    place-items: center;
    width: 44px;
    height: 44px;
    border-radius: 8px;
    background: var(--public-soft);
    color: var(--public-accent);
    font-weight: 900;
}

.public-landing-feature-grid h3 {
    margin: 0;
    color: var(--public-ink);
    font-size: 26px;
}

.public-landing-feature-grid p {
    margin: 0;
    color: var(--public-muted);
    font-size: 16px;
    line-height: 1.5;
}

.public-landing-vehicles,
.public-landing-location {
    display: grid;
    grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
    gap: 44px;
    align-items: center;
}

.public-landing-vehicles {
    width: 100%;
    max-width: none;
    padding: 118px max(32px, calc((100vw - 1680px) / 2));
    background: var(--public-soft);
}

.public-landing-panel-copy {
    display: grid;
    gap: 14px;
}

.public-landing-chip-wall {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 14px;
}

.public-landing-chip-wall span {
    min-height: 86px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 18px;
    border: 1px solid color-mix(in srgb, var(--public-accent) 22%, #ffffff);
    border-radius: 8px;
    background: #ffffff;
    color: var(--public-ink);
    font-size: 22px;
    font-weight: 900;
    text-align: center;
    box-shadow: 0 14px 34px rgba(20, 34, 41, 0.07);
}

.public-landing-models {
    display: grid;
    gap: 28px;
}

.public-landing-model-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
}

.public-landing-model-grid article {
    display: grid;
    gap: 12px;
    min-height: 188px;
    padding: 26px;
    border: 1px solid var(--public-line);
    border-radius: 8px;
    background: #ffffff;
    box-shadow: 0 14px 34px rgba(20, 34, 41, 0.07);
}

.public-landing-model-grid article span {
    color: var(--public-accent);
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-landing-model-grid article strong {
    color: var(--public-ink);
    font-size: 24px;
    line-height: 1.25;
    overflow-wrap: anywhere;
}

.public-landing-model-grid article small {
    align-self: end;
    color: var(--public-muted);
    font-size: 14px;
    font-weight: 800;
}

.public-landing-rates {
    display: grid;
    gap: 26px;
}

.public-landing-rate-cards {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px;
}

.public-landing-rate-cards article span {
    color: var(--public-accent);
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-landing-rate-cards article strong {
    color: var(--public-ink);
    font-size: 42px;
    line-height: 1;
}

.public-landing-rate-cards article small {
    color: var(--public-muted);
    font-weight: 800;
}

.public-landing-calculator {
    display: grid;
    gap: 22px;
    padding: 28px;
    border: 1px solid var(--public-line);
    border-radius: 8px;
    background: #f8fbfb;
    box-shadow: 0 18px 44px rgba(20, 34, 41, 0.08);
}

.public-landing-calculator-head {
    display: grid;
    gap: 4px;
}

.public-landing-calculator-head h3 {
    margin: 0;
    color: var(--public-ink);
    font-size: 34px;
    line-height: 1;
}

.public-landing .public-price-grid {
    grid-template-columns: minmax(190px, 0.85fr) repeat(2, minmax(260px, 1fr)) minmax(190px, 0.7fr);
    gap: 14px;
}

.public-landing .public-price-grid label,
.public-landing .public-price-grid .public-date-time-field {
    gap: 8px;
    color: var(--public-ink);
    font-size: 13px;
    font-weight: 900;
}

.public-landing .public-price-grid input,
.public-landing .public-price-grid select {
    min-height: 54px;
    border-color: var(--public-line);
    background: #ffffff;
    font-size: 16px;
}

.public-landing .public-price-grid button {
    min-height: 54px;
    background: var(--public-accent);
    font-size: 16px;
    font-weight: 900;
}

.public-landing .public-price-grid button:hover {
    background: var(--public-accent-strong);
}

.public-landing-result {
    margin-top: 0;
}

.public-landing-location {
    padding-top: 96px;
}

.public-landing-location .public-landing-secondary {
    border-color: var(--public-line);
    background: #ffffff;
    color: var(--public-accent);
}

.public-landing-location .public-landing-secondary:hover {
    border-color: var(--public-accent);
    background: var(--public-soft);
    color: var(--public-accent-strong);
}

.public-landing-map,
.public-landing-map-fallback {
    min-height: 560px;
    border: 1px solid var(--public-line);
    border-radius: 8px;
    background: var(--public-soft);
    box-shadow: 0 18px 44px rgba(20, 34, 41, 0.08);
}

.public-landing-map-fallback {
    display: grid;
    place-items: center;
    gap: 8px;
    padding: 28px;
    text-align: center;
}

.public-landing-map-fallback strong {
    color: var(--public-ink);
    font-size: 28px;
}

.public-landing-map-fallback span {
    color: var(--public-muted);
    font-weight: 800;
}

.public-landing-contact {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 28px;
    align-items: center;
    width: min(100% - 64px, 1680px);
    margin: 22px auto 0;
    padding: 56px;
    border-radius: 8px;
    background: #102329;
    color: #ffffff;
}

.public-landing-contact h2,
.public-landing-contact p {
    color: #ffffff;
}

.public-landing-contact p {
    color: #ffffff;
}

.public-landing-contact .public-landing-secondary {
    border-color: rgba(255, 255, 255, 0.22);
}

.public-landing-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    width: min(100% - 64px, 1680px);
    margin: 0 auto;
    padding: 34px 0;
    color: var(--public-muted);
}

.public-landing-footer strong {
    color: var(--public-ink);
    font-size: 18px;
}

.public-landing-footer small {
    color: var(--public-muted);
    font-weight: 700;
}

.public-page-owner-preview .public-landing-hero {
    min-height: 820px;
}

@media (max-width: 1160px) {
    .public-landing-copy h1 {
        font-size: 72px;
    }

    .public-landing-hero-inner,
    .public-landing-vehicles,
    .public-landing-location,
    .public-landing-contact {
        grid-template-columns: 1fr;
    }

    .public-landing-hero-card {
        max-width: 620px;
    }

    .public-landing .public-price-grid,
    .public-landing-model-grid,
    .public-landing-rate-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 840px) {
    .public-landing-hero {
        min-height: 100svh;
        padding: 18px 16px 22px;
    }

    .public-landing-nav {
        align-items: flex-start;
        flex-direction: column;
    }

    .public-landing-brand strong {
        max-width: calc(100vw - 116px);
        font-size: 20px;
    }

    .public-landing-links {
        width: 100%;
        flex-wrap: wrap;
        overflow-x: visible;
        justify-content: flex-start;
    }

    .public-landing-links a {
        flex: 1 1 calc(50% - 4px);
    }

    .public-landing-links .public-landing-nav-cta {
        flex-basis: 100%;
    }

    .public-landing-hero-inner {
        padding: 34px 0 22px;
    }

    .public-landing-copy h1 {
        font-size: 52px;
    }

    .public-landing-copy p {
        font-size: 18px;
    }

    .public-landing-hero-card {
        padding: 20px;
    }

    .public-landing-hero-card > strong {
        font-size: 68px;
    }

    .public-landing-hero-strip,
    .public-landing-feature-grid,
    .public-landing-chip-wall,
    .public-landing-model-grid,
    .public-landing .public-price-grid,
    .public-landing-rate-cards {
        grid-template-columns: 1fr;
    }

    .public-landing-section,
    .public-landing-contact,
    .public-landing-footer {
        width: min(100% - 32px, 1680px);
    }

    .public-landing-section {
        padding: 72px 0;
    }

    .public-landing-vehicles {
        padding: 72px 16px;
    }

    .public-landing-section-head h2,
    .public-landing-panel-copy h2,
    .public-landing-contact h2 {
        font-size: 40px;
    }

    .public-date-time {
        grid-template-columns: 1fr;
    }

    .public-landing-map,
    .public-landing-map-fallback {
        min-height: 360px;
    }

    .public-landing-contact {
        padding: 28px;
    }

    .public-landing-contact-actions,
    .public-landing-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .public-landing-primary,
    .public-landing-secondary {
        width: 100%;
    }

    .public-landing-footer {
        align-items: flex-start;
        flex-direction: column;
    }

    .public-whatsapp-float {
        right: 16px;
        bottom: 16px;
        width: 56px;
        height: 56px;
    }

    .public-whatsapp-float svg {
        width: 32px;
        height: 32px;
    }
}

@media (max-width: 520px) {
    .public-landing-copy h1 {
        font-size: 42px;
    }

    .public-landing-section-head h2,
    .public-landing-panel-copy h2,
    .public-landing-contact h2 {
        font-size: 34px;
    }

    .public-landing-rate-cards article strong {
        font-size: 34px;
    }
}

/* Bloques de colores del módulo: las funciones y los pasos ciclan la misma
   paleta viva que las tarjetas de la landing, en claro y en oscuro. */
.module-feature-list article:nth-child(4n + 1),
.module-step-list article:nth-child(4n + 1) {
    border-color: rgba(150, 106, 224, 0.42);
    background: #F1E4FE;
}

.module-feature-list article:nth-child(4n + 2),
.module-step-list article:nth-child(4n + 2) {
    border-color: rgba(242, 169, 0, 0.4);
    background: #FCEECC;
}

.module-feature-list article:nth-child(4n + 3),
.module-step-list article:nth-child(4n + 3) {
    border-color: rgba(47, 107, 255, 0.34);
    background: #DFE9FF;
}

.module-feature-list article:nth-child(4n),
.module-step-list article:nth-child(4n) {
    border-color: rgba(227, 75, 138, 0.36);
    background: #FBDFEA;
}

html[data-landing-theme="dark"] .module-feature-list article:nth-child(4n + 1),
html[data-landing-theme="dark"] .module-step-list article:nth-child(4n + 1) {
    border-color: rgba(173, 63, 227, 0.4);
    background: linear-gradient(180deg, rgba(173, 63, 227, 0.22) 0%, rgba(18, 9, 26, 0.97) 100%);
}

html[data-landing-theme="dark"] .module-feature-list article:nth-child(4n + 2),
html[data-landing-theme="dark"] .module-step-list article:nth-child(4n + 2) {
    border-color: rgba(218, 157, 65, 0.4);
    background: linear-gradient(180deg, rgba(183, 121, 31, 0.22) 0%, rgba(21, 16, 9, 0.97) 100%);
}

html[data-landing-theme="dark"] .module-feature-list article:nth-child(4n + 3),
html[data-landing-theme="dark"] .module-step-list article:nth-child(4n + 3) {
    border-color: rgba(92, 145, 255, 0.4);
    background: linear-gradient(180deg, rgba(37, 99, 235, 0.2) 0%, rgba(9, 13, 26, 0.97) 100%);
}

html[data-landing-theme="dark"] .module-feature-list article:nth-child(4n),
html[data-landing-theme="dark"] .module-step-list article:nth-child(4n) {
    border-color: rgba(224, 108, 124, 0.4);
    background: linear-gradient(180deg, rgba(190, 75, 91, 0.2) 0%, rgba(26, 9, 12, 0.97) 100%);
}

/* El resaltado violeta del borde en hover debe ganarle a los tintes por
