/* Public parking landing: four separate designs */
.public-design {
    --public-nav-height: 86px;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    background: #ffffff;
    color: #000000;
}

.public-design :is(h1, h2, h3, p) {
    margin: 0;
}

.public-design :is(h1, h2, h3) {
    font-family: var(--font-title);
    font-weight: 700;
    letter-spacing: 0;
}

.public-design a {
    text-decoration: none;
}

.public-design [data-public-block] {
    scroll-margin-top: calc(var(--public-nav-height) + 18px);
}

.public-design-brand {
    display: inline-flex;
    align-items: center;
    min-width: 0;
    gap: 8px;
    color: inherit;
}

.public-design-brand img,
.public-design-brand > span {
    width: 54px;
    height: 54px;
    flex: 0 0 auto;
    border-radius: 8px;
    object-fit: cover;
}

.public-design-brand > span {
    display: grid;
    place-items: center;
    background: currentColor;
    color: #ffffff;
    font-size: 20px;
    font-weight: 900;
}

.public-design-brand strong {
    max-width: 300px;
    overflow: hidden;
    font-size: 21px;
    line-height: 1;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.public-sticky-nav {
    position: sticky;
    top: 0;
    z-index: 220;
    order: -200;
    display: grid;
    grid-template-columns: minmax(180px, 0.8fr) minmax(360px, auto) minmax(180px, 0.8fr);
    align-items: center;
    gap: 16px;
    width: 100%;
    min-height: var(--public-nav-height);
    margin-bottom: 0;
    padding: 10px max(18px, calc((100vw - 1680px) / 2));
    border-bottom: 1px solid rgba(255, 255, 255, 0.18);
    background: rgba(8, 18, 22, 0.96);
    color: #ffffff;
    box-shadow: 0 18px 54px rgba(5, 21, 26, 0.28);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

@media (min-width: 761px) {
