.visual-location {
    grid-template-columns: minmax(280px, 0.55fr) minmax(0, 1.45fr);
    align-items: center;
    padding: clamp(96px, 7vw, 128px) 32px 24px;
    border-radius: 0;
    background: transparent;
}

.public-design-visual .visual-location {
    padding: clamp(96px, 7vw, 128px) 32px 24px;
}

.visual-location > div {
    display: grid;
    align-content: center;
    gap: 12px;
    min-inline-size: 0;
    padding-top: clamp(22px, 4vw, 68px);
}

.visual-location-copy > :is(h2, p) {
    width: 100%;
    min-inline-size: 0;
    max-inline-size: 100%;
    text-align: left;
}

.visual-location-copy > h2 {
    overflow-wrap: anywhere;
    word-break: normal;
    hyphens: none;
}

.visual-location-title-prefix {
    white-space: nowrap;
}

.visual-map-pin {
    position: relative;
    display: inline-block;
    justify-self: center;
    width: 72px;
    height: 72px;
    margin-bottom: 8px;
    border-radius: 50% 50% 50% 0;
    background: #e53935;
    box-shadow: 0 12px 24px rgba(148, 25, 25, 0.22);
    transform: rotate(-45deg);
}

.visual-map-pin::after {
    position: absolute;
    inset: 19px;
    border-radius: 999px;
    background: #b91c1c;
    content: "";
}

.visual-map,
.visual-location .public-design-map-fallback {
    border: 1px solid #d4e5e7;
    background: transparent;
}

@media (min-width: 1121px) {
    /* El mapa conserva su alto y el borde derecho; se recorta sólo un 10 %
       desde cada lateral (20 % de ancho total). En la vista apilada vuelve a
       ocupar todo el ancho para no estrechar la interacción táctil. */
    .visual-location > :is(.visual-map, .public-design-map-fallback) {
        inline-size: 80%;
        justify-self: end;
    }
}

.public-template-clasica {
    --tierra-green: #5F7A4A;
    --tierra-green-hover: #526A40;
    --tierra-clay: #A06A45;
    --tierra-clay-hover: #8C5D3D;
    --tierra-dark-green: #13180F;
    --tierra-dark-green-raised: #212B1A;
    --tierra-dark-clay: #20150E;
    --tierra-dark-clay-raised: #382518;
    /* Superficie exclusiva de Contacto; no integra la paleta cerrada de tarifas. */
    --tierra-dark-contact-field: #422C1C;
    --public-accent: var(--tierra-green);
    --public-accent-strong: var(--tierra-green-hover);
    --public-surface: #ffffff;
    --public-soft: rgba(95, 122, 74, 0.2);
    --public-ink: #000000;
    --public-muted: #000000;
    --public-line: rgba(95, 122, 74, 0.35);
}

.public-template-clasica.public-design-visual {
    background: #ffffff;
    color: #000000;
}

.public-template-clasica .visual-location {
