/* Tierra y Urano comparten el reloj y los horarios cíclicos de Registros.
   Cada modelo aporta su paleta mediante los tokens public-control. */
:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock {
    position: relative;
    display: block;
    width: 100%;
    min-width: 0;
    min-height: 52px;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: #000000;
    overflow: visible;
    transition: none;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock[hidden] {
    display: none !important;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock > .parking-registration-clock-summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    min-height: 52px;
    padding: 0 14px;
    border: 1px solid var(--public-control-accent, #5F7A4A);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    font-family: var(--font-body);
    font-size: 16px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    line-height: 1.2;
    cursor: pointer;
    list-style: none;
    gap: 12px;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock > .parking-registration-clock-summary::-webkit-details-marker {
    display: none;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock > .parking-registration-clock-summary:focus-visible {
    outline: 3px solid var(--public-control-focus, rgba(95, 122, 74, 0.28));
    outline-offset: 2px;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock[aria-disabled="true"] > .parking-registration-clock-summary {
    cursor: default;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-value {
    color: inherit;
    font: inherit;
    font-variant-numeric: tabular-nums;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-value.is-placeholder {
    color: var(--placeholder) !important;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-indicator {
    width: 9px;
    height: 9px;
    flex: 0 0 auto;
    border-right: 2px solid currentColor;
    border-bottom: 2px solid currentColor;
    transform: rotate(45deg) translate(-2px, 2px);
    transition: transform 160ms ease;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock[open] .parking-registration-clock-indicator {
    transform: rotate(225deg) translate(-2px, 2px);
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock:focus-within,
:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock[open] {
    border: 0;
    box-shadow: none;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock:focus-within > .parking-registration-clock-summary,
:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock[open] > .parking-registration-clock-summary {
    border-color: var(--public-control-accent, #5F7A4A);
    box-shadow: 0 0 0 3px var(--public-control-focus, rgba(95, 122, 74, 0.2));
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock.is-invalid > .parking-registration-clock-summary {
    border-color: var(--danger);
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock > .parking-registration-clock-panel {
    position: fixed;
    z-index: 160;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    width: min(420px, calc(100vw - 16px));
    max-height: calc(100dvh - 16px);
    padding: 14px;
    border: 1px solid var(--public-control-accent, #5F7A4A);
    border-radius: 9px;
    background: #ffffff;
    box-shadow: 0 18px 44px var(--public-control-shadow, rgba(43, 57, 33, 0.24));
    color: #000000;
    overflow-y: auto;
    gap: 14px;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock:not([open]) > .parking-registration-clock-panel {
    display: none;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-face {
    width: clamp(104px, 38%, 142px);
    min-width: 104px;
    flex: 0 1 142px;
    aspect-ratio: 1;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-face svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-ring {
    fill: #ffffff;
    stroke: var(--public-control-accent, #5F7A4A);
    stroke-width: 2;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-numbers text {
    fill: #000000;
    font-size: 8px;
    font-weight: 700;
    text-anchor: middle;
    dominant-baseline: middle;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-hand {
    stroke: var(--public-control-accent, #5F7A4A);
    stroke-linecap: round;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-hand.is-hour {
    stroke-width: 4;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-hand.is-minute {
    stroke-width: 3;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-pin {
    fill: var(--public-control-accent, #5F7A4A);
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-editor-label {
    display: grid;
    flex: 1 1 190px;
    min-width: 178px;
    color: #000000;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    gap: 6px;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-editor-heading {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    color: #000000;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-format {
    color: inherit;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-editor {
    display: grid;
    grid-template-columns: minmax(44px, 1fr) auto minmax(44px, 1fr);
    align-items: center;
    width: 100%;
    min-width: 0;
    min-height: 44px;
    padding: 0 10px;
    border: 1px solid var(--public-control-accent, #5F7A4A);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
}

:is(.public-template-clasica, .public-template-mapa) .public-price-form .public-tierra-clock .parking-registration-clock-editor:focus-within {
    border-color: var(--public-control-accent, #5F7A4A);
