/* Design 2: Marte */
.public-design-urban {
    background: #1b0f0b;
    color: #ffffff;
}

.urban-hero {
    padding: 22px max(18px, calc((100vw - 1680px) / 2)) 0;
    background:
        radial-gradient(circle at 8% 12%, rgba(217, 103, 47, 0.22), transparent 32%),
        linear-gradient(135deg, #1b0f0b 0%, #30150d 52%, #5c2112 100%);
}

.urban-nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 10px;
    border: 1px solid rgba(255, 176, 106, 0.24);
    border-radius: 8px;
    background: rgba(255, 176, 106, 0.08);
}

.urban-nav > div {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
}

.urban-nav a {
    color: #ffffff;
    font-weight: 900;
}

.urban-nav > div > a {
    padding: 11px 12px;
}

.urban-nav-cta,
.urban-primary {
    background: #e86f32;
    color: #000000;
}

.urban-secondary {
    border: 1px solid rgba(255, 240, 223, 0.28);
    color: #ffffff;
}

.urban-hero-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(18px, 3vw, 42px);
    align-items: stretch;
    padding: clamp(42px, 7vw, 112px) 0 clamp(28px, 5vw, 72px);
}

.urban-status {
    display: grid;
    align-content: center;
    gap: 14px;
    min-height: 420px;
    padding: clamp(22px, 3vw, 32px);
    border-radius: 8px;
    background:
        radial-gradient(circle at 100% 0%, rgba(255, 240, 223, 0.22), transparent 36%),
        linear-gradient(145deg, #f2c35f 0%, #e86f32 48%, #7a2d16 100%);
    color: #000000;
    box-shadow: 0 28px 90px rgba(91, 33, 18, 0.42);
}

.urban-status > span {
    font-size: 13px;
    font-weight: 950;
    letter-spacing: 0;
    text-transform: uppercase;
}

.urban-status > p {
    max-width: 520px;
    margin: 0;
    color: #000000;
    font-size: 18px;
    font-weight: 850;
    line-height: 1.35;
}

.urban-status .public-category-price-panel {
    display: grid;
    gap: 12px;
    margin-top: 10px;
}

.urban-status .public-period-selector {
    gap: 6px;
}

.urban-status .public-period-selector button {
    min-height: 34px;
    padding: 0 10px;
    border-color: rgba(27, 15, 11, 0.24);
    background: rgba(255, 240, 223, 0.68);
    color: #000000;
}

.urban-status .public-period-selector button.is-active {
    background: #1b0f0b;
    color: #ffffff;
}

.urban-status-rate-list {
    display: grid;
    gap: 9px;
}

.urban-status-rate-list article {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 10px;
    align-items: center;
    padding: 13px 14px;
    border: 1px solid rgba(255, 240, 223, 0.18);
    border-radius: 8px;
    background: rgba(27, 15, 11, 0.88);
    color: #ffffff;
}

.urban-status-rate-title {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.urban-status-rate-title > span {
    font-size: 16px;
    font-weight: 950;
}

.urban-model-info {
    display: inline-grid;
    place-items: center;
    width: 1.2em;
    height: 1.2em;
    min-width: 1.2em;
    padding: 0;
    border: 1px solid rgba(247, 207, 114, 0.72);
    border-radius: 999px;
    background: rgba(247, 207, 114, 0.18);
    color: #f7cf72;
    font: inherit;
    font-size: 0.8em;
    line-height: 1;
    cursor: pointer;
}

.urban-model-info[aria-expanded="true"] {
    background: #f7cf72;
    color: #000000;
}

.urban-status-rate-list article strong {
    color: #f7cf72;
    font-size: clamp(22px, 2vw, 30px);
    line-height: 1;
    text-align: right;
}

.urban-status-rate-list article small {
    grid-column: 1 / -1;
    color: #ffffff;
    font-weight: 800;
}

.urban-model-info-text {
    padding: 10px 12px;
    border: 1px solid rgba(247, 207, 114, 0.22);
    border-radius: 8px;
    background: rgba(247, 207, 114, 0.1);
    color: #ffffff !important;
    line-height: 1.45;
}

.urban-model-info-text[hidden] {
    display: none;
}

.urban-copy {
    display: grid;
    align-content: center;
    gap: 20px;
}

