    color: #ffffff;
}

.urban-rates {
    background:
        radial-gradient(circle at 100% 0%, rgba(232, 111, 50, 0.18), transparent 34%),
        #1b0f0b;
    color: #ffffff;
}

.urban-calculator,
.urban-result {
    border: 1px solid rgba(242, 195, 95, 0.32);
    background: #2a120c;
    color: #ffffff;
}

.urban-location {
    grid-template-columns: minmax(420px, 0.46fr) minmax(0, 1fr);
    align-items: center;
    background:
        radial-gradient(circle at 12% 16%, rgba(242, 195, 95, 0.18), transparent 28%),
        linear-gradient(135deg, #3a1a10 0%, #7a2d16 100%);
    color: #ffffff;
}

.urban-location-copy {
    display: grid;
    align-content: center;
    justify-items: start;
    justify-self: start;
    gap: 14px;
    width: 100%;
    max-width: 520px;
    text-align: left;
}

.urban-location-copy .urban-location-pin {
    justify-self: center;
}

.urban-location-copy :is(h2, p) {
