/* Design 3: Urano */
.public-design-map {
    background: #eefcff;
    color: #000000;
}

.map-first {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding: clamp(32px, 5vw, 72px) max(18px, calc((100vw - 1680px) / 2)) clamp(54px, 6vw, 84px);
    background:
        radial-gradient(circle at 82% 14%, rgba(204, 249, 255, 0.68), transparent 30%),
        radial-gradient(circle at 18% 92%, rgba(89, 200, 216, 0.22), transparent 34%),
        linear-gradient(135deg, #f7fdff 0%, #d7f7ff 42%, #72d9e7 100%);
}

.map-hero-media {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
}

.map-hero-media::after {
    position: absolute;
    inset: 0;
    content: "";
}

.map-hero-media img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
}

.map-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    margin-bottom: 22px;
}

.map-links {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.map-links a {
