.public-gallery-grid figcaption {
    display: grid;
    gap: 4px;
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-gallery-grid figcaption span {
    opacity: 1;
}

.public-blog-grid article,
.public-blog-card {
    display: grid;
    align-content: space-between;
    gap: 16px;
    min-height: 178px;
    overflow: hidden;
    padding: 20px;
    border: 1px solid currentColor;
    border-radius: 8px;
    color: currentColor;
    text-decoration: none;
}

.public-blog-card > img,
.public-blog-grid article > img {
    width: calc(100% + 40px);
    max-width: none;
    aspect-ratio: 16 / 9;
    margin: -20px -20px 0;
    object-fit: cover;
}

.public-blog-media {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 10px;
    width: calc(100% + 40px);
    margin: -20px -20px 0;
}

.public-blog-media img {
    width: 100%;
    height: 100%;
    min-height: 220px;
    margin: 0;
    border-radius: 0;
}

.public-blog-media-count-1 img {
    aspect-ratio: 16 / 10;
}

.public-blog-media-count-2 img {
    aspect-ratio: 4 / 3;
}

.public-blog-grid article > div,
.public-blog-card > div {
    display: grid;
    gap: 10px;
}

.public-blog-grid span {
    font-size: 13px;
    font-weight: 900;
    opacity: 1;
    text-transform: uppercase;
}

.public-blog-grid strong {
    font-size: 22px;
    line-height: 1.15;
}

.public-blog-card-more,
.public-blog-read-more {
    width: fit-content;
    color: #2f9dff;
    font-weight: 900;
    text-decoration: none;
}

.public-blog-card-more {
    font-size: 15px;
    opacity: 1;
    text-transform: none;
}

.public-blog-read-more {
    font-size: 18px;
}

.public-blog-card:hover .public-blog-card-more,
.public-blog-card:focus-visible .public-blog-card-more,
.public-blog-read-more:hover,
.public-blog-read-more:focus-visible {
    color: #6ac2ff;
    text-decoration: none;
}

.public-blog-grid p,
.public-blog-grid small {
    margin: 0;
    line-height: 1.45;
    opacity: 1;
}

.public-blog-grid p {
    /* La vista previa vive dentro del editor, cuyos párrafos usan negrita.
       El resumen necesita su peso normal para distinguir los destacados. */
    font-weight: 400;
    white-space: pre-line;
}

/* Los destacados del cuerpo conservan la métrica del párrafo: son negritas,
   no subtítulos. Aplica tanto a las tarjetas como a las vistas de lista y
   detalle de todos los modelos públicos. */
.public-design :is(
    .public-blog-grid p,
    .public-blog-list-card p,
    .public-blog-entry-text p
) strong {
    font-family: inherit;
    font-size: inherit;
    font-weight: 700;
    line-height: inherit;
}

.public-blog-entry-list {
    display: grid;
    gap: 18px;
}

.public-blog-entry {
    display: none;
    gap: 18px;
    scroll-margin-top: 110px;
    padding: clamp(18px, 3vw, 32px);
    border: 1px solid currentColor;
    border-radius: 8px;
    color: currentColor;
}

.public-blog-entry:target {
    display: grid;
}

.public-blog-entry h3 {
    margin: 0;
    font-size: clamp(28px, 4vw, 48px);
    line-height: 1.05;
}

.public-blog-entry-image {
    width: 100%;
    max-height: 560px;
    border-radius: 8px;
    object-fit: cover;
}

.public-blog-entry-image-main {
    aspect-ratio: 16 / 9;
}

.public-blog-entry p {
    margin: 0;
    max-width: 980px;
    font-size: clamp(17px, 2vw, 20px);
    font-weight: 700;
    line-height: 1.62;
}

.public-blog-detail-page {
    display: block;
    min-height: 100vh;
    padding: 0;
    background: #f7fbfa;
    color: #000000;
}

.public-blog-detail-page > .public-sticky-nav {
    grid-template-columns: minmax(210px, 0.7fr) minmax(0, 1.8fr) minmax(150px, 0.55fr);
    margin-bottom: 0;
}

.public-blog-detail-page .public-sticky-links {
    justify-self: center;
    justify-content: space-between;
    width: min(100%, 860px);
}

.public-blog-detail-page .public-sticky-links > a {
    min-width: 94px;
}

.public-blog-detail-article {
    display: grid;
    gap: clamp(22px, 4vw, 42px);
    padding: clamp(28px, 5vw, 72px) max(18px, calc((100vw - 1360px) / 2));
}

.public-blog-detail-back {
    width: fit-content;
    padding: 10px 14px;
    border: 1px solid currentColor;
    border-radius: 8px;
    color: currentColor;
    font-weight: 900;
    text-decoration: none;
}

.public-blog-detail-head {
    max-width: 1240px;
    margin: 0 auto;
    text-align: left;
}

.public-blog-detail-head h1 {
    margin: 0;
    font-size: clamp(34px, 7vw, 78px);
    line-height: 0.98;
}

.public-blog-detail-head > p:first-child {
    margin: 0;
    font-size: 13px;
    font-weight: 900;
    letter-spacing: 0;
    opacity: 1;
    text-transform: uppercase;
}

.public-blog-detail-head > p:not(:first-child) {
    font-weight: 400;
    line-height: 1.55;
    opacity: 1;
}

.public-blog-detail-body {
    display: grid;
    gap: clamp(18px, 3vw, 34px);
    width: min(100%, 1320px);
    margin: 0 auto;
}

.public-blog-entry-text {
    display: grid;
    gap: 14px;
    max-width: 980px;
}

.public-blog-entry-text p {
    margin: 0;
    font-size: clamp(17px, 2vw, 20px);
    font-weight: 400;
    line-height: 1.68;
}

.public-blog-entry-text strong {
    font-weight: 900;
}

.public-blog-list-page {
    min-height: 100vh;
    background: #071418;
    color: #ffffff;
}

.public-blog-list-page > .public-sticky-nav {
    margin-bottom: 0;
}

.public-blog-list-wrap {
    display: grid;
    gap: clamp(28px, 4vw, 56px);
    padding: clamp(34px, 5vw, 78px) max(18px, calc((100vw - 1460px) / 2)) clamp(58px, 8vw, 110px);
}

.public-blog-list-hero {
    display: grid;
    gap: 12px;
    max-width: 980px;
}

.public-blog-list-hero p,
.public-blog-list-hero span {
    margin: 0;
    color: #ffffff;
    font-size: clamp(18px, 2vw, 24px);
    line-height: 1.45;
}

.public-blog-list-hero p {
    color: #ffffff;
    font-size: 14px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-blog-list-hero h1 {
    margin: 0;
    font-size: clamp(58px, 9vw, 128px);
    line-height: 0.92;
}

.public-blog-list-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 22px;
}

.public-blog-list-card {
    display: grid;
    align-content: start;
    overflow: hidden;
    border: 1px solid rgba(116, 214, 223, 0.36);
    border-radius: 8px;
    background: #142328;
    box-shadow: 0 22px 60px rgba(0, 0, 0, 0.2);
}

.public-blog-list-image {
    display: block;
    min-height: 260px;
    background: rgba(255, 255, 255, 0.06);
}

.public-blog-list-image img {
    width: 100%;
    height: 100%;
    min-height: 260px;
    aspect-ratio: 16 / 9;
    object-fit: cover;
}

.public-blog-list-card > div {
    display: grid;
    gap: 14px;
    padding: 24px;
}

.public-blog-list-card small {
    color: #ffffff;
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
}

.public-blog-list-card h2 {
    margin: 0;
    font-size: clamp(25px, 2.8vw, 38px);
    line-height: 1.05;
}

.public-blog-list-card h2 a {
    color: inherit;
    text-decoration: none;
}

.public-blog-list-card p {
    margin: 0;
    color: #ffffff;
    font-size: 18px;
    line-height: 1.48;
}

.public-comments-block {
    display: grid;
    gap: 26px;
    padding: clamp(34px, 6vw, 78px) max(18px, calc((100vw - 1480px) / 2));
}

.public-references-head {
    max-width: 1100px;
}

.public-references-head h2 {
    max-width: none;
    font-size: clamp(34px, 5vw, 58px);
    line-height: 1.02;
}

.public-references-head p {
    max-width: 980px;
    font-size: clamp(18px, 2vw, 24px);
}

.public-references-carousel {
    display: grid;
    grid-template-columns: 44px minmax(0, 1fr) 44px;
    gap: 14px;
    align-items: center;
}

.public-references-viewport {
    overflow: hidden;
}

.public-references-track {
    display: flex;
    align-items: stretch;
    gap: 14px;
    overflow: visible;
    padding: 2px 0 6px;
    scrollbar-width: none;
    transform: translate3d(0, 0, 0);
}

.public-references-track::-webkit-scrollbar {
    display: none;
}

.public-references-track.is-reference-moving {
    pointer-events: none;
    transition: transform 0.42s cubic-bezier(0.42, 0, 0.2, 1);
    will-change: transform;
}

.public-reference-card {
    position: relative;
    display: grid;
    flex: 0 0 calc((100% - 28px) / 3);
    gap: 16px;
    align-content: start;
    min-width: 0;
    min-height: 220px;
    padding: 28px 30px 26px;
    overflow: hidden;
    border: 1px solid rgba(196, 209, 212, 0.82);
    border-radius: 8px;
    background: linear-gradient(180deg, #f7fbfa 0%, #f3f8f7 100%);
    box-shadow: 0 10px 22px rgba(43, 47, 51, 0.06);
}

.public-reference-card::before {
    position: absolute;
    top: 0;
    right: 0;
    left: 0;
    height: 4px;
    background: var(--brand-primary);
    content: "";
}

.public-reference-card p {
    margin: 0;
    color: var(--ink);
    font-size: clamp(17px, 1.45vw, 21px);
    line-height: 1.48;
}

.public-reference-card strong {
    align-self: end;
    color: var(--ink);
    font-size: clamp(17px, 1.35vw, 21px);
}

.public-google-reviews-attribution {
    display: grid;
    max-width: 1100px;
    gap: 7px;
    padding: 15px 18px;
    border: 1px solid color-mix(in srgb, currentColor 20%, transparent);
    border-radius: 10px;
    background: color-mix(in srgb, currentColor 5%, transparent);
    color: var(--ink);
}

.public-google-reviews-status {
    max-width: 1100px;
    margin: 0;
    color: var(--ink);
    font-size: 14px;
    font-weight: 700;
    line-height: 1.45;
}

.public-google-reviews-status[hidden] {
    display: none;
}

.public-google-reviews-attribution[hidden] {
    display: none;
}

.public-google-reviews-attribution p {
    margin: 0;
    color: var(--ink);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.45;
}

.public-google-attribution-line {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px 14px;
}

.public-google-maps-brand {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    min-height: 28px;
    padding: 5px 10px;
    border-radius: 6px;
}

.public-google-maps-logo {
    display: block;
    width: 98px;
    height: 18px;
    object-fit: contain;
}

.public-google-maps-logo-dark {
    display: none;
}

.public-design[data-public-theme="dark"] .public-google-maps-logo-light {
    display: none;
}

.public-design[data-public-theme="dark"] .public-google-maps-logo-dark {
    display: block;
}

.public-google-reviews-attribution a,
.public-google-review-author a,
.public-google-review-link,
.public-google-attributions a,
.public-google-legal-links a {
    color: inherit;
    text-decoration: none;
    text-decoration-thickness: 1px;

}

.public-google-reviews-attribution a:is(:hover, :focus-visible),
.public-google-review-author a:is(:hover, :focus-visible),
.public-google-review-link:is(:hover, :focus-visible),
.public-google-attributions a:is(:hover, :focus-visible),
.public-google-legal-links a:is(:hover, :focus-visible) {
    text-decoration-thickness: 2px;
}

.public-google-place-summary {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 6px 12px;
    color: var(--ink);
}

.public-google-place-summary strong,
.public-google-place-summary span {
    color: var(--ink);
}

.public-google-place-summary strong {
    font-size: 18px;
}

.public-google-place-summary span {
    font-size: 14px;
    font-weight: 700;
}

.public-google-review-card {
    align-content: start;
    overflow-wrap: anywhere;
}

.public-google-review-author {
    display: flex;
    align-items: center;
    min-width: 0;
    gap: 11px;
}

.public-google-review-author > div {
    display: grid;
    min-width: 0;
    gap: 4px;
}

.public-google-review-author strong {
    overflow-wrap: anywhere;
}

.public-google-review-avatar {
    flex: 0 0 auto;
    width: 42px;
    height: 42px;
    border: 1px solid color-mix(in srgb, currentColor 20%, transparent);
    border-radius: 50%;
    background: color-mix(in srgb, currentColor 6%, transparent);
    object-fit: cover;
}

.public-google-review-stars {
    color: #b45f06;
    font-size: 18px;
    font-weight: 900;
    letter-spacing: 0.03em;
    line-height: 1;
}

.public-design[data-public-theme="dark"] .public-google-review-stars {
    color: #fbbf24;
}

.public-google-review-meta,
.public-google-review-actions,
.public-google-attributions,
.public-google-legal-links {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px 12px;
    color: var(--ink);
}

.public-google-review-meta {
    font-size: 14px;
    font-weight: 700;
}

.public-google-review-translation {
    font-style: italic;
}

.public-google-review-actions {
    align-self: end;
    font-size: 14px;
    font-weight: 800;
}

.public-google-review-report {
    font-size: 13px;
}

.public-google-attributions {
    font-size: 13px;
    font-weight: 600;
}

.public-google-legal-links {
    font-size: 13px;
    font-weight: 700;
}

.public-reference-location {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 5px;
    margin-top: -10px;
    color: var(--muted);
    font-size: 15px;
    font-weight: 700;
}

.public-reference-flag {
    display: inline-block;
    flex: 0 0 auto;
    width: 18px;
    height: 12px;
    border-radius: 2px;
    box-shadow: 0 0 0 1px rgba(43, 47, 51, 0.12);
    object-fit: cover;
}

.public-references-carousel > .public-reference-control {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    align-self: center;
    justify-self: center;
    width: 42px;
    min-width: 0;
    height: 42px;
    min-height: 0;
    padding: 0;
    border: 1px solid rgba(109, 40, 217, 0.2);
    border-radius: 50%;
    background: #ffffff;
    color: var(--brand-primary);
    font-size: 30px;
    line-height: 1;
    cursor: pointer;
    box-shadow: 0 8px 18px rgba(43, 47, 51, 0.08);
}

.public-reference-control:disabled {
    cursor: default;
    opacity: 1;
}

@media (max-width: 900px) {
    .public-blog-list-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .public-reference-card {
        flex-basis: calc((100% - 14px) / 2);
    }
}

@media (max-width: 640px) {
    .public-blog-list-grid {
        grid-template-columns: 1fr;
    }

    .public-references-carousel {
        grid-template-columns: 36px minmax(0, 1fr) 36px;
        gap: 8px;
    }

    .public-references-carousel > .public-reference-control {
        width: 36px;
        height: 36px;
        font-size: 26px;
    }

    .public-reference-card {
        flex-basis: 100%;
        min-height: 230px;
        padding: 24px;
    }

    .public-google-reviews-attribution {
        padding: 14px;
    }

    .public-blog-list-image,
    .public-blog-list-image img {
        min-height: 210px;
    }
}

