/* Blog, comentarios y catálogo: el editor visual comparte las etiquetas de Portada. */
.public-blog-metadata-field,
.public-content-tag-field {
    display: grid;
    gap: 8px;
    min-width: 0;
    width: 100%;
    color: var(--ink);
    align-content: start;
}

.public-blog-edit-form > :is(.public-blog-title-field, .public-blog-metadata-field, .public-content-origin) {
    grid-column: 1 / -1;
}

.public-blog-metadata-field > input {
    width: 100%;
    min-height: 52px;
    padding: 14px 16px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
}

.public-content-tags-toolbar {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 6px;
}

.app-shell .public-content-rich-editor,
.public-page-builder-parking[data-public-parking-builder="1"] .public-content-rich-editor {
    display: block;
    width: 100%;
    min-width: 0;
    height: auto;
    min-height: 132px;
    max-height: 320px;
    padding: 14px 16px;
    overflow: auto;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    font-weight: 400;
    line-height: 1.45;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

.app-shell .public-content-rich-editor-single-line,
.public-page-builder-parking[data-public-parking-builder="1"] .public-content-rich-editor-single-line {
    min-height: 52px;
    max-height: 180px;
}

.public-content-rich-editor:focus {
    outline: 2px solid var(--brand-primary);
    outline-offset: 2px;
}

.public-content-rich-editor:empty::before {
    content: attr(data-placeholder);
    color: var(--placeholder);
    pointer-events: none;
}

.public-content-rich-editor [data-public-hero-editor-tag] { color: var(--public-hero-editor-tag-color); }
.public-content-rich-editor [data-public-hero-editor-tag-order="1"] { --public-hero-editor-tag-color: #7c3aed; }
.public-content-rich-editor [data-public-hero-editor-tag-order="2"] { --public-hero-editor-tag-color: #eab308; }
.public-content-rich-editor [data-public-hero-editor-tag-order="3"] { --public-hero-editor-tag-color: #f97316; }
.public-content-rich-editor [data-public-hero-editor-tag-order="4"] { --public-hero-editor-tag-color: #2563eb; }
.public-content-rich-editor [data-public-hero-editor-tag-order="5"] { --public-hero-editor-tag-color: #0ea5e9; }
.public-content-rich-editor [data-public-hero-editor-tag-order="6"] { --public-hero-editor-tag-color: #16a34a; }

.public-content-origin {
    display: block;
    margin-top: 4px;
    color: var(--ink);
    font-size: 12px;
    font-weight: 600;
}

.public-content-catalog {
    display: grid;
    gap: 12px;
    min-width: 0;
    margin-top: 20px;
    color: var(--ink);
}

.public-content-catalog-item {
    min-width: 0;
    padding: 16px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
    overflow-wrap: anywhere;
}

.public-content-catalog-item summary { cursor: pointer; font-weight: 700; }
.public-content-catalog-item summary small { display: block; margin-top: 4px; }
.public-content-catalog-item img { display: block; max-width: 100%; max-height: 260px; object-fit: contain; }
.public-content-catalog-item p { white-space: pre-wrap; }
.public-blog-hashtags { color: var(--ink); overflow-wrap: anywhere; }
.public-blog-hashtags { font-size: 14px; }

.public-blog-detail-body > .public-blog-entry-hashtags {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    min-width: 0;
    margin-top: 16px;
}

.public-blog-entry-hashtags > .public-blog-hashtag {
    text-decoration: none;
}

.public-blog-entry-hashtags > .public-blog-hashtag:hover {
    border-color: var(--public-accent);
}
