/* Modelo Marte: paleta y temas aislados de los demás modelos públicos. */
.public-template-urbana.public-design-urban {
    --mars-orange: #D96B2B;
    --mars-amber: #E3B341;
    --mars-red: #E63946;
    --mars-brown: #3B211B;
    --mars-orange-soft: rgba(217, 107, 43, 0.18);
    --mars-orange-medium: rgba(217, 107, 43, 0.25);
    --mars-amber-soft: rgba(227, 179, 65, 0.18);
    --mars-amber-medium: rgba(227, 179, 65, 0.25);
    --mars-red-soft: rgba(230, 57, 70, 0.18);
    --mars-red-medium: rgba(230, 57, 70, 0.25);
    --mars-energy-gradient: linear-gradient(
        112deg,
        var(--mars-amber) 0%,
        var(--mars-orange) 52%,
        var(--mars-red) 100%
    );
    --mars-paper: #FFF9F4;
    --mars-surface: #FFFFFF;
    --mars-dark-text: #FFFFFF;
    --mars-dark-raised: #4A2A23;
    --public-accent: var(--mars-orange);
    --public-accent-strong: #BF5720;
    --public-surface: var(--mars-surface);
    --public-soft: var(--mars-orange-soft);
    --public-ink: var(--mars-brown);
    --public-muted: var(--mars-brown);
    --public-line: rgba(217, 107, 43, 0.3);
    background: var(--mars-paper);
    color: var(--mars-brown);
}

.public-template-urbana [data-public-price-value][hidden] {
    display: none !important;
}

.public-template-urbana .public-sticky-nav {
    border-bottom-color: rgba(59, 33, 27, 0.3);
    background: var(--mars-energy-gradient);
    color: var(--mars-brown);
    box-shadow: 0 16px 42px rgba(59, 33, 27, 0.18);
}

.public-template-urbana .public-sticky-nav :is(
    .public-design-brand strong,
    .public-sticky-links a,
    .public-theme-toggle
) {
    color: var(--mars-brown);
}

.public-template-urbana .public-sticky-links > a:hover,
.public-template-urbana .public-sticky-links > a:focus-visible {
    background: rgba(227, 179, 65, 0.25);
}

.public-template-urbana .public-sticky-theme {
    border-color: rgba(59, 33, 27, 0.3);
    background: rgba(227, 179, 65, 0.25);
}

.public-template-urbana .urban-hero {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding: 12px max(18px, calc((100vw - 1680px) / 2)) 0;
    background:
        radial-gradient(circle at 8% 12%, rgba(217, 107, 43, 0.18), transparent 34%),
        radial-gradient(circle at 92% 10%, rgba(227, 179, 65, 0.18), transparent 30%),
        radial-gradient(circle at 82% 88%, rgba(230, 57, 70, 0.15), transparent 32%),
        var(--mars-paper);
}

.public-template-urbana .urban-hero-media {
    position: absolute;
    inset: 0;
    z-index: -1;
    overflow: hidden;
    pointer-events: none;
}

.public-template-urbana .urban-hero-media img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    filter: saturate(0.78) contrast(0.9);
}

.public-template-urbana .urban-hero-media::after {
    position: absolute;
    inset: 0;
    background:
        linear-gradient(112deg, rgba(255, 249, 244, 0.62), rgba(217, 107, 43, 0.34) 54%, rgba(230, 57, 70, 0.32)),
        linear-gradient(rgba(255, 249, 244, 0.2), rgba(255, 249, 244, 0.2));
    content: "";
}

.public-template-urbana .urban-hero-grid {
    align-items: center;
    padding: clamp(28px, 4vw, 56px) 0 clamp(24px, 3.5vw, 48px);
}

.public-template-urbana .urban-copy {
    gap: 18px;
    padding: clamp(22px, 3vw, 38px);
    border: 1px solid rgba(59, 33, 27, 0.24);
    border-radius: 8px;
    background: rgba(255, 249, 244, 0.78);
    box-shadow: 0 24px 64px rgba(59, 33, 27, 0.18);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

.public-template-urbana .urban-copy :is(h1, p) {
    color: var(--mars-brown);
}

.public-template-urbana .urban-copy p {
    opacity: 1;
}

.public-template-urbana :is(
    .urban-primary,
    .urban-nav-cta,
    .public-banner-primary,
    .public-contact-submit,
    .public-price-grid button
) {
    border-color: var(--mars-orange);
    background: var(--mars-energy-gradient);
    color: var(--mars-brown);
    box-shadow: none;
}

.public-template-urbana :is(
    .urban-primary,
    .urban-nav-cta,
    .public-banner-primary,
    .public-contact-submit,
    .public-price-grid button
