    background: linear-gradient(
        104deg,
        var(--mars-amber) -10%,
        var(--mars-orange) 38%,
        var(--mars-red) 100%
    );
    color: var(--mars-brown);
}

.public-template-urbana .urban-secondary {
    border-color: var(--mars-orange);
    background: linear-gradient(
        112deg,
        rgba(227, 179, 65, 0.15),
        rgba(217, 107, 43, 0.2) 52%,
        rgba(230, 57, 70, 0.15)
    );
    color: var(--mars-brown);
}

.public-template-urbana .urban-secondary:hover,
.public-template-urbana .urban-secondary:focus-visible {
    background: linear-gradient(
        112deg,
        rgba(227, 179, 65, 0.25),
        rgba(217, 107, 43, 0.25) 52%,
        rgba(230, 57, 70, 0.25)
    );
}

.public-template-urbana .urban-status {
    width: min(100%, 608px);
    min-width: 0;
    justify-self: start;
    min-height: 288px;
    border: 1px solid rgba(59, 33, 27, 0.22);
    background:
        linear-gradient(
