/* Modelo Urano: azul principal, verde aurora y superficies responsivas al tema. */
.public-template-mapa {
    --uranus-blue: #3A7FA3;
    --uranus-green: #4FAF8E;
    --uranus-petrol: #17343D;
    --uranus-white: #FFFFFF;
    --uranus-black: #000000;
    --uranus-blue-soft: rgba(58, 127, 163, 0.18);
    --uranus-blue-medium: rgba(58, 127, 163, 0.25);
    --uranus-green-soft: rgba(79, 175, 142, 0.15);
    --uranus-green-medium: rgba(79, 175, 142, 0.25);
    --public-accent: var(--uranus-blue);
    --public-accent-strong: var(--uranus-petrol);
    --public-highlight: var(--uranus-green);
    --public-surface: var(--uranus-white);
    --public-soft: var(--uranus-blue-soft);
    --public-ink: var(--uranus-black);
    --public-muted: var(--uranus-black);
    --public-line: rgba(58, 127, 163, 0.3);
}

.public-template-mapa.public-design-map:not([data-public-theme="dark"]) {
    background: var(--uranus-white);
    color: var(--uranus-black);
    color-scheme: light;
}

.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-nav {
    border-bottom-color: rgba(58, 127, 163, 0.3);
    background: rgba(58, 127, 163, 0.22);
    color: var(--uranus-black);
    box-shadow: 0 16px 44px rgba(23, 52, 61, 0.15);
    backdrop-filter: blur(18px) saturate(135%);
    -webkit-backdrop-filter: blur(18px) saturate(135%);
}

.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-nav :is(
    .public-design-brand strong,
    .public-design-brand > span,
    .public-sticky-links a,
    .public-sticky-socials a,
    .public-theme-toggle
) {
    color: var(--uranus-black);
    text-shadow: none;
}

.public-template-mapa:not([data-public-theme="dark"])
    .public-sticky-nav
    .public-design-brand
    img,
.public-template-mapa:not([data-public-theme="dark"])
    .public-sticky-nav
    .public-design-brand
    > span {
    border-color: rgba(58, 127, 163, 0.3);
}

.public-template-mapa:not([data-public-theme="dark"])
    .public-sticky-nav
    .public-design-brand
    > span {
    background: rgba(255, 255, 255, 0.3);
}

.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-links > a:hover,
.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-links > a:focus-visible,
.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-socials a:hover,
.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-socials a:focus-visible {
    background: rgba(79, 175, 142, 0.25);
}

.public-template-mapa:not([data-public-theme="dark"]) .public-sticky-theme {
    border-color: rgba(23, 52, 61, 0.3);
    background: rgba(255, 255, 255, 0.25);
    color: var(--uranus-black);
}

.public-template-mapa:not([data-public-theme="dark"]) :is(
    .map-arrival-card h1,
    .map-arrival-card p,
    .map-arrival-card dd,
    .map-vehicles h2,
    .map-section-head h2,
    .public-section-head h2,
    .public-section-head p,
    .public-contact-head h2,
    .public-contact-head p,
    .public-contact-form label,
    .public-contact-form .field-label-line,
    .public-blog-grid strong,
    .public-blog-grid p,
    .public-blog-grid small,
    .public-blog-card-more,
    .public-reference-card strong,
    .public-reference-card p,
    .public-reference-location,
    .public-calculation-mode label,
    .public-cyclic-field legend,
    .public-cyclic-field p,
    .public-cyclic-row-title,
    .public-cyclic-day
) {
    color: var(--uranus-black) !important;
}

.public-template-mapa .map-first {
    background:
        radial-gradient(circle at 88% 12%, rgba(58, 127, 163, 0.25), transparent 34%),
        radial-gradient(circle at 10% 88%, rgba(79, 175, 142, 0.18), transparent 38%),
        var(--uranus-white);
}

/* A 0.52 y con el velo encima la portada cargada quedaba como marca de
   agua. El texto vive en tarjetas propias, así que la foto puede verse. */
.public-template-mapa .map-hero-media img {
    opacity: 0.9;
    filter: saturate(0.9);
}

.public-template-mapa .map-hero-media::after {
    background:
        linear-gradient(115deg, rgba(79, 175, 142, 0.15), rgba(58, 127, 163, 0.18)),
        linear-gradient(rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.08));
}

.public-template-mapa .map-hero-canvas,
.public-template-mapa .map-first .public-design-map-fallback {
    border-color: rgba(58, 127, 163, 0.3);
    background: var(--uranus-blue-soft);
    box-shadow: 0 24px 60px rgba(23, 52, 61, 0.18);
}

.public-template-mapa .map-arrival-card {
    border-color: rgba(58, 127, 163, 0.3);
    background:
        radial-gradient(circle at 100% 0%, rgba(79, 175, 142, 0.18), transparent 38%),
        linear-gradient(135deg, rgba(255, 255, 255, 0.56), rgba(225, 246, 250, 0.56));
    color: var(--uranus-black);
    box-shadow: 0 18px 44px rgba(23, 52, 61, 0.15);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

/* Portada + Mapa comparte un único recuadro apaisado. El mapa ocupa la fila
   entre el título y los accesos de portada. */
.public-template-mapa .map-arrival-card > .map-hero-canvas {
    width: 100%;
    height: clamp(280px, 32vh, 360px);
    min-height: 0;
    min-width: 0;
    border-radius: 8px;
    overflow: hidden;
}

.public-template-mapa .map-first.is-hero-right .map-arrival-card {
    justify-self: end;
}

.public-template-mapa .map-arrival-card h1 {
    --public-parking-hero-title-scale: 0.8;
    min-inline-size: 0;
    max-inline-size: 100%;
    overflow-wrap: anywhere;
    word-break: normal;
    -webkit-hyphens: manual;
    hyphens: manual;
    hyphenate-character: "-";
    text-wrap: balance;
}

.public-template-mapa .map-arrival-card .public-hero-description > p {
