/* ===== Portada 1600 × 700 (2,3:1), navbar traslúcida y recortador ===== */

.public-sticky-nav {
    transition: background 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

.public-site[data-hide-nav-before-footer] > .public-sticky-nav {
    opacity: 1;
    transform: translateY(0);
    visibility: visible;
    transition: background 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease, opacity 0.18s ease, transform 0.22s ease, visibility 0s linear;
}

.public-site[data-hide-nav-before-footer] > .public-sticky-nav.is-nav-hidden {
    opacity: 0;
    transform: translateY(-100%);
    visibility: hidden;
    pointer-events: none;
    transition: opacity 0.18s ease, transform 0.22s ease, visibility 0s linear 0.22s;
}

@media (prefers-reduced-motion: reduce) {
    .public-site[data-hide-nav-before-footer] > .public-sticky-nav,
    .public-site[data-hide-nav-before-footer] > .public-sticky-nav.is-nav-hidden {
        transition: none;
    }
}

