/* Bloque de portada Tierra con proporción 2,3:1 en escritorio: la imagen
   cubre desde la barra (que se ve traslúcida encima) hasta el final del
   bloque. En pantallas chicas se conserva el alto anterior. */
@media (min-width: 761px) {
    .public-template-clasica .tierra-hero {
        aspect-ratio: 1600 / 700;
        min-height: max-content;
    }

    .public-template-clasica .tierra-hero .visual-hero-grid {
        min-height: 0;
        height: 100%;
    }

    .public-design.public-template-clasica > .public-sticky-nav + [data-public-block~="portada"].tierra-hero {
        margin-top: calc(-1 * var(--public-nav-height));
        padding-top: calc(var(--public-nav-height) + 24px);
    }
}

/* Modales del recortador y de error de imagen */
.image-tool-modal {
    position: fixed;
    inset: 0;
    z-index: 4000;
    display: grid;
    place-items: center;
    padding: 24px;
}

.image-tool-modal-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(5, 14, 18, 0.62);
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
}

.image-tool-modal-panel {
    position: relative;
    z-index: 1;
    display: grid;
    gap: 14px;
    width: min(720px, 100%);
    max-height: min(90vh, 780px);
    overflow: auto;
    padding: 20px;
    border-radius: 14px;
    background: #ffffff;
    color: #000000;
    box-shadow: 0 24px 64px rgba(5, 21, 26, 0.42);
}

.image-error-modal .image-tool-modal-panel {
    width: min(460px, 100%);
}

/* El editor de identidad se habilita explícitamente desde el caller. Tiene una
   mesa de trabajo amplia sin cambiar el tamaño de los recortadores de portada
   y Blog, que comparten el mismo módulo. */
.image-crop-modal-identity .image-tool-modal-panel {
    width: min(1020px, 100%);
    max-height: min(94dvh, 940px);
    padding: 24px;
}

.image-crop-editor-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(260px, 300px);
    align-items: start;
    gap: 24px;
    min-width: 0;
}

/* La mesa siempre es cuadrada. El recorte real conserva su propia proporción:
   un logo 1:1 ocupa todo el espacio y una marca horizontal queda centrada. */
.image-crop-workspace {
    --image-crop-checker-base: #ffffff;
    --image-crop-checker-tile: #d5dde0;
    display: grid;
    place-items: center;
    width: min(620px, 100%);
    aspect-ratio: 1;
    min-width: 0;
    margin-inline: auto;
    overflow: hidden;
    border: 1px solid rgba(127, 127, 127, 0.55);
    border-radius: 12px;
}

.image-crop-workspace[data-image-crop-editor-theme="light"] {
    border-color: #000000;
    --image-crop-checker-base: #ffffff;
    --image-crop-checker-tile: #d5dde0;
}

.image-crop-workspace[data-image-crop-editor-theme="dark"] {
    --image-crop-checker-base: #e2e8eb;
    --image-crop-checker-tile: #99aeb8;
    border-color: #ffffff;
}

.image-crop-workspace[data-image-crop-editor-theme],
.image-crop-modal-identity:not(.image-crop-modal-hero) .image-crop-frame {
    background-color: var(--image-crop-checker-base);
    background-image: conic-gradient(
        var(--image-crop-checker-tile) 25%,
        transparent 0 50%,
        var(--image-crop-checker-tile) 0 75%,
        transparent 0
    );
    background-size: 20px 20px;
}

/* La portada usa una única imagen para ambos modos. La mesa queda gris oscuro
   y, cuando el original sobresale del recorte, una copia atenuada permite ver
   qué parte se está dejando afuera sin confundirla con el resultado final. */
.image-crop-workspace.image-crop-workspace-hero {
    position: relative;
    isolation: isolate;
    border-color: #687780;
    background: #25282b;
}

.image-crop-workspace-hero .image-crop-context-picture {
    position: absolute;
    z-index: 0;
    top: 50%;
    left: 50%;
    max-width: none;
    opacity: 0.78;
    filter: brightness(0.42) saturate(0.65);
    user-select: none;
    pointer-events: none;
}

.image-crop-empty-workspace {
    cursor: default;
}

.image-crop-empty-upload {
    display: inline-grid;
    place-items: center;
    width: 76px;
    min-width: 76px;
    height: 76px;
    min-height: 76px;
    padding: 0;
    border: 1px solid #6D28D9;
    border-radius: 20px;
    background: #6D28D9;
    color: #ffffff;
    cursor: pointer;
}

.image-crop-workspace[data-image-crop-editor-theme="dark"] .image-crop-empty-upload {
    color: #ffffff;
}

.image-crop-empty-upload:hover,
.image-crop-empty-upload:focus-visible {
    background: #5b21b6;
    outline: 3px solid #6D28D9;
    outline-offset: 4px;
}

.image-crop-empty-upload svg {
    width: 44px;
    height: 44px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.image-crop-modal-identity .image-crop-frame {
    --image-crop-max-height: 100%;
    width: 100%;
    margin: 0;
    border-radius: 0;
    background: inherit;
}

.image-crop-modal-hero .image-crop-frame {
    z-index: 1;
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.58);
}

.image-crop-editor-controls {
    display: grid;
    align-content: start;
    gap: 18px;
    min-width: 0;
}

.image-crop-editor-image-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
}

.image-crop-editor-image-actions .image-tool-modal-replace {
    margin-right: 0;
}

.image-crop-editor-theme {
    display: grid;
    gap: 8px;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
}

.image-crop-editor-theme-label {
    margin-bottom: 8px;
    padding: 0;
    font-size: 13px;
    font-weight: 700;
}

.image-crop-editor-theme-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.image-crop-editor-theme-option {
    min-width: 0;
    min-height: 40px;
    padding: 8px 12px;
    border: 1px solid rgba(127, 127, 127, 0.65);
    border-radius: 10px;
    background: transparent;
    color: inherit;
    font: inherit;
    font-weight: 700;
    cursor: pointer;
}

.image-crop-editor-theme-option.is-selected {
    border-color: #6D28D9;
