}

.image-crop-editor-theme-option:focus-visible,
.image-crop-center:focus-visible,
.image-crop-remove-background:focus-visible,
.image-crop-restore-background:focus-visible,
.image-tool-modal-download:focus-visible,
.image-tool-modal-delete:focus-visible {
