    gap: 6px 12px;
}

.image-crop-editor-controls :is(.image-crop-zoom-label, .image-crop-aspect-label) {
    text-align: left;
}

.image-crop-editor-controls :is(.image-crop-zoom-range, .image-crop-aspect-range) {
    grid-column: 1 / -1;
    grid-row: 2;
}

.image-crop-edit-actions {
    display: grid;
    justify-items: start;
    gap: 8px;
}

.image-crop-background-actions {
