}

.image-crop-background-actions[hidden],
.image-crop-background-actions > [hidden],
.image-crop-background-status[hidden] {
    display: none;
}

.image-crop-background-status {
    color: inherit;
    font-size: 13px;
}

.image-crop-background-status.is-error {
    color: var(--danger);
}

.image-tool-modal-title {
    margin: 0;
    font-size: 18px;
    padding-right: 32px;
}

/* Cerrar: el mismo botón circular rojo con la cruz que usa la imagen de portada. */
.image-tool-modal-close {
    position: absolute;
    z-index: 2;
    top: 12px;
    right: 12px;
    display: inline-grid;
    place-items: center;
