}

.image-crop-shape-option:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: 2px;
}

.image-tool-modal-message {
    margin: 0;
    line-height: 1.45;
}

.image-tool-modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.image-tool-modal-accept,
.image-tool-modal-cancel,
.image-tool-modal-replace {
