}

.image-tool-modal-accept:hover,
.image-tool-modal-accept:focus-visible {
    background: #5B21B6;
}

.image-tool-modal-cancel {
    background: transparent;
    border-color: rgba(127, 127, 127, 0.55);
    color: inherit;
}

.image-tool-modal-delete {
    border-color: var(--danger);
    background: var(--danger);
    color: #ffffff;
}

.image-tool-modal-download {
