    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-block-visibility-chip {
        flex-basis: calc(50% - 5px);
        max-width: none;
        min-width: 0;
    }

    .public-block-availability-days {
        grid-template-columns: minmax(0, 1fr) 78px;
    }

    .public-block-availability-days span:last-child {
        grid-column: 1 / -1;
    }
}

@media (max-width: 420px) {
    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-branch-visibility-option {
        flex-basis: 100%;
    }
}

/* Sólo el editor de Estacionamiento separa las redes en un segundo grupo.
   Los grupos siempre se apilan dentro de la misma columna: la grilla anterior
   de dos columnas podía medir más que el panel y expulsar las redes hacia la
   derecha cuando no coincidía una sobreescritura más específica. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-portada-buttons-options {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: flex-start;
    min-width: 0;
    width: 100%;
    gap: 24px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    :is(.public-portada-buttons-standard, .public-portada-buttons-social) {
    display: flex;
    flex-wrap: wrap;
    min-width: 0;
    width: min(100%, 530px);
    max-width: 100%;
    gap: 10px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    :is(.public-portada-buttons-standard, .public-portada-buttons-social)
    > .public-portada-button-check {
    flex: 0 0 calc((100% - 20px) / 3);
    width: calc((100% - 20px) / 3);
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-portada-buttons-standard {
    justify-self: start;
    justify-content: flex-start;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-portada-buttons-social {
    justify-self: start;
    justify-content: flex-start;
}

@media (max-width: 560px) {
    .public-page-builder-parking[data-public-parking-builder="1"]
        :is(.public-portada-buttons-standard, .public-portada-buttons-social)
        > .public-portada-button-check {
        flex-basis: calc((100% - 10px) / 2);
        width: calc((100% - 10px) / 2);
    }
}

/* Logo circular e imagen de marca en la página pública */
.public-design-brand-circular img:not(.public-design-brand-marca) {
    border-radius: 50%;
}

.public-identity-image-dark {
    display: none;
}

.public-design[data-public-theme="dark"] .public-identity-image-light {
    display: none;
}

.public-design[data-public-theme="dark"] .public-identity-image-dark {
    display: block;
}

/* El logo oscuro conserva un borde sutil sin tapar su transparencia. */
.public-design[data-public-theme="dark"]
    .public-sticky-nav
    .public-design-brand
    img.public-identity-image-dark-explicit:not(.public-design-brand-marca) {
    border-color: rgba(255, 255, 255, 0.24);
    background: transparent;
}

.public-identity-image-dark[hidden] {
    display: none !important;
}

.public-design[data-public-theme="dark"] .public-identity-image-light.identity-theme-fallback {
    display: block;
}

.public-sticky-nav .public-design-brand .public-design-brand-marca {
    width: auto;
    max-width: 162px;
    height: 54px;
    border: 0;
    border-radius: 0;
    background: transparent;
    object-fit: contain;
}

.public-footer-logo-circular img {
    border-radius: 50%;
}

.public-design .public-sticky-nav .public-design-brand img.public-design-brand-marca {
    border: 0;
    border-radius: 0;
    background: transparent;
}

/* ===== Posición del bloque de portada (izquierda o derecha) ===== */

.visual-hero.is-hero-right .visual-copy {
    justify-self: end;
}

/* En Tierra, la portada de Estacionamiento usa un margen lateral visible pero
   acotado. El padding basado en todo el viewport más el grid centrado sumaban
   dos sangrías y dejaban incluso la posición izquierda demasiado cerca del
   centro. El cuadro queda ahora anclado de forma simétrica al lado elegido. */
@media (min-width: 761px) {
    :is(
        body.public-page[data-module="estacionamiento"],
        .public-page-builder-parking[data-public-parking-builder="1"]
    )
        .public-template-clasica
        .tierra-hero {
        padding-inline: clamp(22px, 3%, 64px);
    }

    :is(
        body.public-page[data-module="estacionamiento"],
        .public-page-builder-parking[data-public-parking-builder="1"]
    )
        .public-template-clasica
        .tierra-hero
        .visual-hero-grid {
        width: 100%;
        margin-inline: 0;
    }

    :is(
        body.public-page[data-module="estacionamiento"],
        .public-page-builder-parking[data-public-parking-builder="1"]
    )
        .public-template-clasica
        .tierra-hero:not(.is-hero-right)
        .visual-copy {
        justify-self: start;
    }
}

@media (min-width: 1121px) {
    .public-template-urbana .urban-hero {
        padding-inline: max(18px, calc((100vw - 1760px) / 2));
    }

    .public-template-urbana .urban-hero-grid,
    .public-page-builder-parking
        .public-page-owner-preview
        .public-template-urbana
        .urban-hero-grid {
        gap: clamp(48px, 3.2vw, 60px);
    }

    .public-template-mapa .map-first {
        padding-inline: clamp(22px, 3%, 64px);
    }

    .public-template-mapa .map-arrival-card h1 {
        --public-parking-hero-title-small-size: clamp(33.28px, 3.2vw, 61.44px);
        font-size: clamp(41.6px, 4vw, 76.8px);
    }

    .public-template-mapa .map-standalone-location .map-hero-canvas {
        width: 95%;
        height: clamp(350px, 41vh, 440px);
        justify-self: end;
    }
}

/* El degradado oscuro acompaña al bloque: si el texto va a la derecha, el
   lado oscuro de la imagen también. */
.visual-hero.is-hero-right {
    --public-hero-overlay-angle: 270deg;
}

@media (max-width: 760px) {
    .visual-hero.is-hero-right .visual-copy {
        justify-self: stretch;
    }
}

/* ===== Barra de formato y etiquetas del texto de portada ===== */

.public-hero-text-toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-start;
    gap: 10px;
}

.public-hero-format-group {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: 4px;
}

.public-hero-format-button {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 7px;
    background: var(--surface);
    color: var(--ink);
    font-size: 13px;
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
}

.public-hero-format-button svg {
    width: 17px;
    height: 17px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
}

.public-hero-format-button:hover,
.public-hero-format-button:focus-visible {
    border-color: var(--brand-primary);
    color: var(--brand-primary);
}

.public-hero-toolbar-separator {
    width: 1px;
    height: 20px;
    margin: 0 4px;
    background: var(--line);
}

/* Las etiquetas son botones sueltos de la misma barra que B / I / U, no un
   recuadro aparte. Cuando no entran al lado del grupo de formato bajan a su
   propio renglón (y a un segundo si hacen falta) en vez de superponerse con el
   estilo de letra o la alineación. Sin tope de alto a propósito: un scroll
   acá escondería etiquetas. */
.public-hero-tags-group {
    display: flex;
    flex: 1 1 auto;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 7px;
    min-width: 0;
}

.public-hero-tag-button {
    min-height: 30px;
    padding: 5px 9px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font: inherit;
    font-size: 12px;
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
    text-transform: none;
}

.public-hero-tag-button:hover,
.public-hero-tag-button:focus-visible {
    border-color: var(--brand-primary);
    background: rgba(126, 34, 206, 0.08);
    color: var(--brand-primary);
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-tag-button[aria-pressed="true"] {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
}

/* Cada botón usado conserva el color de su etiqueta, incluso
   deshabilitado. La paleta por orden se comparte con los chips del editor. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor:is([data-public-block-editor="portada"], [data-public-block-editor="precio_disponibilidad"], [data-public-block-editor="blog"])
    .public-hero-tag-button[aria-pressed="true"][data-public-hero-tag-order] {
    border-color: var(--public-hero-editor-tag-color);
    background: var(--public-hero-editor-tag-color);
    color: var(--public-hero-tag-button-ink, #000000);
    cursor: default;
    opacity: 1;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor:is([data-public-block-editor="portada"], [data-public-block-editor="precio_disponibilidad"], [data-public-block-editor="blog"])
    .public-hero-tag-button:is(
        [data-public-hero-tag-order="1"],
        [data-public-hero-tag-order="4"]
    ) {
    --public-hero-tag-button-ink: #ffffff;
}

/* Texto de portada con formato: párrafos reales y alineación por párrafo. */
.public-hero-description {
    display: grid;
    gap: 20px;
}

.public-hero-description[hidden] {
    display: none;
}

/* La alineación se mide contra el ancho del bloque, no contra el max-width
   heredado del párrafo suelto que había antes. */
.public-hero-description > p {
    max-width: none;
    margin: 0;
}

:is(
    body.public-page[data-module="estacionamiento"],
    .public-page-builder-parking[data-public-parking-builder="1"]
) .public-hero-description {
    gap: 0;
}

:is(
    body.public-page[data-module="estacionamiento"],
    .public-page-builder-parking[data-public-parking-builder="1"]
) .public-hero-description > p {
    line-height: 1.5;
}

/* Sólo la descripción de Portada puede ajustarse hasta un 8 % cuando el
   texto necesita un cuarto renglón. El interlineado mantiene su alto normal. */
:is(
    body.public-page[data-module="estacionamiento"],
    .public-page-builder-parking[data-public-parking-builder="1"]
) .public-hero-description[data-public-hero-fit-text],
:is(
    body.public-page[data-module="estacionamiento"],
    .public-page-builder-parking[data-public-parking-builder="1"]
) .public-hero-description > p[data-public-hero-fit-text] {
    font-size: var(--public-hero-fit-font-size);
    line-height: var(--public-hero-fit-line-height);
}

.public-hero-align-center {
    text-align: center;
}

.public-hero-align-right {
    text-align: right;
}

.public-design [data-public-preview-price-title] > .public-price-title-line {
    display: block;
    margin: 0;
    font: inherit;
    color: inherit;
    text-transform: inherit;
}

/* La barra de formato en el editor oscuro y el foco visible por teclado. */
html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-format-button {
    border-color: #565656;
    background: #0c0c0c;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-format-button[aria-pressed="true"] {
    border-color: #ffffff;
    background: #ffffff;
    color: #000000;
}

html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-tag-button {
    border-color: #565656;
    background: #0c0c0c;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-tag-button:hover,
html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-tag-button:focus-visible {
    border-color: #ffffff;
    background: #1c1c1c;
    color: #ffffff;
    outline: 3px solid rgba(255, 255, 255, 0.24);
}

html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-tag-button[aria-pressed="true"] {
    border-color: #ffffff;
    background: #ffffff;
    color: #000000;
}

html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-toolbar-separator {
    background: #ffffff;
}

html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-format-button:hover,
html[data-theme="dark"] .app-shell
    .public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-format-button:focus-visible {
    border-color: #ffffff;
    background: #1c1c1c;
    color: #ffffff;
    outline: 3px solid rgba(255, 255, 255, 0.24);
}

.public-hero-format-button:focus-visible,
.public-hero-tag-button:focus-visible {
    outline: 3px solid rgba(173, 63, 227, 0.35);
    outline-offset: 1px;
}

/* Sin imagen el fondo de reemplazo también acompaña al bloque de texto. */
.visual-hero-without-image.is-hero-right {
    background:
        radial-gradient(circle at 18% 18%, rgba(255, 255, 255, 0.18), transparent 34%),
        linear-gradient(225deg, var(--public-accent-strong), var(--public-accent));
}

/* --- Portada: círculo de ayuda, láminas sugeridas ------------------------- */

/* Portada usa una sola grilla: imagen y alineación arriba a la izquierda,
   texto debajo y los botones de secciones/redes en la columna derecha. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    > .public-block-editor-grid {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 24px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: minmax(300px, 402px) minmax(280px, 474px) minmax(420px, 1fr);
    grid-template-areas:
        "media position buttons"
        "copy copy buttons";
    align-items: start;
    min-width: 0;
    width: 100%;
    gap: 24px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout
    > .public-portada-main-media {
    grid-area: media;
    align-self: start;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout
    > .public-portada-posicion-field {
    grid-area: position;
    justify-self: start;
    width: min(100%, 350px);
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout
    > .public-portada-buttons-field {
    grid-area: buttons;
    grid-template-rows: auto minmax(0, 1fr);
    position: relative;
    justify-self: center;
    min-width: 0;
    width: min(100%, 650px);
    align-self: stretch;
}

/* Los dos conjuntos empiezan tras rótulos de igual alto; el círculo de ayuda
   no debe desplazar la primera fila respecto de Izquierda/Derecha. */
.public-page-builder-parking[data-public-parking-builder="1"]
    [data-public-block-editor="portada"]
    .public-portada-layout
    > :is(.public-portada-posicion-field, .public-portada-buttons-field)
    > legend {
    min-height: 17px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    [data-public-block-editor="portada"]
    [data-public-portada-buttons]
    > .public-portada-buttons-options {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: flex-start;
    min-height: 0;
    gap: 24px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout
    > .public-portada-main-copy {
    grid-area: copy;
    display: grid;
    align-content: start;
    min-width: 0;
    width: min(100%, 900px);
    gap: 12px;
    color: var(--ink);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.3;
    justify-self: start;
    max-width: 900px;
}

/* Marte conserva sólo imagen, alineación y botones sobre los precios. */
.public-page-builder-parking[data-public-parking-builder="1"][data-public-template-mode="mars"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout {
    grid-template-areas: "media position buttons";
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    .public-portada-layout > [data-public-portada-text][hidden] {
    display: none;
}

.public-page-builder-parking[data-public-parking-builder="1"][data-public-template-mode="mars"]
    [data-public-block-editor="portada"]
    [data-public-portada-buttons] > .public-portada-buttons-options {
    position: static;
    inset: auto;
}

/* El aumento tipográfico pertenece sólo a la superficie de escritura del
   constructor. La descripción que ve el público conserva sus tamaños. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-portada-main-copy
    :is(
        textarea[data-public-hero-text-source],
        .public-hero-rich-editor
    ) {
    height: 112px;
    min-height: 112px;
    max-height: 112px;
    resize: none;
    overflow: auto;
    font-size: 22px;
    line-height: 1;
}

.public-page-builder-parking
    .public-comment-modal
    .public-portada-main-copy
    :is(
        textarea[data-public-comment-field="text"],
        .public-hero-rich-editor
    ) {
    height: 112px;
    min-height: 112px;
    max-height: 112px;
    resize: none;
    overflow: auto;
    font-size: 22px;
    line-height: 1;
}

/* Marte configura los precios dentro de Portada con el mismo editor de Tierra. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-mars-merged-fields {
    grid-template-columns: minmax(0, 1fr);
}

/* El título de Precio comparte la superficie de Portada y deja los períodos
   a su derecha, junto a su propio rótulo. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor-grid.public-price-editor-grid {
    grid-template-columns: minmax(300px, 402px) minmax(280px, 474px) minmax(420px, 1fr);
    align-items: start;
    gap: 24px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-price-editor-grid
    > .public-price-title-field {
    grid-column: 1 / 3;
    width: min(100%, 900px);
    max-width: 900px;
    gap: 12px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-price-title-field
    > .public-field-heading {
    margin-bottom: 2px;
    line-height: 1.2;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-price-editor-grid
    > .public-price-period-picker {
    min-width: 0;
}

/* Con una portada cargada, la miniatura es el único control visible para
   editarla. Si está vacía, el botón violeta ocupa exactamente ese lugar. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .public-image-upload-control {
    display: flex;
    width: 100%;
    align-items: flex-start;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .public-hero-image-preview-frame {
    flex: 0 0 402px;
    width: 402px;
    max-width: 100%;
    height: 176px;
    aspect-ratio: 1600 / 700;
    padding: 0;
    overflow: hidden;
    border: 0;
    border-radius: 12px;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .public-hero-image-preview-frame
    .public-image-upload-preview {
    width: 100%;
    height: 100%;
    aspect-ratio: 1600 / 700;
    border-radius: inherit;
    object-fit: cover;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .public-hero-image-preview-frame:focus-visible {
    outline: 3px solid var(--brand-primary);
    outline-offset: 3px;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .logo-upload-actions {
    display: inline-flex;
    width: auto;
    min-width: 0;
}

.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .logo-upload-actions.has-logo {
    display: none;
}

@media (max-width: 1200px) {
    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-block-editor-grid.public-price-editor-grid {
        grid-template-columns: minmax(0, 1.15fr) minmax(190px, 0.85fr) minmax(260px, 1fr);
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-block-editor[data-public-block-editor="portada"]
        .public-portada-layout {
        grid-template-columns: minmax(0, 1.15fr) minmax(190px, 0.85fr) minmax(260px, 1fr);
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-block-editor[data-public-block-editor="portada"]
        .public-portada-layout
        > .public-portada-buttons-field {
        width: 100%;
    }
}

@media (max-width: 760px) {
    .public-page-builder-parking[data-public-parking-builder="1"][data-public-template-mode="mars"]
        .public-block-editor[data-public-block-editor="portada"]
        .public-portada-layout {
        grid-template-areas: "media" "position" "buttons";
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-block-editor-grid.public-price-editor-grid {
        grid-template-columns: minmax(0, 1fr);
        gap: 18px;
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-price-editor-grid
        > .public-price-title-field {
        grid-column: auto;
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-block-editor[data-public-block-editor="portada"]
        .public-portada-layout {
        grid-template-columns: minmax(0, 1fr);
        grid-template-areas:
            "media"
            "position"
            "buttons"
            "copy";
        gap: 18px;
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        [data-public-block-editor="portada"]
        [data-public-portada-buttons]
        > .public-portada-buttons-options {
        position: static;
        inset: auto;
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        height: auto;
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-hero-image-field
        .public-hero-image-preview-frame {
        flex-basis: auto;
        width: min(100%, 402px);
        height: 176px;
    }

    .public-page-builder-parking[data-public-parking-builder="1"]
        .public-portada-main-copy
        :is(
            textarea[data-public-hero-text-source],
            .public-hero-rich-editor
        ) {
        font-size: 17px;
    }

    .public-page-builder-parking
        .public-comment-modal
        .public-portada-main-copy
        :is(
            textarea[data-public-comment-field="text"],
            .public-hero-rich-editor
        ) {
        font-size: 17px;
    }
}

/* La vista previa queda cerca del último control de Portada sin modificar la
   separación de los demás bloques del constructor. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-block-editor[data-public-block-editor="portada"]
    > .public-block-example-slot.has-inline-preview {
    margin-top: 8px;
}

.public-page-builder-parking
    .public-block-editor[data-public-block-editor="portada"]
    .public-block-editor-grid
    > :is(
        .public-portada-apartados-field,
        .public-hero-image-field,
        .public-short-text-field,
        .public-portada-buttons-field,
        .public-portada-posicion-field
    ) {
    gap: 12px;
}

/* El editor de Página web no es un .entry-form, así que no le llega el 17 px
   que en Configuración achica el círculo (03-gastos.css). Se replica acá para
   que el "!" de Portada se vea igual al de Modalidades de ingreso. */
.public-image-upload-heading .cyclic-help-button,
.public-portada-apartados-field > legend .cyclic-help-button,
.public-portada-buttons-field > legend .cyclic-help-button {
    width: 17px;
    min-width: 17px;
    height: 17px;
    min-height: 17px;
    flex: 0 0 17px;
    font-size: 11px;
}

/* Se conserva el tamaño compacto en los campos que comparten estas clases;
   Portada recupera debajo el tamaño del círculo de Configuración. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-image-upload-heading
    .cyclic-help-button,
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-portada-apartados-field
    > legend
    .cyclic-help-button,
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-portada-buttons-field
    > legend
    .cyclic-help-button {
    flex: 0 0 14px;
    width: 14px;
    min-width: 14px;
    height: 14px;
    min-height: 14px;
    align-self: center;
    font-size: 9px;
}

/* Sólo los círculos de Portada igualan Logo de la empresa en Configuración.
   Los rótulos y el contenido de las ayudas conservan su tipografía. */
.public-page-builder-parking[data-public-parking-builder="1"]
    [data-public-block-editor="portada"]
    :is(
        .public-image-upload-heading,
        .public-portada-apartados-field > legend,
        .public-portada-buttons-field > legend
    )
    .cyclic-help-button {
    flex-basis: 17px;
    width: 17px;
    min-width: 17px;
    height: 17px;
    min-height: 17px;
    font-size: 11px;
}

/* Cada condición de la imagen ocupa exactamente un renglón. */
.public-page-builder-parking[data-public-parking-builder="1"]
    #public-hero-image-help {
    width: max-content;
    min-width: 280px;
    max-width: calc(100vw - 32px);
}

.public-page-builder-parking[data-public-parking-builder="1"]
    #public-hero-image-help
    > span {
    white-space: nowrap;
}

/* El rótulo de Imagen de Portada comparte renglón con Accesos rápidos: sin el
   min-height de 24 px heredado, el centrado de la fila ya no baja el texto y
   ambos títulos arrancan a la misma altura. */
.public-page-builder-parking[data-public-parking-builder="1"]
    .public-hero-image-field
    .public-image-upload-heading {
    min-height: 0;
}

/* El <legend> es display:block y dejaría el círculo apoyado sobre la línea
   base del rótulo. */
.public-portada-buttons-field > legend {
    display: flex;
    align-items: center;
    gap: 6px;
}

/* Las seis portadas predeterminadas dentro del recorte. */
.image-crop-presets {
    display: grid;
    gap: 8px;
    margin: 0;
    padding: 0;
    border: 0;
}

.image-crop-presets-label {
    margin-bottom: 8px;
    padding: 0;
    font-size: 12px;
    font-weight: 600;
}

.image-crop-presets-options {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
}

.image-crop-preset-option {
    display: block;
    overflow: hidden;
    width: 100%;
    padding: 0;
    border: 1px solid rgba(127, 127, 127, 0.45);
    border-radius: 8px;
    background: transparent;
    cursor: pointer;
    line-height: 0;
}

.image-crop-preset-option img {
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: 1600 / 700;
    object-fit: cover;
}

.image-crop-preset-option:hover,
.image-crop-preset-option:focus-visible {
    border-color: #6D28D9;
    outline: none;
}

.image-crop-preset-option[disabled] {
    cursor: progress;
    opacity: 0.55;
}

.image-crop-presets-help {
    font-size: 11px;
    font-weight: 600;
    opacity: 0.75;
}

/* Las etiquetas se distinguen sólo mientras se configura el texto. En la
   portada, incluso si el dato es un enlace, se leen como texto limpio. */
:is(
    body.public-page[data-module="estacionamiento"],
    .public-page-builder-parking[data-public-parking-builder="1"]
) .public-hero-description .public-hero-tag-link {
    color: inherit;
    font-weight: inherit;
    text-decoration: none;
}

/* En el editor todas las etiquetas conservan el mismo texto, aunque luego el
   dato publicado pueda ser un enlace. */
.public-hero-tag-button-red {
    text-decoration: none;
}

/* --- Accesos rápidos: número de orden e ícono de red --------------------- */

/* El número aparece sólo en los accesos elegidos: es su posición en la web. */
.public-portada-button-order {
    display: inline-grid;
    place-items: center;
    min-width: 20px;
    height: 20px;
    padding: 0 4px;
    border-radius: 6px;
    background: rgba(0, 0, 0, 0.14);
    color: inherit;
    font-size: 12px;
    font-weight: 900;
    line-height: 1;
}

.public-portada-button-check:not(:has(input:checked)) .public-portada-button-order {
    display: none;
}

html[data-theme="dark"] .app-shell .public-portada-button-order {
    background: rgba(255, 255, 255, 0.22);
}

/* --- Orden de Apartado (barra de arriba de la página pública) ------------- */

.public-portada-apartados-field {
    display: grid;
    gap: 10px;
    margin: 0;
    padding: 0;
    border: 0;
}

.public-portada-apartados-field > legend {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 12px;
    padding: 0;
}

.public-portada-apartados-field[hidden] {
    display: none !important;
}

/* Horizontal a propósito: se leen de izquierda a derecha, igual que en la web. */
.public-portada-apartados-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
}

/* Mismo alto que los chips de accesos rápidos, para que las dos filas del
   bloque se lean iguales. Sin número: la posición ya se ve en la fila. */
.public-portada-apartado-chip {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-height: 44px;
    padding: 0 6px 0 16px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    font-weight: 900;
    line-height: 1.2;
    cursor: grab;
    touch-action: none;
    user-select: none;
}

.public-portada-apartado-chip.is-dragging {
    opacity: 0.54;
    cursor: grabbing;
}

.public-portada-apartado-chip:active {
    cursor: grabbing;
}

/* El mismo dibujo que el control de arrastre de las filas de bloques
   (.public-block-drag-handle), pero como decorado: es un <span>, no toma foco
   ni responde al clic, y sólo avisa que el chip se puede reacomodar. */
.public-portada-apartado-handle {
    display: inline-grid;
    place-items: center;
    width: 34px;
    height: 34px;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--brand-primary);
    cursor: inherit;
    pointer-events: none;
}

.public-portada-apartado-handle svg {
    width: 21px;
    height: 21px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.65;
    stroke-linecap: round;
    stroke-linejoin: round;
}

html[data-theme="dark"] .app-shell .public-portada-apartado-chip {
    border-color: #5A376B;
    background: #1B0D23;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .public-portada-apartado-handle {
    color: #ffffff;
}

/* La paleta clara conserva texto negro también en la vista previa
   de un panel oscuro. El tema oscuro mantiene sus colores propios. */
.public-template-clasica.public-design:not([data-public-theme="dark"])
    [data-public-category-prices]
    .public-vehicle-category-grid
    :is(article, strong, p, span, b),
html[data-theme] .app-shell .public-page-owner-preview
    .public-template-clasica.public-design:not([data-public-theme="dark"])
    [data-public-category-prices]
    .public-vehicle-category-grid
    :is(article, strong, p, span, b) {
    color: #000000 !important;
}

/* El título de precios usa toda la columna disponible. Las palabras normales
   bajan completas; una cadena sin espacios se parte sólo como salvaguarda y
   nunca agrega guiones ni se pierde fuera de la vista previa. */
.public-design .urban-status .public-section-head,
.public-design .visual-availability .public-section-head {
    width: 100%;
    min-width: 0;
    max-width: none;
}

.public-design .urban-status [data-public-preview-price-title-container][hidden],
.public-design
    .visual-availability
    [data-public-preview-price-title-container][hidden] {
    display: none;
}

.public-design .urban-status [data-public-preview-price-title],
.public-design .visual-availability [data-public-preview-price-title] {
    display: -webkit-box;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
    white-space: pre-line;
    overflow-wrap: anywhere;
    word-break: normal;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    hyphens: none;
}

.public-template-urbana.public-design-urban[data-public-theme="light"]
    [data-public-preview-price-title] {
    color: #000000 !important;
}

/* La tarjeta de Marte es más angosta: al alcanzar el mínimo legible,
   el título sigue completo aunque necesite envolver sus dos renglones. */
.public-design .urban-status
    [data-public-preview-price-title][data-public-adaptive-text-fits="false"] {
    display: block;
    overflow: visible;
    -webkit-line-clamp: unset;
    line-clamp: unset;
}

.public-parking-availability-cards
    .public-availability-card-value[data-public-adaptive-text] {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 7;
    line-clamp: 7;
}

.public-parking-availability-cards
    .public-availability-card-address
    .public-availability-card-value[data-public-adaptive-text] {
    -webkit-line-clamp: 6;
    line-clamp: 6;
}

.public-parking-availability-cards
    .public-availability-card-schedule
    .public-availability-schedule-value[data-public-adaptive-text] {
    display: grid;
    -webkit-line-clamp: unset;
    line-clamp: unset;
}

.public-design .visual-availability
    [data-public-adaptive-text].is-public-adaptive-text-measuring,
.public-parking-availability-cards
    .public-availability-card-value[data-public-adaptive-text].is-public-adaptive-text-measuring {
    display: block;
    max-height: none;
    align-self: stretch;
    overflow: visible;
    -webkit-line-clamp: unset;
    line-clamp: unset;
}

.public-parking-availability-cards
    .public-availability-card-schedule
    .public-availability-schedule-value[data-public-adaptive-text].is-public-adaptive-text-measuring {
    display: grid;
    align-content: start;
}

@media (max-width: 900px) {
    .public-parking-availability-cards {
        grid-template-columns: minmax(0, 1fr);
    }
}

.public-design:not([data-public-theme="dark"])
    .public-parking-availability-cards
    .public-availability-card-label {
    color: #000000 !important;
}

.public-template-clasica:not([data-public-theme="dark"])
    .public-parking-availability-cards
    :is(.public-availability-card-spaces, .public-availability-card-contact)
    .public-availability-card-label,
.public-design[data-public-theme="dark"]
    .public-parking-availability-cards
    :is(.public-availability-card-label, .public-availability-card-value) {
    color: #ffffff !important;
}

/* Las tarjetas de portada limitan también sus pistas internas. Sin esta
   columna explícita, una cadena continua podía conservar un min-content de
   varios miles de píxeles y empujar fuera del borde al título y al texto. */
:is(
    .public-template-clasica .visual-copy,
    .public-template-urbana .urban-copy,
    .public-template-mapa .map-arrival-card
) {
    min-inline-size: 0;
    max-inline-size: 100%;
    grid-template-columns: minmax(0, 1fr);
}

:is(
    .public-template-clasica .visual-copy h1,
    .public-template-urbana .urban-title-prefix,
    .public-template-urbana .urban-title-name,
    .public-template-mapa .map-arrival-card h1
) {
    min-inline-size: 0;
    max-inline-size: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: normal;
    -webkit-hyphens: manual;
    hyphens: manual;
    hyphenate-character: "-";
}

.public-hero-description {
    width: 100%;
    min-inline-size: 0;
    max-inline-size: 100%;
    grid-template-columns: minmax(0, 1fr);
}

.public-hero-description > p {
    min-inline-size: 0;
    max-inline-size: 100%;
    overflow-wrap: anywhere;
    word-break: normal;
}

/* Tierra conserva el ancho aunque cambie el texto, pero deja que la tarjeta
   crezca únicamente en altura: una, dos o tres líneas acercan o separan los
   accesos rápidos sin dejar un hueco fijo entre ambos. */
.public-template-clasica .visual-copy {
    box-sizing: border-box;
    inline-size: min(720px, 100%);
    padding: clamp(19.2px, 3.2vw, 38.4px) clamp(17.6px, 2.4vw, 32px);
    gap: 27.2px;
    block-size: auto;
    min-block-size: 0;
    max-block-size: none;
    overflow: hidden;
    grid-template-rows: repeat(3, max-content);
}

/* Si no hay ningún botón elegido se elimina la pista vacía y uno de los dos
   espacios que la rodeaban; la tarjeta conserva su respiración inferior. */
.public-template-clasica
    .visual-copy:not(:has(> .public-design-actions:not([hidden]))) {
    grid-template-rows: repeat(2, max-content);
}

.public-template-clasica .visual-copy > h1 {
    --public-parking-hero-title-scale: 0.9;
    --public-parking-hero-title-small-size: clamp(29.952px, 4.032vw, 59.904px);
    grid-row: 1;
    font-size: clamp(37.44px, 5.04vw, 74.88px);
}

.public-template-clasica .visual-copy .public-hero-description > p {
    font-size: 19.36px;
}

.public-template-clasica .visual-copy > .public-hero-description {
    grid-row: 2;
    align-content: start;
    overflow: hidden;
}

.public-template-clasica .visual-copy > .public-design-actions {
    grid-row: 3;
}

@media (max-width: 760px) {
    .public-template-clasica .visual-copy {
        inline-size: 100%;
    }

    .public-template-clasica .visual-copy > h1 {
        --public-parking-hero-title-small-size: clamp(24.192px, 8.064vw, 36.864px);
        font-size: clamp(30.24px, 10.08vw, 46.08px);
    }

    .public-template-clasica .visual-copy .public-hero-description > p {
        font-size: 17.6px;
    }
}

/* El ajuste se activa por desborde real desde el JS y queda limitado a la
   portada de Estacionamiento (página pública o vista previa del constructor).
   Cada modelo define arriba su escala equivalente al 80 %. */
:is(
    body.public-page[data-module="estacionamiento"],
    .public-page-builder-parking[data-public-parking-builder="1"]
)
    .public-design
    #inicio
    :is(.visual-copy, .urban-copy, .map-arrival-card)
    > h1.is-public-parking-hero-title-small {
    font-size: var(--public-parking-hero-title-small-size);
}

/* Las ilustraciones originales de las sedes demo son apaisadas. Se conservan
   completas sin cambiar el recorte habitual de los logos cargados por usuarios. */
.public-design-brand img[src^="/assets/demo/estacionamientos/"][src*="-logo-v1.png"],
.public-footer-logo-row img[src^="/assets/demo/estacionamientos/"][src*="-logo-v1.png"] {
    object-fit: contain;
}

/* Los accesos comunes de Portada quedan a la izquierda y las redes forman un
   grupo independiente alineado al borde derecho. Ambos lados alternan las
   tonalidades principal/secundaria desde su primer botón. */
.public-design .public-design-actions[data-public-portada-actions][data-public-portada-primary-class] {
    align-items: flex-end;
    flex-wrap: nowrap;
    width: 100%;
}

.public-design .public-design-actions-group {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    min-width: 0;
    gap: 12px;
}

.public-design .public-design-actions-group[hidden] {
    display: none;
}

.public-design .public-design-actions-standard {
    flex: 1 1 auto;
    justify-content: flex-start;
}

.public-design .public-design-actions-social {
    flex: 0 1 auto;
    justify-content: flex-end;
    margin-inline-start: auto;
}

/* Los accesos sociales de Portada son íconos sin texto que toman las mismas
   tonalidades del tema que el grupo común: nada de colores de marca. El
   alcance queda en la fila de acciones: no toca el selector del editor, los
   enlaces del footer ni el WhatsApp flotante. */
.public-design .public-design-actions a[data-public-portada-red] {
    width: 52px;
    inline-size: 52px;
    block-size: 52px;
    min-block-size: 52px;
    flex: 0 0 52px;
    padding: 0;
    gap: 0;
    overflow: hidden;
}

.public-design .public-design-actions a[data-public-portada-red] svg {
    inline-size: 27px;
    block-size: 27px;
    color: #ffffff;
    fill: currentColor;
}

/* Portadas de Tierra y Marte al 80 %: el contenido acompaña al ancho del
   cuadro, sin alturas fijas que recorten títulos o tarifas. */
.public-template-urbana.public-design-urban .urban-status,
.public-page-builder-parking .public-page-owner-preview .public-design-urban .urban-status {
    padding: clamp(17.6px, 2.4vw, 25.6px);
    gap: 22.4px;
}

.public-template-urbana .urban-status-prices {
    gap: 22.4px;
}

.public-template-urbana .urban-status [data-public-preview-price-title] {
    font-size: clamp(27.2px, 4vw, 49.6px);
}

.public-template-urbana .urban-status-availability {
    display: flex;
    align-items: center;
    gap: 0.16em;
    min-width: 0;
    font-size: clamp(68.8px, 7.2vw, 108.8px);
}

.public-template-urbana .urban-status-availability > strong {
    flex: 0 0 auto;
    font-size: 1em;
    line-height: 0.9;
}

.public-template-urbana .urban-status-availability > b {
    padding: 0;
    background: transparent;
    color: inherit;
    font-size: 0.4em;
    line-height: 1.125;
}

.public-template-urbana .urban-status .public-category-price-panel,
.public-page-builder-parking .public-page-owner-preview .public-design-urban .urban-status .public-category-price-panel {
    gap: 20.8px;
    margin-top: 4px;
}

.public-template-urbana .urban-status-rate-list {
    gap: 7.2px;
    grid-template-columns: minmax(0, max-content) 17px minmax(0, 1fr);
}

.public-template-urbana .urban-status-rate-list article,
.public-page-builder-parking .public-page-owner-preview .public-design-urban .urban-status-rate-list article {
    grid-column: 1 / -1;
    grid-template-columns: subgrid;
    padding: 10.4px 11.2px;
}

.public-template-urbana .urban-status-rate-title {
    display: grid;
    grid-column: span 2;
    grid-template-columns: subgrid;
}

.public-template-urbana .urban-status-rate-list article strong {
    font-size: clamp(20px, 1.6vw, 24px);
}

:is(.public-template-clasica, .public-template-urbana) .public-design-actions,
:is(.public-template-clasica, .public-template-urbana) .public-design-actions-group {
    gap: 9.6px;
}

