/* El velo y el contorno pertenecen al área de salida, también horizontal. */
.image-crop-modal-identity .image-crop-workspace { position: relative; isolation: isolate; }
.image-crop-modal-identity .image-crop-context-picture,
.image-crop-brush-preview {
    position: absolute; top: 50%; left: 50%; max-width: none;
    pointer-events: none; user-select: none;
}
.image-crop-modal-identity .image-crop-context-picture { z-index: 0; }
.image-crop-modal-identity .image-crop-frame { z-index: 1; }
.image-crop-boundary {
    position: absolute; z-index: 3; top: 50%; left: 50%;
    transform: translate(-50%, -50%); pointer-events: none;
    box-shadow: inset 0 0 0 2px rgba(255,255,255,.92), inset 0 0 0 4px rgba(4,12,16,.55), 0 0 0 100vmax rgba(0,0,0,.9);
}
.image-crop-boundary.is-circular { border-radius: 50%; }
.image-crop-workspace[data-image-crop-editor-theme="light"] .image-crop-boundary {
    box-shadow: inset 0 0 0 2px rgba(0,0,0,.9), inset 0 0 0 4px rgba(255,255,255,.8), 0 0 0 100vmax rgba(0,0,0,.9);
}
.image-crop-brush-preview { z-index: 1; }
.image-crop-brush-preview[hidden] { display: none; }
.image-crop-frame.is-brushing { cursor: none; }
.image-crop-frame.is-immovable { cursor: default; }
.image-crop-brush-cursor {
    position: absolute; z-index: 4; box-sizing: border-box;
    border: 2px solid #ffffff; border-radius: 50%;
    box-shadow: 0 0 0 1px #111111, inset 0 0 0 1px #111111;
    background: rgba(220, 38, 38, .16);
    transform: translate(-50%, -50%); pointer-events: none;
}
.image-crop-brush-cursor[data-image-crop-brush="keep"] { background: rgba(22, 163, 74, .16); }
.image-crop-brush-cursor[hidden], .image-crop-brush-tool[hidden] { display: none; }
.image-crop-selection-update {
    min-height: 40px; padding: 8px 12px; border: 0; border-radius: 10px;
    background: #6D28D9; color: #ffffff; font: inherit; cursor: pointer;
}
.image-crop-selection-update:disabled,
.image-crop-modal-identity .image-tool-modal-accept:disabled {
    background: #d9dee1; color: #000000; opacity: 1; cursor: default;
}
html[data-theme="dark"] .image-crop-selection-update:disabled,
html[data-theme="dark"] .image-crop-modal-identity .image-tool-modal-accept:disabled {
    background: #465158; color: #ffffff;
}
.image-crop-selection-update:focus-visible { outline: 3px solid #6D28D9; outline-offset: 2px; }
.image-crop-brush-controls { display: grid; gap: 12px; }
.image-crop-brush-tools { display: flex; gap: 8px; flex-wrap: wrap; }
.image-crop-brush-tool {
    min-height: 40px; padding: 8px 12px; border: 1px solid var(--line); border-radius: 10px;
    background: transparent; color: inherit; font: inherit; cursor: pointer;
}
.image-crop-brush-tool[aria-pressed="true"] { background: #6D28D9; color: #ffffff; }
.image-crop-brush-tool:focus-visible { outline: 3px solid #6D28D9; outline-offset: 2px; }
.image-crop-brush-size { display: grid; gap: 8px; font-size: 13px; font-weight: 600; }
.image-crop-brush-size input { width: 100%; min-width: 0; accent-color: #6D28D9; }
/* Los errores de cotización son un estado breve junto a las acciones. */
.parking-registration-quote-status {
