    }
}
/* Tachito para vaciar un desplegable: va arriba a la derecha del cuadro, en la
   misma franja que el nombre del campo, y sólo aparece cuando hay algo elegido.

   Va en un círculo rojo lleno, el mismo molde que el círculo del signo de
   admiración: los dos son botoncitos sueltos sobre el borde del campo y con el
   tacho apenas dibujado a línea no se leía que fuera un botón. */

.has-select-clear {
    position: relative;
}

/* Se lo nombra con el campo adelante porque si no hereda el molde de los
   botones del formulario (`.entry-form button` los estira a 160 x 42). */
.has-select-clear > .select-clear-button {
    position: absolute;
    top: 0;
    right: 0;
    display: inline-grid;
    place-items: center;
    width: 19px;
    min-width: 19px;
    max-width: 19px;
    height: 19px;
    min-height: 19px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: var(--danger);
    color: #fff;
    line-height: 0;
    box-shadow: none;
    cursor: pointer;
}

.has-select-clear > .select-clear-button[hidden] {
    display: none;
}

/* El icono es chico a propósito; el área que responde al dedo no. */
.has-select-clear > .select-clear-button::after {
    content: "";
    position: absolute;
    inset: -5px;
}

.has-select-clear > .select-clear-button svg {
    width: 12px;
    height: 12px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.has-select-clear > .select-clear-button:hover,
.has-select-clear > .select-clear-button:focus-visible {
    background: color-mix(in srgb, var(--danger) 82%, #000);
    color: #fff;
    filter: none;
}

/* El tema oscuro le apaga el fondo a casi todos los botones del formulario:
   este tiene que seguir siendo el mismo círculo rojo en los dos temas. */
html[data-theme="dark"] .app-shell .has-select-clear > .select-clear-button {
    background: var(--danger);
    color: #fff;
    box-shadow: none;
}

html[data-theme="dark"] .app-shell .has-select-clear > .select-clear-button:hover,
html[data-theme="dark"] .app-shell .has-select-clear > .select-clear-button:focus-visible {
    background: color-mix(in srgb, var(--danger) 78%, #fff);
    color: #fff;
}

/* Selector de dos columnas: conserva un select nativo como fuente de verdad,
   pero muestra las opciones con el dato principal a la izquierda y su detalle
   a la derecha, como el selector de meses y saldos de Cobros. */
.floor-modal-entry-field {
    display: grid;
    min-width: 0;
    gap: 6px;
    color: #000000;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.2;
    text-transform: uppercase;
}

.floor-modal-entry-field > [data-floor-modal-entry-label] {
    padding-right: 26px;
}

.split-picker {
    position: relative;
    display: block;
    min-width: 0;
}

.split-picker-native-select {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
}

.entry-form .split-picker-open {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 18px;
    align-items: center;
    gap: 9px;
    width: 100%;
    min-width: 0;
    height: 42px;
    min-height: 42px;
    padding: 0 13px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    text-align: left;
    text-transform: none;
    box-shadow: none;
    cursor: pointer;
    filter: none;
}

.entry-form .split-picker-open:hover,
.entry-form .split-picker-open:focus-visible,
.entry-form .split-picker-open[aria-expanded="true"] {
    border-color: var(--brand-primary);
    background: #ffffff;
    color: #000000;
    outline: 2px solid color-mix(in srgb, var(--brand-primary) 26%, transparent);
    outline-offset: 1px;
    filter: none;
}

.entry-form .split-picker-open[aria-invalid="true"] {
    border-color: var(--danger);
    box-shadow: 0 0 0 3px rgba(194, 61, 66, 0.14);
}

.split-picker-summary {
    display: flex;
    min-width: 0;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
}

.split-picker-primary,
.split-picker-secondary {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.split-picker-primary {
    flex: 1 1 auto;
    font-weight: 700;
}

.split-picker-secondary {
    flex: 0 1 55%;
    font-weight: 600;
    text-align: right;
}

.split-picker-open > svg {
    width: 18px;
    height: 18px;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
    transition: transform 0.16s ease;
}

.split-picker-open[aria-expanded="true"] > svg {
    transform: rotate(180deg);
}

.split-picker-menu {
    position: absolute;
    z-index: 120;
    top: calc(100% + 6px);
    left: 0;
    display: block;
    width: 100%;
    max-height: min(280px, calc(100vh - 24px));
    padding: 0;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.24);
    overflow-y: auto;
}

.split-picker-menu[hidden] {
    display: none;
}

.entry-form .split-picker-option {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    width: 100%;
    min-width: 0;
    height: 36px;
    min-height: 36px;
    padding: 0 12px;
    border: 0;
    border-radius: 0;
    background: #ffffff;
    color: #000000;
    font-size: 13px;
    font-weight: 600;
    text-align: left;
    text-transform: none;
    box-shadow: none;
    cursor: pointer;
    filter: none;
}

.entry-form .split-picker-option:hover,
.entry-form .split-picker-option:focus-visible,
.entry-form .split-picker-option[aria-selected="true"] {
    background: var(--brand-primary);
    color: #ffffff;
    outline: none;
    filter: none;
}

html[data-theme="dark"] .app-shell .floor-modal-entry-field {
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .split-picker-open,
html[data-theme="dark"] .app-shell .split-picker-menu,
html[data-theme="dark"] .app-shell .entry-form .split-picker-option {
    background: #121a1e;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .split-picker-open:hover,
html[data-theme="dark"] .app-shell .entry-form .split-picker-open:focus-visible,
html[data-theme="dark"] .app-shell .entry-form .split-picker-open[aria-expanded="true"] {
    background: #121a1e;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .split-picker-option:hover,
html[data-theme="dark"] .app-shell .entry-form .split-picker-option:focus-visible,
html[data-theme="dark"] .app-shell .entry-form .split-picker-option[aria-selected="true"] {
    background: var(--brand-primary);
    color: #ffffff;
}
/* Sugerencias de cobro: reemplazan el historial opaco del navegador por
   importes calculados para el registro, mes y descuento elegidos. */

.payment-register-field {
    grid-column: 1 / -1;
    position: relative;
    display: grid;
    min-width: 0;
    gap: 6px;
    color: #000000;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.2;
    text-transform: uppercase;
}

.payment-record-native-select {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
}

.entry-form .payment-record-picker-open {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 18px;
    align-items: center;
    gap: 9px;
    width: 100%;
    min-width: 0;
    min-height: 42px;
    height: auto;
    padding: 7px 13px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    text-align: left;
    text-transform: none;
    box-shadow: none;
    cursor: pointer;
    filter: none;
}

.entry-form .payment-record-picker-open:hover,
.entry-form .payment-record-picker-open:focus-visible,
.entry-form .payment-record-picker-open[aria-expanded="true"] {
    border-color: var(--brand-primary);
    background: #ffffff;
    color: #000000;
    outline: 2px solid color-mix(in srgb, var(--brand-primary) 26%, transparent);
    outline-offset: 1px;
    filter: none;
}

.payment-record-picker-placeholder {
    overflow: hidden;
    font-weight: 700;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.payment-record-picker-selection {
    display: grid;
    grid-template-columns: minmax(52px, 0.7fr) minmax(80px, 1.25fr) minmax(78px, 0.85fr);
    gap: 10px;
    min-width: 0;
}

.payment-record-picker-selection[hidden] {
    display: none;
}

.payment-record-picker-value {
    display: grid;
    gap: 2px;
    min-width: 0;
    padding: 9px 11px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: var(--surface);
}

.entry-form .payment-record-picker-open:not(.is-empty) {
    grid-template-columns: minmax(0, 1fr) 38px;
    padding: 0;
    border: 0;
    background: transparent;
}

.entry-form .payment-record-picker-open:not(.is-empty):hover,
.entry-form .payment-record-picker-open:not(.is-empty):focus-visible,
.entry-form .payment-record-picker-open:not(.is-empty)[aria-expanded="true"] {
    border: 0;
    background: transparent;
    outline: 0;
}

.entry-form .payment-record-picker-open:not(.is-empty) > svg {
    box-sizing: border-box;
    width: 38px;
    height: 38px;
    padding: 9px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: var(--surface);
}

.entry-form .payment-record-picker-open:not(.is-empty):is(:hover, :focus-visible)
    .payment-record-picker-value,
.entry-form .payment-record-picker-open:not(.is-empty):is(:hover, :focus-visible) > svg {
    border-color: var(--brand-primary);
}

.payment-record-picker-value small,
.payment-record-picker-value strong {
    min-width: 0;
    overflow: hidden;
    color: #000000;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.payment-record-picker-value small {
    font-size: 9px;
    font-weight: 850;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.payment-record-picker-value strong {
    font-size: 12px;
    font-weight: 800;
}

.payment-record-picker-open > svg {
    width: 18px;
    height: 18px;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
}

/* En Cargar cobro, Registro usa una sola columna y la misma altura que los
   demás controles. El resumen conserva los tres datos dentro de ese campo. */
.payment-register-field-compact {
    grid-column: auto;
}

.entry-form .payment-register-field-compact .payment-record-picker-open {
    grid-template-columns: minmax(0, 1fr) 18px;
    height: 42px;
    min-height: 42px;
    padding: 0 13px;
    border: 1px solid var(--line-strong);
    background: #ffffff;
}

.entry-form .payment-register-field-compact .payment-record-picker-open:is(:hover, :focus-visible, [aria-expanded="true"]) {
    border: 1px solid var(--brand-primary);
    background: #ffffff;
    outline: 2px solid color-mix(in srgb, var(--brand-primary) 26%, transparent);
    outline-offset: 1px;
}

.payment-register-field-compact .payment-record-picker-selection {
    grid-template-columns: minmax(0, 0.55fr) minmax(0, 1.45fr) auto;
    align-items: center;
    gap: 8px;
}

.payment-register-field-compact .payment-record-picker-value {
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
}

.payment-register-field-compact .payment-record-picker-value small {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
}

.entry-form .payment-register-field-compact .payment-record-picker-open > svg {
    width: 18px;
    height: 18px;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
}

.payment-record-picker-modal {
    z-index: 120;
}

.payment-record-picker-panel {
    grid-template-rows: auto auto auto minmax(0, 1fr);
    width: min(1320px, 100%);
    max-height: min(90dvh, 820px);
    overflow: hidden;
}

.payment-record-picker-panel .record-modal-header h2 {
    font-size: 26px;
}

.payment-record-picker-filters {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    align-items: end;
    gap: 10px;
    min-width: 0;
}

.payment-record-picker-filters label {
    display: grid;
    gap: 6px;
    min-width: 0;
}

.payment-record-picker-filters label > span {
    color: #000000;
    font-size: 11px;
    font-weight: 850;
    letter-spacing: 0.03em;
    line-height: 1.2;
    text-transform: uppercase;
}

.payment-record-picker-filters :is(input, select) {
    width: 100%;
    min-height: 42px;
    padding: 0 12px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    font: inherit;
    font-size: 14px;
    font-weight: 700;
    letter-spacing: normal;
    outline: none;
    text-transform: none;
}

.payment-record-picker-filters select {
    padding-right: 34px;
    font-size: 13px;
}

.payment-record-picker-search input::placeholder {
    color: var(--placeholder);
}

.payment-record-picker-filters :is(input, select):focus {
    border-color: var(--brand-primary);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--brand-primary) 18%, transparent);
}

.payment-record-picker-pagination-toolbar {
    width: 100%;
    min-height: 42px;
    gap: 18px;
    margin: 0;
}

.payment-record-picker-pagination-toolbar > .payment-record-picker-search {
    flex: 0 1 360px;
    width: 360px;
    min-width: 0;
    margin-left: auto;
}

.payment-record-picker-column-head,
.payment-record-picker-option {
    display: grid;
    grid-template-columns: minmax(72px, 0.55fr) minmax(150px, 1.2fr) minmax(110px, 0.8fr) minmax(82px, 0.55fr) minmax(130px, 0.95fr) minmax(125px, 0.85fr);
    align-items: center;
    gap: 13px;
    min-width: 820px;
}

.payment-record-picker-grid {
    min-height: 0;
    overflow: auto;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #ffffff;
    scroll-padding-top: 42px;
}

.payment-record-picker-column-head {
    position: sticky;
    z-index: 2;
    top: 0;
    padding: 11px 14px;
    border-bottom: 1px solid var(--line);
    background: var(--surface-soft);
    color: #000000;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 0.04em;
    line-height: 1.2;
    text-transform: uppercase;
}

.payment-record-picker-list {
    display: grid;
    align-content: start;
    gap: 0;
    min-height: 0;
}

.payment-record-picker-option {
    width: 100%;
    min-height: 52px;
    padding: 10px 14px;
    border: 0;
    border-bottom: 1px solid var(--line);
    border-radius: 0;
    background: #ffffff;
    color: #000000;
    text-align: left;
    box-shadow: none;
    cursor: pointer;
    filter: none;
}

.payment-record-picker-option[hidden] {
    display: none !important;
}

.payment-record-picker-option:last-of-type {
    border-bottom: 0;
}

.payment-record-picker-option:hover,
.payment-record-picker-option:focus-visible {
    background: #f3fbfc;
    color: #000000;
    outline: none;
    box-shadow: inset 0 0 0 2px var(--brand-primary);
    filter: none;
}

.payment-record-picker-option.is-selected {
    background: #eef9fa;
    box-shadow: none;
}

.payment-record-picker-cell {
    min-width: 0;
}

.payment-record-picker-cell strong {
    min-width: 0;
    color: #000000;
    font-size: 13px;
    font-weight: 750;
    line-height: 1.3;
    overflow-wrap: anywhere;
}

.payment-record-picker-cell:nth-child(-n + 2) strong {
    font-size: 14px;
    font-weight: 850;
}






.payment-record-picker-empty {
    margin: 0;
    padding: 18px 12px;
    color: #000000;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.4;
    text-align: center;
}

html[data-theme="dark"] .app-shell .payment-register-field,
html[data-theme="dark"] .app-shell .payment-record-picker-filters label > span,
html[data-theme="dark"] .app-shell .payment-record-picker-column-head,
html[data-theme="dark"] .app-shell .payment-record-picker-option,
html[data-theme="dark"] .app-shell .payment-record-picker-cell strong,
html[data-theme="dark"] .app-shell .payment-record-picker-empty,
