}

html[data-theme="dark"] .app-shell .entry-form .payment-record-picker-open,
html[data-theme="dark"] .app-shell .payment-record-picker-filters :is(input, select),
html[data-theme="dark"] .app-shell .payment-record-picker-grid,
html[data-theme="dark"] .app-shell .payment-record-picker-option {
    background: #121a1e;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .payment-record-picker-filters select option {
    background: #121a1e;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .payment-record-picker-open:hover,
html[data-theme="dark"] .app-shell .entry-form .payment-record-picker-open:focus-visible,
html[data-theme="dark"] .app-shell .entry-form .payment-record-picker-open[aria-expanded="true"] {
    background: #121a1e;
