@media (max-width: 900px) {
    .payment-record-picker-filters {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 640px) {
    .record-modal.payment-record-picker-modal {
        padding: 12px;
    }

    .payment-record-picker-panel {
        grid-template-rows: auto;
        width: 100%;
        max-height: calc(100dvh - 24px);
        overflow-y: auto;
        padding: 26px 16px 16px;
    }

    .payment-record-picker-filters {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .payment-record-picker-pagination-toolbar {
        gap: 12px;
    }

    .payment-record-picker-pagination-toolbar > .payment-record-picker-search {
