    }

    .payment-record-picker-selection {
        grid-template-columns: minmax(48px, 0.65fr) minmax(78px, 1.15fr) minmax(72px, 0.85fr);
        gap: 7px;
    }
}

@media (max-width: 560px) {
    .payment-record-picker-selection {
        grid-template-columns: minmax(0, 1fr);
    }
