/* El descuento conserva el select nativo como valor del formulario, pero se
   presenta con el mismo patrón de dos columnas que las sugerencias de monto. */
.payment-discount-field {
    position: relative;
    display: grid;
    min-width: 0;
    gap: 6px;
    color: #000000;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.2;
    text-transform: uppercase;
}

.payment-discount-label-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    min-width: 0;
}

.entry-form .payment-discount-edit-link {
    flex: 0 0 auto;
    color: var(--link-blue);
    text-transform: none;
}

.payment-discount-native-select {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    border: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
    pointer-events: none;
}

.entry-form .payment-discount-picker-open {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 18px;
    align-items: center;
    gap: 9px;
    width: 100%;
    min-width: 0;
    height: 42px;
    padding: 0 13px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    text-align: left;
    text-transform: none;
    box-shadow: none;
    cursor: pointer;
    filter: none;
}

.entry-form .payment-discount-picker-open:hover,
.entry-form .payment-discount-picker-open:focus-visible,
.entry-form .payment-discount-picker-open[aria-expanded="true"] {
    border-color: var(--brand-primary);
    background: #ffffff;
    color: #000000;
    outline: 2px solid color-mix(in srgb, var(--brand-primary) 26%, transparent);
    outline-offset: 1px;
    filter: none;
}

.payment-discount-picker-open > span {
    min-width: 0;
    overflow: hidden;
    font-weight: 700;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.payment-discount-picker-open svg {
    width: 18px;
    height: 18px;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
    transition: transform 0.16s ease;
}

.payment-discount-picker-open[aria-expanded="true"] svg {
    transform: rotate(180deg);
}

.payment-discount-picker-menu {
    position: absolute;
    z-index: 92;
    top: calc(100% + 6px);
    right: 0;
    display: block;
    width: min(360px, calc(100vw - 32px));
    max-width: calc(100vw - 32px);
    overflow: hidden;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    box-shadow: 0 14px 30px rgba(0, 0, 0, 0.24);
    text-transform: none;
}

.payment-discount-picker-menu[hidden] {
    display: none;
}

.payment-discount-picker-heading,
.entry-form .payment-discount-picker-option {
    display: grid;
    grid-template-columns: minmax(130px, 1fr) minmax(100px, 0.75fr);
    align-items: center;
    gap: 12px;
}

.payment-discount-picker-heading {
    padding: 9px 12px;
    border-bottom: 1px solid var(--line);
    background: var(--surface-soft);
    color: #000000;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.payment-discount-picker-list {
    display: grid;
    max-height: 280px;
    overflow-y: auto;
}

.entry-form .payment-discount-picker-option {
    width: 100%;
    min-width: 0;
    max-width: none;
    min-height: 48px;
    padding: 9px 12px;
    border: 0;
    border-bottom: 1px solid var(--line);
    border-radius: 0;
    background: #ffffff;
    color: #000000;
    text-align: left;
    text-transform: none;
    box-shadow: none;
    filter: none;
}

.entry-form .payment-discount-picker-option:last-child {
    border-bottom: 0;
}

.entry-form .payment-discount-picker-option strong,
.entry-form .payment-discount-picker-option span {
    color: #000000;
    line-height: 1.25;
    overflow-wrap: anywhere;
}

.entry-form .payment-discount-picker-option strong {
    font-size: 15px;
    font-weight: 900;
}

.entry-form .payment-discount-picker-option span {
    font-size: 13px;
    font-weight: 750;
}

.entry-form .payment-discount-picker-option:hover,
.entry-form .payment-discount-picker-option:focus-visible {
    background: #e7f5f7;
    color: #000000;
    outline: 2px solid var(--brand-neutral);
    outline-offset: -2px;
    filter: none;
}

.entry-form .payment-discount-picker-option[aria-selected="true"] {
    background: #dff1f4;
    color: #000000;
}

.payment-discount-edit-panel {
    width: min(720px, 100%);
}

.payment-discount-edit-form {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(220px, 0.75fr);
    gap: 18px;
}

.payment-discount-edit-fields {
    grid-column: 1;
    grid-template-columns: minmax(0, 1fr);
}

.payment-discount-edit-fields label {
    min-width: 0;
}

.payment-discount-edit-fields textarea {
    min-height: 104px;
    resize: vertical;
}

.payment-discount-edit-copy {
    margin: 6px 0 0;
    color: #000000;
    font-size: 13px;
    font-weight: 650;
    line-height: 1.4;
}

.payment-discount-edit-preview {
    grid-column: 2;
    grid-row: 1;
    align-self: stretch;
    min-width: 0;
    padding: 15px;
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--brand-primary);
    border-radius: 8px;
    background: var(--brand-primary-soft);
    color: #000000;
}

.payment-discount-edit-preview h3 {
    margin: 0 0 12px;
    color: #000000;
    font-size: 15px;
    line-height: 1.25;
}

.payment-discount-edit-preview dl {
    display: grid;
    gap: 0;
    margin: 0;
}

.payment-discount-edit-preview dl > div {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
    padding: 9px 0;
    border-bottom: 1px solid var(--line);
}

.payment-discount-edit-preview dl > div:last-child {
    border-bottom: 0;
}

.payment-discount-edit-preview dt,
.payment-discount-edit-preview dd {
    min-width: 0;
    margin: 0;
    color: #000000;
    line-height: 1.3;
}

.payment-discount-edit-preview dt {
    font-size: 12px;
    font-weight: 700;
}

.payment-discount-edit-preview dd {
    font-size: 13px;
    font-weight: 850;
    text-align: right;
    overflow-wrap: anywhere;
}

.payment-discount-edit-preview-total dd {
    color: var(--brand-primary);
    font-size: 16px;
}

.payment-discount-edit-fields small,
.payment-discount-edit-error {
    color: #000000;
    font-size: 12px;
    font-weight: 650;
    line-height: 1.35;
    text-transform: none;
}

.payment-discount-edit-error {
    grid-column: 1 / -1;
    margin: 0;
    color: var(--danger);
    font-weight: 800;
}

.payment-discount-edit-form > .record-modal-actions {
    grid-column: 1 / -1;
}

.payment-movement-description {
    white-space: pre-line;
}

/* El detalle prioriza los datos operativos; las tarjetas funcionan como un
   resumen compacto y la descripción completa queda en cada movimiento. */
.payment-detail-grid {
    grid-template-columns: repeat(auto-fit, minmax(min(140px, 100%), 180px));
    justify-content: start;
    gap: 8px;
}

.payment-detail-grid article {
    min-height: 0;
    padding: 9px 11px;
}

.payment-detail-grid span {
    margin-bottom: 4px;
    font-size: 11px;
    line-height: 1.2;
}

.payment-detail-grid strong {
    font-size: 14px;
    line-height: 1.25;
}

[data-payment-edit-modal][data-payment-editor-mode="add"] .payment-editor-summary {
    display: none;
}

[data-payment-edit-modal][data-payment-editor-mode="add"] .payment-lines > .payment-line:first-child {
    padding: 0;
    border: 0;
    background: transparent;
}

[data-payment-edit-modal][data-payment-editor-mode="add"] .payment-lines > .payment-line:first-child > legend {
    display: none;
}

.entry-form [data-payment-caja-select],
.entry-form [data-payment-caja-select] option,
.parking-cashbox-field,
.parking-cashbox-field :is(button, label, span, small) {
    font-family: var(--font-body);
}

html[data-theme="dark"] .app-shell .payment-discount-field,
html[data-theme="dark"] .app-shell .payment-discount-picker-menu,
html[data-theme="dark"] .app-shell .payment-discount-picker-heading,
html[data-theme="dark"] .app-shell .payment-discount-edit-fields small {
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .payment-discount-edit-copy,
html[data-theme="dark"] .app-shell .payment-discount-edit-preview,
html[data-theme="dark"] .app-shell .payment-discount-edit-preview h3,
html[data-theme="dark"] .app-shell .payment-discount-edit-preview :is(dt, dd) {
