}

html[data-theme="dark"] .app-shell .payment-discount-edit-preview-total dd {
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-open,
html[data-theme="dark"] .app-shell .payment-discount-picker-menu,
html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-option {
    background: #121a1e;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .payment-discount-picker-heading {
    background: #123238;
}

html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-option strong,
html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-option span {
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-open:hover,
html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-open:focus-visible,
html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-open[aria-expanded="true"] {
    background: #121a1e;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-option:hover,
html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-option:focus-visible,
html[data-theme="dark"] .app-shell .entry-form .payment-discount-picker-option[aria-selected="true"] {
    background: #16434a;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .payment-discount-edit-error {
    color: var(--danger);
}

@media (max-width: 640px) {
    .record-modal.payment-discount-edit-modal {
        padding: 12px;
    }

    .payment-discount-edit-panel {
        max-height: calc(100dvh - 24px);
        padding: 26px 16px 16px;
    }

    .payment-discount-edit-form {
        grid-template-columns: minmax(0, 1fr);
        gap: 14px;
    }

    .payment-discount-edit-fields,
    .payment-discount-edit-preview {
        grid-column: 1;
        grid-row: auto;
    }

    .payment-discount-edit-form > .record-modal-actions {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        width: 100%;
    }

    .payment-discount-edit-form > .record-modal-actions > .button {
        width: 100%;
        min-width: 0;
    }
}

/* Varios cobros del mismo registro. El formulario plano se conserva para el
   primer cobro; al agregar otro, cada pago y su caja pasan a su desplegable. */

.payment-multi-cobros {
    grid-column: 1 / -1;
    display: grid;
    gap: 12px;
}

.payment-multi-cobros[hidden] {
    display: none;
}

[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-receipt-field,
[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-receipt-number-field,
[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-date-field,
[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-month-field,
[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-discount-field,
[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-amount-field,
[data-payment-create-form][data-payment-multi-cobros-activo="1"] > .payment-cashbox-field {
    display: none;
}

.app-shell .panel.collapsible-panel.payment-cobro-panel {
    min-width: 0;
    margin: 0;
    border: 1px solid var(--line-strong);
    border-radius: 12px;
}

.app-shell .panel.collapsible-panel.payment-cobro-panel > .collapsible-summary {
    padding: 10px 14px;
}

.app-shell .panel.collapsible-panel.payment-cobro-panel.is-incomplete {
    border-color: var(--danger);
}

.app-shell .panel.collapsible-panel.payment-cobro-panel.is-incomplete > .collapsible-summary {
    background: #fde2e5;
    box-shadow: inset 4px 0 0 var(--danger);
}

.app-shell .panel.collapsible-panel.payment-cobro-panel.is-complete {
    border-color: var(--positive);
}

.app-shell .panel.collapsible-panel.payment-cobro-panel.is-complete > .collapsible-summary {
    background: #eefaf6;
    box-shadow: inset 4px 0 0 var(--positive);
}

.app-shell .panel.collapsible-panel.payment-cobro-panel > .collapsible-summary .collapsible-heading {
    color: #000000;
}

.app-shell .panel.collapsible-panel.payment-cobro-panel.is-incomplete > .collapsible-summary .collapsible-indicator {
    border-color: var(--danger);
    color: var(--danger);
}

.app-shell .panel.collapsible-panel.payment-cobro-panel.is-complete > .collapsible-summary .collapsible-indicator {
    border-color: var(--positive);
    color: var(--positive);
}

.payment-cobro-body {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    align-items: end;
    gap: 13px;
}

.payment-cobro-body label {
    display: grid;
    gap: 6px;
    min-width: 0;
}

.payment-cobro-receipt-field {
    grid-column: span 2;
}

.payment-cobro-discount-input[readonly] {
