    }
}

@media (max-width: 640px) {
    .payment-cobro-body {
        grid-template-columns: minmax(0, 1fr);
    }

    .payment-cobro-receipt-field,
    .payment-cobro-number-field {
        grid-column: 1;
    }

    .payment-cobro-actions {
