       los iconos no se estiran, pero siguen cerrando la fila por la derecha. */
    .module-tabs .module-tabs-icons {
        flex: 0 0 auto;
    }
}
/* Modelo Luna: página pública de Empresa y sus sucursales. */

.public-template-luna {
    --luna-paper: #f3f3f1;
    --luna-surface: #ffffff;
    --luna-surface-raised: #e7e7e4;
    --luna-line: #8f8f8a;
    --luna-night: #111217;
    --luna-night-raised: #272830;
    --luna-ink: #000000;
    --luna-light: #ffffff;
    --public-accent: #111217;
    --public-accent-strong: #000000;
    --public-surface: #ffffff;
    --public-soft: #e7e7e4;
    --public-ink: #000000;
    --public-muted: #000000;
    --public-line: #8f8f8a;
    background: var(--luna-paper);
    color: #000000;
}

.public-template-luna .public-sticky-nav {
    border-bottom: 1px solid #8f8f8a;
    background: #ffffff;
    color: #000000;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.16);
}

.public-template-luna .public-sticky-nav :is(
    .public-design-brand strong,
    .public-sticky-links a,
    .public-theme-toggle
) {
    color: #000000;
}

.public-template-luna .public-sticky-links > a:is(:hover, :focus-visible),
.public-template-luna .public-sticky-theme:is(:hover, :focus-visible) {
    background: #e7e7e4;
    color: #000000;
}

.public-template-luna .public-sticky-theme {
    border-color: #000000;
    background: #ffffff;
}

.public-template-luna .luna-hero {
    position: relative;
    isolation: isolate;
    min-height: min(780px, calc(100svh - var(--public-nav-height, 76px)));
    overflow: hidden;
    padding: clamp(44px, 7vw, 108px) max(20px, calc((100vw - 1440px) / 2));
    background:
        radial-gradient(circle at 82% 22%, #45464f 0 3%, transparent 3.3%),
        radial-gradient(circle at 14% 18%, #383941 0 1px, transparent 2px),
        radial-gradient(circle at 30% 74%, #ffffff 0 1px, transparent 2px),
        linear-gradient(145deg, #07080c 0%, #191a21 56%, #30313a 100%);
    color: #ffffff;
}

.public-template-luna .luna-hero-media {
    position: absolute;
    z-index: -2;
    inset: 0;
}

.public-template-luna .luna-hero-media img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: grayscale(1) contrast(1.08) brightness(0.44);
}

.public-template-luna .luna-hero-media::after {
    position: absolute;
    inset: 0;
    background: linear-gradient(96deg, #07080c 8%, rgba(7, 8, 12, 0.86) 48%, rgba(7, 8, 12, 0.34));
    content: "";
}

.public-template-luna .luna-hero-stars {
    position: absolute;
    z-index: -1;
    inset: 0;
    background-image:
        radial-gradient(circle at 8% 32%, #ffffff 0 1px, transparent 1.5px),
        radial-gradient(circle at 24% 13%, #ffffff 0 1px, transparent 1.5px),
        radial-gradient(circle at 42% 78%, #ffffff 0 1px, transparent 1.5px),
        radial-gradient(circle at 60% 19%, #ffffff 0 1px, transparent 1.5px),
