/* Preferencias propias; Google se carga únicamente después de aceptar. */
.analytics-controls {
    --analytics-surface: #ffffff;
    --analytics-ink: #000000;
    position: relative;
    z-index: 1200;
    color: var(--analytics-ink);
    font-family: Inter, sans-serif;
}

html:is([data-theme="dark"], [data-landing-theme="dark"], [data-public-parking-theme="dark"]) .analytics-controls {
    --analytics-surface: #171717;
    --analytics-ink: #ffffff;
}

.analytics-controls [hidden] { display: none !important; }

.analytics-banner {
    position: fixed;
    bottom: max(12px, env(safe-area-inset-bottom));
    left: 12px;
    border: 1px solid #7c3aed;
    border-radius: 8px;
    background: var(--analytics-surface);
    color: var(--analytics-ink);
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.16);
}

.legal-privacy-preferences {
    display: inline-block;
    max-width: 100%;
    min-height: 44px;
    padding: 8px 0;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: left;
    text-decoration: none;
    cursor: pointer;
}
.legal-privacy-preferences[hidden] { display: none; }
.legal-privacy-preferences:focus-visible { outline: 3px solid #7c3aed; outline-offset: 3px; }

.analytics-banner {
    right: 12px;
    display: flex;
    align-items: center;
    gap: 24px;
    max-height: calc(100dvh - 24px);
    overflow-y: auto;
    padding: 18px 24px;
    box-sizing: border-box;
    font-size: 14px;
    line-height: 1.5;
}

.analytics-copy { flex: 1 1 540px; min-width: 0; }
.analytics-banner h2 { margin: 0 0 6px; font-size: 16px; color: var(--analytics-ink); }
.analytics-banner p { margin: 4px 0 0; color: var(--analytics-ink); }
.analytics-banner a { color: var(--analytics-ink); text-decoration: none; }
.analytics-choice:empty { display: none; }
.analytics-actions { display: flex; flex: 0 1 480px; flex-wrap: wrap; gap: 8px; }
.analytics-actions button {
    flex: 1 1 180px;
    min-height: 42px;
    border: 1px solid #7c3aed;
    border-radius: 8px;
    padding: 8px 12px;
    background: var(--analytics-surface);
    color: var(--analytics-ink);
    font: inherit;
    font-weight: 600;
    cursor: pointer;
}
.analytics-actions button:disabled { cursor: wait; }
.analytics-actions [data-analytics-close] { flex-basis: 100%; }
.analytics-controls :is(button, a):focus-visible { outline: 3px solid #7c3aed; outline-offset: 3px; }
@media (max-width: 760px) {
    .analytics-banner { display: block; padding: 16px; }
    .analytics-actions { margin-top: 12px; }
}
@media print { .analytics-controls { display: none; } }
/* Los ejemplos no forman parte del catálogo de ubicaciones o cuentas. */
html:root .app-shell .location-dependent-picker {
    display: block;
    width: 100%;
    min-width: 0;
