/* Todas las ayudas usan el círculo del logo de la empresa y se abren por clic. */
.field-info {
    position: relative;
    display: inline-flex;
    align-items: center;
    align-self: center;
    vertical-align: middle;
    text-transform: none;
}

/* El envoltorio no hereda la placa de las listas que también usan spans. */
:root .field-info {
    padding: 0 !important;
    border: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
}

.field-info[hidden],
.field-info-button[hidden],
.field-info-popover[hidden] {
    display: none !important;
}

/* La especificidad unifica también las variantes históricas dentro de modales. */
:root .app-shell button.field-info-button,
:root button.field-info-button,
:root .app-shell button.field-info-button:is(:hover, :focus-visible) {
    position: static !important;
    inset: auto !important;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 17px !important;
    width: 17px !important;
    min-width: 17px !important;
    height: 17px !important;
    min-height: 17px !important;
    padding: 0 !important;
    margin: 0 !important;
    border: 0 !important;
    border-radius: 50% !important;
    background: var(--brand-primary) !important;
    color: #ffffff !important;
    font-size: 11px !important;
    font-weight: 900 !important;
    line-height: 1 !important;
    cursor: pointer !important;
    box-shadow: none !important;
    transform: none !important;
    filter: none !important;
}

:root .app-shell button.field-info-button:focus-visible,
:root button.field-info-button:focus-visible {
    outline: 2px solid var(--brand-primary);
    outline-offset: 3px;
}

/* Los avisos no aparecen por hover ni por recibir foco. */
:root .app-shell .field-info .field-info-popover,
:root .field-info .field-info-popover {
    position: fixed;
    inset: auto;
    z-index: 10050;
    display: grid;
    box-sizing: border-box;
    width: min(360px, calc(100vw - 16px));
    min-width: 0;
    max-width: calc(100vw - 16px);
    max-height: calc(100dvh - 16px);
    overflow: auto;
    gap: 5px;
    margin: 0;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    box-shadow: 0 18px 44px rgba(16, 24, 33, 0.16);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.35;
    text-align: left;
    text-transform: none;
    white-space: normal;
    opacity: 1;
    visibility: visible;
    transform: none;
    pointer-events: auto;
    transition: none;
}

.field-info-popover img {
    display: block;
    max-width: 100%;
    max-height: min(320px, 60dvh);
    object-fit: contain;
}

/* El aviso de una URL conserva su lugar dentro del campo, con el mismo botón. */
