.module-guide-section {
    --guide-surface: #ffffff;
    --guide-summary: linear-gradient(135deg, #fafafa, #f3f3f3);
    --guide-open: linear-gradient(135deg, #f3eafa, #faf5ff);
    --guide-line: #d7d7d7;
    --guide-accent: #6d28d9;
    display: grid;
    gap: 24px;
    color: var(--ink);
}

.module-guide {
