}

html[data-landing-theme="dark"] .module-guide-section {
    --guide-surface: #101010;
    --guide-summary: linear-gradient(135deg, #1b1b1b, #141414);
    --guide-open: linear-gradient(135deg, #2b2032, #211925);
    --guide-line: #383838;
    --guide-accent: #ad3fe3;
