    text-decoration: none;
}
.module-guide-video-links [data-guide-link-status] {
    min-width: 0;
    max-width: 100%;
    color: var(--ink);
    font-size: 13px;
    line-height: 1.5;
    overflow-wrap: anywhere;
}
.module-guide-video-links [data-guide-link-status]:empty { display: none; }
.module-guide-video {
    width: min(100%, calc(var(--guide-player-height) * 1.5));
    max-width: 100%;
    margin: 0 auto;
    overflow: hidden;
    border: 1px solid var(--guide-line);
    border-radius: 10px;
    background: #000000;
}
.module-guide-video video {
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: 3 / 2;
    object-fit: contain;
    background: #000000;
}
.module-guide-video figcaption {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 14px;
    color: #ffffff;
    font-size: 14px;
}

/* La vista general de la portada conserva su captura auténtica por tema. */
.module-guide-hero { width: 100%; align-self: center; }
.module-guide-shot { margin: 0; overflow: hidden; border: 1px solid var(--line); border-radius: 10px; }
.module-guide-shot > a { display: block; }
.module-guide-shot img { display: block; width: 100%; height: auto; }
.module-guide-shot img.module-guide-shot-dark { display: none; }
html[data-landing-theme="dark"] .module-guide-shot img.module-guide-shot-light { display: none; }
html[data-landing-theme="dark"] .module-guide-shot img.module-guide-shot-dark { display: block; }
.module-guide-shot figcaption { padding: 12px 16px; color: var(--ink); font-size: 14px; line-height: 1.5; }

@media (max-width: 1100px) {
    .module-guide-index { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
    .module-guide-body,
    .module-guide-chapter-body,
    .module-guide-panel-body,
    .module-guide-block-body { padding: 10px; gap: 12px; }
    .module-guide-section details.panel.collapsible-panel > .collapsible-summary { min-height: 60px; padding: 12px; gap: 10px; }
    .module-guide-section .collapsible-summary .collapsible-heading { font-size: 18px; }
    .module-guide-section .collapsible-summary .collapsible-indicator { flex-basis: 30px; width: 30px; height: 30px; }
    .module-guide-index {
        grid-template-columns: none;
        grid-auto-flow: column;
        grid-auto-columns: 160px;
        gap: 8px;
        padding: 8px;
        overflow-x: auto;
        overscroll-behavior-inline: contain;
        scrollbar-width: thin;
    }
    .module-guide-num { margin-right: 6px; }
}
/* Herramientas consume los controles y las filas compartidas de Registro. */

/* Las métricas comparten las superficies semánticas de Registro y Cobros. */
html:root .app-shell .parking-tools-kpis .kpi-card {
    --wk-kpi-surface: var(--surface-soft);
}

html:root .app-shell .parking-tools-kpis .kpi-card[data-kpi-id="tools_cameras"] {
    --wk-kpi-surface: var(--parking-partial-background);
}

html:root .app-shell .parking-tools-kpis .kpi-card.tone-positive {
    --wk-kpi-surface: var(--active-row-background);
}

html:root .app-shell .parking-tools-kpis .kpi-card.tone-danger {
    --wk-kpi-surface: var(--ended-row-background);
}

html:root .app-shell .parking-tools-kpis .kpi-card:is(.tone-warning, .tone-partial) {
    --wk-kpi-surface: var(--reservation-row-background);
}

html:root .app-shell .parking-tools-kpis .kpi-card > :is(span, strong) {
    color: var(--ink);
}

.tools-shell {
    display: grid;
    gap: 14px;
    margin-top: 18px;
}

/* La primera tarjeta arranca pegada al título: el `gap` de la grilla separa las
   demás. El margen entre hermanas lo anula 00-report.css junto con el de las
   otras pestañas que envuelven sus tarjetas en una grilla; puesto acá perdía la
   cascada contra el selector de hermanos y quedaban al doble de distancia. */
.tools-shell > .panel.collapsible-panel {
    margin-top: 0;
}

/* El contenedor de sección ya aporta 14 px: completar los 18 px de
   Herramientas sin sumar de nuevo el margen del contenedor anidado. */
.variables-shell[data-workraken-section-form] > .variables-shell[data-gestion-herramientas] {
    margin-top: 4px;
}

.tools-body {
    display: grid;
    gap: 12px;
    margin-top: 4px;
}

.tools-note {
    margin: 0;
    color: var(--ink);
    font-size: 13px;
    font-weight: 600;
    line-height: 1.5;
}

.tools-note-muted {
    color: var(--muted);
}

/* El renglón que cuenta si el Conector ya se anotó. Arranca apagado —es una
   espera, no un dato— y se pone verde cuando la máquina aparece. */
.tools-connector-notice {
    color: var(--muted);
}

.tools-connector-notice.tone-positive {
    color: var(--positive);
}

.tools-connector-notice[hidden] {
    display: none;
}

.tools-fields {
    margin-top: 0;
}

.tools-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
}

.tools-actions-hint {
    color: var(--muted);
    font-size: 12px;
    font-weight: 700;
}

/* La ayuda va en su propio renglón: al lado del switch le comía el ancho al
   nombre, que terminaba partido en dos líneas. */
.visibility-toggle.tools-toggle {
    flex-wrap: wrap;
    align-content: center;
    row-gap: 6px;
}

.visibility-toggle.tools-toggle > .visibility-name {
    order: 1;
}

.visibility-toggle.tools-toggle > .mini-switch {
    order: 2;
}

.tools-toggle-hint {
    flex: 1 0 100%;
    order: 3;
    color: var(--muted);
    font-size: 12px;
    font-weight: 600;
    line-height: 1.35;
}

/* Los estados se leen como los de Registro, sin una segunda caja por celda. */
.tools-chip {
    display: inline-block;
    color: var(--ink);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.4;
    white-space: nowrap;
}

/* El contorno pertenece a cada fila oficial; el área de desplazamiento no
   añade un marco y deja que los campos consuman el estilo común de entrada. */
html:root .app-shell .tools-table-wrap.entry-form {
    display: block;
    max-width: 100%;
    overflow: auto;
}

html:root .app-shell .tools-table-wrap[hidden] {
    display: none;
}

html:root .app-shell .tools-table-wrap > .wk-separated-table {
    background: transparent;
    box-shadow: none;
}

.tools-table-wrap .button-compact {
    min-width: 0;
}

/* Las cámaras cargadas son una grilla, una fila por cámara, como la tabla de
   Registros: un grabador de cuatro entra en cuatro renglones que se leen de un
   vistazo, en vez de cuatro fichas desplegables con todos sus campos abiertos.
   El orden de las filas es el orden del mosaico. */
.tools-cameras-wrap {
    margin-top: 2px;
}

.tools-cameras-table {
    width: 100%;
    min-width: 1480px;
}

.tools-cameras-table td {
    vertical-align: middle;
}

.tools-cameras-table input,
.tools-cameras-table select {
    width: 100%;
    min-width: 0;
}

/* El ancho de cada columna va con el selector de la tabla adelante: la regla
   general de arriba es más específica y, sin esto, le ganaba a todas —el nombre
   quedaba en una cajita de dos letras—. */
.tools-cameras-table .tools-camera-nombre {
    min-width: 170px;
}

.tools-cameras-table .tools-camera-host,
.tools-cameras-table .tools-camera-usuario,
.tools-cameras-table .tools-camera-clave {
    min-width: 130px;
}

.tools-cameras-table .tools-camera-ruta {
    min-width: 230px;
}

.tools-cameras-table .tools-camera-canal,
.tools-cameras-table .tools-camera-puerto {
    min-width: 74px;
}

.tools-cameras-table select {
    min-width: 150px;
}

.tools-camera.is-dragging {
    opacity: 0.5;
}

/* El ojito de la contraseña de la cámara. La caja es la misma del login, pero
   acá el campo vive en la grilla de campos del panel. */
.tools-password-field {
    position: relative;
    display: block;
}

.tools-password-field > input {
    width: 100%;
    padding-right: 44px;
}

.tools-password-field > .password-toggle {
    position: absolute;
    top: 50%;
    right: 4px;
    display: inline-grid;
    width: 34px;
    min-width: 34px;
    height: 34px;
    padding: 0;
    border: 0;
    border-radius: 6px;
    place-items: center;
    transform: translateY(-50%);
    background: transparent;
    color: var(--muted);
    cursor: pointer;
}

.tools-password-field > .password-toggle:hover,
.tools-password-field > .password-toggle:focus-visible {
    background: rgba(109, 40, 217, 0.08);
    color: var(--brand-primary);
}

/* El mosaico: cuántas cámaras entran a la vez lo elige el dueño arriba, y las
   que no entran esperan su página. */
.tools-wall-toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.tools-wall-toolbar > .tools-connect-modes {
    margin-bottom: 0;
}

.tools-wall {
    display: grid;
    gap: 10px;
    margin-top: 12px;
    grid-template-columns: repeat(var(--tools-wall-columns, 2), minmax(0, 1fr));
}

.tools-wall[data-tools-wall-columns="1"] {
    --tools-wall-columns: 1;
}

.tools-wall[data-tools-wall-columns="2"] {
    --tools-wall-columns: 2;
}

.tools-wall[data-tools-wall-columns="3"] {
    --tools-wall-columns: 3;
}

.tools-wall-tile {
    display: grid;
    gap: 8px;
    min-width: 0;
}

.tools-wall-tile[hidden] {
    display: none;
}

.tools-wall-tile-foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.tools-wall-tile-name {
    color: var(--ink);
    font-size: 13px;
    font-weight: 700;
    overflow-wrap: anywhere;
}

.tools-wall-pager {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 10px;
}

.tools-wall-pager[hidden] {
    display: none;
}

.tools-wall-page-label {
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
}

/* La pantalla guarda su lugar aunque no haya imagen: sin alto propio, prender
   el vivo empujaría todo el formulario hacia abajo de un salto. */
.tools-camera-live-screen {
    position: relative;
    display: grid;
    place-items: center;
    width: 100%;
    min-height: 180px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
    overflow: hidden;
}

.tools-camera-live-video {
    display: block;
    width: 100%;
    max-height: 60vh;
    border-radius: 8px;
    object-fit: contain;
    background: #000;
}

/* El apagado no deja un rectángulo negro: `display: block` le gana al atributo
   `hidden`, y el mosaico quedaba con un cuadro negro por cámara aunque ninguna
   estuviera transmitiendo. */
.tools-camera-live-video[hidden] {
    display: none;
}

.tools-camera-live-state {
    margin: 0;
    color: var(--ink);
    font-size: 13px;
    font-weight: 600;
    text-align: center;
}

/* Con video el cartel pasa a ser un rótulo encima, no un párrafo debajo: el
   estado tiene que verse sin correr el cuadro de lugar. */
.tools-camera-live-video:not([hidden]) + .tools-camera-live-state {
    position: absolute;
    top: 10px;
    left: 10px;
    padding: 3px 10px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--positive) 18%, var(--surface));
    color: var(--positive);
    font-size: 12px;
}

/* Las máquinas con el Conector prendido: una grilla con una fila por PC, como
   la de Registros. Se lee de un vistazo cuántas hay, cuál está vinculada y cuál
   atiende el video —el turno 1 es la que lo hace—. */
.tools-servers-wrap {
    margin-top: 2px;
}

.tools-servers-table {
    width: 100%;
    /* Siete columnas cortas: la grilla general pide 900px y dejaba la barra de
       scroll puesta con la mitad de la tabla vacía. */
    min-width: 660px;
}

.tools-machine-turn-cell {
    white-space: nowrap;
}

.tools-machine-turn {
    display: inline-block;
    min-width: 22px;
    vertical-align: middle;
    color: var(--ink);
    font-size: 12px;
    font-weight: 800;
}

/* El asa: se arrastra desde acá y no desde la fila entera, para que se pueda
   seleccionar el nombre sin empezar un arrastre. */
.tools-table-wrap .tools-machine-handle {
    display: inline-grid;
    place-items: center;
    width: 30px;
    min-width: 30px;
    height: 30px;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: rgba(126, 34, 206, 0.08);
    color: var(--brand-primary);
    cursor: grab;
    touch-action: none;
    vertical-align: middle;
    margin-right: 8px;
}

.tools-machine-handle svg {
    width: 18px;
    height: 18px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.65;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.tools-machine-handle:hover,
.tools-machine-handle:focus-visible {
    border-color: var(--brand-primary);
    background: rgba(126, 34, 206, 0.14);
    outline: none;
}

.tools-machine-handle:focus-visible {
    outline: 2px solid var(--wk-field-focus-color);
    outline-offset: -2px;
}

.tools-machine-handle:active,
.tools-machine.is-dragging .tools-machine-handle {
    cursor: grabbing;
}

.tools-machine.is-dragging {
    opacity: 0.5;
}

.tools-machine-name {
    width: 100%;
    min-width: 150px;
}

.tools-machine-meta {
    color: var(--ink);
    font-size: 12px;
}

.tools-machine-actions-cell {
    text-align: right;
}

/* Conectar una cámara: los tres caminos —red, serie, QR— comparten el pie de
   usuario y contraseña, así que el que está elegido se marca en el botón. */
.tools-connect-modes {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 12px;
}

.tools-connect-step {
    display: grid;
    gap: 10px;
}

/* Los tres caminos se apagan con `hidden`, pero las clases de arriba fijan un
   `display` que le gana al atributo: sin estas reglas se ven los tres a la vez
   —el campo de la serie y el botón del QR aparecían dentro de "Buscar en la
   red"—. Lo mismo con el pie de usuario y contraseña, que es `.entry-form`. */
.tools-connect-step[hidden],
.tools-connect-alta[hidden] {
    display: none;
}

.tools-connect-alta {
    display: grid;
    gap: 12px;
    margin-top: 12px;
}

.tools-connect-qr {
    display: grid;
    gap: 8px;
    justify-items: start;
}

.tools-connect-qr-button {
    cursor: pointer;
}

/* El campo de archivo se maneja desde el botón, pero no se esconde con
   `hidden`: así sigue existiendo para quien navega con el teclado. */
.tools-connect-qr-input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    border: 0;
    clip-path: inset(50%);
    overflow: hidden;
}

.tools-connect-qr-state,
.tools-connect-state {
    margin: 0;
    color: var(--ink);
    font-size: 13px;
    font-weight: 600;
}

.tools-connect-state[data-tono="positive"] {
    color: var(--positive);
}

.tools-connect-state[data-tono="danger"] {
    color: var(--danger);
}

.tools-connect-state[data-tono="partial"] {
    color: var(--accent-amber);
}

.tools-access-block {
    display: grid;
    gap: 10px;
    padding: 12px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
}

.tools-discovered-wrap {
    margin-top: 2px;
}

.tools-discovered-table {
    width: 100%;
}

.tools-empty {
    margin: 0;
}

html[data-theme="dark"] .app-shell .tools-access-block {
    border-color: var(--line);
    background: var(--surface);
    color: var(--ink);
}

@media (max-width: 760px) {
    .tools-actions {
        align-items: stretch;
    }

    /* En el teléfono no entran cuatro cuadros de video uno al lado del otro:
       sea cual sea el mosaico elegido, van de a uno por renglón. El selector
       lleva el atributo a propósito: sin él le gana la regla de las columnas. */
    .tools-wall[data-tools-wall-columns] {
        --tools-wall-columns: 1;
    }
}
/* Página 404 jugable: una sola composición con identidad visual Workraken. */
.error-game-page {
    --error-game-bg: #edf8f8;
    --error-game-surface: #ffffff;
    --error-game-surface-soft: #e2f2f3;
    --error-game-message-bg: #dff4f5;
    --error-game-line: #b8d8dc;
    --error-game-violet: #6D28D9;
    --error-game-violet-strong: #4C1D95;
    --error-game-yellow: #ffd166;
    --error-game-violet: #7c3aed;
    --error-game-coral: #ff806d;
    height: 100vh;
    height: 100svh;
    min-height: 100vh;
    min-height: 100svh;
    margin: 0;
    overflow-x: hidden;
    overflow-y: auto;
    display: grid;
    grid-template-rows: auto minmax(0, 1fr);
    background:
        radial-gradient(circle at 5% 14%, rgba(255, 209, 102, 0.38), transparent 19rem),
        radial-gradient(circle at 94% 76%, rgba(124, 58, 237, 0.14), transparent 25rem),
        linear-gradient(145deg, var(--error-game-bg), #ffffff);
    color: var(--ink);
}

html[data-theme="dark"] .error-game-page {
    --error-game-bg: #0f181c;
    --error-game-surface: #1a282d;
    --error-game-surface-soft: #26383e;
    --error-game-message-bg: #123139;
    --error-game-line: #49636b;
    --error-game-violet: #A855F7;
    --error-game-violet-strong: #7E22CE;
    background:
        radial-gradient(circle at 5% 14%, rgba(255, 209, 102, 0.16), transparent 19rem),
        radial-gradient(circle at 94% 76%, rgba(124, 58, 237, 0.2), transparent 25rem),
        var(--error-game-bg);
    color: #ffffff;
}

.error-game-header {
    position: relative;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    min-height: 60px;
    padding: 8px clamp(16px, 4vw, 56px);
    border-bottom: 1px solid var(--error-game-line);
    background: var(--error-game-surface);
    box-shadow: 0 7px 24px rgba(109, 40, 217, 0.08);
}

.error-game-brand,
.error-game-header-actions,
.error-game-theme,
.error-game-home-link {
    display: inline-flex;
    align-items: center;
}

.error-game-brand {
    gap: 9px;
    min-width: 0;
}

.error-game-mark {
    width: 38px;
    height: 38px;
    object-fit: contain;
}

.error-game-wordmark-wrap {
    display: inline-grid;
    align-items: center;
}

.error-game-wordmark {
    grid-area: 1 / 1;
    width: 122px;
    max-height: 27px;
    object-fit: contain;
    object-position: left center;
}

.error-game-wordmark-dark {
    display: none;
}

html[data-theme="dark"] .error-game-wordmark-light {
    display: none;
}

html[data-theme="dark"] .error-game-wordmark-dark {
    display: block;
}

.error-game-header-actions {
    justify-content: flex-end;
    gap: 8px;
}

.error-game-theme,
.error-game-home-link {
    justify-content: center;
    min-height: 44px;
    padding: 8px 13px;
    border: 1px solid var(--error-game-line);
    border-radius: 10px;
    background: var(--error-game-surface);
    color: var(--ink);
    font-weight: 750;
    cursor: pointer;
}

.error-game-theme {
    gap: 7px;
}

.error-game-theme-icon {
    font-size: 18px;
    line-height: 1;
}

.error-game-theme:is(:hover, :focus-visible),
.error-game-home-link:is(:hover, :focus-visible) {
    border-color: var(--error-game-violet);
    background: var(--error-game-surface-soft);
}

.error-game-main {
    display: grid;
    width: 100%;
    min-height: 0;
    margin: 0;
    padding: 0;
}

.error-game-visual {
    display: grid;
    grid-template-columns: clamp(270px, 20vw, 360px) minmax(0, 1fr);
    width: 100%;
    height: 100%;
    min-height: 0;
    min-width: 0;
    overflow-x: clip;
    overflow-y: visible;
    background:
        radial-gradient(circle at 4% 84%, rgba(255, 209, 102, 0.34), transparent 16rem),
        radial-gradient(circle at 18% 16%, rgba(124, 58, 237, 0.1), transparent 22rem),
        var(--error-game-surface);
}

.error-game-message {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-width: 0;
    overflow: visible;
    padding: clamp(26px, 3vw, 54px);
    background: transparent;
    isolation: isolate;
}

.error-game-message::before,
.error-game-message::after {
    position: absolute;
    z-index: -1;
    content: "";
    transform: rotate(18deg);
}

.error-game-message::before {
    top: 26%;
    right: -20px;
    width: 92px;
    height: 92px;
    border-radius: 28px;
    background: rgba(255, 128, 109, 0.28);
}

.error-game-message::after {
    bottom: 8%;
    left: -22px;
    width: 62px;
    height: 62px;
    border-radius: 50%;
    background: rgba(124, 58, 237, 0.2);
}

.error-game-message-copy {
    position: relative;
    z-index: 2;
}

.error-game-code {
    display: inline-flex;
    margin: 0 0 16px;
    padding: 7px 11px;
    border: 1px solid #d99b18;
    border-radius: 999px;
    background: var(--error-game-yellow);
    color: #000000;
    font-size: 11px;
    font-weight: 850;
    letter-spacing: 0.11em;
}

.error-game-message h1 {
    max-width: 7ch;
    margin: 0;
    color: var(--ink);
    font-size: clamp(40px, 3.4vw, 60px);
    font-weight: 850;
    letter-spacing: -0.055em;
    line-height: 0.98;
}

.error-game-message-copy > p:last-child {
    max-width: 27ch;
    margin: 18px 0 0;
    color: var(--ink);
    font-size: 17px;
    font-weight: 650;
