}

.error-game-illustration-frame {
    position: relative;
    z-index: 1;
    display: grid;
    place-items: center;
    min-height: 0;
    margin-top: 22px;
}

.error-game-illustration {
    display: block;
    width: min(100%, clamp(230px, 18vw, 320px));
