    min-width: 0;
    overflow: hidden;
    border: 1px solid #000000;
    border-radius: 12px;
    background: #000000;
    box-shadow: 0 10px 26px rgba(0, 0, 0, 0.24);
    isolation: isolate;
}

.error-game-board canvas {
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: var(--game-aspect, 3 / 2);
    background: #000000;
    touch-action: none;
}

.error-game-board canvas:focus-visible {
    outline: 5px solid var(--error-game-violet);
    outline-offset: -8px;
}

.error-game-pause-float {
    position: absolute;
    top: 12px;
    right: 12px;
    z-index: 4;
    display: grid;
    place-items: center;
    width: 44px;
    height: 44px;
    padding: 0;
    border: 2px solid #000000;
    border-radius: 10px;
    background: var(--error-game-yellow);
    color: #000000;
    font-size: 20px;
    font-weight: 900;
    line-height: 1;
    cursor: pointer;
    box-shadow: 3px 3px 0 #000000;
}

.error-game-pause-float[hidden] {
    display: none;
}

.error-game-pause-float:is(:hover, :focus-visible) {
    transform: translate(1px, 1px);
    box-shadow: 2px 2px 0 #000000;
}

.error-game-overlay {
    position: absolute;
    inset: 0;
    z-index: 3;
    display: grid;
    place-items: center;
    padding: 12px;
    pointer-events: none;
}

.error-game-overlay[hidden] {
    display: none;
}

.error-game-overlay-panel {
    width: min(310px, 100%);
    padding: 18px;
    border: 3px solid var(--error-game-yellow);
    border-radius: 16px;
    background: var(--error-game-violet-strong);
