    text-align: center;
    pointer-events: auto;
}

.error-game-overlay-panel h2 {
    margin: 0;
    color: #ffffff;
    font-size: 28px;
    font-weight: 850;
    letter-spacing: -0.035em;
    line-height: 1.05;
}

.error-game-settings {
    display: grid;
    grid-template-columns: minmax(0, 1.55fr) minmax(82px, 0.75fr);
    gap: 7px;
    margin-top: 12px;
}

.error-game-scenario,
.error-game-level {
    display: grid;
    gap: 4px;
    min-width: 0;
    color: #ffffff;
    text-align: left;
}

.error-game-scenario > span,
.error-game-level > span {
    color: #ffffff;
    font-size: 10px;
    font-weight: 850;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.error-game-scenario select,
.error-game-level select {
    width: 100%;
    min-height: 44px;
    padding: 6px 34px 6px 10px;
    border: 2px solid #000000;
    border-radius: 9px;
    background: #ffffff;
    color: #000000;
    font-size: 13px;
    font-weight: 800;
    cursor: pointer;
}

.error-game-scenario select:disabled,
.error-game-level select:disabled {
    border-style: dashed;
    background: var(--error-game-surface-soft);
    color: var(--ink);
    cursor: default;
}

.error-game-settings[hidden],
.error-game-legend[hidden] {
    display: none;
}

.error-game-legend {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 18px;
    margin-top: 10px;
    color: #ffffff;
    font-size: 12px;
    font-weight: 800;
}

.error-game-legend > span {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: #ffffff;
}

.error-game-legend i {
    position: relative;
    display: inline-block;
    flex: 0 0 auto;
    width: 18px;
    height: 18px;
    border: 2px solid #ffffff;
    border-radius: 50%;
    outline: 2px solid #000000;
}

.error-game-legend-player {
    background: var(--error-game-violet);
    box-shadow: 0 0 0 4px rgba(255, 209, 102, 0.46);
}

.error-game-legend-player::after {
    position: absolute;
    top: 4px;
    left: 5px;
    width: 0;
    height: 0;
    border-top: 3px solid transparent;
    border-bottom: 3px solid transparent;
    border-left: 6px solid var(--error-game-yellow);
    content: "";
}

.error-game-legend-rival {
    background: radial-gradient(circle at 35% 30%, #f59aaa, #7c3aed 58%, #5b21b6);
}

.error-game-primary {
    min-width: 132px;
    min-height: 44px;
    margin-top: 12px;
    padding: 9px 18px;
    border: 2px solid #000000;
    border-radius: 10px;
    background: var(--error-game-yellow);
    color: #000000;
    font-weight: 850;
    cursor: pointer;
    box-shadow: 4px 4px 0 #000000;
}

.error-game-primary:is(:hover, :focus-visible) {
    transform: translate(2px, 2px);
    box-shadow: 2px 2px 0 #000000;
}

.error-game-play[data-game-state="won"] .error-game-overlay {
    align-items: end;
}

.error-game-visually-hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

