.error-game-stats { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px; margin-bottom: 12px; color: var(--ink); font-size: 14px; }
.error-game-stats progress { width: 100%; height: 7px; accent-color: var(--error-game-violet); }
.error-game-random-note { align-self: center; margin: 0; color: #ffffff; font-size: 14px; text-align: left; }
.error-game-legend-player { border-radius: 2px !important; background: #ffd166; transform: rotate(45deg); box-shadow: none; }
.error-game-legend-player::after { top: 3px; left: 4px; border-left-color: #000000; transform: rotate(-45deg); }
.error-game-legend-rival { border-radius: 0 !important; background: #ff604f; clip-path: polygon(50% 0, 61% 24%, 85% 10%, 80% 36%, 100% 50%, 76% 61%, 90% 85%, 64% 80%, 50% 100%, 39% 76%, 15% 90%, 20% 64%, 0 50%, 24% 39%, 10% 15%, 36% 20%); }
.error-game-primary:disabled { background: #ffffff; color: #000000; cursor: wait; }
@media (max-width: 900px) {
    .error-game-message { grid-template-columns: 1fr 1fr; align-items: start; }
