/* El modo de prueba conserva la paleta de la gestión. Se identifica por el
   título Estacionamiento prueba, el matraz seleccionado y el aviso textual. */

html.is-demo-hydrating [data-partial-content] {
    visibility: hidden;
    pointer-events: none;
}

html.is-demo-hydrating body::after {
    content: "Abriendo el modo de prueba…";
    position: fixed;
    z-index: 10000;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 24px;
    background: var(--surface);
    color: var(--ink);
    font-size: 18px;
    font-weight: 800;
    pointer-events: none;
    text-align: center;
}

html[data-theme="dark"].is-demo-hydrating body::after {
    background: #000000;
    color: #ffffff;
}

.demo-data-choice-modal {
    z-index: 10002;
}

.demo-data-choice-panel {
    width: min(620px, 100%);
}

.demo-data-choice-panel .record-modal-header h2 {
    color: var(--ink);
}

.demo-data-choice-panel .record-modal-close,
html[data-theme="dark"] .demo-data-choice-panel .record-modal-close {
    border: 0;
    background: var(--danger);
    color: #ffffff;
    text-decoration: none;
}

.demo-data-choice-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.demo-data-choice-option {
    min-height: 52px;
    text-align: center;
    text-decoration: none;
}

.demo-data-choice-panel .record-modal-actions {
    justify-content: flex-end;
}

html[data-theme="dark"] .demo-data-choice-panel {
    border-color: #383838;
    background: #111111;
    color: #ffffff;
}

html[data-theme="dark"] .demo-data-choice-panel .record-modal-header h2 {
    color: #ffffff;
}

html[data-theme="dark"] .demo-data-choice-panel .button-neutral {
    border-color: #565656;
    background: #1c1c1c;
    color: #ffffff;
}

html[data-theme="dark"] .demo-data-choice-panel .button-neutral:is(:hover, :focus-visible) {
    background: #2a2a2a;
    color: #ffffff;
}

.demo-mode-banner {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 58px;
    margin: 0 0 16px;
    padding: 10px 12px;
    border: 2px solid var(--line);
    border-radius: 10px;
    background: var(--surface);
    color: var(--ink);
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.12);
}

.demo-mode-banner[hidden] {
    display: none;
}

.demo-mode-banner-icon {
    display: inline-grid;
    flex: 0 0 40px;
    place-items: center;
    width: 40px;
    height: 40px;
    border: 2px solid var(--line);
    border-radius: 999px;
    background: var(--surface);
    color: var(--ink);
}

.demo-mode-banner-icon svg {
    width: 23px;
    height: 23px;
}

.demo-mode-banner-copy {
    display: grid;
    flex: 1 1 auto;
    gap: 2px;
    min-width: 0;
    color: var(--ink);
}

.demo-mode-banner-copy strong {
    color: var(--ink);
    font-size: 15px;
    font-weight: 800;
}

.demo-mode-banner-copy span {
    color: var(--ink);
    font-size: 13px;
    font-weight: 600;
}

.demo-mode-banner-copy .demo-mode-feedback {
    margin-top: 3px;
    color: var(--ink);
    font-weight: 800;
}

.demo-mode-banner-copy .demo-mode-feedback[hidden] {
    display: none;
}

.demo-mode-banner-actions {
    display: inline-flex;
    flex: 0 0 auto;
    gap: 8px;
}

.demo-mode-reset,
.demo-mode-exit {
    flex: 0 0 auto;
    min-height: 44px;
    padding: 0 14px;
    border: 2px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    cursor: pointer;
    font-size: 13px;
    font-weight: 750;
}

.demo-mode-exit {
    background: #000000;
    color: #ffffff;
}

.demo-mode-reset:hover,
.demo-mode-reset:focus-visible,
.demo-mode-exit:hover,
.demo-mode-exit:focus-visible {
    background: var(--brand-primary);
    color: #ffffff;
    outline: 3px solid var(--brand-primary);
    outline-offset: 2px;
}

.module-tabs button.module-tab-icon {
    border: 1px solid transparent;
    border-radius: 8px;
    background: transparent;
    color: var(--ink);
    cursor: pointer;
}

.module-tabs button.module-tab-icon:hover,
.module-tabs button.module-tab-icon:focus-visible {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
    outline: 3px solid var(--brand-primary);
    outline-offset: 1px;
}

.module-tabs button.demo-mode-toggle.is-demo-active,
body[data-demo-mode="true"] .module-tabs button.demo-mode-toggle {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
    box-shadow: none;
}

/* La prueba incrustada conserva sus controles y distribución propios. */
html.is-demo-hydrating body[data-demo-presentation="embedded"]::after {
    background: var(--surface);
    color: var(--ink);
}

body[data-demo-presentation="embedded"] .demo-mode-banner {
    display: none;
}

body[data-demo-presentation="embedded"] :is(.demo-mode-exit, .demo-mode-toggle) {
    display: none;
}

/* La semilla de pantalla completa ya es visible y segura, pero su shell queda
   inert hasta que el state local se limpia y Navigation instala sus guardias. */
html[data-demo-top-level="true"].is-demo-hydrating [data-partial-content] {
    visibility: visible;
}

html[data-demo-top-level="true"].is-demo-hydrating body::after {
    display: none;
}

html[data-demo-top-level="true"].is-demo-hydrating [data-demo-bootstrap-inert] {
    pointer-events: none;
}

html[data-demo-top-level="true"].is-demo-hydrating body[data-demo-presentation="embedded"] .demo-mode-banner-actions {
    display: none;
}

html[data-theme="dark"].is-demo-hydrating body[data-demo-presentation="embedded"]::after {
    background: #000000;
    color: #ffffff;
}

@media (min-width: 960px) and (max-width: 1280px) {
    body[data-demo-presentation="embedded"] .app-shell.is-demo-mode,
    body[data-demo-presentation="embedded"] .app-shell.is-demo-mode.is-sidebar-collapsed {
        --active-sidebar-width: 240px;
        grid-template-columns: 240px minmax(0, 1fr);
    }

    body[data-demo-presentation="embedded"] .app-shell.is-demo-mode .sidebar {
        position: sticky;
        top: 0;
        align-items: stretch;
        height: 100vh;
        padding: 18px 16px;
    }

    body[data-demo-presentation="embedded"] .app-shell.is-demo-mode .sidebar-toggle {
        display: none;
    }

    body[data-demo-presentation="embedded"] .app-shell.is-demo-mode .nav-list {
        grid-template-columns: 1fr;
    }

    body[data-demo-presentation="embedded"] .app-shell.is-demo-mode .sidebar-session {
        margin-top: auto;
    }
}

@media (max-width: 620px) {
    .demo-data-choice-options {
        grid-template-columns: 1fr;
    }

    .demo-data-choice-panel .record-modal-actions,
    .demo-data-choice-panel .record-modal-actions .button-neutral {
        width: 100%;
    }

    .demo-mode-banner {
        align-items: flex-start;
        flex-wrap: wrap;
    }

    .demo-mode-banner-copy {
        flex-basis: calc(100% - 52px);
    }

    .demo-mode-banner-actions {
        flex: 1 1 100%;
        width: 100%;
    }

    .demo-mode-banner-actions > button {
        flex: 1 1 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .demo-mode-banner,
    .demo-mode-reset,
    .demo-mode-exit,
    .demo-mode-toggle {
        transition: none;
    }
}
/* Apartado Notificaciones: el historial y qué aviso llega de cada apartado. */

.notifications-shell,
.notifications-management-form {
    display: grid;
    gap: 14px;
}

.notifications-shell {
    margin-top: 18px;
}

/* Las tarjetas desplegables sueltas traen su propio margen y se sumaba al `gap`
   de la grilla: los dos desplegables quedaban al doble de distancia que en las
   demás pestañas. */
.notifications-shell > .panel.collapsible-panel,
.notifications-management-form > .panel.collapsible-panel {
    margin-top: 0;
}

.notifications-body {
    display: grid;
    gap: 12px;
    margin-top: 4px;
}

/* La frase corta separa el nombre del panel de la decisión que se toma adentro,
   sin competir con el título. */
.notifications-settings-subtitle {
    display: block;
    margin-top: 5px;
    color: var(--muted);
    font-size: 13px;
    font-weight: 600;
    line-height: 1.35;
}

/* Los desplegables anidados generales son ámbar. En Notificaciones ese color
   se reserva para lo que de verdad está pendiente; los apartados usan la
   superficie neutra del panel y teal cuando están abiertos. */
.app-shell .notifications-settings-panel .notifications-group {
    overflow: visible;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
}

.app-shell .notifications-settings-panel .notifications-group > .collapsible-summary,
.app-shell .notifications-settings-panel .notifications-group:not([open]) > .collapsible-summary {
    align-items: center;
    min-height: 54px;
    margin: 0;
    padding: 10px 14px;
    border: 0;
    border-radius: 11px;
    background: var(--surface-soft);
    box-shadow: none;
}

.app-shell .notifications-settings-panel .notifications-group[open] > .collapsible-summary {
    margin-bottom: 0;
    border-bottom: 1px solid var(--line);
    border-radius: 11px 11px 0 0;
    background: color-mix(in srgb, var(--brand-primary) 9%, var(--surface));
    box-shadow: inset 3px 0 0 var(--brand-primary);
}

.app-shell .notifications-settings-panel .notifications-group > .collapsible-summary:hover {
    background: color-mix(in srgb, var(--brand-primary) 7%, var(--surface-soft));
}

.app-shell .notifications-settings-panel .notifications-group[open] > .collapsible-summary .collapsible-heading {
    color: var(--brand-primary);
}

.app-shell .notifications-settings-panel .notifications-group > .collapsible-summary .collapsible-indicator {
    flex-basis: 30px;
    width: 30px;
    height: 30px;
    border-color: var(--line);
    background: var(--surface);
    color: var(--brand-primary);
}

.notifications-group > .collapsible-summary .collapsible-heading {
    font-size: 15px;
}

.notifications-group-title {
    display: flex;
    flex: 1 1 auto;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.notifications-group-meta {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: flex-end;
    gap: 7px;
}

.notifications-group-status,
.notifications-group-pending {
    display: inline-flex;
    align-items: center;
    min-height: 24px;
    padding: 3px 9px;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: var(--surface);
    color: var(--muted);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.2;
    white-space: nowrap;
}

.notifications-group-pending {
    border-color: color-mix(in srgb, var(--accent-amber) 45%, var(--line));
    background: color-mix(in srgb, var(--accent-amber) 12%, var(--surface));
    color: #8a570f;
}

.notifications-list {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));
    gap: 12px;
    margin: 0;
    padding: 14px;
    /* Cada casilla es tan alta como lo que tiene adentro: el aviso sin campo de
       anticipación no se estira hasta el alto del que sí lo tiene. */
    align-items: start;
}

/* Cabecera y anticipación forman una tarjeta única. El contenedor dibuja el
   borde; las dos filas interiores sólo ordenan el contenido. */
.notifications-list > .notification-card {
    min-width: 0;
    overflow: visible;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--surface);
    box-shadow: 0 8px 22px rgba(16, 24, 33, 0.05);
    transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.notifications-list > .notification-card:has(.mini-switch input:not(:checked)) {
    border-color: color-mix(in srgb, var(--line-strong) 36%, var(--line));
    background: var(--surface-soft);
    box-shadow: none;
}

.notifications-list > .notification-card:hover {
    border-color: color-mix(in srgb, var(--brand-primary) 34%, var(--line));
    box-shadow: 0 10px 26px rgba(16, 24, 33, 0.08);
    transform: translateY(-1px);
}

.notifications-list > .notification-card:focus-within {
    border-color: color-mix(in srgb, var(--brand-primary) 58%, var(--line));
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--brand-primary) 14%, transparent);
}

.notifications-list > .notification-card > .visibility-toggle {
    min-height: 58px;
    padding: 12px 14px;
    border: 0;
    border-radius: 11px;
    background: transparent;
}

.notifications-list > .notification-card:has(.notification-lead) > .visibility-toggle {
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
}

.notification-lead {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    padding: 10px 14px 12px;
    border: 0;
    border-top: 1px solid var(--line);
    border-radius: 0 0 11px 11px;
    background: color-mix(in srgb, var(--brand-primary) 5%, var(--surface-soft));
}

.notification-lead-label,
.notification-lead-suffix {
    color: var(--muted);
    font-size: 12px;
    font-weight: 600;
}

/* Los dos campos son chicos a propósito: el molde de `.entry-form` los estira a
   todo el ancho y acá tienen que entrar en una línea con su rótulo. */
.notifications-list .notification-lead-amount {
    width: 68px;
    min-width: 68px;
    min-height: 38px;
    padding: 4px 8px;
    border-color: var(--line);
    background: var(--surface);
    font-size: 13px;
    font-weight: 700;
    text-align: right;
}

.notifications-list .notification-lead-unit {
    width: auto;
    min-width: 104px;
    min-height: 38px;
    padding: 4px 28px 4px 9px;
    border-color: var(--line);
    background-color: var(--surface);
    font-size: 13px;
    font-weight: 700;
}

.notifications-list :is(.notification-lead-amount, .notification-lead-unit):focus {
    border-color: var(--brand-primary);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--brand-primary) 14%, transparent);
    outline: none;
}

/* Un color por urgencia en la primera columna del historial: el vencido pide
   atención hoy y el programado puede esperar. */
.notification-row td:first-child {
    border-left: 3px solid transparent;
}

.notification-row-danger td:first-child {
    border-left-color: var(--danger);
}

.notification-row-strong td:first-child {
    border-left-color: var(--accent-amber);
}

.notification-row-blue td:first-child {
    border-left-color: var(--accent-blue);
}

.notification-title {
    font-weight: 700;
}

/* Los filtros son los mismos de la tabla de Registros; acá sólo se los despega
   del borde de arriba del desplegable. */
.notifications-filter-form {
    margin-bottom: 4px;
}

/* Una fila escondida por el filtro: `hidden` sola pierde contra el `display`
   que la tabla le da a sus filas. */
.notification-row[hidden] {
    display: none;
}

.notifications-empty-filter {
    margin: 0;
    padding: 18px 4px;
    color: var(--muted);
    font-size: 14px;
    font-weight: 600;
    text-align: center;
}

/* Ninguna notificación es un aviso pelado: cada fila termina en el botón que la
   resuelve, y el color dice de qué tipo es sin tener que leerlo. */
.notification-action-cell {
    white-space: nowrap;
}

.notification-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 92px;
    min-height: 30px;
    padding: 4px 12px;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: var(--surface);
    font-size: 13px;
    font-weight: 700;
    text-decoration: none;
}

/* Chequear lleva a otra pestaña del mismo panel: se queda con el color de link
   de la app. Los otros dos hacen algo —abren WhatsApp, arman un PDF— y por eso
   van pintados. */
.notification-action-chequear {
    color: var(--link-blue);
}

html[data-theme="dark"] .app-shell .notification-action-chequear {
    color: var(--link-blue-dark);
}

.notification-action:hover,
.notification-action:focus-visible {
    filter: brightness(1.08);
}

/* El verde es el de WhatsApp, que es adonde lleva el botón. */
.notification-action-avisar {
    border-color: transparent;
    background: #128c7e;
    color: #fff;
}

.notification-action-generar {
    border-color: transparent;
    background: var(--accent-blue);
    color: #fff;
}

/* `19-notificaciones.css` se concatena después de los temas generales. Estas
   reglas específicas impiden que el estilo ámbar de cualquier subdesplegable
   vuelva marrones los apartados en modo oscuro. */
html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group {
    border-color: var(--line);
    background: var(--surface);
}

html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group > .collapsible-summary,
html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group:not([open]) > .collapsible-summary {
    border-color: var(--line);
    background: var(--surface-soft);
    box-shadow: none;
}

html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group[open] > .collapsible-summary {
    border-color: var(--line);
    background: color-mix(in srgb, #AD3FE3 10%, var(--surface));
    box-shadow: inset 3px 0 0 #AD3FE3;
}

html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group > .collapsible-summary:hover {
    background: color-mix(in srgb, #AD3FE3 8%, var(--surface-soft));
}

html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group[open] > .collapsible-summary .collapsible-heading,
html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group > .collapsible-summary .collapsible-indicator {
    color: #DDA6F7;
}

html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group > .collapsible-summary .collapsible-indicator,
html[data-theme="dark"] .app-shell .notifications-settings-panel .notifications-group-status,
html[data-theme="dark"] .app-shell .notifications-list > .notification-card,
html[data-theme="dark"] .app-shell .notifications-list :is(.notification-lead-amount, .notification-lead-unit) {
    border-color: var(--line);
    background: var(--surface);
    color: var(--ink);
}

html[data-theme="dark"] .app-shell .notifications-list > .notification-card:has(.mini-switch input:not(:checked)) {
    border-color: color-mix(in srgb, var(--line-strong) 34%, var(--line));
    background: var(--surface-soft);
    box-shadow: none;
}

html[data-theme="dark"] .app-shell .notifications-group-pending {
    border-color: color-mix(in srgb, var(--accent-amber) 42%, var(--line));
    background: color-mix(in srgb, var(--accent-amber) 14%, var(--surface));
    color: var(--accent-amber);
}

html[data-theme="dark"] .app-shell .notification-lead {
    border-top-color: var(--line);
    background: color-mix(in srgb, #27c1cf 6%, var(--surface-soft));
}

@media (max-width: 760px) {
    .notifications-settings-subtitle {
        max-width: 34ch;
    }

    .app-shell .notifications-settings-panel .notifications-group > .collapsible-summary,
    .app-shell .notifications-settings-panel .notifications-group:not([open]) > .collapsible-summary {
        padding: 10px 12px;
    }

    .notifications-group-title {
        align-items: flex-start;
        gap: 8px;
    }

    .notifications-group-meta {
        flex-wrap: wrap;
    }

    .notifications-list {
        grid-template-columns: 1fr;
        gap: 10px;
