.app-date-picker-popover {
    position: fixed;
    z-index: 190;
    box-sizing: border-box;
    display: grid;
    width: min(340px, calc(100vw - 24px));
    max-height: calc(100vh - 24px);
    max-height: calc(100dvh - 24px);
    gap: 12px;
    padding: 14px;
    border: 1px solid var(--line-strong);
    border-radius: 12px;
    background: #ffffff;
    color: #000000;
    box-shadow: 0 18px 44px rgba(0, 0, 0, 0.28);
    overflow-y: auto;
    overscroll-behavior: contain;
}

.app-date-picker-popover[hidden] {
    display: none;
}

.app-date-picker-header {
    display: grid;
    grid-template-columns: 40px minmax(0, 1fr) 40px;
    align-items: center;
    gap: 8px;
}

.app-date-picker-title {
    color: #000000;
    font-size: 15px;
    font-weight: 800;
    line-height: 1.2;
    text-align: center;
}

.app-date-picker-navigation {
    display: grid;
    width: 40px;
    height: 40px;
    place-items: center;
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface-soft);
    color: #000000;
    font: inherit;
    font-size: 27px;
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
}

.app-date-picker-navigation:hover,
.app-date-picker-navigation:focus-visible {
    border-color: var(--brand-primary);
    background: color-mix(in srgb, var(--brand-primary) 12%, #ffffff);
    color: #000000;
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 18%, transparent);
}

.app-date-picker-navigation:disabled {
    border-color: var(--line);
    background: var(--surface-soft);
    color: #000000;
    cursor: default;
}

.app-date-picker-weekdays,
.app-date-picker-grid {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 4px;
}

.app-date-picker-weekdays span {
    padding: 2px 0;
    color: #000000;
    font-size: 11px;
    font-weight: 800;
    line-height: 1.2;
    text-align: center;
    text-transform: uppercase;
}

.app-date-picker-day {
    display: grid;
    min-width: 0;
    min-height: 38px;
    place-items: center;
    padding: 0;
    border: 1px solid transparent;
    border-radius: 8px;
    background: transparent;
    color: #000000;
    font: inherit;
    font-size: 13px;
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
}

.app-date-picker-day.is-adjacent {
    color: #2563eb;
    font-weight: 600;
}

.app-date-picker-day:hover,
.app-date-picker-day:focus-visible {
    border-color: var(--brand-primary);
    background: color-mix(in srgb, var(--brand-primary) 12%, #ffffff);
    color: #000000;
    outline: 2px solid color-mix(in srgb, var(--brand-primary) 22%, transparent);
}

.app-date-picker-day.is-today {
    border-color: #0891b2;
}

/* El día enfocado al abrir egreso conserva el mismo relleno que ingreso,
   aunque el campo siga vacío hasta que se confirme una fecha. */
.app-date-picker-day:focus,
.app-date-picker-day.is-selected,
.app-date-picker-day[aria-selected="true"] {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand-primary) 24%, transparent);
}

.app-date-picker-day:disabled {
    border-color: transparent;
    background: transparent;
    color: #000000;
    cursor: default;
}

.app-date-picker-day.is-adjacent:disabled {
    color: #2563eb;
}

