/* Ajustes de Comunicación: destinatario y aviso en una misma fila. */
html:root .app-shell .report-message-contact-form [data-contact-message-purpose-field][hidden],
html:root .app-shell .report-message-preview[hidden],
html:root .app-shell .contact-message-tab[hidden],
html:root .app-shell .contact-record-picker-column-head[hidden] { display: none !important; }
html:root .app-shell .report-message-contact-form .report-message-prepare-actions,
html:root .app-shell .contact-nonclient-form .report-message-prepare-actions {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-column: 1 / -1;
    align-items: start;
    justify-content: start;
    gap: 16px;
    margin: 0;
}
html:root .app-shell .report-message-prepare-actions > button {
    min-height: 42px;
    margin: 0;
    justify-self: start;
}
html:root .app-shell .report-message-prepare-actions > button[type="submit"] { width: 100%; }
html:root .app-shell .report-message-prepare-actions > .button-neutral {
    background: var(--surface-soft);
    color: var(--ink);
    border-color: var(--line);
}
html:root .app-shell .contact-record-picker-panel {
    width: min(1320px, 100%);
    max-height: min(90dvh, 820px);
}
html:root .app-shell .contact-record-picker-panel .record-pagination-toolbar {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    width: 100%;
}
html:root .app-shell .contact-record-picker-panel .expandable-filter-search {
    grid-column: 4;
    width: 100%;
    max-width: none;
    margin: 0;
}
html:root .app-shell .contact-record-picker-panel [data-parking-record-picker-option][hidden] { display: none; }
@media (max-width: 760px) {
    html:root .app-shell .report-message-contact-form .report-message-prepare-actions,
    html:root .app-shell .contact-nonclient-form .report-message-prepare-actions,
    html:root .app-shell .contact-record-picker-panel .record-pagination-toolbar { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    html:root .app-shell .contact-record-picker-panel .expandable-filter-search { grid-column: 2; }
}
@media (max-width: 440px) {
    html:root .app-shell .report-message-contact-form .report-message-prepare-actions,
    html:root .app-shell .contact-nonclient-form .report-message-prepare-actions,
    html:root .app-shell .contact-record-picker-panel .record-pagination-toolbar { grid-template-columns: minmax(0, 1fr); }
    html:root .app-shell .contact-record-picker-panel .expandable-filter-search { grid-column: 1; }
}

/* El paginador ocupa una celda completa, igual que en Registros. */
html:root .app-shell .contact-record-picker-panel .record-pagination-toolbar > .record-pagination-controls {
    width: 100%;
    max-width: 100%;
    flex: initial;
}
html:root .app-shell .report-message-prepare-actions > [hidden] { display: none !important; }
html:root .app-shell .report-message-prepare-actions > .contact-message-action {
    width: 100%;
    min-height: 42px;
    justify-content: center;
    border: 1px solid var(--brand-primary);
    border-radius: 8px;
    background: var(--brand-primary);
    color: #ffffff;
    font-weight: 600;
}
html:root .app-shell .contact-message-tags-panel {
    width: min(900px, 100%);
    max-height: 85dvh;
    overflow-y: auto;
}
html:root .app-shell .contact-message-tags-categories {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px;
    color: var(--ink);
}
html:root .app-shell .contact-message-tags-category { display: grid; align-content: start; gap: 12px; min-width: 0; }
html:root .app-shell .contact-message-tags-category h3 { margin: 0; font-size: 16px; color: var(--ink); }
html:root .app-shell .contact-message-tags-category > div { display: flex; flex-wrap: wrap; gap: 8px; }
html:root .app-shell .contact-message-tags-category button { min-height: 38px; width: auto; background: var(--surface-soft); color: var(--ink); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }
@media (max-width: 600px) {
    html:root .app-shell .contact-message-tags-categories { grid-template-columns: minmax(0, 1fr); }
}

html:root .app-shell .contact-record-picker-panel .record-pagination-toolbar { column-gap: var(--pagination-grid-gap); }
html:root .app-shell .contact-record-picker-filters > label[hidden] { display: none !important; }

html:root .app-shell [data-communication-contact] { cursor: pointer; }
html:root .app-shell [data-communication-contact-modal] [hidden] { display: none !important; }
/* Selección del modelo PDF en toda la tarjeta, como Registro. */
.report-pdf-model-card.is-selected,
.report-pdf-model-card:has(input:checked) {
    --ink: #ffffff;
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff !important;
    box-shadow: none;
}
.report-pdf-model-card.is-selected::before,
.report-pdf-model-card:has(input:checked)::before {
    content: none;
    display: none;
}
.report-pdf-model-card:focus-within {
    outline-color: var(--brand-primary);
}

.report-pdf-form .report-pdf-model-card {
    grid-template-rows: auto 1fr auto;
    text-transform: none;
}

.report-pdf-model-copy small {
    color: inherit;
}

.report-pdf-model-thumbnail {
    display: block;
    padding: 0;
    background: #fff;
    border-color: var(--line);
    box-shadow: none;
}

.report-pdf-model-sheets,
.report-pdf-model-sheet {
    display: block;
    width: 100%;
    height: 100%;
    margin: 0;
}

.report-pdf-model-sheet canvas {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
}

.report-pdf-model-thumbnail-loading {
    position: absolute;
    inset: 0;
    display: grid;
    place-content: center;
    max-width: none;
    padding: 20px;
    background: #fff;
    color: #000;
}

.report-pdf-model-controls {
    position: absolute;
    right: 8px;
    bottom: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 3px 5px;
    border-radius: 9px;
    background: #fff;
    color: #000;
    font-size: 12px;
    font-weight: 700;
}

.report-pdf-model-controls button {
    display: grid;
    place-items: center;
    width: 24px;
    min-width: 24px;
    height: 24px;
    min-height: 24px;
    padding: 0;
    border: 0;
    border-radius: 6px;
    background: var(--brand-primary);
    color: #fff;
    font-size: 20px;
    line-height: 1;
}

html:root .app-shell .report-pdf-model-controls button:disabled {
    --ink: #000;
    --control-disabled-background: #fff;
    --control-disabled-border: #fff;
    background: #fff !important;
    color: #000 !important;
    opacity: 1;
}

.report-pdf-model-controls [data-report-pdf-model-retry] {
    width: auto;
    padding: 0 6px;
    font-size: 12px;
}

.report-pdf-model-visualize {
    justify-self: stretch;
    text-align: center;
}

.report-pdf-model-card:is(.is-selected, :has(input:checked)) .report-pdf-model-visualize {
    border-color: #fff;
    background: transparent;
    color: #fff;
}

.report-pdf-model-card [hidden] {
    display: none !important;
}

/* Las páginas pertenecen al scroll de Comunicación, sin un segundo visor. */
.report-pdf-form > .report-pdf-preview {
    grid-column: 1 / -1;
    min-width: 0;
    height: auto;
    max-height: none;
    overflow: visible;
}

.report-pdf-preview .report-pdf-preview-heading {
    flex-wrap: wrap;
    border-bottom: 0;
}

.report-pdf-preview .report-pdf-preview-heading p,
.report-pdf-preview .report-pdf-preview-status {
    color: var(--ink);
}

.report-pdf-preview .report-pdf-preview-stage,
.report-pdf-preview.has-preview .report-pdf-preview-stage,
.report-pdf-preview .report-pdf-preview-pages {
    min-width: 0;
    height: auto;
    max-height: none;
    overflow: visible;
}

.report-pdf-preview .report-pdf-preview-stage {
    min-height: 200px;
}

.report-pdf-preview.has-preview .report-pdf-preview-stage {
    min-height: 0;
}

.report-pdf-preview .report-pdf-preview-pages {
    justify-items: stretch;
    gap: 24px;
}

.report-pdf-preview-page {
    position: relative;
    width: 100%;
    min-width: 0;
    background: #fff;
}

.report-pdf-preview-page canvas {
    display: block;
    width: 100%;
    max-width: 100%;
    height: auto;
}

.report-pdf-preview-accessible-text {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    color: #000;
}

.report-pdf-original-link {
    color: var(--ink);
    font-weight: 700;
    overflow-wrap: anywhere;
}

.report-pdf-original-link[hidden] {
    display: none;
}
/* Configuración comparte las etiquetas de Registro, también cuando el campo
   compuesto necesita un div en lugar de un label. */
[data-parking-tools-form] :is(
    .entry-form label,
    .field-label-line,
    .field-label-row,
    .variable-select-list-heading,
    .institutional-contact-label,
    .logo-upload-title
),
:is(.variable-dialog-modal, .variable-increment-modal, [data-company-selector-modal]) :is(
    .entry-form label,
    .field-label-line,
    .field-label-row,
    .variable-select-list-heading
) {
    font-family: inherit;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.2;
    text-transform: uppercase;
}

/* Todos usan la flecha del select común: la envoltura no agrega otra. */
[data-parking-tools-form] .space-location-list-grid .floor-control-row::after {
    content: none;
}
/* Categorías usa los mismos campos y desplegables de las fichas de Registro. */
html:root .app-shell .record-modal[data-vehicle-modal] :is(.record-modal-header, .record-modal-actions) {
    border: 0;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-category-dialog-section, .vehicle-period-rate) {
    display: block;
    min-width: 0;
    padding: 0;
    border-radius: 12px;
    background: var(--surface);
    overflow: visible;
    contain: none;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-category-dialog-section, .vehicle-period-rate) > .collapsible-summary {
    display: flex;
    align-items: center;
    min-height: 72px;
    margin: 0;
    padding: 16px 18px;
    border-radius: 12px;
    color: var(--ink);
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .collapsible-summary :is(.collapsible-heading, .collapsible-indicator) {
    color: var(--ink);
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .collapsible-summary .collapsible-heading {
    font-size: 18px;
    font-weight: 700;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-category-period-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 14px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-category-basics-grid, .vehicle-period-rate-body) {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    align-items: start;
    gap: 14px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-period-rate-body {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    padding: 18px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-period-rate-controls {
    display: contents;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-rate-rounding {
    display: grid;
    grid-column: auto;
    gap: 6px;
    order: 0;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-rate-rounding-controls {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(58px, 0.35fr);
    gap: 8px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-controls > .vehicle-period-rate-field {
    order: 0;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-controls > .vehicle-period-rate-mode-field {
    order: 0;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-period-rate-actions {
    display: flex;
    grid-column: 1 / -1;
    justify-content: flex-end;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-period-rate-field, .vehicle-rate-rounding) {
    gap: 6px;
    align-self: stretch;
    align-content: start;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-period-rate-field > span, .vehicle-rate-rounding > span) {
    min-height: 29px;
    color: var(--ink);
    font-family: inherit;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.2;
    text-transform: uppercase;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-category-basics-grid, .vehicle-period-rate-body) :is(input, select) {
    width: 100%;
    min-width: 0;
    height: 42px;
    min-height: 42px;
    font-size: 13px;
    font-weight: 600;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-period-rate.is-invalid {
    border-color: var(--danger);
}

/* El editor ocupa todo el viewport: la navegación queda tras su fondo. */
.app-shell:has(:is([data-vehicle-modal], [data-vehicle-rate-tiers-modal]):not([hidden])) > .sidebar {
    z-index: 70;
}

@media (max-width: 1100px) {
    html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-category-basics-grid, .vehicle-period-rate-body) {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

}

@media (max-width: 720px) {
    html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form :is(.vehicle-category-basics-grid, .vehicle-period-rate-body) {
        grid-template-columns: minmax(0, 1fr);
    }

    html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-period-rate-field > span,
    html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form .vehicle-rate-rounding > span {
        min-height: 0;
    }
}

/* La ventana crece con su contenido, hasta un tamaño cómodo de edición. */
html:root .app-shell .record-modal:is([data-vehicle-modal], [data-vehicle-rate-tiers-modal]) {
    inset: 0;
    padding: 12px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .variable-dialog-panel {
    width: min(1180px, calc(100vw - 48px));
    height: auto;
    max-width: 1180px;
    max-height: calc(100dvh - 64px);
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form {
    padding-top: 12px;
    padding-bottom: 12px;
    scrollbar-gutter: stable;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-summary:focus-visible {
    outline: 2px solid var(--brand-primary);
    outline-offset: 2px;
    box-shadow: none;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-summary {
    justify-content: flex-start;
    gap: 14px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-summary > .collapsible-indicator {
    margin-left: auto;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-title-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-title-row > label {
    display: block;
    margin: 0;
    font: inherit;
}

html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-period-rate-more {
    width: auto;
    min-height: 0;
    padding: 0;
    flex: 0 0 auto;
    font-size: 12px;
    line-height: 16px;
    text-transform: none;
}

/* Tramos: una cabecera común y filas uniformes con separación exterior. */
html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tiers-panel {
    width: min(1500px, calc(100vw - 24px));
    height: auto;
    max-height: calc(100dvh - 24px);
}

html:root .app-shell [data-vehicle-rate-tiers-modal] :is(.vehicle-rate-tiers-panel, .record-modal-header, .record-modal-actions, .vehicle-rate-tiers-form) {
    background: var(--surface);
    color: var(--ink);
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tiers-form {
    grid-template-columns: minmax(0, 1fr);
    align-content: start;
    gap: 18px;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tiers-columns {
    grid-template-columns: repeat(var(--vehicle-rate-tier-columns, 1), minmax(620px, 1fr));
    min-width: 0;
    padding: 0 0 16px;
    gap: 18px;
    align-items: start;
}

html:root .app-shell :is([data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-tier-column-head {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    align-items: end;
    gap: 6px 14px;
    min-width: 0;
    max-width: none;
}

html:root .app-shell :is([data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-tier-column-title {
    grid-column: 1 / -1;
}

html:root .app-shell :is([data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-tier-column-head > :is(label, .vehicle-rate-rounding) {
    display: grid;
    align-self: end;
    gap: 6px;
    margin: 0;
}

html:root .app-shell :is([data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-rounding > span {
    color: var(--ink);
    font-size: 12px;
    font-weight: 600;
    line-height: 1.2;
    text-transform: uppercase;
}

html:root .app-shell :is([data-vehicle-modal], [data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-rounding-controls {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(58px, 0.35fr);
    gap: 8px;
    min-width: 0;
}

html:root .app-shell :is([data-vehicle-modal], [data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-rounding-controls > select {
    border-radius: 8px;
}

html:root .app-shell :is([data-vehicle-modal], [data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-rounding-controls > input {
    border-radius: 8px;
    border-left-width: 1px;
    width: 100%;
}

html:root .app-shell :is([data-vehicle-modal], [data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-rounding-controls > :focus {
    position: relative;
    z-index: 1;
}

html:root .app-shell :is([data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-tier-column-head :is(input, select, .vehicle-rate-tiers-filter, .category-discount-add) {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    height: 42px;
    min-height: 42px;
    margin-top: 0;
    margin-bottom: 0;
    font-size: 13px;
    font-weight: 600;
}

html:root .app-shell :is([data-vehicle-rate-tiers-modal], .category-discounts) .vehicle-rate-tier-column-head > :is(.vehicle-rate-tier-toolbar-action, .category-discount-add) {
    display: flex;
    align-items: center;
    justify-content: center;
    align-self: end;
    width: 100%;
    min-width: 0;
    min-height: 42px;
    margin: 0;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tiers-rows {
    min-width: calc(146px + var(--vehicle-rate-tier-columns, 1) * 474px);
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tier-row {
    grid-template-columns: minmax(120px, 0.6fr) repeat(var(--vehicle-rate-tier-columns, 1), minmax(460px, 3fr));
    gap: 14px;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] :is(.vehicle-rate-tier-cell, .vehicle-rate-tier-cell-head) {
    display: grid;
    grid-template-columns: minmax(100px, 0.8fr) repeat(2, minmax(150px, 1fr));
    gap: 12px;
    align-items: center;
    min-width: 0;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] :is(.vehicle-rate-tier-field, .vehicle-rate-tier-grid-head) {
    color: var(--ink);
    font-size: 12px;
    font-weight: 600;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tier-field {
    display: grid;
    min-width: 0;
    margin: 0;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tier-row .vehicle-rate-tier-toggle {
    justify-content: flex-start;
    align-self: center;
    padding: 8px;
    min-height: 42px;
    background: transparent;
    color: var(--ink);
    border-color: transparent;
    border-radius: 6px;
    text-transform: none;
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tier-row .vehicle-rate-tier-toggle:has(input:checked) {
    border-color: var(--brand-primary);
    background: var(--surface-soft);
}

html:root .app-shell [data-vehicle-rate-tiers-modal] .vehicle-rate-tier-row input:not([type="checkbox"]) {
    width: 100%;
    height: 42px;
    min-width: 0;
}

/* Readonly usa el gris de Registro, con texto pleno en los dos temas. */
html:root .app-shell .record-modal:is([data-vehicle-modal], [data-vehicle-rate-tiers-modal]) .entry-form input:is([readonly], :disabled):not([type="checkbox"]):not([type="radio"]):not([type="hidden"]) {
    background: #d9dee1;
    border-color: #9aa5ad;
    color: #000000;
    -webkit-text-fill-color: #000000;
    box-shadow: none;
    cursor: default;
    opacity: 1;
}

html[data-theme="dark"] .app-shell .record-modal:is([data-vehicle-modal], [data-vehicle-rate-tiers-modal]) .entry-form input:is([readonly], :disabled):not([type="checkbox"]):not([type="radio"]):not([type="hidden"]) {
    background: #465158;
    border-color: #687780;
    color: #ffffff;
    -webkit-text-fill-color: #ffffff;
}

@media (max-width: 720px) {
    html:root .app-shell .record-modal[data-vehicle-modal] .vehicle-category-dialog-form {
