    width: 100%;
    min-width: 0;
}

html:root .app-shell :is(
    .record-filter-form,
    .gastos-provider-picker-filters,
    .payment-record-picker-filters
):has(+ .record-pagination-toolbar) > :is(label, div),
html:root .app-shell :is(
    .record-filter-form,
    .gastos-provider-picker-filters,
    .payment-record-picker-filters
):has(+ .record-pagination-toolbar) > label > :is(input, select) {
    width: 100%;
    min-width: 0;
    max-width: none;
}

html:root .app-shell :is(
