    display: none;
}

html:root .app-shell .record-pagination-controls :is(.record-page-size-control, .record-page-picker, .record-pagination) {
    display: inline-flex;
    width: auto;
    min-width: 0;
    align-items: center;
    flex-direction: row;
    flex-wrap: nowrap;
    gap: 5px;
    margin: 0;
    font-size: 12px;
    white-space: nowrap;
    text-transform: none;
}

html:root .app-shell .record-pagination-controls > .record-pagination {
    flex: 0 0 auto;
    margin-left: auto;
}

html:root .app-shell .record-pagination-controls :is(.record-page-size-control, .record-pagination)[hidden] {
    display: none;
}

/* La especificidad conserva esta posición frente a la flecha general del tema
   oscuro, incluso deshabilitada. Los 35 px reservan padding, bordes y 1 px de
   margen para el redondeo subpíxel del ancho de los números. */
html:root .app-shell .record-pagination-toolbar .record-pagination-controls select:is(.record-page-size-select, .record-page-select):not([multiple]):not([size]) {
    flex: 0 0 auto;
    width: max(46px, calc(var(--pagination-select-chars, 3) * 1ch + 35px));
    min-width: max(46px, calc(var(--pagination-select-chars, 3) * 1ch + 35px));
    max-width: none;
    height: 42px;
    padding-inline: 8px 24px;
    font-size: 12px;
    background-position: right 7px center;
    background-size: 10px;
}

html:root .app-shell .record-pagination-controls .record-page-button {
    flex: 0 0 28px;
    width: 28px;
    min-width: 28px;
    height: 28px;
    min-height: 28px;
    padding: 4px;
}

