    gap: 18px;
    padding: 28px 22px 22px;
    border-radius: 8px;
}

[data-availability-modal] .availability-dialog-form {
    min-width: 0;
    gap: 18px;
}

[data-availability-modal] .availability-season-panel {
    gap: 8px;
    padding: 0;
    border: 0;
    background: transparent;
}

[data-availability-modal] .availability-season-heading {
    min-height: 18px;
    gap: 6px;
}

[data-availability-modal] .availability-season-heading .field-label-line {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
}

[data-availability-modal] .availability-season-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 13px;
}

[data-availability-modal] :is(.availability-season-option, .availability-day, .availability-all-day) {
    height: 42px;
    min-height: 42px;
    box-sizing: border-box;
    margin: 0;
    padding: 0 10px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.2;
}

[data-availability-modal] .availability-schedule-scroll {
    min-width: 0;
    padding: 3px 2px 5px;
}

[data-availability-modal] .availability-schedule-grid {
    grid-template-columns: 100px repeat(7, minmax(108px, 1fr));
    min-width: 912px;
    gap: 13px;
}

[data-availability-modal] .availability-row-title {
    display: flex;
    align-items: center;
    gap: 4px;
    min-height: 42px;
    color: var(--ink);
    font-size: 12px;
}

[data-availability-modal] .availability-schedule-grid input[type="time"] {
    height: 42px;
    min-height: 42px;
    box-sizing: border-box;
    padding: 0 8px;
    font-size: 13px;
    font-variant-numeric: tabular-nums;
}

html:root .app-shell [data-availability-modal] .availability-schedule-grid input[type="time"][aria-invalid="true"] {
    border-color: var(--danger) !important;
    outline: 2px solid color-mix(in srgb, var(--danger) 22%, transparent) !important;
}

.availability-time-cell {
    display: block;
    min-width: 0;
    min-height: 42px;
}

/* Se conserva la columna al ocultar campos de días cerrados o de 24 horas. */
[data-availability-modal] :is(.availability-time-cell.is-inactive, .availability-all-day.is-inactive) {
    visibility: hidden;
}

[data-availability-modal] .availability-visit-separator {
    margin-top: 5px;
    padding-top: 0;
    border: 0;
    font-size: 13px;
}

[data-availability-modal] .availability-saved-schedules {
    padding-top: 8px;
    border: 0;
}

[data-availability-modal] .availability-saved-schedules > summary {
    min-height: 34px;
    cursor: pointer;
    list-style: none;
}

[data-availability-modal] .availability-saved-schedules > summary > strong::before {
    content: "▸";
    display: inline-block;
    width: 17px;
}

[data-availability-modal] .availability-saved-schedules[open] > summary > strong::before {
    content: "▾";
}

[data-availability-modal] .availability-saved-schedules[open] .availability-saved-schedules-list {
    margin-top: 8px;
}

[data-availability-modal] .availability-saved-schedule {
    padding: 8px 0;
    border: 0;
    background: transparent;
    box-shadow: none;
}

[data-availability-modal] .availability-saved-schedule-copy > span {
    overflow: visible;
    white-space: normal;
    line-height: 1.5;
}

