    --style-font-field-background: #0c0c0c;
}

html:root .app-shell .entry-form .style-font-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    width: 100%;
    min-width: 0;
    min-height: 44px;
    padding: 10px 12px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: var(--style-font-field-background);
    color: var(--ink);
    font-size: 14px;
    line-height: 1.4;
    text-align: left;
    text-transform: none;
}

html:root .app-shell .entry-form .style-font-trigger:is(:hover, :focus-visible, [aria-expanded="true"]) {
    border-color: var(--brand-primary);
    background: var(--style-font-field-background);
    color: var(--ink);
    filter: none;
}

