    outline: 2px solid var(--brand-primary);
    outline-offset: 2px;
}

.style-font-trigger::after {
    content: "";
    flex: 0 0 auto;
    width: 8px;
    height: 8px;
    margin-right: 3px;
    border-right: 2px solid currentColor;
    border-bottom: 2px solid currentColor;
    transform: translateY(-2px) rotate(45deg);
}

.style-font-trigger[aria-expanded="true"]::after {
    transform: translateY(2px) rotate(225deg);
}

.style-font-options {
    position: fixed;
    display: grid;
    z-index: 30;
    max-height: min(380px, 50dvh);
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 4px;
    border: 1px solid var(--line-strong);
    border-radius: 8px;
    background: var(--surface);
    color: var(--ink);
    box-shadow: 0 8px 24px rgb(0 0 0 / 20%);
}

.style-font-options[hidden] {
    display: none;
}

.style-font-option {
    display: block;
    padding: 9px 10px;
    border-radius: 5px;
    color: var(--ink);
    font-size: 16px;
    line-height: 1.4;
    cursor: pointer;
    text-transform: none;
}

.style-font-option:hover,
.style-font-option.is-active {
    background: color-mix(in srgb, var(--brand-primary) 15%, var(--surface));
}

.style-font-option[aria-selected="true"] {
    background: var(--selection-option-background);
    box-shadow: none;
}

