            "mark copy"
            "actions actions";
        gap: 14px;
        margin: 0 0 18px;
        padding: 18px;
        overflow: hidden;
        border: 1px solid rgba(109, 40, 217, 0.24);
        border-radius: 14px;
        background: linear-gradient(145deg, #ffffff 0%, #f7effd 100%);
