    }

    .mobile-app-notice::before {
        position: absolute;
        top: 0;
        bottom: 0;
        left: 0;
        width: 4px;
        background: #6d28d9;
        content: "";
    }

    .mobile-app-notice-mark {
        grid-area: mark;
        width: 48px;
        height: 48px;
        object-fit: contain;
    }

    .mobile-app-notice-copy {
        grid-area: copy;
        min-width: 0;
    }

    .mobile-app-notice-eyebrow {
        display: inline-flex;
        align-items: center;
        min-height: 24px;
        padding: 0 9px;
        border-radius: 999px;
        background: #e9d5ff;
        color: #5b21b6;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }

    .mobile-app-notice h2 {
        margin: 8px 0 0;
