        line-height: 1.12;
    }

    .mobile-app-notice p {
        margin: 10px 0 0;
        color: var(--muted);
        font-size: 14px;
        line-height: 1.5;
    }

    .mobile-app-notice-actions {
        grid-area: actions;
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        gap: 8px;
    }

    .mobile-app-notice-cta {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 100%;
        min-height: 44px;
        padding: 8px 14px;
        border: 1px solid transparent;
        border-radius: 8px;
        font-size: 14px;
        font-weight: 600;
        line-height: 1.25;
        text-align: center;
        text-decoration: none;
    }

    .mobile-app-notice-cta.is-disabled {
        border-color: var(--line);
        background: rgba(255, 255, 255, 0.7);
        color: var(--muted);
        cursor: default;
    }

    .mobile-app-notice-cta.is-primary {
        background: #6d28d9;
        color: #ffffff;
    }

    .mobile-app-notice-cta.is-secondary {
        border-color: rgba(109, 40, 217, 0.28);
        background: transparent;
        color: #5b21b6;
    }

    .mobile-app-notice-cta:is(a, button):is(:hover, :focus-visible) {
        border-color: #6d28d9;
        outline: 3px solid rgba(109, 40, 217, 0.18);
        outline-offset: 2px;
    }

    .mobile-app-notice-logout {
        margin: 0;
    }

    .mobile-app-notice-logout button {
        cursor: pointer;
    }

    html[data-theme="dark"] .mobile-app-notice {
        border-color: rgba(221, 166, 247, 0.24);
        background: linear-gradient(145deg, #21102a 0%, #170b1e 100%);
        box-shadow: 0 14px 34px rgba(0, 0, 0, 0.28);
    }

    html[data-theme="dark"] .mobile-app-notice-eyebrow {
        background: rgba(173, 63, 227, 0.2);
        color: #e6b8fb;
    }

    html[data-theme="dark"] .mobile-app-notice-cta.is-disabled {
        border-color: rgba(221, 166, 247, 0.2);
        background: rgba(255, 255, 255, 0.04);
        color: #ffffff;
    }

    html[data-theme="dark"] .mobile-app-notice-cta.is-secondary {
        border-color: rgba(221, 166, 247, 0.28);
        color: #e6b8fb;
    }
