}
.public-services-carousel > .public-reference-control:disabled { cursor: default; background: var(--public-soft, #f3edf8); color: inherit; opacity: 1; }
.public-services-money { display: grid; gap: 16px; margin-top: 28px; }
.public-services-money h3, .public-services-currency-note > strong { margin: 0; font-size: clamp(24px, 2.5vw, 34px); line-height: 1.2; }
.public-service-currencies { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 24px; }
.public-service-currencies li { display: flex; flex-direction: column; align-items: center; gap: 8px; width: 176px; text-align: center; }
.public-service-currency-circle { position: relative; display: block; width: 160px; height: 160px; border-radius: 50%; background: var(--public-soft, var(--surface-soft, #ffffff)); }
/* La moneda conserva una escala menor que el servicio, incluso cuando el
