[data-public-currency-style="billete"] .public-service-currency-banknote { display: block; }
[data-public-currency-style="billete"] .public-service-currency-circle > .public-service-currency-country-badge { display: block; position: absolute; right: -2px; bottom: -2px; width: 36px; height: 36px; border: 3px solid var(--public-surface, var(--surface, #ffffff)); }
.public-service-currency-symbol { font-weight: 700; font-size: 24px; }
