.public-services-options .public-service-option { position: relative; display: grid; gap: 12px; min-width: 0; align-content: start; justify-items: center; white-space: normal; padding: 14px; border: 2px solid var(--line); border-radius: 18px; cursor: pointer; background: var(--surface); color: var(--ink); }
.public-service-option > input { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
