    line-height: 1.2;
}
/* Los bloques compartidos con Tierra conservan sus medidas y controles.
   Urano aporta el azul, el celeste y el petróleo de su propio modelo. */
.public-template-mapa {
    --uranus-sky: #9BCDE5;
    --public-control-accent: var(--uranus-blue);
    --public-control-hover: var(--uranus-petrol);
    --public-control-dark-border: var(--uranus-sky);
    --public-control-dark-surface: var(--uranus-petrol);
    --public-control-focus: rgba(58, 127, 163, 0.25);
    --public-control-shadow: rgba(23, 52, 61, 0.24);
}

.public-template-mapa .visual-availability {
    display: grid;
    gap: 24px;
    width: min(100% - 64px, 1680px);
    margin: 0 auto;
    padding: clamp(46px, 4vw, 66px) 0 58px;
    color: var(--public-ink);
}

.public-template-mapa .map-consult.visual-calculation {
    display: grid;
    gap: 24px;
    width: 100%;
    margin: 0 auto;
    padding: clamp(56px, 4vw, 75px) max(32px, calc((100% - 1680px) / 2)) 58px;
    background: linear-gradient(var(--uranus-blue-soft), var(--uranus-blue-soft)), var(--public-surface);
}

.public-template-mapa :is(.visual-availability, .visual-calculation) h2 {
    max-width: 920px;
    font-size: clamp(38px, 5vw, 68px);
    line-height: 1;
}

.public-template-mapa :is(.visual-feature-grid article, .visual-feature-grid a, .public-vehicle-category-grid article, .public-category-note, .visual-calculator) {
    border-color: var(--uranus-blue);
    background: var(--public-surface);
    color: var(--public-ink);
}

.public-template-mapa :is(.visual-feature-grid article, .visual-feature-grid a) {
    box-shadow: 0 18px 44px rgba(58, 127, 163, 0.2);
}

.public-template-mapa.public-design[data-public-theme] :is(.visual-calculator, .public-calculation-mode, .public-tierra-cyclic-field) {
    box-shadow: none;
}

.public-template-mapa :is(.public-category-price, .public-category-price b) {
    color: var(--public-ink);
}

.public-template-mapa .public-price-form[data-public-registration-stay-controls] [data-public-stay-shortcut] {
    border: 0 !important;
    background: transparent !important;
    color: var(--public-ink) !important;
}

.public-template-mapa .visual-feature-grid :is(.public-availability-card-spaces, .public-availability-card-contact) {
    background: var(--uranus-blue);
}

.public-template-mapa .visual-feature-grid .public-availability-card-address,
.public-template-mapa [data-public-category-prices] .public-vehicle-category-grid article:nth-child(4n + 2) {
    background: linear-gradient(var(--uranus-blue-soft), var(--uranus-blue-soft)), var(--public-surface);
}

.public-template-mapa [data-public-category-prices] .public-vehicle-category-grid article:nth-child(4n + 3) {
    background: linear-gradient(var(--uranus-blue-medium), var(--uranus-blue-medium)), var(--public-surface);
}

.public-template-mapa [data-public-category-prices] .public-vehicle-category-grid article:nth-child(4n) {
    background: linear-gradient(rgba(23, 52, 61, 0.2), rgba(23, 52, 61, 0.2)), var(--public-surface);
}

.public-template-mapa .visual-feature-grid :is(.public-availability-card-spaces, .public-availability-card-contact) :is(h3, p, span, strong) {
    color: #ffffff !important;
}

.public-template-mapa .map-contact.visual-contact.public-contact-block.public-parking-contact {
    padding-block: clamp(31px, 4vw, 56px);
    padding-inline: max(18px, calc((100% - 1680px) / 2));
}

.public-template-mapa .visual-contact.public-parking-contact .public-contact-submit {
    justify-self: end;
}

.public-template-mapa.public-design :is(.public-contact-submit, .public-banner-primary, .public-banner-secondary, .public-price-grid > button) {
    border: 1px solid var(--uranus-blue);
    background: var(--uranus-blue);
    color: #ffffff !important;
}

.public-template-mapa.public-design :is(.public-contact-submit, .public-banner-primary, .public-banner-secondary, .public-price-grid > button):is(:hover, :focus-visible) {
    border-color: var(--uranus-petrol);
    background: var(--uranus-petrol);
    color: #ffffff !important;
}

.public-template-mapa.public-design :is(.public-footer-socials, .map-socials) a {
    border-color: var(--uranus-sky);
    background: var(--uranus-sky);
    color: #000000 !important;
}

.public-template-mapa.public-design :is(.public-footer-socials, .map-socials) a:is(:hover, :focus-visible) {
    border-color: var(--uranus-blue);
    background: var(--uranus-blue);
    color: #ffffff !important;
}

@media (max-width: 760px) {
    .public-template-mapa :is(.visual-availability, .map-consult.visual-calculation) {
