.app-shell .entry-form input[data-client-dni]:is([aria-invalid="true"], [data-identity-document-review="true"]):not(:disabled),
html[data-theme="dark"] .app-shell .entry-form input[data-client-dni]:is([aria-invalid="true"], [data-identity-document-review="true"]):not(:disabled):not([type="checkbox"]):not([type="radio"]):not([type="hidden"]) {
    border-color: var(--danger);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--danger) 18%, transparent);
}

.app-shell .entry-form input[data-client-dni]:is([aria-invalid="true"], [data-identity-document-review="true"]):not(:disabled):is(:focus, :focus-visible),
html[data-theme="dark"] .app-shell .entry-form input[data-client-dni]:is([aria-invalid="true"], [data-identity-document-review="true"]):not(:disabled):is(:focus, :focus-visible) {
    border-color: var(--danger);
    outline: 3px solid var(--danger);
}

.app-shell .parking-document-label-group {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
}

.app-shell .parking-identity-document-status {
