    flex: 0 0 22px;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 18px;
    color: var(--ink);
}

.app-shell .parking-identity-document-status svg {
    width: 22px;
    height: 18px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.app-shell .parking-identity-document-status[data-state="valid"] {
    color: var(--positive);
}

.app-shell .parking-identity-document-status:is([data-state="invalid"], [data-state="review"]) {
    color: var(--danger);
}
/*
 * Diálogo de duración de la estadía o del contrato ("Ver más").
 *
 * Va después de 20-paleta-oscura-neutra.css y antes de 20-texto-legible.css,
 * que por contrato cierra la cascada. Sus fichas son controles nuevos: ninguna
 * regla previa las alcanza y las variantes oscuras se declaran acá mismo.
 */

.parking-registration-exit-date-label-row > .map-text-link,
.parking-registration-contract-end-tools {
    margin-left: auto;
}

.parking-registration-contract-end-tools {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

/* El enlace arranca oculto para que no titile antes de que el JS resuelva su
   fecha de origen. Esta regla de autor es necesaria porque map-text-link usa
   display: inline-flex y, sin ella, le gana al [hidden] nativo del navegador. */
.entry-form :is(
    .parking-registration-exit-preset-open,
    .parking-registration-contract-end-preset-open
)[hidden] {
    display: none;
}

/* Cuando aparece, el tacho de la fecha ocupa la misma esquina que "Ver más".
   Sólo entonces la fila reserva su ancho y también los 5 px extra de su área
   táctil; con el campo vacío, el enlace llega hasta el borde derecho. */
.app-shell .entry-form label.has-select-clear:has(
    > .select-clear-button:not([hidden])
)
    > .parking-registration-exit-date-label-row {
    box-sizing: border-box;
    padding-inline-end: 32px;
}

/* Mientras la fecha de destino está apagada —la tarjeta del espacio todavía no
   se activó, la reserva trae fechas fijas o Crear contrato no está elegido— no
   hay nada que calcular. */
.entry-form label:has(> input[type="date"]:disabled)
    :is(
        .parking-registration-exit-preset-open,
        .parking-registration-contract-end-preset-open
    ) {
    display: none;
}

/* Se abre por encima del modal de edición del registro (z-index 80) y del de
   importes (120), que pueden estar abiertos cuando se toca "Ver más". */
.record-modal.parking-registration-exit-preset-modal {
    z-index: 150;
}

.record-modal-panel.parking-registration-exit-preset-panel {
    align-self: center;
    gap: 16px;
    width: min(620px, 100%);
    max-height: min(88dvh, 560px);
    border-color: var(--line);
    background: var(--surface);
    color: #000000;
}

/* Aplicar es la acción primaria de este diálogo. Conserva el violeta también
   mientras está deshabilitada, sin atenuar el texto ni usar opacidad. */
.app-shell .record-modal.parking-registration-exit-preset-modal
    .record-modal-panel.parking-registration-exit-preset-panel
    button[data-registration-exit-preset-apply],
.app-shell .record-modal.parking-registration-exit-preset-modal
    .record-modal-panel.parking-registration-exit-preset-panel
    button[data-registration-exit-preset-apply]:disabled {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
    opacity: 1;
}

.app-shell .record-modal.parking-registration-exit-preset-modal
    .record-modal-panel.parking-registration-exit-preset-panel
    button[data-registration-exit-preset-apply]:not(:disabled):hover,
.app-shell .record-modal.parking-registration-exit-preset-modal
    .record-modal-panel.parking-registration-exit-preset-panel
    button[data-registration-exit-preset-apply]:not(:disabled):focus-visible {
    border-color: #5B21B6;
    background: #5B21B6;
    color: #ffffff;
}

/* Cada período ocupa una fila. El botón activa esa parte de la duración y su
   campo aparece inmediatamente a la derecha; varias filas pueden convivir. */
.parking-registration-exit-preset-units {
    display: grid;
    gap: 10px;
    min-width: 0;
}

.parking-registration-exit-preset-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    min-width: 0;
    min-height: 42px;
}

.parking-registration-exit-preset-row[hidden] {
    display: none;
}

.parking-registration-exit-preset-unit {
    display: inline-flex;
    align-self: stretch;
    width: 100%;
    min-width: 0;
    min-height: 42px;
    align-items: center;
    justify-content: center;
    padding: 0 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: #000000;
    font: inherit;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.2;
    text-align: center;
    text-transform: uppercase;
    cursor: pointer;
    user-select: none;
}

.parking-registration-exit-preset-unit:hover {
    border-color: var(--brand-primary);
}

.parking-registration-exit-preset-unit:focus-visible {
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 25%, transparent);
    outline-offset: 2px;
}

.parking-registration-exit-preset-unit.is-selected,
.parking-registration-exit-preset-unit[aria-pressed="true"] {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
}

.parking-registration-exit-preset-amount-field {
    display: flex;
    align-items: stretch;
    min-width: 0;
    color: #000000;
}

.parking-registration-exit-preset-amount-field[hidden] {
    display: none;
}

.parking-registration-exit-preset-amount-field input {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    min-height: 42px;
    padding: 10px 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: var(--surface);
    color: #000000;
    font: inherit;
    font-size: 14px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    line-height: 1.2;
    text-transform: none;
}

.parking-registration-exit-preset-amount-field input:focus {
    border-color: var(--brand-primary);
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 25%, transparent);
    outline-offset: 2px;
}

.parking-registration-exit-preset-amount-field input[aria-invalid="true"] {
    border-color: var(--danger);
}

html[data-theme="dark"] .app-shell .record-modal-panel.parking-registration-exit-preset-panel {
    border-color: #383838;
    background: #111111;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .parking-registration-exit-preset-unit,
html[data-theme="dark"] .app-shell .parking-registration-exit-preset-amount-field input {
    border-color: #565656;
    background: #0c0c0c;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .parking-registration-exit-preset-unit:hover,
html[data-theme="dark"] .app-shell .parking-registration-exit-preset-unit.is-selected,
html[data-theme="dark"] .app-shell .parking-registration-exit-preset-unit[aria-pressed="true"] {
    border-color: #6D28D9;
}

html[data-theme="dark"] .app-shell .parking-registration-exit-preset-unit.is-selected,
html[data-theme="dark"] .app-shell .parking-registration-exit-preset-unit[aria-pressed="true"] {
    background: #6D28D9;
    color: #ffffff;
}
/* Con entregas habilitadas, Registro rápido reserva la segunda fila para
   espacio, entrega y usuarios; los demás modos conservan su ficha de vehículo. */
.entry-form[data-parking-quick-delivery-layout="1"]
    .parking-registration-simple-vehicle-grid
    > [data-registration-simple-space-field] {
    grid-column-start: 1;
}

@media (min-width: 721px) and (max-width: 1100px) {
    .parking-contract-alternative-actions:has(> :is(
        [data-parking-delivery-field],
        [data-parking-key-delivery-field],
        [data-parking-card-delivery-field]
    ):not([hidden]):not(.parking-registration-delivery-source))
        > label:first-child {
        grid-column: 1;
    }

    .parking-contract-alternative-actions
        > :is(
            [data-parking-delivery-field],
            [data-parking-key-delivery-field],
            [data-parking-card-delivery-field]
        ):not([hidden]):not(.parking-registration-delivery-source) {
