        grid-row: 1;
    }
}
.record-modal.parking-registration-delivery-modal {
    z-index: 2100;
    padding: 16px;
    align-items: center;
}

.record-modal-panel.parking-registration-delivery-panel {
    width: min(440px, 100%);
    min-height: 0;
    max-height: calc(100dvh - 32px);
    gap: 20px;
    align-content: start;
    background: var(--surface);
    color: var(--text);
}

.parking-registration-delivery-fields {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr));
    gap: 16px;
}

.parking-registration-delivery-fields label {
    display: grid;
    gap: 8px;
    min-width: 0;
}

.parking-registration-delivery-panel .record-modal-actions {
