.parking-registration-delivery-panel .record-modal-actions button {
    min-width: 0;
}

.parking-registration-delivery-panel .button-neutral {
    background: var(--surface-soft);
    color: var(--text);
}

/* Los select originales mantienen nombres, valores y validación del registro. */
:is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-source {
