    font: inherit;
    text-align: left;
    text-transform: none;
    cursor: pointer;
    box-shadow: none;
    filter: none;
}

html :is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-field .parking-registration-delivery-trigger {
    position: relative;
    display: flex;
    align-items: center;
    height: 42px;
    padding: 0 36px 0 12px;
}

.parking-registration-delivery-trigger > span:first-child {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

html :is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-field .parking-registration-delivery-trigger.is-placeholder {
    color: var(--placeholder) !important;
}

html :is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-field .parking-registration-delivery-trigger.is-invalid {
    border-color: var(--danger, #d93036);
}

.parking-registration-delivery-chevron {
    position: absolute;
    top: 14px;
    right: 14px;
    width: 9px;
    height: 9px;
    border-right: 2px solid var(--brand-primary);
