    gap: 7px;
    padding: 9px;
    max-height: min(280px, 48vh);
    overflow: auto;
    border: 1px solid var(--line);
    border-radius: 9px;
    background: var(--surface);
    box-shadow: 0 18px 38px rgba(16, 24, 33, 0.2);
}

html :is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-field .parking-registration-delivery-option {
