html :is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-field button:is(:hover, :focus-visible) {
    border-color: var(--brand-primary);
}

html :is(.entry-form, .parking-registration-delivery-panel) .parking-registration-delivery-field button:focus-visible {
