@media (max-width: 1100px) {
    .availability-space-detail-fields.parking-record-detail-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 720px) {
    .availability-space-detail-fields.parking-record-detail-grid {
        grid-template-columns: minmax(0, 1fr);
    }
}
/* Espacios, selector y alternativas comparten la paleta de ocupación.
   El aviso se monta en body y también debe recibirla fuera de .app-shell. */
:root {
    --parking-partial-background: #eadcfb;
    --parking-partial-accent: #6d28a8;
    --parking-fragmented-background: #dceffc;
    --parking-fragmented-accent: #166fa8;
}

html[data-theme="dark"] {
    --parking-partial-background: #292440;
    --parking-partial-accent: #b2a5eb;
    --parking-fragmented-background: #19344a;
    --parking-fragmented-accent: #67b9f1;
}

html :is(.app-shell, .app-notice-modal) :is(
    .availability-space-item.is-free,
    .availability-space-legend-swatch.is-free
) {
    --parking-space-background: var(--active-row-background);
    --parking-space-accent: var(--active-row-accent);
}

html :is(.app-shell, .app-notice-modal) :is(
    .availability-space-item.is-occupied,
    .availability-space-legend-swatch.is-occupied
) {
    --parking-space-background: var(--ended-row-background);
    --parking-space-accent: var(--ended-row-accent);
}

html :is(.app-shell, .app-notice-modal) :is(
    .availability-space-item.is-partial,
    .availability-space-legend-swatch.is-partial
) {
    --parking-space-background: var(--parking-partial-background);
    --parking-space-accent: var(--parking-partial-accent);
}

html :is(.app-shell, .app-notice-modal) :is(
    .availability-space-item.is-fragmented,
    .availability-space-legend-swatch.is-fragmented
) {
    --parking-space-background: var(--parking-fragmented-background);
    --parking-space-accent: var(--parking-fragmented-accent);
}

html :is(.app-shell, .app-notice-modal) :is(
    .availability-space-item.is-reserved,
    .availability-space-legend-swatch.is-reserved
) {
    --parking-space-background: var(--reservation-row-background);
    --parking-space-accent: var(--reservation-row-accent);
}

html:root :is(.app-shell, .app-notice-modal) .availability-space-list .availability-space-item:is(.is-free, .is-occupied, .is-partial, .is-fragmented, .is-reserved),
html:root :is(.app-shell, .app-notice-modal) .availability-space-legend-swatch:is(.is-free, .is-occupied, .is-partial, .is-fragmented, .is-reserved) {
    border-color: var(--parking-space-accent, var(--line));
