html[data-theme="dark"] :is(.app-shell, .app-notice-modal) .availability-space-list .availability-space-item:is(.is-free, .is-occupied, .is-partial, .is-fragmented, .is-reserved),
html[data-theme="dark"] :is(.app-shell, .app-notice-modal) .availability-space-legend-swatch:is(.is-free, .is-occupied, .is-partial, .is-fragmented, .is-reserved) {
    color: #ffffff;
}

html:root :is(.app-shell, .app-notice-modal) .availability-space-list .availability-space-item:is(.is-free, .is-occupied, .is-partial, .is-fragmented, .is-reserved):is(:hover, :focus-visible) {
