/* Selector emergente del color de los vehículos de Registro. */

.record-modal.parking-color-picker-modal {
    z-index: 170;
}

.record-modal-panel.parking-color-picker-panel {
    align-self: center;
    gap: 16px;
    width: min(780px, 100%);
    max-height: min(92dvh, 780px);
    border-color: var(--line);
    background: var(--surface);
    color: #000000;
}

.parking-color-picker-options {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 10px;
    min-width: 0;
}

.parking-color-picker-option {
    display: grid;
    grid-template-columns: 30px minmax(0, 1fr);
    min-width: 0;
    min-height: 48px;
    align-items: center;
    gap: 9px;
    padding: 8px 10px;
    border: 1px solid var(--line);
    border-radius: 9px;
    background: var(--surface);
    color: #000000;
    font: inherit;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.2;
    text-align: left;
    cursor: pointer;
}

.parking-color-picker-option:not(:disabled):hover {
    border-color: var(--brand-primary);
    background: color-mix(in srgb, var(--brand-primary) 10%, var(--surface));
    color: #000000;
}

.parking-color-picker-option.is-selected,
.parking-color-picker-option[aria-pressed="true"] {
    border-color: var(--brand-primary);
    background: var(--brand-primary);
    color: #ffffff;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand-primary) 24%, transparent);
}

.parking-color-picker-option.is-selection-locked,
.parking-color-picker-option:disabled {
    border-color: #9aa5ad;
    background: #d9dee1;
    color: #000000;
    cursor: default;
}

.parking-color-picker-option.is-selection-locked .parking-color-picker-swatch,
.parking-color-picker-option:disabled .parking-color-picker-swatch {
    filter: grayscale(1);
}

.parking-color-picker-option:focus-visible {
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 28%, transparent);
    outline-offset: 2px;
}

.parking-color-picker-swatch {
    display: block;
    width: 30px;
    height: 30px;
    border: 1px solid var(--line-strong);
    border-radius: 50%;
    background: var(--parking-color-swatch, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, #ffffff 28%, transparent);
}

.parking-color-picker-custom {
    display: grid;
    flex: 1 1 300px;
    min-width: 0;
    gap: 6px;
    color: #000000;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.2;
    text-transform: uppercase;
}

.parking-color-picker-custom[hidden] {
    display: none;
}

.parking-color-picker-custom input {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    height: 42px;
    padding: 0 12px;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #ffffff;
    color: #000000;
    font: inherit;
    font-size: 14px;
    text-transform: none;
}

.parking-color-picker-custom input:focus {
    border-color: var(--brand-primary);
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 14%, transparent);
}

/* El campo de "Otro": de sólo lectura, muestra el hex elegido con su
   circulito adentro; el click reabre el selector nativo. Al lado, el
   tachito para quitar el color y des-seleccionar "Otro". */
.parking-color-picker-custom-row {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.parking-color-picker-custom-field {
    position: relative;
    display: block;
    flex: 1 1 auto;
    min-width: 0;
}

/* El mismo molde que los tachitos de siempre (select-clear): círculo lleno
   rojo con el tacho a línea blanca, igual en claro y oscuro. */
.parking-color-picker-custom-clear {
    display: inline-grid;
    flex: 0 0 auto;
    place-items: center;
    width: 36px;
    height: 36px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: var(--danger);
    color: #ffffff;
    line-height: 0;
    cursor: pointer;
}

.parking-color-picker-custom-clear:hover,
.parking-color-picker-custom-clear:focus-visible {
    background: color-mix(in srgb, var(--danger) 82%, #000);
    color: #ffffff;
}

.parking-color-picker-custom-clear:focus-visible {
    outline: 3px solid color-mix(in srgb, var(--danger) 30%, transparent);
    outline-offset: 2px;
}

/* Su display propio le ganaría al hidden del navegador: sin esto el tachito
   quedaría siempre a la vista. */
.parking-color-picker-custom-clear[hidden] {
    display: none;
}

.parking-color-picker-custom-clear svg {
    width: 16px;
    height: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.parking-color-picker-custom-field input {
    padding-right: 38px;
    cursor: pointer;
}

.parking-color-picker-custom-swatch {
    position: absolute;
    top: 50%;
    right: 12px;
    width: 16px;
    height: 16px;
    border: 1px solid var(--line-strong);
    border-radius: 50%;
    background: var(--parking-color-swatch, transparent);
    transform: translateY(-50%);
    pointer-events: none;
}

.parking-color-picker-custom-swatch[hidden] {
    display: none;
}

/* El selector nativo vive invisible adentro del bloque "Otro" de la grilla:
   el navegador ancla su desplegable donde está el input. */
.parking-color-picker-option {
    position: relative;
}

.parking-color-picker-native {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    clip-path: inset(50%);
    pointer-events: none;
}

/* Los circulitos del campo: uno por color guardado, al lado del texto y antes
   de la flechita del desplegable. */
.parking-color-field-swatches {
    position: absolute;
    right: 34px;
    bottom: 14px;
    display: flex;
    pointer-events: none;
}

.parking-color-field-swatch {
    width: 16px;
    height: 16px;
    border: 1px solid var(--line-strong);
    border-radius: 50%;
    background: var(--parking-color-swatch, transparent);
    box-shadow: 0 0 0 1px color-mix(in srgb, #ffffff 40%, transparent);
}

.parking-color-field-swatch + .parking-color-field-swatch {
    margin-left: -6px;
}

.parking-color-picker-actions {
    align-items: end;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: flex-end;
}

/* Los botones nunca se encogen por debajo de su texto: si falta lugar, cede
   la sección del personalizado (el hex se corta con puntos suspensivos). */
.parking-color-picker-actions > .button {
    flex-shrink: 0;
    width: auto;
    min-width: 0;
    min-height: 42px;
    white-space: nowrap;
}

label.parking-color-picker-field {
    position: relative;
}

label.parking-color-picker-field::after {
    position: absolute;
    right: 16px;
    bottom: 18px;
    width: 8px;
    height: 8px;
    border-right: 2px solid var(--brand-primary);
    border-bottom: 2px solid var(--brand-primary);
    content: "";
    pointer-events: none;
    transform: rotate(45deg) translateY(-2px);
}

input[data-parking-color-picker-prepared="1"] {
    padding-right: 40px;
    cursor: pointer;
}

