    box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand-primary) 14%, transparent);
}

.expandable-filter-search:focus-within {
    outline: 3px solid var(--brand-primary);
    outline-offset: 2px;
}

.expandable-filter-search-toggle,
.expandable-filter-search-clear {
    display: inline-grid;
    flex: 0 0 40px;
    width: 40px;
    min-width: 40px;
    height: 40px;
    min-height: 40px;
    place-items: center;
    padding: 0;
    border: 0;
    background: transparent;
    color: #000000;
    cursor: pointer;
}

.expandable-filter-search-toggle svg,
.expandable-filter-search-clear svg {
    width: 20px;
    height: 20px;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
}

.expandable-filter-search-toggle:focus-visible,
.expandable-filter-search-clear:focus-visible {
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 25%, transparent);
    outline-offset: -4px;
}

.expandable-filter-search-field {
    position: relative;
    display: flex;
    flex: 1 1 auto;
    min-width: 0;
    align-items: center;
    visibility: hidden;
}

.expandable-filter-search.is-expanded .expandable-filter-search-field {
    visibility: visible;
}

.expandable-filter-search .expandable-filter-search-field > input[type="search"] {
    appearance: none;
    width: 100%;
    min-width: 0;
    min-height: 40px;
    padding: 0 40px 0 2px;
    border: 0;
    border-radius: 0;
    outline: 0;
    background: transparent;
    color: #000000;
    font-size: 13px;
    font-weight: 600;
}

.expandable-filter-search .expandable-filter-search-field > input[type="search"]::-webkit-search-cancel-button {
    display: none;
}

.expandable-filter-search .expandable-filter-search-field > input[type="search"]::placeholder {
    color: var(--placeholder);
}

.expandable-filter-search-clear {
    position: absolute;
    top: 0;
    right: 0;
}

.expandable-filter-search-clear[hidden] {
    display: none;
}

html[data-theme="dark"] .app-shell .expandable-filter-search {
    border-color: #565656;
    background: #0c0c0c;
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .expandable-filter-search.is-expanded {
    border-color: #565656;
}

html[data-theme="dark"] .app-shell .expandable-filter-search:focus-within {
    outline-color: #ffffff;
}

html[data-theme="dark"] .app-shell :is(.expandable-filter-search-toggle, .expandable-filter-search-clear) {
    color: #ffffff;
}

html[data-theme="dark"] .app-shell .expandable-filter-search .expandable-filter-search-field > input[type="search"] {
    border: 0;
    background: transparent;
    color: #ffffff;
}

/* Las búsquedas de las ventanas comparten el control compacto del listado;
   .entry-form no debe convertir su lupa en una acción primaria de 160 px. */
html:root .app-shell .expandable-filter-search :is(
