    .expandable-filter-search-toggle, .expandable-filter-search-clear
)[hidden] {
    display: none;
}

html:root .app-shell .expandable-filter-search .expandable-filter-search-field > input[type="search"],
html[data-theme="dark"] .app-shell .entry-form .expandable-filter-search .expandable-filter-search-field > input[type="search"] {
