    box-sizing: border-box;
    flex: 0 0 var(--parking-search-column-width);
    width: var(--parking-search-column-width);
    min-width: 0;
    max-width: none;
    height: var(--parking-search-control-height);
    min-height: var(--parking-search-control-height);
