.app-shell .record-pagination-toolbar > :is(
    [data-record-search],
    [data-parking-vehicle-search],
    [data-parking-contract-search],
    [data-next-availability-search],
    [data-parking-config-search],
    [data-floor-modal-search],
    [data-zone-reason-search]
) {
    --parking-search-control-height: 40px;
}

.app-shell :is(.record-pagination-toolbar, .availability-results-toolbar) > .expandable-filter-search :is(.expandable-filter-search-toggle, .expandable-filter-search-clear) {
    height: calc(var(--parking-search-control-height) - 2px);
    min-height: calc(var(--parking-search-control-height) - 2px);
}

.app-shell :is(.record-pagination-toolbar, .availability-results-toolbar) > .expandable-filter-search .expandable-filter-search-field > input[type="search"] {
    height: calc(var(--parking-search-control-height) - 2px);
