.rental-module .rental-description dd { margin: 5px 0 0; font-size: 14px; overflow-wrap: anywhere; }
.rental-module .rental-unit-section { margin-block-end: 14px; }
.rental-module .rental-period-rate { grid-column: 1 / -1; margin: 0; }
