.rental-module .rental-ledger-row { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; text-decoration: none; color: var(--ink); }
.rental-module .rental-featured-unit { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.rental-module .rental-ledger-row > div { display: grid; gap: 6px; }
.rental-module .rental-priorities { display: flex; flex-wrap: wrap; gap: 14px; margin-block-end: 16px; }
.rental-module :is(.rental-metrics > article, .rental-tool) { padding: 18px; color: var(--ink); }
.rental-module .rental-metrics h3 { margin: 0 0 10px; font-size: 14px; }
