    margin-top: 4px;
}

html:root .app-shell [data-parking-summary-kpis] .kpi-card {
    --wk-kpi-surface: var(--surface-soft);
}
html:root .app-shell [data-parking-summary-kpis] .kpi-card.tone-positive {
    --wk-kpi-surface: var(--active-row-background);
}
html:root .app-shell [data-parking-summary-kpis] .kpi-card.tone-danger {
    --wk-kpi-surface: var(--ended-row-background);
}
html:root .app-shell [data-parking-summary-kpis] .kpi-card.tone-warning {
    --wk-kpi-surface: var(--reservation-row-background);
}
