    background: var(--surface);
}

html:root .app-shell #parking-summary-sections .parking-summary-filter-form > label {
    grid-column: auto / span 1;
    min-width: 0;
    width: 100%;
}

html:root .app-shell #parking-summary-sections .parking-summary-filter-form select {
    width: 100%;
}

.app-shell .parking-summary-metrics-body > :first-child {
    margin-top: 0;
}

.app-shell .parking-summary-metrics-body > :last-child {
    margin-bottom: 0;
}

/* Sólo disposición de columnas. Cabecera, filas, superficie y tipografía
   proceden del listado principal de Registro y de wk-record-table. */
