}

.app-shell .wk-metric-preview-current,
.app-shell .wk-metric-series-dot {
    fill: var(--accent-purple);
}

.app-shell .wk-metric-preview-previous {
    fill: var(--accent-blue);
}

.app-shell .wk-metric-preview-line,
.app-shell .wk-metric-series-line {
    fill: none;
    stroke: var(--accent-purple);
    stroke-width: 3;
}

.app-shell .wk-metric-preview-area,
.app-shell .wk-metric-series-area {
    fill: color-mix(in srgb, var(--accent-purple) 25%, transparent);
}

.app-shell .wk-metric-point-track {
