/* La flecha aprobada de Año y Ordenar es el recurso oficial de todos los
   desplegables. El mismo SVG se pinta en select nativos y botones accesibles. */
html:root .app-shell {
    --workraken-select-arrow-light: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 8' fill='none' stroke='%236D28D9' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M1 1L6 6L11 1'/%3E%3C/svg%3E");
    --workraken-select-arrow-dark: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 8' fill='none' stroke='%23ffffff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M1 1L6 6L11 1'/%3E%3C/svg%3E");
    --workraken-select-arrow: var(--workraken-select-arrow-light);
}

html[data-theme="dark"] .app-shell {
    --workraken-select-arrow: var(--workraken-select-arrow-dark);
}

html[data-theme="dark"] .app-shell .public-page-owner-preview {
    --workraken-select-arrow: var(--workraken-select-arrow-light);
}

html:root .app-shell select:not([multiple]):not([size]) {
    appearance: none;
    padding-right: 40px;
    background-image: var(--workraken-select-arrow);
    background-repeat: no-repeat;
    background-position: right 16px center;
    background-size: 12px 8px;
}

/* Un selector simple conserva la medida tipográfica del campo que reemplaza.
   Cajas y País/Moneda mantienen su variante propia de 12 px. */
html:root .app-shell .workraken-single-select .currency-country-trigger {
    height: var(--workraken-field-height, 42px);
    font-size: var(--workraken-field-font-size, inherit);
    font-weight: var(--workraken-field-font-weight, inherit);
}

html:root .app-shell .workraken-single-select .currency-country-option {
    font-size: var(--workraken-field-font-size, inherit);
    font-weight: var(--workraken-field-font-weight, inherit);
}

html:root .app-shell .workraken-single-select .currency-country-menu {
    width: 100%;
    min-width: 0;
}

/* Las superficies deshabilitadas usan un shorthand de fondo en la paleta. */
html:root .app-shell select:not([multiple]):not([size]):disabled,
html:root[data-theme="dark"] .app-shell select:not([multiple]):not([size]):disabled {
    background-image: var(--workraken-select-arrow);
    background-repeat: no-repeat;
    background-position: right 16px center;
    background-size: 12px 8px;
}

.availability-state-filter-chevron {
    width: 12px;
    height: 8px;
    background-image: var(--workraken-select-arrow);
    background-repeat: no-repeat;
    background-position: center;
    background-size: 12px 8px;
    transition: transform 0.16s ease;
}

.availability-state-filter.is-open .availability-state-filter-chevron {
    transform: rotate(180deg);
}

/* La opción y el valor elegido muestran la misma muestra sólida de estado. */
