    .availability-state-filter-swatch.availability-space-legend-swatch.is-activo {
    border: 1px solid #ffffff;
}

/* Estructura compartida del desplegable múltiple. Cajas y Motivos aportan
   sus datos y resúmenes; el control conserva una sola superficie. */
.workraken-multi-select {
    position: relative;
    display: block;
    width: 100%;
    min-width: 0;
    max-width: 100%;
}

.entry-form .workraken-multi-select-trigger {
    position: relative;
    display: block;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    height: 46px;
    padding: 0 42px 0 14px;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 8px;
    background: #ffffff;
    color: var(--ink);
    font: inherit;
    font-weight: 700;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: pointer;
    box-shadow: none;
    filter: none;
}

.entry-form .workraken-multi-select-trigger:focus-visible {
    border-color: var(--brand-primary);
    outline: 3px solid color-mix(in srgb, var(--brand-primary) 24%, transparent);
    outline-offset: 1px;
}

.entry-form .workraken-multi-select-trigger > .workraken-multi-select-summary {
    display: block;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.workraken-multi-select-menu {
    position: absolute;
    z-index: 45;
    top: calc(100% + 7px);
    right: 0;
    left: 0;
    display: grid;
    gap: 8px;
    min-width: min(320px, calc(100vw - 48px));
    max-height: min(330px, 48vh);
    padding: 9px;
    overflow: auto;
    border: 1px solid var(--line);
    border-radius: 9px;
    background: var(--surface);
    box-shadow: 0 18px 38px rgba(16, 24, 33, 0.2);
}

.workraken-multi-select-menu[hidden] {
