    .public-calculation-vehicle-check, .public-calculation-discount-check, .public-service-option,
    .parking-client-check, .cycle-day-cell, .availability-day, .availability-all-day,
    .availability-season-option, .space-vehicle-option, .vehicle-rate-tier-toggle,
    .space-category-choice, .parking-maintenance-radio-options label,
    .country-picker-option, .location-country-option, .split-picker-option,
    .parking-registration-delivery-option, .payment-discount-picker-option,
    .parking-registration-quote-option, .availability-state-filter-option, .company-catalog-option, .parking-space-picker-item.is-payment-record, [role="option"]
):not(:disabled):not([aria-disabled="true"]):not(:has(input:disabled)):not(.is-selection-locked):not(.is-registration-mode-locked):not(.is-invalid):not(:has(input[aria-invalid="true"])):focus-within:is(:focus, :has(input:focus)) {
