    outline: none !important;
    box-shadow: none !important;
}

html:root .app-shell .workraken-multi-select-option--cash:focus-within > label {
    outline: none !important;
    box-shadow: none !important;
}

/* Cobros: selección completa neutra, sin franjas ni marcas visibles. */
html:root .app-shell .workraken-multi-select-option--neutral {
