    border-color: var(--selection-neutral-border) !important;
    background: var(--selection-neutral-background) !important;
    box-shadow: none !important;
    color: var(--ink) !important;
}

html:root .app-shell .workraken-multi-select-option--neutral::before {
    content: none !important;
