}

html:root[data-theme="dark"] .app-shell .workraken-multi-select-option--neutral {
    --selection-neutral-tone: #ffffff;
}

html:root .app-shell .workraken-multi-select-option--neutral:focus-within {
    border: 2px solid var(--wk-field-focus-color) !important;
    outline: none !important;
    box-shadow: none !important;
}

/* La flecha y el campo son un componente: mismo espacio reservado y borde derecho. */
html:root .app-shell :is(
    .parking-client-picker-button, .payment-record-picker-open, .workraken-multi-select-trigger, .currency-country-trigger
):not(.workraken-dialog-selector--inline-currency) {
